import { Book } from "@/lib/types";

export const ezekiel: Book = {
  id: "ezekiel",
  name: "Hesekiel",
  shortName: "Hes",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "*Und es geschah im dreißigsten Jahr, im vierten <Monat>, am Fünften des Monats; als ich mitten unter den Weggeführten am Fluss Kebar war*, da öffnete sich der Himmel*, und ich sah Gotteserscheinungen*.", heading: "Hesekiels Berufungsvision: die Herrlichkeit des HERRN", footnotes: ["℘ Kap. 10", "℘ Kap. 3,15.23; Ps 137,1", "℘ Mt 3,16; Apg 7,56; Offb 4,1", "℘ Kap. 8,3; 2Kor 12,1"] },
      { number: 2, text: "Am Fünften des Monats — das ist das fünfte Jahr <nach> der Wegführung des Königs Jojachin* —", footnotes: ["℘ Kap. 8,1; 33,21; 2Kö 24,12.15"] },
      { number: 3, text: "geschah das Wort des HERRN ausdrücklich zu Hesekiel, dem Sohn des Busi, dem Priester, im Land der Chaldäer am Fluss Kebar*; dort kam die Hand des HERRN über ihn*.", footnotes: ["℘ Kap. 3,15.23; Ps 137,1", "LXX und die syr. Üs. lesen: über mich\n℘ Kap. 3,22; 8,1; 33,22; 40,1; 1Kö 18,46"] },
      { number: 4, text: "Und ich sah: Und siehe, ein Sturmwind kam von Norden her*, eine große Wolke und ein Feuer*, das hin- und herzuckte*, und Glanz war rings um sie* her. Und aus seiner Mitte, aus der Mitte des Feuers, <strahlte es> wie das Funkeln von glänzendem Metall.", footnotes: ["℘ 1Kö 19,11; 2Kö 2,11; Hi 38,1", "℘ Ps 50,3; 97,3", "℘ 2Mo 9,24", "d. i. die Wolke"] },
      { number: 5, text: "Und aus seiner Mitte hervor <erschien> die Gestalt von vier lebenden Wesen*; und dies war ihr Aussehen: Die Gestalt eines Menschen hatten sie.", footnotes: ["℘ Offb 4,6"] },
      { number: 6, text: "Und vier Gesichter hatte jedes, und vier Flügel hatte jedes von ihnen." },
      { number: 7, text: "Und ihre Beine waren gerade Beine und ihre Fußsohlen wie die Fußsohle eines Kalbes; und sie funkelten wie das Funkeln von blanker Bronze*.", footnotes: ["℘ Dan 10,6"] },
      { number: 8, text: "Und Menschenhände waren unter ihren Flügeln an ihren vier Seiten; und die vier hatten ihre Gesichter und ihre Flügel." },
      { number: 9, text: "Ihre Flügel berührten sich, einer mit dem anderen*; sie wandten sich nicht um, wenn sie gingen; sie gingen, ein jedes gerade vor sich hin.", footnotes: ["d. h. der rechte Flügel des einen Cherubs rührte an den linken Flügel des anderen, indem die Cherubim paarweise einander gegenüberstanden und ein Ganzes bildeten\n℘ 2Chr 3,11"] },
      { number: 10, text: "Und <das war> die Gestalt ihrer Gesichter: Das Gesicht eines Menschen und das Gesicht eines Löwen* hatten die vier rechts, und das Gesicht eines Stieres hatten die vier links, und das Gesicht eines Adlers hatten die vier*.", footnotes: ["℘ Kap. 41,19", "℘ Offb 4,7"] },
      { number: 11, text: "Und ihre Flügel* waren <nach> oben ausgespannt; jedes hatte zwei, die sich einer <mit dem anderen> berührten, und zwei, die ihre Leiber bedeckten*.", footnotes: ["so mit LXX und der alten lat. Üs.; Mas. T.: Und ihre Gesichter und ihre Flügel", "℘ Jes 6,2"] },
      { number: 12, text: "Und sie gingen ein jedes gerade vor sich hin; wohin der Geist gehen wollte, dahin gingen sie; sie wandten sich nicht um, wenn sie gingen." },
      { number: 13, text: "Und mitten zwischen den lebenden Wesen war ein Schein wie von brennenden Feuerkohlen*; wie ein Schein von Fackeln war das, was zwischen den lebenden Wesen hin- und herfuhr; und das Feuer hatte einen Glanz, und aus dem Feuer fuhren Blitze hervor*.", footnotes: ["so mit LXX; Mas. T.: Und die Gestalt der lebenden Wesen, ihr Aussehen war wie brennende Feuerkohlen", "℘ Ps 104,4; Offb 4,5"] },
      { number: 14, text: "Und die lebenden Wesen liefen hin und her, so dass es aussah wie Blitze*.", footnotes: ["w. liefen und kehrten zurück: wie das Aussehen des Blitzes"] },
      { number: 15, text: "Und als ich die lebenden Wesen sah, siehe, da war ein Rad auf der Erde neben den lebenden Wesen, bei ihren vier Vorderseiten*.", footnotes: ["d. h. an der Vorderseite eines jeden; LXX liest lediglich: bei den vieren"] },
      { number: 16, text: "Das Aussehen der Räder und ihre Verarbeitung war wie das Funkeln von Türkis, und die vier hatten ein und dieselbe Gestalt; und ihr Aussehen und ihre Verarbeitung war, wie wenn ein Rad mitten im <anderen> Rad wäre." },
      { number: 17, text: "Wenn sie gingen, dann gingen sie nach ihren vier Seiten hin; sie wandten sich nicht um, wenn sie gingen." },
      { number: 18, text: "Und ihre Felgen, sie waren hoch, und als ich sie anblickte, <sah ich,> dass ihre Felgen voller Augen waren* rings herum bei den vieren*.", footnotes: ["T.; Mas. T.: Und ihre Felgen und sie hatten Höhe, und sie hatten Furcht, und sie waren voller Augen", "℘ Offb 4,6"] },
      { number: 19, text: "Und wenn die lebenden Wesen gingen, gingen <auch> die Räder neben ihnen her; und wenn die lebenden Wesen sich von der Erde erhoben, erhoben sich <auch> die Räder." },
      { number: 20, text: "Wohin der Geist gehen wollte, gingen sie, dahin, wohin der Geist gehen <wollte>. Und die Räder erhoben sich gleichzeitig mit ihnen, denn der Geist des lebenden Wesens war in den Rädern." },
      { number: 21, text: "Wenn <jene> gingen, gingen <auch diese>, und wenn <jene> stehen blieben, dann blieben <auch diese> stehen; und wenn sich <jene> von der Erde erhoben, <dann> erhoben sich die Räder gleichzeitig mit ihnen. Denn der Geist des lebenden Wesens war in den Rädern." },
      { number: 22, text: "Und über den Häuptern des lebenden Wesens war etwas wie ein festes Gewölbe*, wie das Funkeln eines Furcht einflößenden Kristalls, ausgebreitet oben über ihren Häuptern.", footnotes: ["w. die Nachbildung eines festen Gewölbes; d. i. des Himmelsgewölbes; vgl. 1Mo 1,6—8"] },
      { number: 23, text: "Und unter dem festen Gewölbe waren ihre Flügel gerade* <ausgebreitet>, einer gegen den anderen*; und jedes hatte zwei <Flügel>, die ihnen ihre Leiber bedeckten*.", footnotes: ["d. h. waagerecht", "Andere lesen nach Kap. 3,13 und in Anlehnung an LXX: unter dem festen Gewölbe berührten die Flügel einer den anderen", "w. jedes hatte zwei, die sie bedeckten, und jedes hatte zwei, die ihnen ihre Leiber bedeckten"] },
      { number: 24, text: "Und wenn sie gingen, hörte ich das Rauschen ihrer Flügel wie das Rauschen großer Wasser*, wie die Stimme des Allmächtigen, das Rauschen einer Volksmenge, wie das Rauschen eines Heerlagers*. Wenn sie stillstanden, ließen sie ihre Flügel sinken.", footnotes: ["℘ Kap. 43,2; Offb 1,15", "℘ Kap. 3,13; Dan 10,6"] },
      { number: 25, text: "Und es kam eine Stimme von <dem Raum> oberhalb des festen Gewölbes, das über ihren Häuptern war. Wenn sie stillstanden, ließen sie ihre Flügel sinken." },
      { number: 26, text: "Und oberhalb des festen Gewölbes, das über ihren Häuptern war, <befand sich> — wie das Aussehen eines Saphirsteines* — etwas wie ein Thron und auf dem, was wie ein Thron <aussah>, oben auf ihm eine Gestalt, dem Aussehen eines Menschen gleich*.", footnotes: ["℘ 2Mo 24,10", "℘ Dan 7,9; Offb 1,13; 4,2"] },
      { number: 27, text: "Und ich sah: Wie das Funkeln von glänzendem Metall, wie das Aussehen von Feuer, das ringsum ein Gehäuse hat, <war es> von dem Aussehen seiner Hüften an aufwärts; und von dem Aussehen seiner Hüften an abwärts sah ich <etwas> wie das Aussehen von Feuer; und ein Glanz war rings um ihn*.", footnotes: ["℘ Kap. 8,2; 1Chr 16,27; Hab 3,4; Offb 1,15"] },
      { number: 28, text: "Wie das Aussehen des Bogens, der am Regentag in der Wolke ist*, so war das Aussehen des Glanzes ringsum*. Das war das Aussehen des Abbildes der Herrlichkeit des HERRN*. —Und als ich es sah, fiel ich auf mein Gesicht nieder*; und ich hörte die Stimme eines Redenden.", heading: "Hesekiels Berufungsvision", footnotes: ["℘ 1Mo 9,13.14", "℘ 2Mo 24,17; Offb 4,3; 10,1", "℘ Kap. 8,4", "℘ Kap. 3,23; Ri 13,20; Dan 8,17.18; Apg 9,4"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und er sprach zu mir: Menschensohn*, stelle dich auf deine Füße, und ich will mit dir reden!", footnotes: ["℘ Dan 8,17"] },
      { number: 2, text: "Und als er zu mir redete, kam der Geist in mich* und stellte mich auf meine Füße*; und ich hörte den, der zu mir redete*.", footnotes: ["℘ Kap. 11,5", "℘ Kap. 3,24; Dan 8,18; Apg 14,10; 26,16", "℘ Apg 22,9"] },
      { number: 3, text: "Und er sprach zu mir: Menschensohn, ich sende dich zu den Söhnen Israel, zu den empörerischen Nationen, die sich gegen mich empört haben; sie und ihre Väter haben mit mir gebrochen bis auf diesen heutigen Tag*.", footnotes: ["℘ 2Kö 17,14; Jes 30,1; Jer 3,25; Am 7,15; Mal 3,7"] },
      { number: 4, text: "<Zu> den Söhnen mit frechem Gesicht und hartem Herzen*, zu ihnen sende ich dich; und du sollst zu ihnen sagen: »So spricht der Herr, HERR!«*", footnotes: ["℘ Kap. 3,7; Jes 48,4", "℘ Kap. 3,27"] },
      { number: 5, text: "Und sie, mögen sie hören oder es lassen* — denn sie sind ein widerspenstiges Haus* —, sie sollen doch erkennen, dass ein Prophet in ihrer Mitte gewesen ist*.", footnotes: ["℘ Kap. 3,11", "w. Haus Widerspenstigkeit; d. i. wohl eine bewusste Anspielung auf die Anrede »Haus Israel«\n℘ Kap. 3,26; 17,12; 24,3; 44,6", "℘ Kap. 33,33; 2Kö 5,8"] },
      { number: 6, text: "Und du, Menschensohn, fürchte dich nicht vor ihnen*, und fürchte dich nicht vor ihren Worten, wenn <auch> Dornen dich umgeben* und du auf Skorpionen sitzt*. Vor ihren Worten fürchte dich nicht, und erschrick nicht vor ihrem Angesicht! Denn ein widerspenstiges Haus* sind sie*.", footnotes: ["℘ Jer 1,8.17", "℘ 2Sam 23,6; Mi 7,4", "so in Anlehnung an LXX; Mas. T.: denn sie sind widerspenstig und Dornen sind <gegen> dich", "s. Anm. zu Kap. 2,5", "℘ Kap. 3,9"] },
      { number: 7, text: "Und du sollst meine Worte zu ihnen reden*, mögen sie hören oder es lassen! Denn widerspenstig sind sie*.", footnotes: ["℘ Kap. 3,4; 2Mo 6,29; Jer 44,20", "℘ Jer 6,28"] },
      { number: 8, text: "Und du, Menschensohn, höre, was ich zu dir rede! Sei nicht widerspenstig* wie das widerspenstige Haus*: Öffne deinen Mund und iss, was ich dir gebe*! —", footnotes: ["℘ Jon 1,3", "s. Anm. zu Kap. 2,5\n℘ Jes 8,11", "℘ Offb 10,9"] },
      { number: 9, text: "Und ich sah: und siehe, eine Hand war zu mir hin ausgestreckt*; und siehe, in ihr* <befand sich> eine Buchrolle*.", footnotes: ["℘ Kap. 8,3", "so mit LXX; Mas. T.: »in ihm« beruht offenbar auf einem Schreibfehler", "℘ Offb 10,2; Sach 5,3"] },
      { number: 10, text: "Und er breitete sie vor mir aus, und sie war auf der Vorder- und auf der Rückseite beschrieben*; und es waren darauf geschrieben Klagen und Seufzen und Wehgeschrei.", footnotes: ["℘ Offb 5,1"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und er sprach zu mir: Menschensohn, was du findest, iss! Iss diese Rolle, und geh hin, rede zum Haus Israel!" },
      { number: 2, text: "Und ich öffnete meinen Mund, und er gab mir diese Rolle zu essen." },
      { number: 3, text: "Und er sprach zu mir: Menschensohn, deinem Bauch gib zu essen, und deinen Leib fülle mit dieser Rolle, die ich dir gebe! Und ich aß sie, und sie war in meinem Munde süß wie Honig*.", footnotes: ["℘ Ps 19,11; Jer 15,16; Offb 10,9.10"] },
      { number: 4, text: "Und er sprach zu mir: Menschensohn, auf, geh hin zum Haus Israel und rede mit meinen Worten zu ihnen*!", footnotes: ["℘ Kap. 2,4.7; 11,4.25"] },
      { number: 5, text: "Denn nicht zu einem Volk mit dunkler Sprache und schwieriger Rede bist du gesandt*, <sondern> zum Haus Israel.", footnotes: ["℘ Jes 33,19"] },
      { number: 6, text: "Nicht zu vielen Völkern mit dunkler Sprache und schwieriger Rede, deren Worte du nicht verstehst*. *Würde ich dich zu diesen senden, sie würden auf dich hören.*", footnotes: ["℘ Jes 33,19", "so mit LXX und Vulg.; Mas. T.: sondern zu ihnen habe ich dich gesandt, sie hören auf dich.", "so mit LXX und Vulg.; Mas. T.: sondern zu ihnen habe ich dich gesandt, sie hören auf dich."] },
      { number: 7, text: "Aber das Haus Israel wird nicht auf dich hören wollen, denn sie wollen nicht auf mich hören*. Denn das ganze Haus Israel hat eine harte Stirn und ein verstocktes Herz*.", footnotes: ["℘ Jer 6,17; 7,27; Sach 7,11", "℘ Kap. 2,4"] },
      { number: 8, text: "Siehe, ich habe dein Angesicht hart gemacht, genau wie ihr Angesicht, und deine Stirn hart, genau wie ihre Stirn*;", footnotes: ["℘ Jer 1,18; 15,20"] },
      { number: 9, text: "wie einen Diamanten, härter als einen Kieselstein, habe ich deine Stirn gemacht*. Fürchte sie nicht und erschrick nicht vor ihrem Angesicht*! Denn ein widerspenstiges Haus* sind sie*. —", footnotes: ["℘ Jes 50,7", "℘ Lk 12,4", "s. Anm. zu Kap. 2,5", "℘ Kap. 2,6"] },
      { number: 10, text: "Und er sprach zu mir: Menschensohn, alle meine Worte, die ich zu dir reden werde, nimm in dein Herz auf, und höre <sie> mit deinen Ohren*!", footnotes: ["℘ Ps 85,9"] },
      { number: 11, text: "Und <mache dich> auf, geh hin zu den Weggeführten, zu den Söhnen deines Volkes*, rede zu ihnen und sage zu ihnen: »So spricht der Herr, HERR!« Sie mögen hören oder es lassen*.", footnotes: ["℘ Kap. 33,2", "℘ V. 27; Kap. 2,4.5; Jer 29,20"] },
      { number: 12, text: "Und der Geist hob mich empor*; und ich hörte hinter mir den Schall eines starken *Getöses, als sich die Herrlichkeit des HERRN von ihrer Stätte erhob*,", footnotes: ["℘ Kap. 8,3; 11,1.24; 43,5; 1Kö 18,12", "So wahrscheinlich der ursprüngliche Text. Mas. T.: Getöses: Gepriesen sei die Herrlichkeit des HERRN von ihrer Stätte her!", "So wahrscheinlich der ursprüngliche Text. Mas. T.: Getöses: Gepriesen sei die Herrlichkeit des HERRN von ihrer Stätte her!\n℘ Kap. 43,4.5; Ps 26,8; Lk 2,14"] },
      { number: 13, text: "und das Rauschen der Flügel der lebenden Wesen, die einer den anderen berührten, und das Sausen der Räder, die <sich> gleichzeitig mit ihnen <bewegten>, und den Schall eines starken Getöses*.", footnotes: ["℘ Kap. 1,24"] },
      { number: 14, text: "Und der Geist hob mich empor* und nahm mich hinweg*; und ich fuhr dahin, erbittert in der Erregung meines Geistes*; und die Hand des HERRN war hart auf mir*.", footnotes: ["℘ Kap. 8,3; 11,1.24; 43,5; 1Kö 18,12", "℘ Apg 8,39", "℘ Jer 6,11", "℘ Jes 8,11"] },
      { number: 15, text: "Und ich kam nach Tel-Abib zu den Weggeführten, die am Fluss Kebar wohnten*; und ich blieb <bei denen>, die dort wohnten*; und ich saß dort sieben Tage betäubt* in ihrer Mitte*.", footnotes: ["℘ Kap. 1,1.3", "o. Ich kam zu den Weggeführten nach Tel-Abib, wo diese wohnten, die am Fluss Kebar wohnten", "w. entsetzeneinflößend", "℘ Hi 2,13"] },
      { number: 16, text: "*Und es geschah am Ende von sieben Tagen, da geschah das Wort des HERRN zu mir so:", heading: "Hesekiels Beauftragung und Verantwortung für den Einzelnen in Gottes Volk", footnotes: ["℘ V. 16-21: Kap. 33,1-20"] },
      { number: 17, text: "Menschensohn, ich habe dich für das Haus Israel zum Wächter gegeben*. Und hörst du ein Wort aus meinem Mund, so sollst du sie von mir verwarnen*!", footnotes: ["℘ Jes 62,6; Jer 6,17", "℘ Jer 1,7"] },
      { number: 18, text: "Wenn ich zu dem Gottlosen spreche: »Du musst sterben*!« und du hast ihn nicht gewarnt und hast nicht geredet, um den Gottlosen vor seinem gottlosen Weg zu warnen, um ihn am Leben zu erhalten, dann wird er, der Gottlose, um seiner Schuld willen sterben, aber sein Blut werde ich von deiner Hand fordern.", footnotes: ["℘ Kap. 18,4.20"] },
      { number: 19, text: "Du aber, wenn du den Gottlosen gewarnt hast und er ist von seiner Gottlosigkeit und von seinem gottlosen Weg nicht umgekehrt, dann wird er um seiner Schuld willen sterben, du aber hast deine Seele gerettet*.", footnotes: ["℘ Apg 18,6"] },
      { number: 20, text: "Und wenn ein Gerechter von seiner Gerechtigkeit umkehrt und Unrecht tut* und ich einen Anstoß vor ihn lege, dann wird er sterben. Wenn du ihn nicht gewarnt hast, wird er um seiner Sünde willen sterben, und an seine gerechten Taten*, die er getan hat, wird man nicht <mehr> denken; aber sein Blut werde ich von deiner Hand fordern*.", footnotes: ["℘ Kap. 18,24.26; 2Petr 2,21", "w. an seine Gerechtigkeiten", "℘ Hebr 13,17"] },
      { number: 21, text: "Du aber, wenn du ihn, den Gerechten, gewarnt hast, damit der Gerechte nicht sündige, und er hat nicht gesündigt, so wird er leben*, weil er sich hat warnen lassen; du aber, du hast deine Seele gerettet*.", footnotes: ["w. so wird <ihm> sein Leben werden", "℘ Apg 18,6"] },
      { number: 22, text: "Und die Hand des HERRN kam dort über mich*, und er sprach zu mir: Mache dich auf, geh hinaus in das Tal*. Und dort will ich mit dir reden!", heading: "Vision Hesekiels: Die Herrlichkeit des HERRN — Vom HERRN auferlegte Beschränkung", footnotes: ["℘ Kap. 1,3; 8,4", "w. in die Talebene"] },
      { number: 23, text: "Da machte ich mich auf und ging hinaus in das Tal*, und siehe, dort stand die Herrlichkeit des HERRN wie die Herrlichkeit, die ich am Fluss Kebar gesehen hatte*; und ich fiel nieder auf mein Gesicht*.", footnotes: ["w. in die Talebene", "℘ Kap. 1,3; 8,4", "℘ Kap. 1,28; 43,3; 44,4; Jos 5,14"] },
      { number: 24, text: "Da kam der Geist in mich hinein und stellte mich auf meine Füße*. Und er* redete mit mir und sprach zu mir: Geh, schließ dich in deinem Haus ein!", footnotes: ["℘ Kap. 2,2", "d. i. der HERR"] },
      { number: 25, text: "Und du, Menschensohn, siehe, man wird dir Stricke anlegen und dich damit binden, dass du nicht in ihre Mitte hinausgehen kannst*.", footnotes: ["℘ Kap. 4,8"] },
      { number: 26, text: "Und ich werde deine Zunge an deinem Gaumen kleben lassen, damit du verstummst und für sie nicht mehr jemand bist, der zurechtweist; denn ein widerspenstiges Haus* sind sie*.", footnotes: ["s. Anm. zu Kap. 2,5", "℘ Kap. 2,5.6; 12,2.3"] },
      { number: 27, text: "Wenn ich aber mit dir reden werde, will ich deinen Mund öffnen*, und du sollst zu ihnen sagen: »So spricht der Herr, HERR!«* Wer hören will, der höre, und wer es lässt, der lasse es*! Denn ein widerspenstiges Haus* sind sie*.", footnotes: ["℘ Kap. 24,27; 33,22", "℘ Kap. 2,4", "℘ V. 11", "s. Anm. zu Kap. 2,5", "℘ Kap. 2,5.6; 12,2.3"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und du, Menschensohn, nimm dir einen Ziegelstein, und lege ihn vor dich hin, und zeichne darauf eine Stadt, <nämlich> Jerusalem!*", heading: "Verschiedene Zeichenhandlungen zur Darstellung der Belagerung und Schuld Jerusalems", footnotes: ["℘ Kap. 5,1.2; 12,3; Jes 20,3"] },
      { number: 2, text: "Und verhänge eine Belagerung gegen sie, und baue Belagerungstürme gegen sie, und schütte gegen sie einen Belagerungswall auf, und stelle Heerlager gegen sie, und errichte Sturmböcke gegen sie ringsherum!*", footnotes: ["℘ Kap. 21,27; Jer 6,6; Lk 19,43"] },
      { number: 3, text: "Und du, nimm dir eine eiserne Pfanne, und stelle sie als eine eiserne Wand zwischen dich und die Stadt! Und richte dein Gesicht gegen sie, dass sie in Belagerung sei und du sie belagerst!* Das ist ein Wahrzeichen für das Haus Israel*.", footnotes: ["℘ Jes 22,7", "℘ Kap. 12,6.11; 24,24.27"] },
      { number: 4, text: "Und du, lege dich auf deine linke Seite, und lege die Schuld des Hauses Israel auf dich*: Nach der Anzahl der Tage, die du auf ihr liegst, <so lange> sollst du ihre Schuld tragen!", footnotes: ["T.; Mas. T.: auf sie; d. i. die linke Seite, auf der Hesekiel liegt"] },
      { number: 5, text: "Und ich habe dir die Jahre ihrer Schuld zu einer Anzahl von Tagen gemacht: 390 Tage. <So lange> sollst du die Schuld des Hauses Israel tragen." },
      { number: 6, text: "Und hast du diese <Zeit> vollendet, so lege dich zum zweiten Mal hin, <nun> auf deine rechte Seite, und trage die Schuld des Hauses Juda! Vierzig Tage lang, je einen Tag für ein Jahr, habe ich <sie> dir auferlegt*. —", footnotes: ["w. gegeben\n℘ 4Mo 14,34; Dan 9,24"] },
      { number: 7, text: "Und gegen die Belagerung Jerusalems richte dein Gesicht und deinen entblößten Arm, und du sollst gegen es weissagen!" },
      { number: 8, text: "Und siehe, ich lege dir Stricke an, dass du dich nicht von einer Seite auf die andere umdrehen kannst, bis du die Tage deiner Belagerung vollendet hast*.", footnotes: ["℘ Kap. 3,25; 5,2"] },
      { number: 9, text: "Und du, nimm dir Weizen und Gerste und Bohnen und Linsen und Hirse und Korn*, und tu sie in ein <einziges> Gefäß! Und mache dir Brot daraus nach der Zahl der Tage, die du auf deiner Seite liegst: 390 Tage sollst du davon essen!", footnotes: ["eine unbekannte Kornart"] },
      { number: 10, text: "Und deine Nahrung, die du essen wirst, soll nach <genau abgemessenem> Gewicht sein: zwanzig Schekel für den Tag; von Zeit zu Zeit* sollst du davon essen!", footnotes: ["d. i. zu festgesetzten Zeiten"] },
      { number: 11, text: "Und Wasser sollst du nach <genau festgesetztem> Maß trinken: ein sechstel Hin; von Zeit zu Zeit* sollst du trinken!", footnotes: ["d. i. zu festgesetzten Zeiten"] },
      { number: 12, text: "Und wie Gerstenbrotfladen sollst du sie* essen, und du sollst sie in Mistfladen aus Menschenkot vor ihren Augen backen!", footnotes: ["nämlich die in V. 9 genannten Dinge"] },
      { number: 13, text: "Und der HERR sprach: So werden die Söhne Israel ihr Brot unrein essen unter den Nationen, wohin ich sie vertreiben werde*.", footnotes: ["℘ Dan 1,8; Hos 9,3.4"] },
      { number: 14, text: "Da sprach ich: Ach, Herr, HERR! Siehe, meine Seele ist nie unrein gemacht worden, und weder Aas noch Zerrissenes habe ich gegessen* von meiner Jugend an bis jetzt, und nichts Unreines* ist in meinen Mund gekommen*.", footnotes: ["℘ 2Mo 22,30; 3Mo 11,39.40", "d. i. kultisch unrein gewordenes Opferfleisch", "℘ 5Mo 14,3; Apg 10,14"] },
      { number: 15, text: "Und er sprach zu mir: Siehe, ich habe dir Rindermist statt Menschenkot gestattet; und darauf magst du dein Brot bereiten." },
      { number: 16, text: "Und er sprach zu mir: Menschensohn, siehe, ich zerbreche den Stab* des Brotes in Jerusalem* — und sie werden Brot essen nach <genau abgemessenem> Gewicht und in Angst und Wasser trinken nach <genau abgemessenem> Maß und in Entsetzen* —,", footnotes: ["Gemeint sind die Stöcke, an denen die ringförmigen Brote aufgehängt sind.", "℘ Kap. 5,16; 14,13; 3Mo 26,26; 2Kö 25,3", "℘ Kap. 12,18.19; Kla 4,9.10"] },
      { number: 17, text: "damit sie an Brot und Wasser Mangel haben und miteinander* verschmachten und in ihrer Schuld* dahinschwinden*.", footnotes: ["w. ein Mann und sein Bruder", "o. um ihrer Schuld willen", "℘ Kap. 24,23; 3Mo 26,39; 2Kö 6,25; 2Chr 34,24"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Und du, Menschensohn, nimm dir ein scharfes Schwert: als Schermesser sollst du es dir nehmen* und damit über deinen Kopf und über deinen Bart fahren; und nimm dir Waagschalen und teile die Haare*!", footnotes: ["℘ V. 1-17: Jer 19,1-13", "℘ Jes 7,20", "w. sie"] },
      { number: 2, text: "Ein Drittel sollst du mitten in der Stadt mit Feuer verbrennen*, wenn die Tage der Belagerung erfüllt sind*; und ein Drittel sollst du nehmen <und es> rings um sie her mit dem Schwert schlagen; und ein Drittel sollst du in den Wind streuen! Denn ich werde das Schwert ziehen hinter ihnen her*.", footnotes: ["℘ Kap. 4,1", "℘ Kap. 4,7.8", "℘ Kap. 12,14; Jer 9,15; 15,2; Am 9,4"] },
      { number: 3, text: "Und du sollst davon etwas nehmen, wenig an Zahl, und in deine <Mantel>zipfel binden." },
      { number: 4, text: "Und von diesen sollst du noch einmal nehmen und sie mitten ins Feuer werfen und sie mit Feuer verbrennen! Davon wird ein Feuer ausgehen gegen das ganze Haus Israel." },
      { number: 5, text: "So spricht der Herr, HERR: Das ist Jerusalem! Mitten unter die Nationen habe ich es gesetzt und Länder rings um es her*.", heading: "Die Botschaft der Zeichenhandlungen: Gott selbst gibt Jerusalem preis", footnotes: ["℘ Ps 87,3"] },
      { number: 6, text: "Und es war widerspenstig gegen meine Rechtsbestimmungen, gottloser als die Nationen, und gegen meine Ordnungen, mehr als die Länder, die rings um es her sind. Denn meine Rechtsbestimmungen haben sie verworfen, und in meinen Ordnungen haben sie nicht gelebt*.", footnotes: ["w. sind sie nicht gegangen\n℘ Kap. 11,12; 16,47.48; 2Mo 16,28; 2Kö 21,9.11; Neh 9,34.35; Dan 9,5.10.11"] },
      { number: 7, text: "Darum, so spricht der Herr, HERR: Weil ihr getobt habt* mehr als die Nationen, die rings um euch her sind, in meinen Ordnungen nicht gelebt* und meine Rechtsbestimmungen nicht gehalten habt, ja, <selbst> nach den Rechtsbestimmungen der Nationen, die rings um euch her sind, nicht gehandelt habt,", footnotes: ["w. wegen eures Getöses. — Andere nehmen als ursprünglich an: Weil ihr widerspenstig gewesen seid", "w. nicht gegangen seid"] },
      { number: 8, text: "darum, so spricht der Herr, HERR: Siehe, <jetzt> will auch ich gegen dich sein und will Strafgerichte in deiner Mitte üben vor den Augen der Nationen*.", footnotes: ["℘ Kap. 11,9; 16,41"] },
      { number: 9, text: "Und ich will an dir tun, was ich <noch> nie getan habe und desgleichen ich nicht wieder tun werde*, um all deiner Gräuel willen*.", footnotes: ["℘ Dan 9,12", "℘ Kap. 33,29"] },
      { number: 10, text: "Darum werden Väter <ihre> Söhne essen in deiner Mitte, und Söhne werden ihre Väter essen*. Und ich will Strafgerichte an dir üben und will deinen ganzen Rest in alle Winde zerstreuen*.", footnotes: ["℘ 3Mo 26,29; Kla 2,20", "℘ Kap. 12,14; 22,15; Neh 1,8; Kla 4,16; Dan 9,7"] },
      { number: 11, text: "Darum, so wahr ich lebe, spricht der Herr, HERR*: Fürwahr, weil du mein Heiligtum unrein gemacht hast mit all deinen Scheusalen und mit all deinen Gräueln*, so will auch ich <dich> scheren und <deinetwegen> nicht betrübt sein*, und auch ich will kein Mitleid haben*.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "℘ Kap. 8,5-16.18; 23,38.39; Jer 7,9-11", "w. und mein Auge soll nicht fließen; d. h. nicht weinen", "℘ Kap. 7,4.9; 8,18; 9,5.10; 24,14; Kla 2,21; 1Kor 3,17"] },
      { number: 12, text: "Ein Drittel von dir soll an der Pest sterben und in deiner Mitte durch Hunger umkommen; und ein Drittel soll durchs Schwert fallen rings um dich her*; und ein Drittel werde ich in alle Winde zerstreuen, und ich werde das Schwert ziehen hinter ihnen her*.", footnotes: ["℘ Kap. 6,12; 7,3.15; 14,21; 16,42; 21,22; 24,13; 43,8; Jes 1,24; Jer 14,12; 15,9; Offb 6,8", "℘ Kap. 12,14; Jer 9,15; 15,2; Am 9,4"] },
      { number: 13, text: "Und mein Zorn soll sich erfüllen, und meinen Grimm werde ich an ihnen stillen und Rache nehmen*. Und sie werden erkennen, dass ich, der HERR, in meinem Eifer geredet habe*, wenn ich meinen Grimm an ihnen erfülle.", footnotes: ["℘ Kap. 6,12; 7,3.15; 14,21; 16,42; 21,22; 24,13; 43,8; Jes 1,24; Jer 14,12; 15,9; Offb 6,8", "℘ Kap. 6,10; 17,21.24; 23,25"] },
      { number: 14, text: "Und ich werde dich zur Trümmerstätte machen und zum Hohn unter den Nationen, die rings um dich her sind, vor den Augen eines jeden, der vorübergeht*.", footnotes: ["℘ Kap. 36,34; Neh 2,17"] },
      { number: 15, text: "Und du wirst* <zum> Hohn und <zur> Spottrede sein, <zur> Warnung und <zum> Grausen für die Nationen*, die rings um dich her sind, wenn ich Strafgerichte an dir übe* im Zorn und im Grimm und mit grimmigen Züchtigungen* — ich, der HERR, habe geredet —,", footnotes: ["so mit den alten Üs.; Mas. T.: es wird", "℘ 3Mo 26,32; 5Mo 28,37; 1Kö 9,7; Kla 2,15-17", "℘ Kap. 11,9; 16,41", "℘ 2Chr 29,8; Jer 29,18"] },
      { number: 16, text: "wenn ich die bösen Pfeile des Hungers gegen sie sende, die zur Vernichtung sind, die ich sende, um euch zu vernichten, und <wenn> ich den Hunger über euch häufe und euch den Stab des Brotes* zerbreche*", footnotes: ["s. Anm. zu Kap. 4,16", "℘ Kap. 4,16"] },
      { number: 17, text: "und <wenn> ich Hunger über euch sende und böse Tiere, dass sie dich kinderlos machen, und <wenn> Pest und Blut durch dich* hindurchziehen und ich das Schwert über dich bringe*. Ich, der HERR, habe geredet.", footnotes: ["d. i. durch Jerusalem", "℘ Kap. 14,21; 28,23; 33,27; 3Mo 26,22; Offb 6,8"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Gerichtsandrohung wegen Götzendienstes und heidnischer Gräuel — Verschonung eines Restes" },
      { number: 2, text: "Menschensohn, richte dein Gesicht gegen die Berge Israels, und weissage gegen sie*", footnotes: ["℘ Kap. 21,7"] },
      { number: 3, text: "und sprich: Berge Israels, hört das Wort des Herrn, HERRN!* So spricht der Herr, HERR, zu den Bergen und zu den Hügeln, zu den Bachrinnen und zu den Tälern: Siehe, ich, ich bringe das Schwert über euch* und werde eure Höhen zugrunde richten*.", footnotes: ["℘ Kap. 36,1; Mi 6,1.2", "℘ 3Mo 26,25", "℘ 3Mo 26,30; Am 7,9"] },
      { number: 4, text: "Und eure Altäre sollen verwüstet und eure Räucheraltäre zerbrochen werden. Und ich werde eure Erschlagenen hinfallen lassen vor euren Götzen*;", footnotes: ["w. Mistkugeln, o. Klötze(n); ein verächtlicher Ausdruck\n℘ Jer 7,32; 8,1.2"] },
      { number: 5, text: "und die Leichen der Söhne Israel werde ich vor ihre Götzen* hinlegen und eure Gebeine rings um eure Altäre streuen*.", footnotes: ["w. Mistkugeln, o. Klötze(n); ein verächtlicher Ausdruck", "℘ Jer 7,32; 8,1.2"] },
      { number: 6, text: "An allen euren Wohnsitzen sollen die Städte in Trümmern und die Höhen verwüstet daliegen, damit eure Altäre in Trümmern und wüst daliegen und eure Götzen* zerbrochen seien und verschwinden und eure Räucheraltäre umgehauen und eure Machwerke ausgelöscht seien*.", footnotes: ["w. Mistkugeln, o. Klötze(n); ein verächtlicher Ausdruck", "℘ 3Mo 26,31; 1Kö 14,23; Jes 2,18; Jer 9,10; 51,18; Mi 1,7"] },
      { number: 7, text: "Und Erschlagene sollen in eurer Mitte hinfallen. Und ihr werdet erkennen, dass ich der HERR bin." },
      { number: 8, text: "Doch will ich einen Rest lassen: Wenn ihr solche habt, die dem Schwert entkommen sind unter den Nationen, wenn ihr in die Länder zerstreut sein werdet*,", footnotes: ["℘ Kap. 12,16; 14,22; Neh 1,8; Jes 6,13; Zef 3,12"] },
      { number: 9, text: "dann werden eure Entkommenen unter den Nationen, wohin sie gefangen weggeführt wurden*, sich an mich erinnern, der ich ihr hurerisches Herz* zerbrochen habe*, das von mir abgewichen ist, und ihre Augen, die ihren Götzen* nachhurten. Und sie werden über sich selbst Ekel empfinden wegen der bösen Taten, die sie begangen haben nach allen ihren Gräueln*.", footnotes: ["℘ 5Mo 30,1.12; Jer 51,50; Sach 10,9", "℘ 4Mo 15,39", "so mit den alten Üs.; Mas. T.: der ich <durch> ihr hurerisches Herz zerbrochen wurde", "w. Mistkugeln, o. Klötze(n); ein verächtlicher Ausdruck", "℘ Kap. 20,43; 36,31"] },
      { number: 10, text: "Und sie werden erkennen, dass ich, der HERR, nicht umsonst geredet habe, ihnen dieses Unheil anzutun!*", footnotes: ["℘ Kap. 5,13.15.17; 22,14"] },
      { number: 11, text: "So spricht der Herr, HERR: Schlage in deine Hand*, und stampfe mit deinem Fuß auf und sprich: Wehe über alle bösen Gräuel des Hauses Israel!* Denn durch das Schwert, durch den Hunger und durch die Pest müssen sie fallen*.", footnotes: ["℘ Kap. 21,19", "℘ Kap. 9,4", "℘ Kap. 5,12.13; 33,27; Jer 24,10; 42,22"] },
      { number: 12, text: "Wer fern ist, wird an der Pest sterben, und wer nahe ist, wird durch das Schwert fallen, und wer übrig geblieben und bewahrt worden ist, wird vor Hunger sterben. Und ich vollende meinen Grimm an ihnen*.", footnotes: ["℘ Kap. 5,12.13; 33,27; Jer 24,10; 42,22"] },
      { number: 13, text: "Und ihr werdet erkennen, dass ich der HERR bin, wenn sich ihre Erschlagenen mitten unter ihren Götzen befinden, rings um ihre Altäre her, auf jedem hohen Hügel, auf allen Berggipfeln und unter jedem grünen Baum und unter jeder dicht belaubten Terebinthe, an dem Ort, wo sie allen ihren Götzen* wohlgefälligen Geruch* dargebracht haben*,", footnotes: ["w. Mistkugeln, o. Klötze(n); ein verächtlicher Ausdruck", "w. Geruch der Befriedigung o. der Beschwichtigung", "℘ Kap. 20,28; 23,41; 1Kö 14,23; Jes 57,5-7; Jer 13,27"] },
      { number: 14, text: "und wenn ich meine Hand gegen sie ausstrecke* und das Land zum Entsetzen* und Grausen mache* in all ihren Wohnsitzen* von der Wüste <Juda> an bis nach Ribla*. Und sie werden erkennen, dass ich der HERR bin.", footnotes: ["℘ Jes 5,25", "o. zur Öde und zum", "℘ Kap. 15,8; 33,28", "℘ Kap. 35,9; Jes 24,1.7; Jer 25,11", "so mit mehreren hebr. Handschr.; Mas. T.: von der Wüste Diblata an; o. mehr als die Wüste Diblata\n℘ 4Mo 33,46"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Ankündigung des endgültigen Gerichts mit seinen Schrecken" },
      { number: 2, text: "Und du, Menschensohn<, sage>: So spricht der Herr, HERR, zum Land Israel*: Ein Ende kommt, <es kommt> das Ende über die vier Ecken des Landes*.", footnotes: ["℘ Kap. 21,7", "o. über die vier Zipfel der Erde\n℘ Kla 4,18; Am 8,2; Offb 7,1"] },
      { number: 3, text: "Jetzt <kommt> das Ende über dich, und ich lasse meinen Zorn gegen dich los und richte dich nach deinen Wegen*; und alle deine Gräuel bringe ich über dich*.", footnotes: ["℘ V. 27; Kap. 16,59; 18,30; 24,14; Hos 12,3", "℘ Kap. 9,10; 11,21; 16,43; 22,31"] },
      { number: 4, text: "Ich werde deinetwegen nicht betrübt sein* und werde kein Mitleid haben*; sondern deine Wege will ich über dich bringen, und deine Gräuel sollen sich in deiner Mitte auswirken*. Und ihr werdet erkennen, dass ich der HERR bin.", footnotes: ["w. Und mein Auge wird über dich nicht fließen (d. h. weinen)", "℘ Kap. 5,11; Jer 13,14", "℘ Kap. 33,29"] },
      { number: 5, text: "So spricht der Herr, HERR: Unheil über Unheil, siehe, es kommt!*", footnotes: ["℘ Spr 13,21; Jer 19,3"] },
      { number: 6, text: "Ein Ende kommt; es kommt das Ende, es erwacht gegen dich; siehe, es kommt!*", footnotes: ["℘ Kla 4,18; Am 8,2; Offb 7,1"] },
      { number: 7, text: "Es kommt die Wende über dich*, Bewohner des Landes. Es kommt die Zeit, nahe ist der Tag*: Bestürzung und nicht Jauchzen auf den Bergen*!", footnotes: ["o. Jetzt kommt die Reihe an dich", "℘ Kap. 12,23; 30,3; Joe 1,15", "w. Jauchzen der Berge; das Wort meint den Jubelruf der Kelterer in den Weinbergen; vgl. Jes 16,10; Jer 25,30. Das Wort »Jauchzen« wurde durch Hinzufügung zweier Buchstaben gewonnen; das im Mas. T. stehende Wort konnte bisher nicht gedeutet werden.\n℘ Jes 16,10; Zef 1,14-16"] },
      { number: 8, text: "Jetzt werde ich bald meinen Grimm über dich ausgießen* und vollende meinen Zorn an dir und richte dich nach deinen Wegen*; und alle deine Gräuel bringe ich über dich*.", footnotes: ["℘ Kap. 20,8.13.21", "℘ Kap. 9,10; 11,21; 16,43; 22,31", "℘ Kap. 9,10; 11,21; 16,43; 22,31"] },
      { number: 9, text: "Und ich werde <deinetwegen> nicht betrübt sein* und werde kein Mitleid haben*. Nach deinen Wegen werde ich es über dich bringen, und deine Gräuel sollen sich in deiner Mitte auswirken. Und ihr werdet erkennen, dass ich, der HERR, einer bin, der schlägt*.", footnotes: ["w. mein Auge wird nicht fließen (d. h. weinen)", "℘ Kap. 5,11; Jer 13,14", "℘ Kap. 22,22; Jer 36,31; Mi 6,9"] },
      { number: 10, text: "Siehe, der Tag!* Siehe, er kommt! Die Wende kommt hervor. Es blüht die Rute*, es sprosst der Übermut;", footnotes: ["℘ Kap. 12,23; 30,3; Joe 1,15", "d. h. die Zuchtrute; w. der Stab; bei anderer Vokalisierung: Beugung <des Rechts>"] },
      { number: 11, text: "die Gewalttat erhebt sich zur Rute* der Gottlosigkeit. Nichts von ihnen <wird bleiben>, nichts von ihrem Prunk und nichts von ihrem Lärmen und nichts Herrliches an ihnen*.", footnotes: ["o. zum <Herrscher>stab", "℘ Jer 7,34"] },
      { number: 12, text: "Die Zeit kommt, der Tag trifft ein*. Der Käufer freue sich nicht, und der Verkäufer sei nicht traurig! Denn Zornglut <kommt> über seinen* ganzen Prunk*.", footnotes: ["℘ Kap. 12,23; 30,3; Joe 1,15", "Gemeint ist Israel.", "℘ Jes 24,1-3; Jer 7,20"] },
      { number: 13, text: "Denn der Verkäufer wird nicht zum Verkauften* zurückkehren*, auch wenn er noch am Leben ist*; denn die Zornglut* gegen all ihren Prunk wird sich nicht wenden. Und wegen seiner Schuld wird niemand sein Leben festhalten können*.", footnotes: ["T.; Mas. T.: Und ein Mensch, in seiner Schuld ist sein Leben, sie werden nicht erstarken", "℘ 3Mo 25,13", "w. auch wenn ihr Leben noch unter den Lebenden ist", "T.; Mas. T.: die Vision", "T.; Mas. T.: die Vision\n℘ Kap. 12,25.28"] },
      { number: 14, text: "Man stößt ins Horn und macht alles bereit, aber niemand zieht in den Kampf; denn meine Zornglut <kommt> über seinen* ganzen Prunk*.", footnotes: ["Gemeint ist Israel.", "℘ Jes 24,1-3; Jer 7,20"] },
      { number: 15, text: "Das Schwert ist draußen und die Pest und der Hunger drinnen. Wer auf dem Feld ist, wird durchs Schwert sterben; und wer in der Stadt ist, den werden Hunger und Pest fressen*.", footnotes: ["℘ Kap. 5,12; 5Mo 32,25; Kla 1,20; 4,9"] },
      { number: 16, text: "Und wenn Entkommene von ihnen entkommen, *dann werden sie auf den Bergen sein wie Tauben der Täler; sie alle stöhnen*, jeder wegen seiner Schuld*.", footnotes: ["Manche nehmen an, der Text habe ursprünglich gelautet: und wenn sie — girrenden Tauben gleich — auf den Bergen sind, so sollen sie <doch> alle sterben", "Manche nehmen an, der Text habe ursprünglich gelautet: und wenn sie — girrenden Tauben gleich — auf den Bergen sind, so sollen sie <doch> alle sterben", "℘ Jes 59,11.12; Jer 3,21; Sach 12,14"] },
      { number: 17, text: "Alle Hände werden erschlaffen, und alle Knie werden von Wasser triefen*.", footnotes: ["℘ Kap. 21,12; Jer 6,24"] },
      { number: 18, text: "Und sie werden sich Sacktuch umgürten, und Schauder wird sie bedecken*; auf allen Gesichtern wird Beschämung sein und auf all ihren Häuptern Kahlheit*.", footnotes: ["℘ Jer 6,25.26", "℘ Jes 15,2"] },
      { number: 19, text: "Ihr Silber werden sie auf die Gassen werfen, und ihr Gold wird als Unflat* gelten; ihr Silber und ihr Gold wird sie nicht retten können am Tag des Grimms des HERRN*. Ihre Gier* werden sie <damit> nicht sättigen und ihren Bauch <davon> nicht füllen. Denn es ist ein Anstoß zu ihrer Schuld geworden*.", footnotes: ["o. Befleckung", "℘ Zef 1,18", "o. Seele", "℘ Kap. 14,3.4.7"] },
      { number: 20, text: "Und die Zierde seines Schmuckes*, zum Hochmut hat man sie gebraucht, und ihre Gräuelbilder, ihre Scheusale, haben sie daraus verfertigt*; darum habe ich es ihnen zum Unflat gemacht*.", footnotes: ["d. h. des Silbers", "℘ Kap. 16,16.17; Ri 8,24-27", "℘ Jes 30,22"] },
      { number: 21, text: "Und ich gebe es in die Hand der Fremden zur Plünderung hin und den Gottlosen der Erde zur Beute, dass sie es entweihen." },
      { number: 22, text: "Und ich werde mein Angesicht von ihnen abwenden, dass sie mein Kleinod* entweihen; und Räuber werden in es eindringen und es entweihen*.", footnotes: ["w. mein Verborgenes; d. i. das Heiligtum", "℘ Kap. 24,21"] },
      { number: 23, text: "Verfertige die Kette! Denn* das Land ist voller Blutschuld und die Stadt voller Gewalttat*.", footnotes: ["Andere nehmen einen Schreibfehler im Mas. T. an und üs.: Sie veranstalten ein Gemetzel; ja,", "℘ Kap. 8,16.17; 9,9; 12,19"] },
      { number: 24, text: "Und ich lasse die schlimmsten der Nationen kommen*, dass sie ihre Häuser in Besitz nehmen*. Und ich mache dem Hochmut ihrer Stärke* ein Ende*, dass ihre Heiligtümer entweiht werden*.", footnotes: ["℘ Kap. 21,36", "℘ Jer 6,12; 17,4; Kla 5,2", "so mit mehreren alten Üs.; Mas. T.: dem Hochmut der Starken", "℘ Kap. 33,28", "℘ Ps 74,7; Zef 1,13"] },
      { number: 25, text: "Schrecken kommt; und sie suchen Frieden, doch da ist keiner*.", footnotes: ["℘ Jer 8,15"] },
      { number: 26, text: "Unheil über Unheil kommt, und Nachricht über Nachricht trifft ein. Und man sucht vom Propheten Visionen*; aber Weisung* geht dem Priester verloren und Rat den Ältesten.", footnotes: ["℘ Kla 2,9; Mi 3,6.7", "o. Gesetz"] },
      { number: 27, text: "Der König wird trauern, und der Fürst wird sich in Entsetzen kleiden, und die Hände des Volkes des Landes werden zittern. Nach ihren Wegen will ich mit ihnen handeln, und mit ihren <eigenen> Rechtsbestimmungen will ich sie richten*, und sie werden erkennen, dass ich der HERR bin.", footnotes: ["℘ V. 3.8; Kap. 14,23"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und es geschah im sechsten Jahr, im sechsten <Monat>, am Fünften des Monats*: Ich saß in meinem Haus, und die Ältesten von Juda saßen vor mir*, und dort fiel die Hand des Herrn, HERRN, auf mich*.", heading: "Vision Hesekiels: Versetzung nach Jerusalem — Gräuel des Götzendienstes im Tempel und im Land", footnotes: ["℘ Kap. 1,2; 24,1; 26,1; 29,1; 30,20; 31,1; 32,1", "℘ Kap. 14,1; 20,1; 2Kö 6,32", "℘ Kap. 1,3; 37,1"] },
      { number: 2, text: "Und ich sah: und siehe, eine Gestalt mit dem Aussehen eines Mannes*: von seinen Hüften an* abwärts Feuer; und von seinen Hüften an aufwärts wie das Aussehen eines Glanzes, wie das Funkeln von glänzendem Metall*.", footnotes: ["so mit LXX und der alten lat. Üs.; Mas. T.: wie das Aussehen von Feuer", "w. von dem Aussehen seiner Hüften an", "℘ Kap. 1,26.27; 40,3; Dan 10,6"] },
      { number: 3, text: "Und er streckte *etwas wie eine Hand* aus und nahm mich beim Haarschopf meines Kopfes. Und der Geist hob mich zwischen Erde und Himmel empor* und brachte mich in Gotteserscheinungen* nach Jerusalem, an den Eingang des Tores des inneren <Vorhofs>, das nach Norden weist*, wo der Standort des Götzenbildes der Eifersucht war, das zur Eifersucht reizt*.", footnotes: ["w. das Gebilde einer Hand", "w. das Gebilde einer Hand", "℘ Kap. 2,9; 3,14", "℘ Kap. 1,1; 11,24; 40,2", "℘ Kap. 9,2", "℘ 5Mo 32,21; Jer 7,30"] },
      { number: 4, text: "Und siehe, dort war die Herrlichkeit des Gottes Israels, wie die Erscheinung, die ich im Tal gesehen hatte*.", footnotes: ["℘ Kap. 1,28; 3,22.23; 43,3"] },
      { number: 5, text: "Und er sprach zu mir: Menschensohn, erhebe doch deine Augen nach Norden! Da erhob ich meine Augen nach Norden, und siehe, nördlich vom Tor war ein Altar, das Götzenbild der Eifersucht selbst <stand> am Eingang." },
      { number: 6, text: "Und er sprach zu mir: Menschensohn, siehst du, was sie tun? Große Gräuel sind es, die das Haus Israel hier verübt, damit ich mich von meinem Heiligtum entferne*. Aber du sollst noch größere Gräuel sehen*.", footnotes: ["o. indem sie sich von meinem Heiligtum fern halten\n℘ Kap. 10,18; 11,23; 2Chr 29,5", "℘ Kap. 43,8"] },
      { number: 7, text: "Und er brachte mich an den Eingang des Vorhofs; und ich sah: und siehe, ein Loch war in der Wand." },
      { number: 8, text: "Und er sprach zu mir: Menschensohn, durchbrich doch die Wand! Da durchbrach ich die Wand; und siehe, da war eine Tür." },
      { number: 9, text: "Und er sprach zu mir: Geh hinein und sieh die schlimmen Gräuel, die sie hier verüben!" },
      { number: 10, text: "Und ich ging hinein und sah, und siehe, da waren allerlei Abbilder von Kriechtieren und Vieh: Abscheuliches und allerlei Götzen des Hauses Israel ringsherum auf der Wand als Ritzzeichnung <zu sehen>*.", footnotes: ["℘ 5Mo 4,16; Röm 1,23"] },
      { number: 11, text: "Und siebzig Männer* von den Ältesten des Hauses Israel standen davor, und Jaasanja, der Sohn Schafans*, stand mitten unter ihnen; und jeder hatte seine Räucherpfanne in seiner Hand; und der Duft einer Weihrauchwolke stieg empor*.", footnotes: ["℘ Kap. 9,6; 2Mo 24,1", "℘ Jer 26,24", "℘ Jer 19,4"] },
      { number: 12, text: "Und er sprach zu mir: Hast du gesehen, Menschensohn, was die Ältesten des Hauses Israel im Finstern tun*, jeder in seinen Bilderkammern? Denn sie sagen: »Der HERR sieht uns nicht, der HERR hat das Land verlassen*.«", footnotes: ["℘ 5Mo 27,15; 2Kö 17,9; Jes 29,15; Joh 3,20", "℘ Kap. 9,9; Hi 24,15; Jes 47,10"] },
      { number: 13, text: "Und er sprach zu mir: Du sollst noch größere Gräuel sehen, die sie verüben*. —", footnotes: ["℘ 2Tim 3,13"] },
      { number: 14, text: "Und er brachte mich an den Eingang des Tores am Haus des HERRN, das nach Norden <weist>; und siehe, dort saßen Frauen, die den Tammus* beweinten.", footnotes: ["Diese Gottheit stellte in der babylonischen Mythologie die absterbende und wiederauflebende Vegetation dar."] },
      { number: 15, text: "Und er sprach zu mir: Hast du gesehen, Menschensohn? Du sollst noch mehr, <noch> größere Gräuel sehen als diese*. —", footnotes: ["℘ Kap. 5,11"] },
      { number: 16, text: "Und er brachte mich in den inneren Vorhof des Hauses des HERRN; und siehe, am Eingang des Tempels des HERRN, zwischen der Vorhalle und dem Altar*, <standen> etwa 25 Männer, ihre Rücken gegen den Tempel des HERRN und ihre Gesichter nach Osten <gerichtet>*; und sie warfen sich nach Osten hin anbetend vor der Sonne nieder*.", footnotes: ["℘ Joe 2,17", "℘ 2Chr 29,6", "℘ 5Mo 4,19; 2Kö 21,5; 23,11.12; Hi 31,27; Jer 7,18; 8,2"] },
      { number: 17, text: "Und er sprach zu mir: Hast du gesehen, Menschensohn? Ist es dem Haus Juda zu wenig, die Gräuel zu verüben, die sie hier verüben — denn sie haben das Land mit Gewalttat erfüllt* —, dass sie mich immer wieder reizen? Denn siehe, sie halten die Ranke an meine* Nase.", footnotes: ["℘ Kap. 7,23", "so der ursprüngliche Text; Mas. T.: ihre <eigene>"] },
      { number: 18, text: "So will auch ich handeln im Grimm, ich werde <ihretwegen> nicht betrübt sein* und werde kein Mitleid haben*. Und rufen sie auch vor meinen Ohren mit lauter Stimme, so werde ich sie doch nicht erhören*.", footnotes: ["w. mein Auge wird nicht fließen (d. h. weinen)", "℘ Kap. 5,11", "℘ 1Sam 8,18"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und er rief vor meinen Ohren mit lauter Stimme und sprach: Nahegekommen sind die Heimsuchungen der Stadt. Jeder habe sein Werkzeug der Zerstörung in seiner Hand*!", heading: "Schonung der Frommen und Tötung der Gottlosen in Jerusalem — Hesekiels vergebliche Fürbitte", footnotes: ["℘ Jer 4,6; Mi 4,14"] },
      { number: 2, text: "Und siehe, sechs Männer kamen aus der Richtung vom oberen Tor, das nach Norden gewandt ist*, jeder mit seinem Werkzeug zum Zerschlagen in seiner Hand*; und ein Mann war in ihrer Mitte, mit Leinen bekleidet*, mit dem Schreibzeug eines Schreibers an seiner Hüfte; und sie kamen und stellten sich neben den bronzenen Altar*.", footnotes: ["℘ Kap. 8,3", "℘ Jer 4,6; Mi 4,14", "℘ Kap. 10,2.6.7; Offb 15,6", "℘ Am 9,1"] },
      { number: 3, text: "Und die Herrlichkeit des Gottes Israels erhob sich von dem Cherub, über dem sie war, zu der Schwelle des Hauses hin*. Und er rief dem mit Leinen bekleideten Mann zu, der das Schreibzeug eines Schreibers an seiner Hüfte hatte,", footnotes: ["℘ Kap. 10,4.19; 11,22"] },
      { number: 4, text: "und der HERR sprach zu ihm: Geh mitten durch die Stadt, mitten durch Jerusalem, und zeichne ein Kennzeichen an die Stirnen der Männer*, die seufzen und stöhnen über all die Gräuel, die in ihrer Mitte geschehen*!", footnotes: ["℘ Offb 7,2.3", "℘ Kap. 6,11; Ps 119,136; 2Petr 2,8"] },
      { number: 5, text: "Und zu jenen sprach er vor meinen Ohren: Geht hinter ihm her durch die Stadt, und schlagt zu; ihr sollt <ihretwegen> nicht betrübt sein* und sollt kein Mitleid haben*!", footnotes: ["w. euer Auge soll nicht fließen (d. h. weinen)", "℘ 2Mo 32,27"] },
      { number: 6, text: "Greise, junge Männer und Jungfrauen, Kinder und Frauen erschlagt* <bis> zur <vollständigen> Vernichtung, aber niemandem, an dem das Kennzeichen ist, dürft ihr euch nähern*! Bei meinem Heiligtum sollt ihr anfangen*! Da fingen sie bei den Männern an, <nämlich bei> den Ältesten, die vor dem Haus* waren*.", footnotes: ["℘ 5Mo 32,23.25; 2Chr 36,17; Jer 6,11", "℘ 2Mo 12,23; Offb 9,4", "℘ Jer 25,29; 1Petr 4,17", "Gemeint ist der Tempel.", "℘ Kap. 8,11.16"] },
      { number: 7, text: "Und er sprach zu ihnen: Macht das Haus* unrein und füllt die Vorhöfe mit Erschlagenen*; geht hinaus! Und sie gingen hinaus und erschlugen in der Stadt.", footnotes: ["Gemeint ist der Tempel.", "℘ Kla 2,20"] },
      { number: 8, text: "Und es geschah, als sie erschlugen und ich <allein> übrig blieb, da fiel ich nieder auf mein Gesicht* und schrie und sagte: Ach, Herr, HERR! Willst du den ganzen Rest Israels vernichten*, indem du deinen Grimm über Jerusalem ausgießt?", footnotes: ["℘ 4Mo 16,4; 1Chr 21,16", "℘ Kap. 11,13; Am 7,5"] },
      { number: 9, text: "Da sprach er zu mir: Die Schuld des Hauses Israel und Juda ist über die Maßen groß*, und das Land ist mit Gewalttat erfüllt*, und die Stadt ist voller Beugung <des Rechts>*. Denn sie sagen: Der HERR hat das Land verlassen, und der HERR sieht <uns> nicht*.", footnotes: ["℘ Jer 5,1-11", "℘ Kap. 7,23; Jes 59,3-7", "℘ Jes 59,3", "℘ Kap. 8,12; Ps 10,11"] },
      { number: 10, text: "So auch ich — ich werde nicht betrübt sein* und werde kein Mitleid haben*; ihren Weg bringe ich auf ihren Kopf*.", footnotes: ["w. mein Auge wird nicht fließen (d. h. weinen)", "℘ Kap. 5,11; Sach 11,6", "℘ Kap. 7,3.4; 16,43; 17,19; 22,31; 43,3; 1Kö 8,32"] },
      { number: 11, text: "Und siehe, der mit Leinen bekleidete Mann, der das Schreibzeug an seiner Hüfte hatte, brachte Antwort und sprach: Ich habe getan, wie du mir befohlen hast." },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und ich sah: Und siehe, auf dem festen Gewölbe, das über dem Haupt der Cherubim war, <befand sich> einem Saphirstein gleich etwas, das aussah wie ein Thron, der über ihnen sichtbar wurde.", heading: "Befehl zur Verbrennung Jerusalems — Die Herrlichkeit des HERRN erscheint im Tempel und verlässt das Heiligtum", footnotes: ["℘ Kap. 1,1-28"] },
      { number: 2, text: "Und er sprach zu dem mit Leinen bekleideten Mann*, und er sagte: Geh hinein zu <der Stelle> zwischen dem Räderwerk, zu <der Stelle> unterhalb des Cherubs, und fülle deine Hände mit Feuerkohlen von <der Stelle> zwischen den Cherubim, und streue sie über die Stadt hin*! Da ging er vor meinen Augen hinein.", footnotes: ["℘ Kap. 9,2", "℘ 2Kö 25,9; Offb 8,5"] },
      { number: 3, text: "Die Cherubim* aber standen zur rechten Seite des Hauses, als der Mann hineinging; und die Wolke erfüllte den inneren Vorhof.", footnotes: ["℘ 2Mo 25,18"] },
      { number: 4, text: "Da erhob sich die Herrlichkeit des HERRN von dem Cherub weg auf die Schwelle des Hauses*; und das Haus wurde von der Wolke erfüllt, und der Vorhof war voll von dem Glanz der Herrlichkeit des HERRN*.", footnotes: ["℘ Kap. 9,3", "℘ Kap. 43,5; 44,4; 1Kö 8,10.11"] },
      { number: 5, text: "Und das Rauschen der Flügel der Cherubim wurde bis zum äußeren Vorhof gehört wie die Stimme Gottes, des Allmächtigen, wenn er redet." },
      { number: 6, text: "Und es geschah, als er dem mit Leinen bekleideten Mann befahl: Nimm Feuer von <der Stelle> zwischen dem Räderwerk, von <der Stelle> zwischen den Cherubim weg!, da ging er hinein und trat neben das Rad." },
      { number: 7, text: "Und der Cherub streckte seine Hand aus zwischen den Cherubim hervor nach dem Feuer, das zwischen den Cherubim war, und hob es auf und gab es in die Hände dessen, der mit Leinen bekleidet war; der nahm es und ging hinaus." },
      { number: 8, text: "Und es erschien an den Cherubim unter ihren Flügeln etwas wie eine Menschenhand." },
      { number: 9, text: "Und ich sah: Und siehe, vier Räder* waren neben den Cherubim, je ein Rad neben je einem Cherub. Und das Aussehen der Räder war wie das Funkeln eines Türkis-Steines;", footnotes: ["℘ 1Kö 7,30"] },
      { number: 10, text: "und ihr Aussehen: Die vier hatten ein und dieselbe Gestalt, wie wenn ein Rad mitten im <anderen> Rad wäre." },
      { number: 11, text: "Wenn sie gingen, <dann> gingen sie nach ihren vier Seiten hin: sie wandten sich nicht um, wenn sie gingen; denn an den Ort, wohin das Vorderste sich wandte, folgten sie ihm; sie wandten sich nicht um, wenn sie gingen." },
      { number: 12, text: "Und ihr ganzer Leib und ihr Rücken und ihre Hände und ihre Flügel und die Räder waren voller Augen ringsum* bei <allen> vieren, <nämlich> ihren Rädern.", footnotes: ["℘ Offb 4,8"] },
      { number: 13, text: "Die Räder, sie wurden vor meinen Ohren »Galgal*« genannt.", footnotes: ["d. h. Räderwerk; vgl. V. 2.6"] },
      { number: 14, text: "Vier Gesichter hatte jedes. Das Gesicht des Ersten war das Gesicht eines Cherubs, und das Gesicht des Zweiten war das Gesicht eines Menschen und des Dritten das Gesicht eines Löwen und des Vierten das Gesicht eines Adlers." },
      { number: 15, text: "Und die Cherubim hoben sich empor. Das war das lebende Wesen, das ich am Fluss Kebar gesehen hatte." },
      { number: 16, text: "Und wenn die Cherubim gingen, <dann> gingen die Räder neben ihnen; und wenn die Cherubim ihre Flügel erhoben, um sich von der Erde emporzuheben, so wandten sich auch sie, die Räder, nicht von ihrer Seite." },
      { number: 17, text: "Wenn sie stehen blieben, blieben <auch> die Räder* stehen; und wenn sie sich emporhoben, hoben sich die Räder* mit ihnen empor. Denn der Geist des lebenden Wesens war in ihnen.", footnotes: ["w. sie", "w. sie"] },
      { number: 18, text: "Und die Herrlichkeit des HERRN verließ die Schwelle des Hauses und stellte sich über die Cherubim*.", footnotes: ["℘ Kap. 8,6; 28,14; Ps 18,11; 99,1"] },
      { number: 19, text: "Und die Cherubim erhoben ihre Flügel und hoben sich vor meinen Augen von der Erde empor, als sie hinauszogen; und die Räder <erhoben sich> gleichzeitig mit ihnen. Und sie stellte sich* an den Eingang des östlichen Tores* des Hauses des HERRN, und die Herrlichkeit des Gottes Israels war oben über ihnen.", footnotes: ["d. i. die Herrlichkeit des HERRN; LXX: sie stellten sich; womit die Cherubim gemeint sind", "℘ Kap. 11,1; 43,1"] },
      { number: 20, text: "Das war das lebende Wesen, das ich unter dem Gott Israels am Fluss Kebar gesehen hatte; und ich erkannte, dass es Cherubim waren." },
      { number: 21, text: "Jeder hatte vier Gesichter, und jeder hatte vier Flügel, und etwas wie Menschenhände war unter ihren Flügeln." },
      { number: 22, text: "Und die Gestalt ihrer Gesichter war die jener Gesichter, die ich am Fluss Kebar gesehen hatte*, ihr Aussehen und sie selbst. Sie gingen ein jeder gerade vor sich hin.", footnotes: ["℘ Kap. 43,3"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und der Geist hob mich empor* und brachte mich zum östlichen Tor des Hauses des HERRN, das nach Osten weist*. Und siehe, am Eingang des Tores waren 25 Männer; und ich sah in ihrer Mitte Jaasanja, den Sohn Asurs, und Pelatja, den Sohn Benajas, die Obersten des Volkes.", heading: "Den Heilssicheren in Jerusalem kündigt Gott das Exil an, den Verschleppten die Rückkehr", footnotes: ["℘ V. 24; Kap. 3,12.14", "℘ Kap. 10,19; 40,6"] },
      { number: 2, text: "Und er sprach zu mir: Menschensohn, das sind die Männer, die Unheil ersinnen und bösen Rat erteilen in dieser Stadt*,", footnotes: ["℘ Ps 36,5"] },
      { number: 3, text: "die sagen: »Es ist nicht an der Zeit*, Häuser zu bauen; sie ist der Topf, und wir sind das Fleisch*.«", footnotes: ["w. <die Zeit> ist nicht nahe", "℘ Kap. 24,3-5"] },
      { number: 4, text: "Darum weissage über sie! Weissage, Menschensohn*! —", footnotes: ["℘ Kap. 3,4"] },
      { number: 5, text: "Und der Geist des HERRN fiel auf mich* und sprach zu mir: Sage: So spricht der HERR: So redet ihr, Haus Israel; und was in eurem Geist aufsteigt, ich kenne es*.", footnotes: ["℘ Kap. 2,2", "℘ 1Chr 28,9; Ps 139,2; Hebr 4,13"] },
      { number: 6, text: "Ihr habt eure Erschlagenen zahlreich gemacht in dieser Stadt und ihre Straßen mit Erschlagenen gefüllt*.", footnotes: ["℘ Kla 4,13"] },
      { number: 7, text: "Darum, so spricht der Herr, HERR: Eure Erschlagenen, die ihr in ihrer Mitte hingestreckt habt, die sind das Fleisch, und sie ist der Topf*; euch aber werde ich* aus ihrer Mitte hinausführen.", footnotes: ["℘ Kap. 24,6; Jer 1,13", "so mit vielen hebr. Handschr. und alten Üs.; Mas. T.: wird er"] },
      { number: 8, text: "Ihr fürchtet das Schwert! So werde ich das Schwert über euch bringen*, spricht der Herr, HERR*.", footnotes: ["℘ Spr 10,24; Jer 42,16.17", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 9, text: "Und ich führe euch aus ihrer Mitte hinaus und gebe euch in die Hand von Fremden* und übe Strafgerichte an euch*.", footnotes: ["℘ 5Mo 28,36; Esr 9,7", "℘ Kap. 5,8.15"] },
      { number: 10, text: "Durch das Schwert sollt ihr fallen; an der Grenze Israels werde ich euch richten*. Und ihr werdet erkennen, dass ich der HERR bin.", footnotes: ["℘ Jer 52,10"] },
      { number: 11, text: "Sie wird euch nicht zum Topf werden, so dass ihr in ihrer Mitte zum Fleisch würdet; <sondern> an der Grenze Israels werde ich euch richten." },
      { number: 12, text: "Und ihr werdet erkennen, dass ich der HERR bin, ich, in dessen Ordnungen ihr nicht gelebt* und dessen Rechtsbestimmungen ihr nicht befolgt habt*; sondern ihr habt nach den Rechtsbestimmungen der Nationen gehandelt, die rings um euch her sind*. —", footnotes: ["w. gegangen seid", "℘ Kap. 5,6; 2Kö 18,12; Neh 9,33.34", "℘ 5Mo 12,30; 2Kö 21,2.9"] },
      { number: 13, text: "Und es geschah, als ich weissagte, da starb Pelatja, der Sohn Benajas*. Und ich fiel nieder auf mein Gesicht und schrie mit lauter Stimme und sprach: Ach, Herr, HERR, willst du mit dem Rest Israels ein Ende machen?*", footnotes: ["℘ Spr 6,15", "so in Entsprechung zu Kap. 9,8; Mas. T.: du machst ja dem Rest Israels ein Ende.\n℘ Kap. 9,8"] },
      { number: 14, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 15, text: "Menschensohn, deine Brüder, deine Brüder, die Männer deiner Verwandtschaft, <sind es> und das ganze Haus Israel insgesamt, zu denen die Bewohner von Jerusalem sagen: Sie sind fern* von dem HERRN; uns ist dieses Land zum Besitz gegeben*!", footnotes: ["o. mit anderer Vokalisierung: Bleibt fern", "℘ Kap. 33,24"] },
      { number: 16, text: "Darum sage: So spricht der Herr, HERR: Ja, ich habe sie fern unter den Nationen sein lassen, ja, ich habe sie in die Länder zerstreut* und bin ihnen <nur> wenig zum Heiligtum geworden* in den Ländern, wohin sie gekommen sind.", footnotes: ["℘ Kap. 20,23; 5Mo 4,27", "o. doch bin ich ihnen ein wenig zum Heiligtum geworden"] },
      { number: 17, text: "Darum sage: So spricht der Herr, HERR: Ich werde euch aus den Völkern sammeln und euch aus den Ländern zusammenbringen, in die ihr zerstreut worden seid*, und werde euch das Land Israel geben*.", footnotes: ["℘ Kap. 20,34.41; Sach 8,7", "℘ Kap. 28,25; 34,13; 5Mo 30,3-5; Jes 60,21; Jer 29,10"] },
      { number: 18, text: "Und sie werden dorthin kommen und alle seine Scheusale und alle seine Gräuel daraus entfernen*.", footnotes: ["℘ Kap. 37,23; Hos 14,9"] },
      { number: 19, text: "Und ich werde ihnen ein Herz* geben* und werde einen neuen Geist in ihr* Inneres geben*, und ich werde das steinerne Herz aus ihrem Fleisch entfernen und ihnen ein fleischernes Herz geben*,", footnotes: ["3 hebr. Handschr. lesen: ein neues Herz", "℘ Kap. 18,31; Jer 31,33; 32,39", "so mit LXX, der syr., aram. Üs. und Vulg.; Mas. T.: in euer", "℘ Kap. 36,26-28; 2Kor 3,3", "℘ Jer 4,6; Mi 4,14"] },
      { number: 20, text: "damit sie in meinen Ordnungen leben* und meine Rechtsbestimmungen bewahren und sie befolgen*. Und sie werden mir zum Volk, und ich werde ihnen zum Gott sein*.", footnotes: ["w. gehen", "℘ 5Mo 30,6-8", "℘ Kap. 14,11; 37,23.27; 1Mo 17,8; Jer 24,5-7; 30,22; 32,39"] },
      { number: 21, text: "Jene aber — ihr Herz folgt ihren Scheusalen und ihren Gräueln nach* —, ihren Weg bringe ich auf ihren Kopf*, spricht der Herr, HERR*.", footnotes: ["w. dem Herzen ihrer Scheusale . . . folgt ihr Herz nach\n℘ Kap. 14,3", "℘ Kap. 7,3.8", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 22, text: "Und die Cherubim erhoben ihre Flügel, und die Räder <bewegten sich> gleichzeitig mit ihnen; und die Herrlichkeit des Gottes Israels war oben über ihnen*.", heading: "Die Herrlichkeit des HERRN verlässt Jerusalem — Rückkehr des Propheten nach Babylon", footnotes: ["℘ Kap. 9,3"] },
      { number: 23, text: "Und die Herrlichkeit des HERRN stieg auf, mitten aus der Stadt hinweg, und stellte sich auf den Berg, der im Osten der Stadt ist*.", footnotes: ["℘ Kap. 8,6; 43,2; Sach 14,4; Apg 1,12"] },
      { number: 24, text: "Und der Geist hob mich empor* und brachte mich in der Erscheinung durch den Geist Gottes* zu den Weggeführten nach Chaldäa; und die Erscheinung, die ich gesehen hatte, hob sich von mir weg.", footnotes: ["℘ V. 1; Kap. 37,1", "℘ Kap. 8,3"] },
      { number: 25, text: "Und ich redete zu den Weggeführten alle Worte des HERRN, die er mich hatte sehen lassen*.", footnotes: ["℘ Kap. 3,4"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Zwei Zeichenhandlungen: das Gericht der Verschleppung und die Verzweiflung der Belagerten" },
      { number: 2, text: "Menschensohn, du wohnst mitten in dem widerspenstigen Haus*, <bei solchen,> die Augen haben zu sehen und <doch> nicht sehen*, die Ohren haben zu hören und <doch> nicht hören*; denn ein widerspenstiges Haus* sind sie.", footnotes: ["s. Anm. zu Kap. 2,5\n℘ Kap. 3,26.27; Jer 7,26", "℘ Röm 11,10", "℘ 5Mo 29,3; Jes 44,18; Jer 5,21; Mk 8,18", "s. Anm. zu Kap. 2,5"] },
      { number: 3, text: "Und du, Menschensohn, mach dir Gepäck zur Verbannung <zurecht>* und zieh bei Tage vor ihren Augen in die Verbannung aus! Und du sollst vor ihren Augen von deinem Ort zu einem anderen Ort in die Verbannung ausziehen!* Vielleicht sehen sie es*; denn ein widerspenstiges Haus* sind sie*.", footnotes: ["℘ Jer 27,2", "℘ Kap. 4,1.2; Jer 10,17", "℘ Jer 26,3; 2Tim 2,25", "s. Anm. zu Kap. 2,5", "℘ Kap. 3,26.27; Jer 7,26"] },
      { number: 4, text: "Und trage dein Gepäck wie Gepäck zur Verbannung bei Tage vor ihren Augen hinaus! Und du, ziehe am Abend vor ihren Augen aus, wie man auszieht, um in die Verbannung zu gehen*!", footnotes: ["w. wie Auszüge Verbannter"] },
      { number: 5, text: "Vor ihren Augen durchbrich dir die Mauer, und trage <dein Gepäck> dadurch hinaus!" },
      { number: 6, text: "Vor ihren Augen nimm es auf die Schulter, in Finsternis trage es hinaus! Du sollst dein Gesicht verhüllen, damit du das Land nicht siehst! Denn zu einem Wahrzeichen habe ich dich für das Haus Israel gemacht*. —", footnotes: ["℘ Kap. 4,3; Sach 3,8"] },
      { number: 7, text: "Da tat ich so, wie mir befohlen war. Mein Gepäck trug ich wie Gepäck zur Verbannung bei Tage hinaus, und am Abend durchbrach ich mir die Mauer mit der Hand. In Finsternis trug ich es hinaus, ich nahm es vor ihren Augen auf die Schulter. —" },
      { number: 8, text: "Und das Wort des HERRN geschah zu mir am Morgen:" },
      { number: 9, text: "Menschensohn, hat nicht das Haus Israel, das widerspenstige Haus*, zu dir gesagt: Was tust du*?", footnotes: ["s. Anm. zu Kap. 2,5\n℘ Kap. 17,12", "℘ Kap. 24,19"] },
      { number: 10, text: "Sprich zu ihnen: So spricht der Herr, HERR: Den Fürsten in Jerusalem <betrifft> dieser Ausspruch* und das ganze Haus Israel, in dessen Mitte sie sind*.", footnotes: ["℘ Kap. 21,30", "Andere üs. mit Änderung eines Buchstabens: Israel, das in seiner (Jerusalems) Mitte ist"] },
      { number: 11, text: "Sprich: Ich bin ein Wahrzeichen für euch*. Wie ich getan habe, so soll ihnen getan werden: in die Verbannung*, in die Gefangenschaft werden sie gehen*.", footnotes: ["w. Ich bin euer Wahrzeichen\n℘ Kap. 4,1.2; Jer 10,17", "℘ Kap. 4,1.2; Jer 10,17", "℘ 2Kö 25,7.11; Jer 52,15"] },
      { number: 12, text: "Und der Fürst, der in ihrer Mitte ist, wird <sein Gepäck> in der Finsternis auf die Schulter nehmen und ausziehen. Sie werden die Mauer durchbrechen, um es durch sie hinauszutragen. Er wird sein Gesicht verhüllen, weil er selbst mit <seinen> Augen das Land nicht sehen will*.", footnotes: ["LXX: Er wird sein Gesicht verhüllen, damit er nicht gesehen wird mit dem Auge, und er wird das Land nicht sehen.\n℘ Jer 39,4"] },
      { number: 13, text: "Und ich spanne mein Fangnetz über ihm aus, und in meinem Jagdnetz wird er gefangen*; und ich bringe ihn nach Babel*, ins Land der Chaldäer, aber sehen wird er es nicht; und er wird dort sterben*.", footnotes: ["℘ Kap. 32,3; Hos 7,12", "℘ Kap. 17,20; Jer 39,7; 52,11; Kla 1,13; 4,20", "℘ Kap. 17,16"] },
      { number: 14, text: "Und alle, die um ihn her sind, seine Helfer und alle seine Scharen, will ich in alle Winde zerstreuen*; und hinter ihnen her werde ich das Schwert ziehen*.", footnotes: ["℘ Kap. 5,10", "℘ Kap. 5,2.12; 17,21"] },
      { number: 15, text: "Und sie werden erkennen, dass ich der HERR bin, wenn ich sie unter die Nationen versprenge und sie in die Länder zerstreue*.", footnotes: ["℘ Kap. 5,10"] },
      { number: 16, text: "Und ich werde von ihnen einige Leute übrig lassen vom Schwert, vom Hunger und von der Pest, damit sie alle ihre Gräuel erzählen unter den Nationen, zu denen sie kommen*. Dann werden sie erkennen, dass ich der HERR bin.", footnotes: ["℘ Kap. 6,8-10; Ps 59,12"] },
      { number: 17, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 18, text: "Menschensohn, dein Brot sollst du mit Beben essen und dein Wasser mit Zittern und in Angst trinken*!", footnotes: ["℘ Kap. 4,10.11.16"] },
      { number: 19, text: "Und du sollst zum Volk des Landes sagen: So spricht der Herr, HERR, von den Bewohnern Jerusalems im Land Israel: Ihr Brot werden sie in Angst essen und ihr Wasser mit Entsetzen trinken, weil ihr Land* öde daliegt*, ohne seine Fülle, wegen der Gewalttat all derer, die in ihm wohnen*.", footnotes: ["so mit mehreren hebr. Handschr.; Mas. T.: sein Land; was sich auf Jerusalem beziehen könnte", "℘ Jer 25,11; Mi 7,13; Sach 7,14", "℘ Kap. 7,23; Ps 107,34"] },
      { number: 20, text: "Und die bewohnten Städte werden in Trümmern liegen und das Land wird eine Einöde werden*. Dann werdet ihr erkennen, dass ich der HERR bin.", footnotes: ["℘ 3Mo 26,31"] },
      { number: 21, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Drohworte an die Verächter von Weissagungen", footnotes: ["℘ V. 21-25: Jer 23,33-40"] },
      { number: 22, text: "Menschensohn, was ist das für ein Sprichwort, das ihr im Land Israel habt, indem ihr sagt: »Die Tage ziehen sich in die Länge, und jede Vision geht verloren«?*", footnotes: ["℘ 2Petr 3,4"] },
      { number: 23, text: "Darum sage zu ihnen: So spricht der Herr, HERR: Ich will diesem Sprichwort ein Ende machen, und man soll es nicht mehr als Sprichwort gebrauchen in Israel. Sondern rede zu ihnen: Nahe herbeigekommen sind die Tage und das Wort einer jeden Vision*.", footnotes: ["d. h. das, was jede Vision angesagt hat\n℘ Kap. 7,6.7; Joe 2,1"] },
      { number: 24, text: "Denn es wird nicht länger irgendeine nichtige Vision oder irgendeine schmeichlerische Wahrsagung geben inmitten des Hauses Israel*.", footnotes: ["℘ Kap. 13,23"] },
      { number: 25, text: "Denn ich, der HERR, ich rede; das Wort, das ich rede, wird auch geschehen, es wird sich nicht länger hinziehen*. Denn in euren Tagen, widerspenstiges Haus*, rede ich ein Wort und tue es auch, spricht der Herr, HERR*.", footnotes: ["℘ Kap. 7,13; Jer 1,11.12; Offb 10,6", "s. Anm. zu Kap. 2,5", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 26, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 27, text: "Menschensohn, siehe, das Haus Israel sagt: Die Vision, die der schaut, <geht> auf viel <spätere> Tage <hinaus>; und auf ferne Zeiten hin weissagt er*.", footnotes: ["℘ Am 6,3"] },
      { number: 28, text: "Darum sage zu ihnen: So spricht der Herr, HERR: Es wird sich nicht länger irgendeines meiner Worte hinziehen*; das Wort, das ich rede, wird auch geschehen, spricht der Herr, HERR*.", footnotes: ["℘ Kap. 7,13; Jer 1,11.12; Offb 10,6", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Gottes Gerichtshandeln an den Friedenspropheten" },
      { number: 2, text: "Menschensohn, weissage über die Propheten Israels, die da weissagen, und sage zu denen, <die> aus ihrem <eigenen> Herzen <weissagen>*: Hört das Wort des HERRN!", footnotes: ["℘ V. 17; Jer 14,14"] },
      { number: 3, text: "*So spricht der Herr, HERR: Wehe den törichten* Propheten, die ihrem <eigenen> Geist nachgehen und dem, was sie nicht gesehen haben!", footnotes: ["℘ V. 3-16: Jer 23,9-32", "o. gottlosen"] },
      { number: 4, text: "Wie Füchse in den Trümmerstätten* sind deine Propheten geworden, Israel.", footnotes: ["℘ Kla 5,18"] },
      { number: 5, text: "In die Risse seid ihr nicht getreten*, und die Mauer habt ihr nicht vermauert um das Haus Israel her, um standzuhalten im Kampf am Tag des HERRN*.", footnotes: ["℘ Kap. 22,30", "℘ Zef 2,3"] },
      { number: 6, text: "Sie schauen Nichtiges und Lügenwahrsagung*, die da sagen: »Ausspruch des HERRN«, obwohl der HERR sie nicht gesandt hat; und <dabei> erwarten sie, dass er <ihr> Wort eintreffen lässt*.", footnotes: ["℘ Kap. 22,28; Jer 5,31", "℘ 1Kö 22,12.15; Jer 28,1-4.15; Mt 24,5"] },
      { number: 7, text: "Habt ihr <da> nicht ein nichtiges Gesicht geschaut, und habt ihr nicht Lügenwahrsagung gesprochen, als ihr sagtet: »Ausspruch des HERRN«, wo ich doch nicht geredet habe?*", footnotes: ["℘ Neh 6,12; Sach 10,2"] },
      { number: 8, text: "Darum, so spricht der Herr, HERR: Weil ihr Nichtiges redet und Lüge schaut, darum, siehe, will ich an euch, ist der Ausspruch des Herrn, HERRN." },
      { number: 9, text: "Und ich werde meine Hand gegen die Propheten ausstrecken*, die Nichtiges schauen und Lüge wahrsagen. Im Kreis meines Volkes sollen sie nicht sein, und im Verzeichnis des Hauses Israel werden sie nicht aufgeschrieben sein*, und in das Land Israel werden sie nicht kommen*. Und ihr werdet erkennen, dass ich der Herr, HERR, bin.", footnotes: ["so mit LXX; Mas. T.: Und meine Hand wird gegen die Propheten sein", "℘ Kap. 14,9; Ps 101,7.8", "℘ Kap. 20,38; Ps 95,11; Hos 4,5; Mi 3,5.6"] },
      { number: 10, text: "Deshalb, ja deshalb, weil sie mein Volk irreführen und sagen: Friede!, obwohl kein Friede da ist* — und baut es eine Wand, siehe, sie bestreichen sie mit Tünche* —,", footnotes: ["℘ Jer 6,14", "℘ Kap. 22,28; Jer 5,31"] },
      { number: 11, text: "sage zu den Tünchestreichern: Sie soll fallen! Es kommt ein überschwemmender Regen. Und ihr Hagelsteine, ihr werdet fallen, und ein Sturmwind wird <sie> spalten;" },
      { number: 12, text: "und siehe, die Mauer fällt*. Wird man euch nicht sagen: Wo ist das Getünchte, das ihr getüncht habt? —", footnotes: ["℘ Mt 7,27"] },
      { number: 13, text: "Darum, so spricht der Herr, HERR: So lasse ich einen Sturmwind losbrechen in meinem Grimm, und ein überschwemmender Regen wird durch meinen Zorn kommen und Hagelsteine durch <meinen> Grimm zur Vernichtung*.", footnotes: ["℘ Hi 38,23; Jer 23,19; Kla 2,1-8; Offb 6,17"] },
      { number: 14, text: "Und ich breche die Mauer ab, die ihr mit Tünche bestrichen habt, und lasse sie zu Boden stürzen, dass ihr Grund bloßgelegt wird*; und sie* soll fallen*, und ihr werdet in ihrer* Mitte umkommen*. Und ihr werdet erkennen, dass ich der HERR bin.", footnotes: ["℘ Mi 1,6", "d. i. die Stadt Jerusalem", "℘ Jes 30,13", "d. i. die Stadt Jerusalem", "℘ Jes 28,17.18"] },
      { number: 15, text: "Und so werde ich meinen Grimm vollenden an der Mauer und an denen, die sie mit Tünche bestreichen. Und ich werde zu euch sagen: Die Mauer gibt es nicht <mehr>, und die, die sie tünchten, gibt es nicht <mehr>,*", footnotes: ["Die syr. Üs. liest: Und man wird sagen: Wo ist die Mauer und wo sind die, die sie tünchten?\n℘ Jer 14,15"] },
      { number: 16, text: "die Propheten Israels, die über Jerusalem weissagen und für es Visionen des Friedens schauen, obwohl kein Friede da ist*, spricht der Herr, HERR*.", footnotes: ["℘ Jer 6,14", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 17, text: "Und du, Menschensohn, richte dein Gesicht gegen die Töchter deines Volkes, die aus ihrem <eigenen> Herzen weissagen*. Und weissage gegen sie", footnotes: ["℘ V. 2"] },
      { number: 18, text: "und sage: So spricht der Herr, HERR: Wehe denen, die Binden zusammennähen* für alle Handgelenke* und Kopfhüllen machen für Köpfe* jedes Wuchses*, um Seelen* zu fangen*! Seelen wollt ihr fangen bei meinem Volk und <andere> Seelen für euch <selbst> am Leben erhalten?*", footnotes: ["wahrscheinlich für magische Praktiken", "so mit einigen hebr. Handschr., der aram. und syr. Üs.; Mas. T.: für alle meine Handgelenke", "so mit einigen hebr. Handschr., der aram. und syr. Üs.; Mas. T.: für alle meine Handgelenke", "w. die Kopfhüllen für den Kopf jedes Wuchses machen", "Mit »Seele« ist die ganze Person des Menschen gemeint.", "℘ 2Petr 2,14", "Einen Fragesatz überliefert die aram. Üs.; Mas. T. bietet einen Aussagesatz."] },
      { number: 19, text: "Und ihr entweiht mich bei meinem Volk für <einige> Hände voll Gerste und für <einige> Bissen Brot*, indem ihr Seelen* tötet, die nicht sterben sollten, und Seelen* am Leben erhaltet, die nicht leben sollten*; indem ihr mein Volk anlügt, das auf Lügen hört! —", footnotes: ["℘ Kap. 22,27; Spr 28,21", "Mit »Seele« ist die ganze Person des Menschen gemeint.", "Mit »Seele« ist die ganze Person des Menschen gemeint.", "℘ Spr 17,15; Jes 5,20; Mi 3,5"] },
      { number: 20, text: "Darum, so spricht der Herr, HERR: Siehe, ich will an eure Binden, in denen* ihr die Seelen* wie Vögel* fangt, und will sie von euren Armen wegreißen. Und ich lasse die Seelen* los, die ihr fangt, die Seelen*, dass sie wegfliegen.", footnotes: ["w. wo", "Mit »Seele« ist die ganze Person des Menschen gemeint.", "w. als Vögel", "w. als Vögel", "Andere üs.: als Freigelassene"] },
      { number: 21, text: "Und ich reiße eure Kopfhüllen weg und rette mein Volk aus eurer Hand, damit sie in eurer Hand nicht mehr zur Jagdbeute werden. Und ihr werdet erkennen, dass ich der HERR bin." },
      { number: 22, text: "Weil ihr das Herz des Gerechten <mit> Lüge verzagt macht, obwohl ich ihm doch keinen Schmerz zugefügt habe, und weil ihr die Hände des Gottlosen stärkt, damit er nicht von seinem bösen Weg umkehrt, sich am Leben zu erhalten*,", footnotes: ["℘ Jer 23,14.17; Kla 2,14"] },
      { number: 23, text: "darum sollt ihr nicht <mehr> Nichtiges schauen und nicht länger Wahrsagerei treiben*. Und ich werde mein Volk aus eurer Hand retten*, und ihr werdet erkennen, dass ich der HERR bin.", footnotes: ["℘ Kap. 12,24; Mi 3,6", "℘ Kap. 34,10"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und es kamen* Männer von den Ältesten Israels zu mir, und sie setzten sich vor mir nieder*.", heading: "Keine Antwort Gottes auf Fragen der Götzendiener", footnotes: ["so mit 6 hebr. Handschr. und den alten Üs.; Mas. T.: es kam", "℘ Kap. 8,1"] },
      { number: 2, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 3, text: "Menschensohn, diese Männer haben ihre Götzen in ihrem Herzen aufkommen lassen und den Anstoß zu ihrer Schuld vor ihr Gesicht gestellt*. Sollte ich mich da etwa von ihnen befragen lassen*?", footnotes: ["℘ Kap. 7,19; 11,21; 44,12", "℘ Kap. 20,3; 2Kö 3,13.14; Jer 21,2"] },
      { number: 4, text: "Darum rede mit ihnen und sage zu ihnen: So spricht der Herr, HERR: Jedermann vom Haus Israel, der seine Götzen in seinem Herzen aufkommen lässt und den Anstoß zu seiner Schuld vor seinem Gesicht aufrichtet und <dann> zum Propheten kommt — ich, der HERR, ich selbst*, lasse mich für ihn zu einer Antwort bewegen, gemäß* der Menge seiner Götzen*,", footnotes: ["w. in mir selbst; so mit der aram. Üs.; Mas. T.: in ihr; d. i. der Menge", "o. trotz", "o. ich selbst lasse mich zu einer Antwort bewegen für den, der <zu mir> mit der Menge seiner Götzen kommt"] },
      { number: 5, text: "damit ich das Haus Israel an seinem Herzen fasse, weil sie sich allesamt um ihrer Götzen willen von mir abgewandt haben*. —", footnotes: ["℘ Jer 2,5-13"] },
      { number: 6, text: "Darum sage zum Haus Israel: So spricht der Herr, HERR: Kehrt um, und wendet euch ab von euren Götzen, und von allen euren Gräueln wendet euer Gesicht ab*!", footnotes: ["℘ Kap. 18,30.31; Sach 1,4"] },
      { number: 7, text: "Denn jedermann vom Haus Israel und von den Fremden, die sich in Israel aufhalten, der sich von mir* trennt und seine Götzen in seinem Herzen aufkommen lässt und den Anstoß zu seiner Schuld vor seinem Gesicht aufrichtet und <dann> zum Propheten kommt, um mich für sich zu befragen — ich, der HERR, ich selbst, lasse mich für ihn zu einer Antwort bewegen.", footnotes: ["w. von <der Nachfolge> hinter mir her"] },
      { number: 8, text: "Und ich richte mein Angesicht gegen einen solchen Mann* und mache ihn zu einem Denkzeichen und zu Sprichwörtern* und rotte ihn aus der Mitte meines Volkes aus*. Und ihr werdet erkennen, dass ich der HERR bin. —", footnotes: ["℘ Ps 34,17", "so mit den alten Üs.; Mas. T.: ich veranlasse, dass man ihn zu . . . Sprichwörtern macht", "℘ 5Mo 29,19"] },
      { number: 9, text: "Wenn aber der Prophet sich verleiten lässt und ein Wort redet, dann habe ich, der HERR, diesen Propheten verleitet*; und ich werde meine Hand gegen ihn ausstrecken und ihn aus der Mitte meines Volkes Israel austilgen*.", footnotes: ["℘ 1Kö 22,22.23", "℘ Kap. 13,9"] },
      { number: 10, text: "So sollen sie <beide> ihre Schuld tragen; wie die Schuld des Fragenden, so wird die Schuld des Propheten sein*,", footnotes: ["℘ Jer 14,15.16"] },
      { number: 11, text: "damit das Haus Israel nicht mehr von mir* abirre und sie sich nicht mehr mit all ihren Vergehen unrein machen. Und sie werden mir zum Volk, und ich selbst werde ihnen zum Gott sein*, spricht der Herr, HERR*.", footnotes: ["w. von <der Nachfolge> hinter mir her", "℘ Kap. 11,20; Sach 13,9", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 12, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Selbst Noah, Daniel und Hiob könnten das Gericht an Jerusalem nicht verhindern" },
      { number: 13, text: "Menschensohn, wenn ein Land gegen mich sündigt, indem es Untreue begeht, und ich meine Hand gegen es ausstrecke und ihm den Stab des Brotes zerbreche und Hunger hinein sende* und aus ihm Menschen und Vieh ausrotte —", footnotes: ["℘ Kap. 4,16.17"] },
      { number: 14, text: "und diese drei Männer wären in seiner Mitte: Noah*, Daniel* und Hiob* —, es würde um ihrer Gerechtigkeit willen <nur> ihre eigene Seele gerettet werden*, spricht der Herr, HERR*.", footnotes: ["℘ 1Mo 7,1; 1Chr 1,4", "℘ Dan 9,23", "℘ Hi 1,1.8; Jer 15,1", "℘ Spr 11,4", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 15, text: "*Oder <wenn> ich böse Tiere das Land durchstreifen lasse*, so dass sie es entvölkern und es eine Öde wird, weil wegen der Tiere niemand hindurchzieht* —", footnotes: ["so mit Änderung eines Buchstabens in Entsprechung zu V. 17.19; Mas. T.: Ach wenn ich doch . . . durchstreifen ließe", "so mit Änderung eines Buchstabens in Entsprechung zu V. 17.19; Mas. T.: Ach wenn ich doch . . . durchstreifen ließe", "℘ Kap. 5,17; Jes 51,19"] },
      { number: 16, text: "<wären> diese drei Männer in seiner Mitte, so wahr ich lebe, spricht der Herr, HERR*, *sie würden weder Söhne noch Töchter retten*; sie allein würden gerettet, das Land aber würde eine Öde werden.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "w. wenn sie Söhne oder wenn sie Töchter retten<, dann . . .!> — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte — wahrscheinlich eine Verwünschung — nicht ausgesprochen wurde.", "w. wenn sie Söhne oder wenn sie Töchter retten<, dann . . .!> — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte — wahrscheinlich eine Verwünschung — nicht ausgesprochen wurde."] },
      { number: 17, text: "Oder <wenn> ich das Schwert über jenes Land kommen lasse und spreche: Schwert, fahre durch das Land! und aus ihm Menschen und Vieh ausrotte* —", footnotes: ["℘ Kap. 21,8-10.14; 33,2; Jer 47,7"] },
      { number: 18, text: "und diese drei Männer wären in seiner Mitte —, so wahr ich lebe, spricht der Herr, HERR*, *sie würden weder Söhne noch Töchter retten*; sondern sie allein würden gerettet werden.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "w. wenn sie Söhne oder wenn sie Töchter retten<, dann . . .!> — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte — wahrscheinlich eine Verwünschung — nicht ausgesprochen wurde.", "w. wenn sie Söhne oder wenn sie Töchter retten<, dann . . .!> — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte — wahrscheinlich eine Verwünschung — nicht ausgesprochen wurde."] },
      { number: 19, text: "Oder <wenn> ich die Pest in jenes Land sende und meinen Grimm in Blut über es ausgieße, um Menschen und Vieh darin auszurotten* —", footnotes: ["℘ Jer 21,6"] },
      { number: 20, text: "und Noah, Daniel und Hiob wären in seiner Mitte —, so wahr ich lebe, spricht der Herr, HERR*, *sie würden weder Sohn noch Tochter retten*; sie würden um ihrer Gerechtigkeit willen <nur> ihre <eigene> Seele retten.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "s. vorige Anm.", "s. vorige Anm."] },
      { number: 21, text: "Denn so spricht der Herr, HERR: Ja, wenn ich nun meine vier bösen Gerichte, Schwert und Hunger und böse Tiere und die Pest*, gegen Jerusalem entsende, um aus ihm Menschen und Vieh auszurotten*!", footnotes: ["℘ Kap. 5,12.17", "℘ Kap. 5,17; Jes 51,19"] },
      { number: 22, text: "*Doch siehe, Entkommene werden darin übrig bleiben*, die herausgeführt werden, Söhne und Töchter. Siehe, sie werden zu euch hinausziehen, und ihr werdet ihren Weg und ihre Taten sehen; und ihr werdet euch trösten über das Unheil, das ich über Jerusalem habe kommen lassen, alles, was ich über es habe kommen lassen.", footnotes: ["o. Und sind dann <dennoch> Entkommene darin übrig geblieben", "o. Und sind dann <dennoch> Entkommene darin übrig geblieben\n℘ Kap. 6,8"] },
      { number: 23, text: "Und sie werden euch trösten, wenn ihr ihren Weg und ihre Taten seht, und ihr werdet erkennen, dass ich nicht ohne Ursache all das getan habe, was ich an ihm* getan*, spricht der Herr, HERR*.", footnotes: ["d. i. an Jerusalem", "℘ Kap. 7,27; 3Mo 26,40.41; Hi 33,27", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Gleichnis: Jerusalem, das unnütze Holz der Weinrebe", footnotes: ["℘ Kap. 21,1-5"] },
      { number: 2, text: "Menschensohn, was hat <denn> das Holz des Weinstocks* allem <anderen> Holz voraus, die Ranke, die unter den Bäumen des Waldes ist?", footnotes: ["℘ Jer 2,21"] },
      { number: 3, text: "Wird von ihm Holz genommen, um es zu einer Arbeit zu verwenden? Oder nimmt man von ihm einen Pflock, um irgendein Gerät daran aufzuhängen?" },
      { number: 4, text: "Siehe, dem Feuer ist es zum Fraß gegeben. Seine beiden Enden hat das Feuer gefressen, und seine Mitte ist versengt. Wird es <noch> zu einer Arbeit tauglich sein?" },
      { number: 5, text: "Siehe, <selbst> wenn es unversehrt ist, wird es zu keiner Arbeit verwendet. Wie viel weniger, wenn das Feuer es gefressen hat und es versengt ist, kann es noch zu einer Arbeit verwendet werden! —" },
      { number: 6, text: "Darum, so spricht der Herr, HERR: Wie das Holz des Weinstocks unter den Bäumen des Waldes, das ich dem Feuer zum Fraß gebe, so gebe ich die Bewohner von Jerusalem dahin*.", footnotes: ["℘ Jes 5,24.25; 27,11"] },
      { number: 7, text: "Und ich richte mein Angesicht gegen sie: Aus dem Feuer sind sie herausgekommen, doch Feuer wird sie fressen*. Und ihr werdet erkennen, dass ich der HERR bin, wenn ich mein Angesicht gegen sie richte.", footnotes: ["℘ Kap. 19,12"] },
      { number: 8, text: "Und ich werde das Land zur Einöde machen*, weil sie Untreue begangen haben*, spricht der Herr, HERR*.", footnotes: ["℘ Kap. 6,14", "℘ Kap. 33,29; 39,26", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Gleichnis: Jerusalem, die trotz aller Liebesbeweise untreu gewordene Ehefrau", footnotes: ["℘ V. 1-63: Kap. 23"] },
      { number: 2, text: "Menschensohn, lass <die Stadt> Jerusalem ihre Gräuel erkennen*", footnotes: ["℘ Kap. 20,4; 22,2; Jes 58,1"] },
      { number: 3, text: "und sage: So spricht der Herr, HERR, zu Jerusalem: Deine Herkunft und deine Abstammung* sind aus dem Land der Kanaaniter; dein Vater war ein Amoriter* und deine Mutter eine Hetiterin*.", footnotes: ["o. Geburt; wie V. 4", "℘ Jes 43,27", "℘ V. 45"] },
      { number: 4, text: "Und <was> deine Geburt <betrifft>: an dem Tag, als du geboren wurdest, wurde deine Nabelschnur nicht abgeschnitten, und du wurdest nicht mit Wasser abgewaschen zur Reinigung und nicht mit Salz abgerieben und nicht in Windeln gewickelt*.", footnotes: ["℘ Hos 2,5"] },
      { number: 5, text: "Niemand blickte mitleidig auf dich*, um dir eines dieser Dinge aus Mitleid mit dir zu tun, sondern du wurdest auf die Fläche des Feldes geworfen, aus Abscheu vor deinem Leben, an dem Tag, als du geboren wurdest. —", footnotes: ["w. Kein Auge floss deinetwegen"] },
      { number: 6, text: "Da ging ich an dir vorüber und sah dich in deinem Blut zappeln; und zu dir in deinem Blut sprach ich: Bleibe leben! Ja, zu dir in deinem Blut sprach ich: Bleibe leben," },
      { number: 7, text: "und wachse wie das Gewächs des Feldes*! Und du wuchsest heran und wurdest groß, und du gelangtest zu höchster Anmut; die Brüste rundeten sich, und dein Haar wuchs reichlich; aber du warst nackt und bloß.", footnotes: ["so mit LXX; Mas. T.: <zu> Zehntausend — wie das Gewächs des Feldes — habe ich dich gemacht\n℘ 5Mo 1,10"] },
      { number: 8, text: "Und ich ging <wieder> an dir vorüber und sah dich, und siehe, deine Zeit war da, die Zeit der Liebe; und ich breitete meinen <Gewand>zipfel über dich aus und bedeckte deine Blöße. Und ich schwor dir und trat in einen Bund mit dir*, spricht der Herr, HERR*, und du wurdest mein*.", footnotes: ["℘ 2Mo 24,8; Röm 9,4; 2Mo 15,16", "w. ist der Ausspruch des Herrn, HERRN", "℘ Jes 43,1; Jer 2,2; 31,32; Joh 10,3"] },
      { number: 9, text: "Und ich wusch dich mit Wasser* und spülte dein Blut von dir ab und salbte dich mit Öl.", footnotes: ["℘ Kap. 36,25; Eph 5,26; 1Petr 3,20.21; 1Jo 5,6-8"] },
      { number: 10, text: "Und ich bekleidete dich mit Buntwirkerei* und beschuhte dich mit Delfinhäuten*, ich umwand dich mit Byssus und bedeckte dich mit Seide.", footnotes: ["Bunte Stoffe waren besonders kostbar.\n℘ Ps 45,15", "w. mit Tachaschhaut; d. i. besonders wertvolles Leder, das für die äußerste Decke der Stiftshütte verwendet wurde; Tachasch ist wahrscheinlich der große Tümmler; nach anderen: Dachs o. Seekuh"] },
      { number: 11, text: "Und ich schmückte dich mit Schmuck: ich legte Spangen um deine Handgelenke* und eine Kette um deinen Hals,", footnotes: ["w. Hände\n℘ 1Mo 24,22; Lk 15,22"] },
      { number: 12, text: "und ich legte einen Reif an deine Nase und Ringe an deine Ohren* und <setzte> eine prachtvolle Krone auf deinen Kopf.", footnotes: ["℘ Hl 1,10; Jes 3,19.21"] },
      { number: 13, text: "So legtest du goldenen und silbernen Schmuck an, und deine Kleidung <bestand aus> Byssus, Seide und Buntwirkerei. Du aßest Weizengrieß und Honig und Öl*. Und du warst sehr, sehr schön* und warst des Königtums würdig*.", footnotes: ["℘ 5Mo 32,13; Ps 147,14", "℘ Kla 2,15", "w. zum Königtum tauglich"] },
      { number: 14, text: "Und dein Ruf ging aus unter die Nationen wegen deiner Schönheit*; denn sie war vollkommen durch meinen Glanz, den ich auf dich gelegt hatte, spricht der Herr, HERR*.", footnotes: ["℘ Kla 2,15", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 15, text: "Aber du vertrautest auf deine Schönheit, und du hurtest auf deinen Ruf hin und gossest deine Hurereien aus über jeden, der vorbeikam: Ihm wurde sie* <zuteil>*.", footnotes: ["Eine griech. Üs. liest in Entsprechung zu V. 8: Sein wurdest du", "℘ Kap. 23,3; Jer 2,20; Hos 1,2; 4,18; 9,1"] },
      { number: 16, text: "Und du nahmst von deinen Kleidern und machtest dir bunte Höhen*, und du hurtest auf ihnen, *<Dinge, die> nie vorgekommen sind und was nie <wieder> geschehen wird*.", footnotes: ["Vielleicht sind damit heidnische Grabhügel gemeint, an denen bunte Tuchstücke aufgehängt waren; andere vermuten bunte Zelte, die bei Fruchtbarkeitsfesten auf den Höhen errichtet wurden.\n℘ Kap. 7,20; Hos 2,10", "Der Mas. T. ist unklar.", "Der Mas. T. ist unklar.\n℘ Jer 2,10"] },
      { number: 17, text: "Und du nahmst deine prächtigen Geschmeide von meinem Gold und von meinem Silber, das ich dir gegeben hatte, und machtest dir Abbilder von Männern und hurtest mit ihnen." },
      { number: 18, text: "Und du nahmst deine buntgewirkten Kleider und bedecktest sie <damit>; und mein Öl und mein Räucherwerk setztest du ihnen vor*;", footnotes: ["℘ Jer 1,16"] },
      { number: 19, text: "und mein Brot, das ich dir gegeben habe — mit Weizengrieß und Öl und Honig habe ich dich gespeist —, das setztest du ihnen vor zum wohlgefälligen Geruch*; ja, so war es, spricht der Herr, HERR*. —", footnotes: ["w. zum Geruch der Befriedigung o. der Beschwichtigung\n℘ Kap. 7,20; Hos 2,10", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 20, text: "Und du nahmst deine Söhne und deine Töchter, die du mir geboren, und opfertest sie ihnen zum Fraß*. War es zu wenig mit deiner Hurerei,", footnotes: ["℘ V. 36; Ps 106,38; Jes 57,5; Jer 3,24; 19,5"] },
      { number: 21, text: "dass du meine Söhne schlachtetest und sie hingabst, indem du sie für sie durch <das Feuer> gehen ließest*?", footnotes: ["℘ Kap. 20,26; 2Chr 28,3"] },
      { number: 22, text: "Und bei allen deinen Gräueln und deinen Hurereien dachtest du nicht an die Tage deiner Jugend, als du nackt und bloß warst, zappelnd in deinem Blut lagst*. —", footnotes: ["℘ V. 43; Hos 11,1"] },
      { number: 23, text: "Und es geschah, nach all deiner Bosheit — wehe, wehe dir*!, spricht der Herr, HERR* —", footnotes: ["℘ Jer 13,27", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 24, text: "bautest du dir einen Hurenaltar und machtest dir <dein> Hochlager* auf jedem freien Platz*;", footnotes: ["w. <deine> Anhöhe", "℘ Kap. 20,28.29; 1Kö 14,23; 2Chr 21,11; 28,25"] },
      { number: 25, text: "an jeder Straßenecke* bautest du dein Hochlager*. Und du machtest deine Schönheit zu einem Gräuel und spreiztest deine Beine für jeden, der vorbeikam, und machtest deine Hurerei groß.", footnotes: ["w. am Anfang jedes Weges o. jeder Strecke", "w. deine Anhöhe"] },
      { number: 26, text: "Du hurtest mit den Söhnen Ägyptens, deinen Nachbarn, mit dem großen Fleisch*; und du machtest deine Hurerei groß, um mich zu reizen*.", footnotes: ["Gemeint ist das männliche Glied.", "℘ 1Kö 12,28"] },
      { number: 27, text: "Und siehe, ich streckte meine Hand gegen dich aus und kürzte deinen Anteil<, der dir bestimmt war>. Und ich gab dich der Gier derer hin, die dich hassen*, der Töchter der Philister*, die sich vor deinem unzüchtigen Weg* schämen.", footnotes: ["℘ Ps 106,41", "℘ V. 57; 2Chr 28,18", "w. vor deinem Weg der Schandtat"] },
      { number: 28, text: "Und du hurtest mit den Söhnen Assurs*, weil du <noch> nicht satt warst; und du hurtest mit ihnen und wurdest auch nicht satt.", footnotes: ["℘ Jer 2,18"] },
      { number: 29, text: "Und du vermehrtest deine Hurerei zum Händlerland Chaldäa hin; aber selbst davon wurdest du nicht satt." },
      { number: 30, text: "Wie fieberheiß ist dein Herz*, spricht der Herr, HERR*, wenn du dies alles tust — das Tun eines selbstherrlichen Hurenweibes* —,", footnotes: ["Andere leiten das Verb von einer anderen Wurzel ab und üs.: Wie bin ich mit Wut gegen dich erfüllt\n℘ Ps 78,37", "w. ist der Ausspruch des Herrn, HERRN", "o. eines gewaltigen Hurenweibes\n℘ Jer 3,1-3.6; Hos 9,1"] },
      { number: 31, text: "wenn du deinen Hurenaltar an jeder Straßenecke baust und dein Hochlager* auf jedem freien Platz machst! Dabei warst du nicht <einmal> wie eine <gewöhnliche> Hure, <denn> du verschmähtest <sogar> den Lohn.", footnotes: ["w. deine Anhöhe"] },
      { number: 32, text: "Die ehebrecherische Frau nimmt statt ihres Mannes fremde <Männer>*!", footnotes: ["In Anlehnung an LXX lässt sich auch üs.: Die Frau, die anstelle ihres Mannes ehebrecherisch <einen anderen wählt>, nimmt Geschenke an.\n℘ Spr 7,19; Jer 3,20"] },
      { number: 33, text: "Allen Huren gibt man Geschenke*; du aber gabst deine Liebesgeschenke all deinen Liebhabern, und du beschenktest sie, damit sie von ringsumher zu dir kämen wegen deiner Hurereien*.", footnotes: ["℘ 1Mo 38,16", "℘ Jes 57,9; Jer 2,24; Hos 8,10"] },
      { number: 34, text: "So geschah bei dir das Gegenteil von <dem, was sonst üblich ist unter> den Frauen, dass du <nämlich> Hurerei triebst*, während man dir nicht nachhurte, dass du Lohn gabst, während dir kein Lohn gegeben wurde. So wurdest du das Gegenteil.", footnotes: ["w. bei deinen Hurereien"] },
      { number: 35, text: "Darum, Hure, höre das Wort des HERRN!" },
      { number: 36, text: "So spricht der Herr, HERR: Weil du deine Scham entblößt* und deine Blöße aufgedeckt hast* bei deinen Hurereien mit deinen Liebhabern und mit all deinen gräulichen Götzen und wegen des Blutes* deiner Söhne, die du ihnen hingegeben hast*:", footnotes: ["so mit der aram. Üs.; Mas. T.: Weil deine Monatsblutung ausgegossen wurde", "so mit der syr. Üs.; Mas. T.: deine Blöße aufgedeckt wurde", "so mit den meisten hebr. Handschr.; LXX, Vulg. und einer aram. Üs.; Mas. T.: gemäß dem Blut", "℘ V. 20"] },
      { number: 37, text: "Darum, siehe, werde ich alle deine Liebhaber sammeln, denen du gefielst, und alle, die du geliebt, mit allen, die du gehasst hast. Ich sammle sie von allen Seiten gegen dich und decke deine Blöße vor ihnen auf, so dass sie deine ganze Blöße sehen*.", footnotes: ["℘ Jer 13,26; Offb 17,16"] },
      { number: 38, text: "Und ich richte dich nach den Rechtsbestimmungen für Ehebrecherinnen* und Blutvergießerinnen* und bringe <meinen> Zorn und Eifer über dich*.", footnotes: ["℘ 5Mo 22,22", "℘ Kap. 36,18; 4Mo 35,31", "so mit Kap. 23,25; Mas. T.: mache dich zum Blut des Grimms und Eifers o. der Eifersucht"] },
      { number: 39, text: "Und ich gebe dich in ihre Hand, und sie werden deinen Hurenaltar zerstören und deine Höhen niederreißen* und dir deine Kleider ausziehen und deine prächtigen Geschmeide nehmen und dich nackt und bloß liegen lassen*.", footnotes: ["℘ 3Mo 26,30", "℘ Hos 2,5.11.12"] },
      { number: 40, text: "Und sie werden eine Versammlung gegen dich heraufkommen lassen* und dich steinigen und werden dich mit ihren Schwertern niedermetzeln*.", footnotes: ["℘ Jer 25,9; Kap. 23,25", "℘ 2Chr 36,17"] },
      { number: 41, text: "Und sie werden deine Häuser mit Feuer verbrennen* und Strafgerichte an dir üben* vor den Augen vieler Frauen*. Und so werde ich dich aufhören lassen, Hure zu sein*, und <auch> Lohn wirst du nicht mehr geben.", footnotes: ["℘ Jer 52,13; Offb 17,16", "℘ Kap. 5,8.15", "℘ Hi 34,26", "℘ Mi 5,12.13"] },
      { number: 42, text: "Und ich werde meinen Zorn an dir stillen*, und mein Eifer wird sich von dir abwenden; und ich werde ruhig sein und nicht mehr zürnen. —", footnotes: ["℘ Kap. 5,13"] },
      { number: 43, text: "Weil du nicht an die Tage deiner Jugend gedacht hast und mich durch das alles erregt hast*, siehe, so habe auch ich deinen Weg auf deinen* Kopf gebracht*, spricht der Herr, HERR*. Hast du diese Schandtat nicht zu all deinen <anderen> Gräueln hinzu begangen?*", footnotes: ["T.; Mas. T.: gegen mich erregt gewesen bist\n℘ V. 22.58", "so mit 3 hebr. Handschr., LXX, Vulg. und der syr. Üs.; Mas. T.: auf den", "℘ Kap. 7,3.4; 9,10; 17,19; Dan 9,13.14", "w. ist der Ausspruch des Herrn, HERRN", "T.; Mas. T.: Dass du <diese> Schandtat nicht zu all deinen Gräueln hinzutust."] },
      { number: 44, text: "Siehe, jeder, der einen Spottvers über dich macht, wird diesen Spottvers* sagen: Wie die Mutter, so ihre Tochter!", footnotes: ["o. ein Sprichwort . . . dieses Sprichwort"] },
      { number: 45, text: "Eine <echte> Tochter deiner Mutter bist du, die ihren Mann und ihre Söhne verabscheut hat; und eine <echte> Schwester deiner Schwestern* bist du, die ihre Männer und ihre Kinder verabscheut haben. Eure Mutter war eine Hetiterin und euer Vater ein Amoriter*.", footnotes: ["so mit LXX und Vulg.; Mas. T.: deiner Schwester", "℘ V. 3"] },
      { number: 46, text: "Und deine größere Schwester ist Samaria*, sie und ihre Töchter*, die zu deiner Linken wohnt; und deine Schwester, die kleiner ist als du <und> die zu deiner Rechten wohnt, ist Sodom* und ihre Töchter*.", footnotes: ["℘ Jes 10,11; Hos 14,1; Mi 1,5", "d. h. vielleicht ihre Tochterstädte", "℘ 5Mo 32,32", "d. h. vielleicht ihre Tochterstädte"] },
      { number: 47, text: "Aber du bist nicht <nur> auf ihren Wegen gegangen und hast <nicht nur> nach ihren Gräueln getan, <sondern> es fehlte nur wenig, und du hättest verdorbener als sie gehandelt* auf all deinen Wegen*.", footnotes: ["o. <Ja>. Nach kurzer Zeit hast du verdorbener als sie gehandelt", "℘ Kap. 5,6.7"] },
      { number: 48, text: "So wahr ich lebe, spricht der Herr, HERR*, wenn deine Schwester Sodom, sie und ihre Töchter, <jemals> getan haben, wie du getan hast, du und deine Töchter*!", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte — wahrscheinlich eine Verwünschung — nicht ausgesprochen wurde."] },
      { number: 49, text: "Siehe, das war die Schuld deiner Schwester Sodom: Hochmut, Fülle von Brot und sorglose Ruhe* hatte sie mit ihren Töchtern*, aber die Hand des Elenden und des Armen stärkte sie nicht*;", footnotes: ["℘ Jes 47,8", "d. h. vielleicht ihre Tochterstädte", "℘ Kap. 18,7.8"] },
      { number: 50, text: "und sie wurden hochmütig und verübten Gräuel vor meinem Angesicht. Und ich tat sie hinweg, sobald ich es sah*.", footnotes: ["Einige griech. Üs. und Vulg. lesen: wie du gesehen hast"] },
      { number: 51, text: "Und Samaria hat nicht halb so viel Sünden begangen wie du; und du hast deine Gräuel zahlreicher werden lassen als sie und hast deine Schwestern als gerecht erscheinen lassen durch all deine Gräuel, die du verübt hast*.", footnotes: ["℘ Jer 3,11"] },
      { number: 52, text: "So trage auch du deine Schmach, die du für deine Schwestern* eingetreten bist durch deine Sünden, die du gräulicher begangen hast als sie*! <So> sind sie gerechter als du. Und so schäme auch du dich, und trage deine Schmach*, weil du deine Schwestern* als gerecht hast erscheinen lassen!", footnotes: ["so mit den alten Üs.; Mas. T.: deine Schwester", "℘ Röm 2,1", "℘ Jer 23,40", "so mit den alten Üs.; Mas. T.: deine Schwester"] },
      { number: 53, text: "Und ich wende ihr Geschick*, das Geschick Sodoms und ihrer Töchter* und das Geschick Samarias und ihrer Töchter, *und ich wende dein Geschick* in ihrer Mitte:", heading: "Verheißung der Wiederannahme Jerusalems", footnotes: ["℘ Jer 46,27", "d. h. vielleicht ihre Tochterstädte", "so mit LXX; Mas. T.: und die Gefangenschaft deiner Gefangenschaft", "so mit LXX; Mas. T.: und die Gefangenschaft deiner Gefangenschaft"] },
      { number: 54, text: "damit du deine Schmach trägst und dich all dessen schämst, was du getan hast, wodurch du sie tröstest." },
      { number: 55, text: "Und deine Schwestern, Sodom und ihre Töchter*, werden in ihren früheren Zustand zurückkehren, und Samaria und ihre Töchter werden in ihren früheren Zustand zurückkehren, und auch du und deine Töchter, ihr werdet in euren früheren Zustand zurückkehren.", footnotes: ["d. h. vielleicht ihre Tochterstädte"] },
      { number: 56, text: "Hat nicht deine Schwester Sodom zu einer <abschreckenden> Kunde in deinem Mund gedient* am Tag deines Hochmutes,", footnotes: ["T.; Mas. T. bietet einen Aussagesatz"] },
      { number: 57, text: "bevor deine <eigene> Bosheit* aufgedeckt wurde, so wie jetzt das Höhnen* der Töchter Edoms* — und all derer, die rings um sie her <wohnen>, der Töchter der Philister, die dich verachteten — von allen Seiten <über dich ertönt>*?", footnotes: ["3 hebr. Handschr. lesen im Einklang mit V. 37: deine Blöße", "so mit LXX und Vulg.; Mas. T.: wie zur Zeit des Höhnens", "so mit den meisten hebr. Handschr. und der syr. Üs.; Mas. T.: der Töchter Arams", "℘ V. 27; 2Chr 28,5"] },
      { number: 58, text: "Deine Schandtat und deine Gräuel, die musst du <jetzt> tragen*, spricht der HERR*.", footnotes: ["℘ V. 43", "w. ist der Ausspruch des HERRN"] },
      { number: 59, text: "Denn so spricht der Herr, HERR: Ja, ich will dir tun, wie du getan*, die du den Eid verachtet, indem du den Bund gebrochen hast*.", footnotes: ["℘ Kap. 7,8; Jes 3,11", "℘ 5Mo 29,24; Jes 24,5; Jer 11,10"] },
      { number: 60, text: "Ich aber, ich will an meinen Bund denken, <den ich> mit dir in den Tagen deiner Jugend <geschlossen habe>*, und will dir einen ewigen Bund aufrichten*.", footnotes: ["T.; Mas. T.: Ich aber will an meinen Bund denken, an dich in den Tagen deiner Jugend\n℘ Ps 106,45; Jes 14,1", "℘ Kap. 37,26; Jes 55,3; 61,8; Lk 1,72; 22,20"] },
      { number: 61, text: "Und du wirst an deine Wege denken und dich schämen*, wenn du deine Schwestern <zu dir> nimmst*, die größer sind als du, samt denen, die kleiner sind als du, und ich sie dir zu Töchtern gebe*, aber nicht wegen deines Bundes<verhaltens>*.", footnotes: ["℘ Kap. 20,43; 43,10; Röm 6,21", "Andere vermuten, der Text habe ursprünglich gelautet: wenn ich deine Schwestern nehme", "℘ Sach 2,15", "o. aber nicht auf der Grundlage <meines> Bundes mit dir\n℘ Kap. 36,32"] },
      { number: 62, text: "Und ich selbst werde meinen Bund mit dir aufrichten*, und du wirst erkennen, dass ich der HERR bin:", footnotes: ["℘ Hos 2,20"] },
      { number: 63, text: "damit du daran denkst und dich schämst und den Mund nicht mehr öffnest* wegen deiner Schmach*, wenn ich dir alles vergebe*, was du getan hast*, spricht der Herr, HERR*.", footnotes: ["℘ Hi 40,4; Röm 3,19", "w. und du keinen Anlass <zum Öffnen> des Mundes mehr hast", "w. wenn ich dir Sühnung gewähre für alles", "℘ 5Mo 32,43; Ps 85,3; Jes 33,24; 44,22", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Gleichnis von Adler und Zeder: Treuebruch des Königs von Juda gegen den König von Babel" },
      { number: 2, text: "Menschensohn, gib ein Rätsel auf* und rede ein Gleichnis zum Haus Israel*", footnotes: ["℘ Ri 14,12", "℘ Kap. 21,5; 24,3; Hos 12,11"] },
      { number: 3, text: "und sprich: So spricht der Herr, HERR: Der große Adler mit großen Flügeln, langen Schwingen, vollem Gefieder, der bunte <Federn> hatte*, kam zum Libanon und nahm den Wipfel der Zeder*.", footnotes: ["℘ 5Mo 28,49", "℘ Jer 22,23"] },
      { number: 4, text: "Den obersten ihrer Triebe brach er ab und brachte ihn ins Land der Händler, in die Stadt der Kaufleute setzte er ihn*.", footnotes: ["℘ 2Kö 24,12.15; Jer 24,1"] },
      { number: 5, text: "Und er nahm von dem Samen des Landes und setzte ihn in ein Saatfeld, als Weide an reichlich <strömendes> Wasser, als Ufergewächs setzte er ihn," },
      { number: 6, text: "damit er wachse und zu einem wuchernden Weinstock werde* von niedrigem Wuchs, damit seine Ranken sich zu ihm hin* wendeten und seine Wurzeln unter ihm wären. Und er wurde zu einem Weinstock und bildete Triebe und streckte <seine> Äste aus*. —", footnotes: ["So konnte der Satz vor der Festlegung durch die Masoreten verstanden werden. Mas. T.: Und er wuchs und wurde zu einem wuchernden Weinstock", "d. h. zu dem Adler hin", "℘ Kap. 19,10; 2Chr 36,10"] },
      { number: 7, text: "Und da war ein Adler, ein anderer, großer, mit großen Flügeln und viel Gefieder. Und siehe, dieser Weinstock drehte seine Wurzeln zu ihm hin und streckte seine Ranken nach ihm aus, damit er ihn tränke, weg von dem Beet, in das er gepflanzt war*.", footnotes: ["w. weg von den Beeten seiner Pflanzung"] },
      { number: 8, text: "In ein gutes Feld, an reichlich <strömendes> Wasser war er gepflanzt, um Zweige zu treiben und Frucht zu tragen, um zu einem herrlichen Weinstock zu werden." },
      { number: 9, text: "Sage: So spricht der Herr, HERR: Wird er gedeihen?* Wird man nicht seine Wurzeln ausreißen und seine Frucht abschneiden, so dass alle frischen <Blätter> seines Sprosses verdorren? <Ja>, er wird <ganz> verdorren! <Es wird> nicht <nötig sein,> mit starkem Arm und zahlreichem Volk ihn aus seinen Wurzeln loszureißen*.", footnotes: ["so mit einigen hebr. Handschr.; Mas. T.: Er wird gedeihen.", "w. in die Höhe zu heben"] },
      { number: 10, text: "Und siehe, ist er <auch> gepflanzt, wird er gedeihen? Wird er nicht, sobald der Ostwind ihn berührt, ganz verdorren*? Auf dem Beet, auf dem er sprosste, wird er verdorren.", footnotes: ["℘ Kap. 19,12; 1Mo 41,6"] },
      { number: 11, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 12, text: "Sprich doch zu dem widerspenstigen Haus*: Erkennt ihr nicht, was das ist? Sage: Siehe, der König von Babel ist nach Jerusalem gekommen und hat seinen König und seine Obersten weggenommen und hat sie zu sich nach Babel weggeführt*.", footnotes: ["℘ Kap. 2,5; 12,9", "℘ Jer 34,21"] },
      { number: 13, text: "Und er nahm <einen> von den königlichen Nachkommen und schloss mit ihm einen Bund und ließ ihn einen Eid eingehen. Die Mächtigen des Landes aber nahm er <gefangen>," },
      { number: 14, text: "damit das Königtum niedrig bleibe <und> damit es sich nicht erhebe <und> damit es seinen Bund halte, dass es* bestehen bleibe.", footnotes: ["So lautet der Text, der den Masoreten vorlag. Sie selbst schlagen vor zu lesen: dass er; d. i. der Bund"] },
      { number: 15, text: "Aber er empörte sich gegen ihn*, indem er seine Boten nach Ägypten sandte, damit es ihm Pferde und viel <Kriegs>volk gebe*. Wird es Gedeihen haben? Wird er, der das getan hat, entkommen? Da er den Bund gebrochen hat, sollte er entkommen?*", footnotes: ["℘ 2Kö 24,20", "℘ 5Mo 17,16; Jes 31,1-3; Jer 37,5", "℘ Kap. 21,28; Jer 32,4"] },
      { number: 16, text: "So wahr ich lebe, spricht der Herr, HERR*, wenn er an dem Ort des Königs, der ihn zum König gemacht hat, dessen Eid er verachtet und dessen Bund er gebrochen hat, <wenn er> bei ihm in Babel nicht sterben wird*!*", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte — wahrscheinlich eine Verwünschung — nicht ausgesprochen wurde.", "℘ Kap. 12,13; Jos 9,20; Jer 34,3.21"] },
      { number: 17, text: "Und der Pharao wird ihm nicht mit einem großen Heer und mit einer zahlreichen Schar im Krieg beistehen*, wenn man einen Belagerungswall aufschüttet und Belagerungstürme baut, um viele Seelen auszurotten.", footnotes: ["℘ Kap. 29,6.7; Jes 36,6"] },
      { number: 18, text: "Hat er doch den Eid verachtet und den Bund gebrochen! Siehe, er hatte ja seine Hand darauf gegeben* und tat <dennoch> all dieses. Er wird nicht entkommen.", footnotes: ["℘ 2Kö 10,15"] },
      { number: 19, text: "Darum spricht der Herr, HERR: So wahr ich lebe, wenn ich meinen Eid, den er verachtet, und meinen Bund, den er gebrochen hat, ihm nicht auf seinen Kopf bringe*!", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte — wahrscheinlich eine Verwünschung — nicht ausgesprochen wurde.\n℘ Kap. 9,10; 16,43; 1Kö 2,32.33.44"] },
      { number: 20, text: "Und ich spanne mein Fangnetz über ihn aus, und in meinem Jagdnetz wird er gefangen; und ich bringe ihn nach Babel*, und dort gehe ich mit ihm ins Gericht* wegen seiner Untreue, die er gegen mich begangen hat,", footnotes: ["℘ Kap. 12,13; Jer 34,21", "w. vor Gericht"] },
      { number: 21, text: "<mit ihm> und mit all seinen ausgewählten Truppen*. Unter all seinen Scharen werden sie durchs Schwert fallen, und die Übriggebliebenen werden in alle Winde zerstreut. Und ihr werdet erkennen, dass ich, der HERR, geredet habe*.", footnotes: ["Diesen Text bieten sehr viele hebr. Handschr.; Mas. T. überliefert ein Wort, das nur hier vorkommt und vielleicht »Flüchtlinge« bedeutet.", "℘ Kap. 5,13.15; 12,14.15"] },
      { number: 22, text: "So spricht der Herr, HERR: Und ich selbst werde von dem Wipfel der hohen Zeder <einen Trieb> nehmen und <ihn> einsetzen*; von dem obersten ihrer Triebe werde ich einen zarten abbrechen und werde ihn selber einpflanzen auf einem hohen und aufragenden Berg*.", heading: "Zukünftige Wiederherstellung des Königtums Davids", footnotes: ["℘ Jes 11,1; Jer 23,5", "℘ Ps 2,6"] },
      { number: 23, text: "Auf den hohen Berg Israels* werde ich ihn pflanzen; und er wird Zweige treiben und Frucht tragen und zu einer herrlichen Zeder werden. Und unter ihr werden alle Vögel wohnen*, alles, was Flügel hat; im Schatten ihrer Zweige werden sie wohnen.", footnotes: ["℘ Kap. 20,40", "℘ Kap. 31,6; Dan 4,8.9; Mi 4,1; Mt 13,32"] },
      { number: 24, text: "Und alle Bäume des Feldes werden erkennen, dass ich, der HERR, den hohen Baum erniedrige, den niedrigen Baum erhöhe, dass ich den grünen Baum vertrocknen lasse und den dürren Baum zum Blühen bringe*. Ich, der HERR, habe geredet und werde es tun*.", footnotes: ["℘ 1Sam 2,7; Mt 23,12; Lk 1,52.53", "℘ Kap. 22,14; 24,14; 36,36; 37,14"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Gottes großes Angebot zu einem Neubeginn im Exil" },
      { number: 2, text: "Was habt ihr, dass ihr dieses Sprichwort im Land Israel gebraucht und sprecht: Die Väter essen unreife Trauben, und die Zähne der Söhne werden stumpf*?", footnotes: ["℘ 2Mo 20,5; Jer 31,29; Kla 5,7"] },
      { number: 3, text: "So wahr ich lebe, spricht der Herr, HERR*, wenn ihr diesen Spruch in Israel noch gebraucht*!", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "s. Anm. zu Kap. 17,19"] },
      { number: 4, text: "Siehe, alle Seelen gehören mir*; wie die Seele des Vaters, so auch die Seele des Sohnes. Sie gehören mir. Die Seele, die sündigt, sie <allein> soll sterben*.", footnotes: ["℘ Jes 42,5; 57,16", "℘ V. 20; Kap. 3,18; 33,8; 5Mo 24,16; Hi 8,4; Röm 2,9"] },
      { number: 5, text: "Und wenn jemand gerecht ist und Recht und Gerechtigkeit übt*,", footnotes: ["℘ Jer 7,5; Apg 10,35"] },
      { number: 6, text: "auf den Bergen nicht isst* und seine Augen nicht erhebt zu den Götzen des Hauses Israel und die Frau seines Nächsten nicht unrein macht und einer Frau <zur Zeit ihrer> Absonderung* nicht naht*", footnotes: ["℘ Kap. 22,9", "o. Ausscheidung; d. i. die Monatsregel", "℘ 3Mo 18,19.20"] },
      { number: 7, text: "und niemanden unterdrückt, das Pfand des Schuldners* zurückgibt*, keinen Raub begeht*, sein Brot dem Hungernden gibt und den Nackten mit Kleidung bedeckt*,", footnotes: ["so üs. LXX; Mas. T.: »sein Pfand, die Schuld«, das könnte meinen: das Pfand für seine Schuldforderung", "℘ Kap. 33,15; 2Mo 22,25", "w. <wer> Raub nicht raubt\n℘ Jer 22,3", "℘ Kap. 16,49; Jes 58,7"] },
      { number: 8, text: "auf Zins nicht gibt* und Aufschlag nicht nimmt, seine Hand vom Unrecht zurückhält, rechtes Gericht übt* zwischen Mann und Mann*,", footnotes: ["℘ 5Mo 23,20.21; Neh 5,10", "w. zuverlässigen Rechtsspruch fällt", "℘ 5Mo 16,19.20; Sach 8,16"] },
      { number: 9, text: "in meinen Ordnungen lebt* und meine Rechtsbestimmungen hält, um <sie> getreu zu befolgen*: Gerecht ist er*. Leben soll er*, spricht der Herr, HERR*. —", footnotes: ["w. geht", "℘ 1Kö 9,4", "℘ 5Mo 6,25", "℘ Kap. 20,11; Spr 12,28", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 10, text: "Zeugt er aber einen gewalttätigen* Sohn, der Blut vergießt und eines von diesen <Dingen> tut* —", footnotes: ["w. räuberischen", "T.; Mas. T.: und — wehe! — <etwas> von einem von diesen <Dingen> tut"] },
      { number: 11, text: "er selbst aber hat alles das nicht getan —, wenn <der> sogar auf den Bergen isst und die Frau seines Nächsten unrein macht," },
      { number: 12, text: "den Elenden und den Armen unterdrückt, Raub an sich reißt, das Pfand nicht zurückgibt und seine Augen zu den Götzen erhebt*, Gräuel verübt,", footnotes: ["℘ Kap. 33,25"] },
      { number: 13, text: "auf Zins gibt und Aufschlag nimmt: Sollte er leben? Er soll nicht leben! All diese Gräuel hat er verübt: Er muss getötet werden, sein Blut wird auf ihm sein*.", footnotes: ["℘ 3Mo 20,9; Hi 34,11"] },
      { number: 14, text: "Und siehe, der zeugt einen Sohn, und dieser sieht alle Sünden seines Vaters, die der tut; er sieht <sie> und tut nicht desgleichen*:", footnotes: ["℘ Kap. 20,18; 2Kö 22,1.2"] },
      { number: 15, text: "Er isst nicht auf den Bergen und erhebt seine Augen nicht zu den Götzen des Hauses Israel, er macht nicht die Frau seines Nächsten unrein," },
      { number: 16, text: "und er unterdrückt niemanden, pfändet kein Pfand und begeht* keinen Raub, er gibt dem Hungernden sein Brot und bedeckt den Nackten mit Kleidung,", footnotes: ["w. raubt"] },
      { number: 17, text: "er hält seine Hand vom Unrecht* zurück, nimmt weder Zins noch Aufschlag, er befolgt meine Rechtsbestimmungen, lebt* in meinen Ordnungen*: Der wird nicht wegen der Schuld seines Vaters sterben. Leben soll er!", footnotes: ["so liest LXX entsprechend V. 8; Mas. T.: vom Elenden", "w. geht", "℘ Ps 119,3"] },
      { number: 18, text: "Sein Vater, weil er Erpressung* verübt, am Bruder Raub begangen* und das, was nicht gut war, inmitten seines Volkes getan hat: siehe, er <allein> soll um seiner Schuld willen sterben.", footnotes: ["o. Gewalttat", "w. <vom> Bruder . . . geraubt hat"] },
      { number: 19, text: "*Ihr aber sagt: Warum trägt der Sohn nicht an der Schuld des Vaters <mit>? Dabei hat der Sohn <doch> Recht und Gerechtigkeit geübt, hat alle meine Ordnungen bewahrt und sie getan: Leben soll er!", footnotes: ["℘ V. 19-32: Kap. 33,10-20"] },
      { number: 20, text: "Die Seele, die sündigt, sie soll sterben*. Ein Sohn soll nicht an der Schuld des Vaters <mit>tragen, und ein Vater soll nicht an der Schuld des Sohnes <mit>tragen. Die Gerechtigkeit des Gerechten soll auf ihm sein, und die Gottlosigkeit des Gottlosen* soll auf ihm sein*.", footnotes: ["℘ 2Mo 32,33; Röm 6,23", "o. die Ungerechtigkeit des Ungerechten", "℘ 2Chr 6,23; Gal 6,7.8"] },
      { number: 21, text: "Wenn aber der Gottlose* umkehrt von all seinen Sünden, die er getan hat, und alle meine Ordnungen bewahrt und Recht und Gerechtigkeit übt: Leben soll er <und> nicht sterben*.", footnotes: ["o. der Ungerechte", "℘ Jer 18,8; 26,3"] },
      { number: 22, text: "All seine Vergehen, die er begangen hat, sollen ihm nicht angerechnet werden*; um seiner Gerechtigkeit willen, die er geübt hat, soll er leben*.", footnotes: ["℘ Ps 103,12", "℘ Röm 2,7"] },
      { number: 23, text: "Sollte ich wirklich Gefallen haben am Tod des Gottlosen*, spricht der Herr, HERR*, nicht <vielmehr> daran, dass er von seinen Wegen umkehrt und lebt*?", footnotes: ["o. des Ungerechten", "w. ist der Ausspruch des Herrn, HERRN", "℘ 2Sam 14,14; Lk 15,10; 1Tim 2,4; 2Petr 3,9"] },
      { number: 24, text: "Wenn aber ein Gerechter von seiner Gerechtigkeit umkehrt und Unrecht tut nach all den Gräueln, die der Gottlose* verübt hat — tut er es, sollte er leben? —: An all seine gerechten Taten*, die er getan hat, soll nicht gedacht werden. Wegen seiner Untreue, die er begangen, und wegen seiner Sünde, die er getan hat, ihretwegen soll er sterben*.", footnotes: ["o. der Ungerechte", "w. Gerechtigkeiten", "℘ Kap. 3,20; 2Petr 2,20"] },
      { number: 25, text: "Aber ihr sagt: »Der Weg des Herrn ist nicht recht.«* Hört doch, Haus Israel: Ist mein Weg nicht recht? Sind nicht <vielmehr> eure Wege nicht recht?", footnotes: ["℘ Spr 19,3"] },
      { number: 26, text: "Wenn ein Gerechter von seiner Gerechtigkeit umkehrt und Unrecht tut und um dieser <Sünden> willen stirbt, so stirbt er wegen seines Unrechts, das er getan hat." },
      { number: 27, text: "Wenn aber ein Gottloser von seiner Gottlosigkeit*, die er begangen hat, umkehrt und Recht und Gerechtigkeit übt: er wird seine Seele am Leben erhalten.", footnotes: ["o. Wenn aber der Ungerechte von seiner Ungerechtigkeit"] },
      { number: 28, text: "Sieht er es ein und kehrt er um von all seinen Vergehen, die er begangen hat: leben soll er <und> nicht sterben. —" },
      { number: 29, text: "Aber das Haus Israel sagt: »Der Weg des Herrn ist nicht recht.« Sind meine Wege nicht recht, Haus Israel?* Sind nicht <vielmehr> eure Wege nicht recht?", footnotes: ["℘ Ps 18,31"] },
      { number: 30, text: "Darum werde ich euch richten, Haus Israel, jeden nach seinen Wegen*, spricht der Herr, HERR*. Kehrt um* und wendet euch ab von allen euren Vergehen*, dass es euch nicht ein Anstoß zur Schuld wird!*", footnotes: ["℘ Kap. 7,3.27; 36,19; Jer 7,3; Mt 16,27", "w. ist der Ausspruch des Herrn, HERRN", "℘ Jer 3,22", "℘ Kap. 14,6; Apg 3,19.26", "℘ Lk 13,3.5"] },
      { number: 31, text: "Werft von euch alle eure Vergehen, mit denen ihr euch vergangen habt*, und schafft euch ein neues Herz und einen neuen Geist!* Ja, wozu wollt ihr sterben, Haus Israel?", footnotes: ["℘ Jes 55,7; Sach 1,3.4", "℘ Kap. 11,19; Jer 4,4; 44,4"] },
      { number: 32, text: "Denn ich habe kein Gefallen am Tod dessen, der sterben muss*, spricht der Herr, HERR*. So kehrt um*, damit ihr lebt!", footnotes: ["w. des Sterbenden\n℘ Jes 55,7; Sach 1,3.4", "w. ist der Ausspruch des Herrn, HERRN", "so mit der aram. Üs.; Mas. T.: wendet euch ab"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und du, erhebe ein Klagelied* über die Fürsten Israels,", heading: "Klagelied über das Königshaus von Juda", footnotes: ["℘ Kap. 26,17; 27,2"] },
      { number: 2, text: "und sage: Was war <doch> deine Mutter für eine Löwin unter Löwen! Sie lagerte unter Junglöwen, zog ihre Jungen groß." },
      { number: 3, text: "Und sie zog eins von ihren Jungen auf*, es wurde ein Junglöwe*; und er lernte Raub rauben, er fraß Menschen.", footnotes: ["o. sie erhöhte eins von ihren Jungen", "℘ Kap. 32,2; 2Chr 36,1; Sach 11,3"] },
      { number: 4, text: "Da bot man Nationen gegen ihn auf*, in ihrer Grube wurde er gefangen; und sie brachten ihn mit Haken* in das Land Ägypten.", footnotes: ["T.; Mas. T.: Und Nationen hörten auf ihn", "Das sind Haken, die durch die Nase gezogen wurden; vgl. Kap. 29,4; Hi 40,25"] },
      { number: 5, text: "Und als sie sah, dass ihre Hoffnung dahin, verloren war*, da nahm sie ein anderes von ihren Jungen und machte es zu einem Junglöwen.", footnotes: ["w. dass ihre Hoffnung sich als töricht erwiesen hatte, verloren war. — Diese Üs. beruht auf Änderung eines Buchstabens; Mas. T.: dass ihre Hoffnung erwartet wurde, verloren war"] },
      { number: 6, text: "Und es lebte* unter Löwen, wurde ein Junglöwe; und er lernte Raub rauben, er fraß Menschen.", footnotes: ["w. ging"] },
      { number: 7, text: "Und er zerbrach ihre Paläste*, ihre Städte legte er in Trümmer; und das Land und seine Fülle entsetzte sich* vor der Stimme seines Gebrülls*.", footnotes: ["Mas. T.: Und er erkannte seine Witwen", "o. lag öde da", "℘ Kap. 34,4; 2Kö 23,33-35; Jer 22,17"] },
      { number: 8, text: "Da setzte man gegen ihn die Nationen ringsum aus den Provinzen ein; und sie spannten ihr Fangnetz über ihn aus, in ihrer Grube wurde er gefangen*.", footnotes: ["℘ 2Kö 24,1.2; Kla 4,20"] },
      { number: 9, text: "Und sie setzten ihn mit Haken* in den Käfig und brachten ihn zum König von Babel, <und> er brachte ihn in Gewahrsam*, damit seine Stimme nicht mehr gehört würde* auf den Bergen Israels*.", footnotes: ["Das sind Haken, die durch die Nase gezogen wurden; vgl. Kap. 29,4; Hi 40,25", "so mit LXX; Mas. T.: sie brachten ihn in Fangnetzen", "℘ Kap. 34,4; 2Kö 23,33-35; Jer 22,17", "℘ 2Chr 36,6"] },
      { number: 10, text: "Deine Mutter glich einem Weinstock*, an Wassern gepflanzt; er wurde fruchtbar und voller Ranken vom vielen Wasser.", footnotes: ["so mit aram. Üs.; Mas. T.: Deine Mutter war wie ein Weinstock in deinem Blut\n℘ Kap. 17,6; Jes 5,1"] },
      { number: 11, text: "Und er bekam starke Zweige, <geeignet> für Herrscher-Zepter*, und sein Wuchs erhob sich empor zwischen das dichte Laub <der Bäume>*; und er wurde sichtbar durch seine Höhe, durch die Menge seiner Ranken*.", footnotes: ["℘ Esr 4,20", "Andere streichen im Mas. T. 2 Buchstaben und lesen: zwischen die Wolken", "℘ 1Kö 5,1"] },
      { number: 12, text: "Aber er wurde ausgerissen im Zorn, zu Boden geworfen*, und der Ostwind ließ seine Frucht verdorren*; sie wurden abgerissen und vertrockneten; sein starker Zweig* — Feuer verzehrte ihn*.", footnotes: ["℘ Ps 80,13", "℘ Kap. 17,10; Hos 13,15", "Diese Üs. ergibt sich, wenn man dem Versmaß folgt. Mas. T.: Es wurden abgerissen und vertrockneten sein starker Zweig", "℘ Kap. 15,2-7; 5Mo 32,22"] },
      { number: 13, text: "Und nun ist er in die Wüste gepflanzt, in ein dürres und durstiges Land*.", footnotes: ["℘ 2Chr 36,20"] },
      { number: 14, text: "Und ein Feuer ging vom Gezweig seiner Triebe aus <und> hat seine Frucht verzehrt*; und kein starker Zweig war <mehr> an ihm, kein Zepter zum Herrschen*. Ein Klagelied ist es, und zum Klagelied wurde es.", footnotes: ["℘ Ri 9,15; 2Kö 24,20", "℘ Hos 3,4"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und es geschah im siebten Jahr, im fünften <Monat>, am Zehnten des Monats*, da kamen Männer von den Ältesten Israels, um den HERRN zu befragen; und sie setzten sich vor mir nieder.", heading: "Die Geschichte der Untreue Israels und Neuanfang nach dem Gericht", footnotes: ["℘ Kap. 8,1"] },
      { number: 2, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 3, text: "Menschensohn, rede zu den Ältesten Israels, und sage zu ihnen: So spricht der Herr, HERR: Um mich zu befragen, seid ihr gekommen? So wahr ich lebe, wenn ich mich von euch befragen lasse*!, spricht der Herr, HERR*.", footnotes: ["s. Anm. zu Kap. 17,19\n℘ V. 31; Kap. 14,1-3; Jes 58,2", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 4, text: "Willst du sie <nicht vielmehr> richten*? Willst du richten, Menschensohn? Die Gräuel ihrer Väter lass sie erkennen*,", footnotes: ["℘ Kap. 22,2", "℘ Kap. 16,2; 23,36"] },
      { number: 5, text: "und sage zu ihnen: So spricht der Herr, HERR: An dem Tag, als ich Israel erwählte*, da erhob ich meine Hand der Nachkommenschaft des Hauses Jakob <zum Schwur>* und gab mich ihnen im Land Ägypten kund und erhob meine Hand ihnen <zum Schwur> und sprach: Ich bin der HERR, euer Gott!*", footnotes: ["℘ 5Mo 7,6.7", "℘ 2Mo 6,8", "℘ Kap. 34,24; 2Mo 20,2; 3Mo 18,2.30"] },
      { number: 6, text: "An jenem Tag erhob ich für sie meine Hand <zum Schwur>, dass ich sie aus dem Land Ägypten herausführen würde* in ein Land, das ich für sie ausgekundschaftet hatte, das von Milch und Honig überfließt*; die Zierde ist es unter allen Ländern*.", footnotes: ["℘ Neh 9,9-12", "℘ V. 15; 2Mo 3,8.17", "℘ V. 15; 5Mo 3,25; Jer 3,19; Dan 8,9"] },
      { number: 7, text: "Und ich sprach zu ihnen: Werft die Scheusale weg, an denen eure Augen hängen*, und macht euch nicht mit den Götzen Ägyptens* unrein! Ich bin der HERR, euer Gott*.", footnotes: ["w. Werft jeder die Scheusale seiner Augen weg", "℘ Jos 24,14", "℘ Kap. 34,24; 2Mo 20,2; 3Mo 18,2.30"] },
      { number: 8, text: "Aber sie waren widerspenstig gegen mich und wollten nicht auf mich hören*; keiner warf die Scheusale weg, an denen seine Augen hingen,* und die Götzen Ägyptens verließen sie nicht*. Da gedachte ich, meinen Grimm über sie auszugießen*, meinen Zorn an ihnen zu vollenden mitten im Land Ägypten.", footnotes: ["℘ 5Mo 9,24; Ps 78,8; 81,12", "w. die Scheusale ihrer Augen warfen sie nicht weg — jeder!", "℘ Kap. 23,3.8", "℘ V. 13.21; Kap. 7,8"] },
      { number: 9, text: "Aber ich handelte <gnädig> um meines Namens willen*, damit er nicht entweiht würde vor den Augen der Nationen, in deren Mitte sie waren und vor deren Augen ich mich ihnen kundgegeben hatte, <indem ich schwor,> sie aus dem Land Ägypten herauszuführen*.", footnotes: ["℘ V. 14.22; Kap. 36,21.22; 1Sam 12,22", "℘ V. 14; 5Mo 9,28"] },
      { number: 10, text: "Und ich führte sie aus dem Land Ägypten und brachte sie in die Wüste." },
      { number: 11, text: "Und ich gab ihnen meine Ordnungen, und meine Rechtsbestimmungen ließ ich sie wissen*, durch die der Mensch, wenn er sie tut, lebt*.", footnotes: ["℘ 5Mo 4,5; Neh 9,13.14; Ps 147,19", "℘ V. 21; Kap. 18,9; 33,15.16; 3Mo 18,5; 5Mo 30,19; Spr 6,23; Joh 5,39"] },
      { number: 12, text: "Und auch meine Sabbate gab ich ihnen, dass sie zum <Bundes>zeichen seien zwischen mir und ihnen, damit man erkenne, dass ich, der HERR, es bin, der sie heiligt*. —", footnotes: ["℘ Kap. 37,28; 2Mo 31,13"] },
      { number: 13, text: "Aber das Haus Israel war widerspenstig gegen mich in der Wüste*; sie lebten* nicht in meinen Ordnungen und verwarfen meine Rechtsbestimmungen, durch die der Mensch, wenn er sie tut, lebt; und meine Sabbate entweihten sie sehr*. Da gedachte ich, meinen Grimm in der Wüste über sie auszugießen, um sie zu vernichten*.", footnotes: ["℘ 5Mo 9,7", "w. gingen", "℘ V. 16.24; Neh 13,17.18", "℘ 4Mo 14,12"] },
      { number: 14, text: "Aber ich handelte <gnädig> um meines Namens willen, damit er nicht entweiht würde vor den Augen der Nationen, vor deren Augen ich sie herausgeführt hatte." },
      { number: 15, text: "Doch auch erhob ich ihnen meine Hand in der Wüste <zum Schwur>, dass ich sie nicht in das Land bringen würde, das ich <ihnen> gegeben hatte*, das von Milch und Honig überfließt — die Zierde ist es unter allen Ländern* —,", footnotes: ["℘ V. 6; 5Mo 1,34.35; Ps 106,26", "℘ Kap. 34,24; 2Mo 20,2; 3Mo 18,2.30"] },
      { number: 16, text: "weil sie meine Rechtsbestimmungen verwarfen und in meinen Ordnungen nicht lebten und meine Sabbate entweihten; denn ihr Herz lief ihren Götzen nach*.", footnotes: ["℘ Am 5,26"] },
      { number: 17, text: "Aber ich war ihretwegen betrübt*, so dass ich sie nicht vernichtete, und ich machte mit ihnen kein Ende in der Wüste*.", footnotes: ["w. mein Auge floss (weinte) ihretwegen", "℘ Neh 9,19; Ps 78,38"] },
      { number: 18, text: "Und ich sprach zu ihren Söhnen in der Wüste: Lebt* nicht in den Ordnungen eurer Väter, und ihre Rechtsbestimmungen bewahrt nicht, und mit ihren Götzen macht euch nicht unrein*!", footnotes: ["w. Geht", "℘ Kap. 18,14-17; 1Petr 1,18"] },
      { number: 19, text: "Ich bin der HERR, euer Gott: Lebt* in meinen Ordnungen, und bewahrt meine Rechtsbestimmungen und tut sie!*", footnotes: ["w. Geht", "℘ 3Mo 18,4; 5Mo 5,32; Ps 119,4"] },
      { number: 20, text: "Und heiligt meine Sabbate*, damit sie zum <Bundes>zeichen seien zwischen mir und euch, damit ihr erkennt, dass ich der HERR, euer Gott bin. —", footnotes: ["℘ Kap. 22,8; 2Mo 20,8"] },
      { number: 21, text: "Aber <auch> die Söhne waren widerspenstig gegen mich*; in meinen Ordnungen lebten* sie nicht, und meine Rechtsbestimmungen bewahrten sie nicht, sie zu tun, durch die <doch> der Mensch, wenn er sie tut, lebt. Und meine Sabbate entweihten sie. Da gedachte ich, meinen Grimm über sie auszugießen, meinen Zorn an ihnen zu vollenden in der Wüste.", footnotes: ["℘ 5Mo 31,27; Ps 78,10", "w. gingen"] },
      { number: 22, text: "Aber ich wandte meine Hand zurück und handelte <gnädig> um meines Namens willen, damit er nicht entweiht würde vor den Augen der Nationen, vor deren Augen ich sie herausgeführt hatte." },
      { number: 23, text: "<Doch> auch erhob ich ihnen meine Hand in der Wüste <zum Schwur>, dass ich sie unter die Nationen versprengen und sie in die Länder zerstreuen würde*,", footnotes: ["℘ Kap. 11,16; 5Mo 4,27; Ps 106,27"] },
      { number: 24, text: "weil sie meine Rechtsbestimmungen nicht taten und meine Ordnungen verwarfen und meine Sabbate entweihten und ihre Augen hinter den Götzen ihrer Väter her waren*.", footnotes: ["℘ Jer 2,7"] },
      { number: 25, text: "Und auch ich gab ihnen Ordnungen, die nicht gut waren, und Rechtsbestimmungen, durch die sie nicht leben konnten*.", footnotes: ["℘ Röm 7,9.10"] },
      { number: 26, text: "Und ich machte sie durch ihre Gaben unrein, indem sie alle Erstgeburt des Mutterleibes durch <das Feuer> gehen ließen*; damit ich ihnen Entsetzen einflößte, damit sie erkannten, dass ich der HERR bin.", footnotes: ["℘ Kap. 16,20.21; 2Kö 16,3"] },
      { number: 27, text: "Darum, Menschensohn, rede zum Haus Israel und sage zu ihnen: So spricht der Herr, HERR: <Auch> noch dadurch haben eure Väter mich gelästert, dass sie Untreue gegen mich begingen*:", footnotes: ["℘ Kap. 39,26"] },
      { number: 28, text: "Als ich sie in das Land gebracht, das ihnen zu geben ich meine Hand <zum Schwur> erhoben hatte, wählten sie <sich> jeden hohen Hügel und jeden dicht belaubten Baum aus und opferten dort ihre Schlachtopfer und gaben dort ihre widerwärtigen Opfergaben* und brachten dort ihren wohlgefälligen Geruch* dar und spendeten ihre Trankopfer*.", footnotes: ["w. die Kränkung (o. Reizung) ihrer Opfergaben\n℘ 3Mo 17,5; 2Kö 17,9", "w. den Geruch ihrer Beschwichtigungen; s. Anm. zu Kap. 6,13", "℘ Kap. 6,13; 2Kö 17,10-12; Ps 78,58; Jes 65,7; Jer 32,30"] },
      { number: 29, text: "Und ich sprach zu ihnen: Was ist das für eine Höhe, wohin ihr geht*? So wurde ihr Name Bama* genannt, bis auf diesen Tag.", footnotes: ["℘ Kap. 16,24.25", "d. h. Höhe"] },
      { number: 30, text: "Darum sage zum Haus Israel: So spricht der Herr, HERR: Wollt ihr euch auf die Weise eurer Väter unrein machen und ihren Scheusalen nachhuren*?", footnotes: ["℘ 2Chr 30,7; Ps 106,39; Jer 7,9"] },
      { number: 31, text: "Ja, indem ihr eure Gaben darbringt* und eure Söhne durchs Feuer gehen lasst*, macht ihr euch unrein bis heute an all euren Götzen*! Da sollte ich mich von euch befragen lassen, Haus Israel? So wahr ich lebe, spricht der Herr, HERR*, wenn ich mich von euch befragen lasse*!", footnotes: ["w. indem ihr eure Gaben hochhebt; d. h. der Gottheit weiht", "℘ Kap. 23,37; Ps 106,37; Jes 57,5; Jer 7,31", "o. für all eure Götzen", "w. ist der Ausspruch des Herrn, HERRN", "s. Anm. zu Kap. 17,19\n℘ V. 3"] },
      { number: 32, text: "Und was in eurem Geist aufgestiegen ist, soll niemals geschehen*, dass ihr <nämlich> sagt: Wir wollen sein wie die Nationen und wie die Geschlechter der Länder, um im Dienst von Holz und Stein zu stehen*.", footnotes: ["℘ Ps 33,10; Spr 19,21", "℘ Jer 44,17; Hos 4,12"] },
      { number: 33, text: "So wahr ich lebe, spricht der Herr, HERR*, wenn ich nicht mit starker Hand und mit ausgestrecktem Arm* und mit ausgegossenem Grimm als König über euch herrschen werde*!", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "℘ 2Mo 6,6", "s. Anm. zu Kap. 17,19\n℘ Jer 21,5"] },
      { number: 34, text: "Und ich werde euch aus den Völkern herausführen und euch aus den Ländern, in die ihr zerstreut worden seid*, mit starker Hand und mit ausgestrecktem Arm und mit ausgegossenem Grimm sammeln.", footnotes: ["℘ Kap. 11,17; Jer 31,8; 32,37"] },
      { number: 35, text: "Und ich werde euch in die Wüste der Völker bringen* und dort mit euch ins Gericht* gehen von Angesicht zu Angesicht;", footnotes: ["℘ Jer 31,2; Hos 2,16", "w. vor Gericht"] },
      { number: 36, text: "wie ich mit euren Vätern ins Gericht* gegangen bin in der Wüste des Landes Ägypten, ebenso werde ich mit euch ins Gericht* gehen*, spricht der Herr, HERR*.", footnotes: ["w. vor Gericht", "w. vor Gericht", "℘ 4Mo 14,21-35", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 37, text: "Und ich werde euch unter dem <Hirten>stab hindurchziehen lassen* und euch abgezählt* hineinbringen.", footnotes: ["℘ Kap. 34,17", "so mit LXX; Mas. T.: euch in das Band (o. die Überlieferung) des Bundes"] },
      { number: 38, text: "Und ich werde von euch ausscheiden, die sich empörten und mit mir brachen*; ich werde sie aus dem Land ihrer Fremdlingschaft herausführen, aber in das Land Israel sollen sie* nicht kommen*. Und ihr werdet erkennen, dass ich der HERR bin.", footnotes: ["℘ Kap. 34,20.22; Jer 29,32; Mt 25,33", "so mit einigen hebr. Handschr. und den alten Üs.; Mas. T.: soll er", "℘ Kap. 13,9; Jer 44,14"] },
      { number: 39, text: "Ihr aber, Haus Israel, so spricht der Herr, HERR: Geht <doch> hin, dient ein jeder seinen Götzen!* Aber nachher — solltet ihr wirklich nicht auf mich hören? — dann werdet ihr meinen heiligen Namen nicht mehr entweihen mit euren Gaben und mit euren Götzen.", footnotes: ["℘ Jos 24,15; Ri 10,14; Am 4,4"] },
      { number: 40, text: "Denn auf meinem heiligen Berg, auf dem hohen Berg Israels*, spricht der Herr, HERR*, dort wird mir das ganze Haus Israel insgesamt dienen im Land*. Dort werde ich sie wohlgefällig annehmen*, und dort werde ich eure Hebopfer einfordern und die Erstlinge eurer Geschenke, all eure heiligen Gaben*.", footnotes: ["℘ Kap. 17,23", "w. ist der Ausspruch des Herrn, HERRN", "℘ Jer 31,12", "℘ Kap. 43,27; Jes 56,7", "o. all eure Weihegaben\n℘ Mal 3,4"] },
      { number: 41, text: "Beim wohlgefälligen Geruch* <eurer Opfer> werde ich euch wohlgefällig annehmen, wenn ich euch aus den Völkern herausführe und euch aus den Ländern sammle, in die ihr zerstreut worden seid*, und ich mich an euch als heilig erweise vor den Augen der Nationen*.", footnotes: ["w. Beim Geruch der Befriedigung o. der Beschwichtigung", "℘ Kap. 11,17", "℘ Kap. 28,25; 36,23; 38,16.23; 39,27; 4Mo 20,13"] },
      { number: 42, text: "Und ihr werdet erkennen, dass ich der HERR bin, wenn ich euch in das Land Israel bringe, in das Land, <über> das ich meine Hand <zum Schwur> erhoben habe, es euren Vätern zu geben." },
      { number: 43, text: "Und ihr werdet dort an eure Wege und all eure Taten denken, mit denen ihr euch unrein gemacht habt*; und ihr werdet an euch selbst Ekel empfinden wegen all eurer bösen Taten, die ihr begangen habt.", footnotes: ["℘ Kap. 6,9; 16,61"] },
      { number: 44, text: "Und ihr werdet erkennen, dass ich der HERR bin, wenn ich mit euch handle um meines Namens willen* <und> nicht nach euren bösen Wegen und nach euren Verderben bringenden Taten*, Haus Israel, spricht der Herr, HERR*.", footnotes: ["℘ Ps 79,9", "℘ Kap. 36,21.22", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Gerichtsworte und Zeichenhandlungen: Das Schwert des HERRN", footnotes: ["℘ V. 1-5: Kap. 15"] },
      { number: 2, text: "Menschensohn, richte dein Gesicht nach Süden, und rede* zum Mittag hin und weissage gegen den Wald des Gefildes* im Südland*!", footnotes: ["w. lass <deine Worte> herabfließen, o. lass <die Rede> strömen", "℘ Jes 37,24", "hebr. Negev; d. i. die übliche Bezeichnung für den Süden Palästinas"] },
      { number: 3, text: "Und sage zum Wald des Südlandes: Höre das Wort des HERRN! So spricht der Herr, HERR: Siehe, ich will in dir ein Feuer anzünden; das wird jeden grünen Baum und jeden dürren Baum in dir verzehren*. Die lodernde Flamme wird nicht verlöschen*, und vom Süden bis zum Norden* werden alle Gesichter durch sie versengt.", footnotes: ["℘ Ps 80,17; 83,15; Jer 21,14; Am 5,6; 7,4", "℘ Kap. 24,9; Jer 17,27", "℘ V. 9.10"] },
      { number: 4, text: "Und alles Fleisch soll sehen, dass ich, der HERR, es angezündet habe. Es wird nicht erlöschen*.", footnotes: ["℘ V. 9.10"] },
      { number: 5, text: "Und ich sprach: Ach, Herr, HERR! Sie sagen von mir: Redet er nicht in Gleichnissen?*", footnotes: ["℘ Kap. 17,2; Mt 13,10"] },
      { number: 6, text: "Und das Wort des HERRN geschah zu mir:" },
      { number: 7, text: "Menschensohn, richte dein Gesicht nach Jerusalem, und rede* gegen die Heiligtümer* und weissage gegen das Land Israel*!", footnotes: ["w. lass <deine Worte> herabfließen, o. lass <die Rede> strömen", "℘ Jer 26,12", "℘ Kap. 6,2; 7,2"] },
      { number: 8, text: "Und sprich zu dem Land Israel: So spricht der HERR: Siehe, ich will an dich und werde mein Schwert aus seiner Scheide ziehen; und ich werde aus dir den Gerechten und den Ungerechten* ausrotten*!", footnotes: ["o. den Gottlosen", "℘ Kap. 14,17"] },
      { number: 9, text: "Weil ich aus dir den Gerechten und den Ungerechten* ausrotten will, darum soll mein Schwert aus seiner Scheide fahren gegen alles Fleisch vom Süden bis zum Norden*.", footnotes: ["o. den Gottlosen", "℘ V. 3; Hi 9,22; Jer 12,12; 47,7"] },
      { number: 10, text: "Und alles Fleisch wird erkennen, dass ich, der HERR, mein Schwert aus seiner Scheide gezogen habe; es soll nicht wieder <dahin> zurückkehren*.", footnotes: ["℘ V. 4; Jer 23,20"] },
      { number: 11, text: "Und du, Menschensohn, stöhne! Mit brechenden Hüften und mit bitterem <Schmerz> sollst du vor ihren Augen stöhnen*!", footnotes: ["℘ Est 4,1; Jes 22,4"] },
      { number: 12, text: "Und es soll geschehen, wenn sie zu dir sagen: »Weswegen stöhnst du?«, dann sollst du sagen: »Wegen der kommenden Nachricht*.« Und jedes Herz wird zerschmelzen, und alle Hände werden erschlaffen, und jeder Geist wird verzagen, und alle Knie werden von Wasser triefen*. Siehe, es kommt und geschieht*, spricht der Herr, HERR*.", footnotes: ["w. Wegen der Nachricht, weil sie kommt", "℘ Kap. 7,17; Jes 13,7", "℘ Joe 2,1", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 13, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 14, text: "Menschensohn, weissage! Und du sollst sagen: So spricht der Herr: Sage: Ein Schwert, ein Schwert, geschärft und auch geschliffen*!", footnotes: ["℘ Jer 47,7"] },
      { number: 15, text: "Damit es ein Schlachten anrichtet, ist es geschärft; damit es blitzt, ist es geschliffen*. — Oder sollen wir uns freuen <und sagen>: Das Zepter meines Sohnes verwirft alles Holz?* —", footnotes: ["℘ V. 33", "o. Oder sollen wir uns freuen? Die für meinen Sohn bestimmte Rute verachtet jedes <andere> Holz."] },
      { number: 16, text: "Und man hat es zum Schleifen gegeben, um es mit der Faust zu packen. Geschärft ist es, das Schwert, es ist geschliffen, damit man es in die Hand eines Mörders gebe*.", footnotes: ["℘ Kap. 28,23; Offb 6,4"] },
      { number: 17, text: "Schreie um Hilfe und heule, Menschensohn! Denn es richtet sich gegen mein Volk, es <richtet sich> gegen alle Fürsten Israels: Sie sind dem Schwert verfallen samt meinem Volk*. Darum schlag dir auf die Hüften*!", footnotes: ["℘ Jer 6,25", "℘ Kap. 36,31; Jer 31,19"] },
      { number: 18, text: "Denn die Probe ist gemacht. Und warum sollte es, wenn du sogar das Zepter* verwirfst, nicht geschehen*?, spricht der Herr, HERR*. —", footnotes: ["o. die Rute; vgl. Anm. zu V. 15", "So konnte der Text vor der Festlegung durch die Masoreten verstanden werden; Mas. T. lautet jetzt: Und warum — wenn sogar das verachtende Zepter nicht sein wird?", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 19, text: "Und du, Menschensohn, weissage und schlag die Hände zusammen*! Da verdoppelt sich das Schwert, <ja> verdreifacht sich*, ein Schwert der Erschlagenen ist es, *ein gewaltiges Schwert der Erschlagenen*, das tief in sie eindringt*.", footnotes: ["℘ Kap. 6,11; 22,13", "so mit Vulg.; Mas. T.: da verdoppelt sich das Schwert, <und zwar> sein Drittel", "so mit anderer Wortabtrennung bei zwei Wörtern. Mas. T.: ein Schwert des erschlagenen Gewaltigen", "so mit anderer Wortabtrennung bei zwei Wörtern. Mas. T.: ein Schwert des erschlagenen Gewaltigen", "o. das sie umkreist"] },
      { number: 20, text: "Damit das Herz verzage und viele zum Stürzen gebracht werden*, bringe ich an all ihre Tore das Schlachten* des Schwertes! Wehe! Zum Blitzen ist es gemacht, zum Schlachten geschärft*.", footnotes: ["so in Anlehnung an LXX und Vulg.; Mas. T.: und es die Anstöße zahlreich mache", "so mit LXX; die Bedeutung des im Mas. T. stehenden Wortes ist unbekannt", "T.; Mas. T.: verhüllt; nach anderen: gezückt"] },
      { number: 21, text: "*Erweise deine Schärfe, <und> wende dich nach rechts, wende dich nach links*, wohin deine Schneide <gerade> gerichtet ist!", footnotes: ["so mit LXX und Vulg.; Mas. T.: Sammle dich, wende dich nach rechts, lass legen, wende dich nach links", "so mit LXX und Vulg.; Mas. T.: Sammle dich, wende dich nach rechts, lass legen, wende dich nach links"] },
      { number: 22, text: "Und auch ich will meine Hände zusammenschlagen und meinen Grimm stillen*. Ich, der HERR, habe geredet.", footnotes: ["℘ Kap. 5,13"] },
      { number: 23, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Das Schwert des Königs von Babel" },
      { number: 24, text: "Und du, Menschensohn, mache dir zwei Wege, auf denen das Schwert des Königs von Babel kommt! Von einem Land sollen sie beide ausgehen. *Und setze* einen Wegweiser, an den Anfang des Weges zur Stadt setze* <ihn>!", footnotes: ["Andere nehmen als ursprünglichen Text an: Und je einen Wegweiser sollst du am Anfang eines jeden Weges anbringen — 25 damit das Schwert komme —: »Rabba der Söhne Ammon« und »Juda, das <nur noch> in Jerusalem befestigt ist«.", "w. rode", "w. rode"] },
      { number: 25, text: "Du sollst einen Weg machen, damit das Schwert komme nach Rabba* der Söhne Ammon und nach Juda, das <nur noch> in Jerusalem befestigt ist.*", footnotes: ["℘ Kap. 25,5; Jer 49,1.2; Am 1,14", "Andere nehmen als ursprünglichen Text an: Und je einen Wegweiser sollst du am Anfang eines jeden Weges anbringen — 25 damit das Schwert komme —: »Rabba der Söhne Ammon« und »Juda, das <nur noch> in Jerusalem befestigt ist«.\n℘ Ps 48,13.14"] },
      { number: 26, text: "Denn der König von Babel bleibt am Kreuzweg stehen, am Anfang der beiden Wege, um das Losorakel zu befragen*; er schüttelt die Pfeile, befragt die Terafim*, beschaut die Leber.", footnotes: ["℘ Jes 47,12", "℘ Ri 17,5"] },
      { number: 27, text: "In seiner Rechten ist das Losorakel »Jerusalem«, dass er Sturmböcke aufstelle, den Mund öffne mit Geschrei*, die Stimme erhebe mit Kriegsgeschrei, Sturmböcke gegen die Tore aufstelle, Belagerungswälle aufschütte und Belagerungstürme baue*. —", footnotes: ["so mit LXX; Mas. T.: mit Mord", "℘ Kap. 4,2; Jer 32,24; 52,4"] },
      { number: 28, text: "In ihren Augen* aber ist es ihnen wie ein falsches Orakel — sie haben ja die heiligsten Eide* —; er aber bringt <ihre> Schuld in Erinnerung, damit sie gefasst werden*.", footnotes: ["d. i. in den Augen der Jerusalemer", "w. Eide der Eide", "℘ Kap. 17,13-20; 2Chr 36,17; Hos 9,9"] },
      { number: 29, text: "Darum, so spricht der Herr, HERR: Weil ihr eure Schuld in Erinnerung bringt, indem eure Verbrechen offenbar werden, so dass eure Sünden in allen euren Taten gesehen werden*, weil ihr angezeigt worden seid*, werdet ihr mit <harter> Hand gefasst werden*.", footnotes: ["℘ Jer 6,7", "w. genannt worden seid; möglich ist auch: weil <eure Sünden> von euch genannt worden sind", "℘ Hos 7,2"] },
      { number: 30, text: "Und du, erschlagener Gottloser*, Fürst Israels, dessen Tag gekommen ist* zur Zeit der endgültigen Strafe*!", footnotes: ["T.; Mas. T.: Und du, entweihter Gottloser", "℘ Kap. 12,10", "w. der Strafe des Endes, o. der Schuld des Endes; das hieße dann: der Schuld, die das Ende herbeiführt"] },
      { number: 31, text: "So spricht der Herr, HERR: Weg mit dem Kopfbund, und fort mit der Krone*! Nichts bleibt, wie es ist*. Das Niedrige soll erhöht und das Hohe erniedrigt werden*!", footnotes: ["℘ Ps 89,40; Hos 3,4", "w. Dies <bleibt> nicht dies", "℘ Lk 1,52"] },
      { number: 32, text: "Zu Trümmern, Trümmern, Trümmern mache ich es*. Auch das bleibt nicht — bis der kommt*, dem das Recht gehört*; dem gebe ich es*.", footnotes: ["d. i. Jerusalem; vgl. V. 27", "o. Auch das geschieht nicht, bis der kommt", "o. dem das Gericht zusteht", "℘ 1Mo 49,10; Mi 5,1; Sach 9,9"] },
      { number: 33, text: "*Und du, Menschensohn, weissage und sprich: So spricht der Herr, HERR, über die Söhne Ammon und über ihr Höhnen. Und sprich: Schwert, Schwert, zum Schlachten gezückt, zum Fressen geschliffen, damit es als Blitz dreinfahre*,", heading: "Das Unheilswort über Ammon", footnotes: ["℘ V. 33-37: Kap. 25,1-7; Jer 49,1-6; Am 1,13-15; Zef 2,8-11", "℘ V. 14-16"] },
      { number: 34, text: "um dich*, während man dir Nichtiges schaut, während man dir Lüge wahrsagt, an die Hälse der <tödlich> verwundeten Gottlosen zu legen, deren Tag gekommen ist zur Zeit der endgültigen Strafe*!", footnotes: ["d. i. das Schwert", "w. der Strafe des Endes, o. der Schuld des Endes; das hieße dann: der Schuld, die das Ende herbeiführt"] },
      { number: 35, text: "Stecke es wieder in seine Scheide! An dem Ort, wo du geschaffen bist, in dem Land deiner Herkunft, werde ich dich richten." },
      { number: 36, text: "Und ich werde meinen Zorn über dich ausgießen, das Feuer meines Grimms gegen dich anfachen*; und ich werde dich in die Hand roher* Männer geben, die Verderben schmieden*.", footnotes: ["℘ Kap. 22,21", "w. viehischer", "℘ Kap. 7,24; Hab 1,6.9"] },
      { number: 37, text: "Du wirst dem Feuer zum Fraß <gegeben> werden, dein Blut wird mitten im Land sein; an dich wird nicht mehr gedacht werden. Denn ich, der HERR, habe geredet." },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Jerusalem, die Blutstadt" },
      { number: 2, text: "Und du, Menschensohn, willst du richten, willst du richten die Stadt der Blutschuld*? So lass sie alle ihre Gräuel erkennen*,", footnotes: ["℘ Kap. 20,4; 24,6.9; 2Kö 21,16", "℘ Kap. 16,2"] },
      { number: 3, text: "und sage: So spricht der Herr, HERR: <Du> Stadt, die in ihrer Mitte Blut vergießt*, damit ihre <Gerichts>zeit komme, und die sich* Götzen macht, so dass sie sich unrein mache!*", footnotes: ["℘ Kap. 33,25; 2Kö 24,3.4; Jes 1,21; Mi 3,10", "w. bei sich", "℘ 2Kö 21,2-9; Ps 106,39"] },
      { number: 4, text: "Durch dein Blut, das du vergossen hast, bist du schuldig geworden; und durch deine Götzen, die du gemacht, hast du dich unrein gemacht; und du hast deine <Gerichts>tage herbeigeführt und bist zu deinen Jahren gekommen*. Darum habe ich dich zum Hohn für die Nationen gemacht und zum Gespött für alle Länder*.", footnotes: ["d. h. ans Ende deines Lebens", "℘ Kap. 23,32; Dan 9,16"] },
      { number: 5, text: "Die <dir> nahe und die von dir entfernt <wohnen>, verspotten dich, deren Ruf befleckt, deren Bestürzung gewaltig ist*. —", footnotes: ["℘ Ps 79,4"] },
      { number: 6, text: "Siehe, die Fürsten Israels waren in dir — jeder <pochte> auf seine Macht —, um Blut zu vergießen*.", footnotes: ["℘ Kap. 45,8; Jer 22,17; Mi 3,1-3; Zef 3,3.4"] },
      { number: 7, text: "Vater und Mutter verachtet man in dir*, dem Fremden tut man Gewalt an in deiner Mitte, Waise und Witwe unterdrückt man in dir*.", footnotes: ["℘ 5Mo 27,16", "℘ Ps 94,5.6; Jes 1,23"] },
      { number: 8, text: "Meine heiligen Dinge verachtest du, und meine Sabbate entweihst du*.", footnotes: ["℘ Kap. 20,20"] },
      { number: 9, text: "Verleumder sind in dir, um Blut zu vergießen*. Und auf den Bergen isst man in dir*, Schandtaten verübt man in deiner Mitte.", footnotes: ["℘ 3Mo 19,16; 1Sam 24,10", "℘ Kap. 18,6.11"] },
      { number: 10, text: "Die Blöße des Vaters deckt man auf in dir, die in ihrer Absonderung* Unreine missbraucht man in dir*.", footnotes: ["o. Ausscheidung; d. i. die Monatsregel", "℘ 3Mo 18,6-20"] },
      { number: 11, text: "Der eine verübt Gräuel mit der Frau seines Nächsten*, der andere macht seine Schwiegertochter durch Schandtat unrein, und ein anderer missbraucht in dir seine Schwester, die Tochter seines Vaters*.", footnotes: ["℘ Kap. 33,26; Jer 5,7", "℘ 3Mo 18,6-20"] },
      { number: 12, text: "Bestechungsgeschenke nimmt man in dir, um Blut zu vergießen*; Zins und Aufschlag nimmst du* und übervorteilst deinen Nächsten mit Gewalt*. Mich aber vergisst du*, spricht der Herr, HERR*.", footnotes: ["℘ 5Mo 27,25", "℘ 3Mo 25,37", "℘ Jer 6,13; 9,1; Am 8,4-6", "℘ Kap. 23,35; 5Mo 32,18", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 13, text: "Und siehe, ich schlage in meine Hand* wegen deines unrechten Gewinns, den du gemacht hast, und über deine Blutschuld, die in deiner Mitte ist.", footnotes: ["℘ Kap. 21,19.22"] },
      { number: 14, text: "Wird dein Herz festbleiben, oder werden deine Hände stark sein in den Tagen, da ich mit dir handeln werde? Ich, der HERR, habe geredet und werde handeln*.", footnotes: ["℘ Kap. 6,10; 17,24; 23,34; Jes 28,22"] },
      { number: 15, text: "Und ich werde dich versprengen unter die Nationen und dich zerstreuen in die Länder* und deine Unreinheit ganz aus dir wegschaffen*.", footnotes: ["℘ Kap. 5,10; 36,19", "℘ Kap. 23,27; 24,11"] },
      { number: 16, text: "Und du wirst durch dich selbst entweiht werden* vor den Augen der Nationen*; und du wirst erkennen, dass ich der HERR bin.", footnotes: ["d. h. durch deine eigene Schuld entweiht werden; andere nehmen als ursprünglichen Text an: So werde ich durch dich entweiht werden", "℘ Ps 9,17"] },
      { number: 17, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 18, text: "Menschensohn, das Haus Israel ist für mich zu Schlacken geworden*; sie alle sind Kupfer und Zinn und Eisen und Blei im Schmelzofen; Silberschlacken sind sie geworden*.", footnotes: ["℘ Ps 119,119; Jes 1,22; Jer 6,28", "T.; Mas. T.: Schlacken, Silber sind sie geworden"] },
      { number: 19, text: "Darum, so spricht der Herr, HERR: Weil ihr alle zu Schlacken geworden seid, darum, siehe, werde ich euch in Jerusalem zusammentun." },
      { number: 20, text: "<Wie> man Silber und Kupfer und Eisen und Blei und Zinn in einen Schmelzofen zusammentut, um Feuer darunter* anzublasen, um es zu schmelzen, so werde ich euch in meinem Zorn und in meinem Grimm zusammentun und euch hineinlegen und schmelzen.", footnotes: ["w. gegen ihn"] },
      { number: 21, text: "Und ich werde euch sammeln und das Feuer meines Grimms gegen euch anblasen*, dass ihr darin geschmolzen werdet.", footnotes: ["℘ Kap. 21,36; 5Mo 32,22"] },
      { number: 22, text: "Wie Silber im Ofen geschmolzen wird, so werdet ihr mitten in ihm* geschmolzen werden. Und ihr werdet erkennen, dass ich, der HERR, meinen Grimm über euch ausgegossen habe*.", footnotes: ["d. h. im Feuer meines Grimms", "℘ Kap. 7,9"] },
      { number: 23, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 24, text: "Menschensohn, sprich zu ihm: Du bist ein Land, das nicht benetzt*, nicht beregnet ist am Tag des Zorns,", footnotes: ["so mit LXX; Mas. T.: das nicht für rein erklärt"] },
      { number: 25, text: "*dessen Obere in seiner Mitte sind wie ein brüllender Löwe*, der Beute reißt. Seelen fressen sie*, Reichtum und Kostbarkeiten nehmen sie, seine Witwen lassen sie zahlreich werden in seiner Mitte.", footnotes: ["Die Üs. folgt LXX; Mas. T.: Verschwörung seiner Propheten ist in seiner Mitte wie ein brüllender Löwe", "Die Üs. folgt LXX; Mas. T.: Verschwörung seiner Propheten ist in seiner Mitte wie ein brüllender Löwe", "℘ Kla 4,13"] },
      { number: 26, text: "Seine Priester tun meinem Gesetz Gewalt an und entweihen meine heiligen Dinge*; zwischen heilig und nicht heilig unterscheiden sie nicht, und <den Unterschied> zwischen unrein und rein lassen sie nicht erkennen*; und vor meinen Sabbaten verhüllen sie ihre Augen*. So werde ich in ihrer Mitte entweiht.", footnotes: ["℘ Mal 1,6; 2,7.8", "℘ Kap. 44,23; 3Mo 10,10", "℘ Kap. 23,38.39; 44,24"] },
      { number: 27, text: "Seine Obersten sind in seiner Mitte wie Wölfe, die Beute reißen, um Blut zu vergießen, Seelen zugrunde zu richten*, damit sie unrechten Gewinn erlangen*.", footnotes: ["℘ Kla 4,13", "℘ Kap. 13,19; 2Chr 36,14; Jes 1,23; Mi 3,11; Zef 3,3"] },
      { number: 28, text: "Und seine Propheten streichen ihnen Tünche <darüber>, indem sie Nichtiges schauen und ihnen Lügen wahrsagen und sprechen: So spricht der Herr, HERR! Und doch hat der HERR nicht geredet*.", footnotes: ["℘ Kap. 13,6.10.16; Jes 28,15"] },
      { number: 29, text: "Das Volk des Landes verübt Erpressung* und begeht* Raub; und den Elenden und Armen unterdrücken sie*, und am Fremden handeln sie gegen <jedes> Recht*.", footnotes: ["o. Gewalttat", "w. raubt Raub", "℘ Mi 6,12", "so mit LXX; Mas. T.: und den Fremden behandeln sie widerrechtlich gewalttätig\n℘ 2Mo 23,9; 3Mo 19,13.33"] },
      { number: 30, text: "Und ich suchte einen Mann unter ihnen, der die Mauer zumauern und vor mir für das Land in den Riss* treten könnte*, damit ich es nicht verheeren müsste; aber ich fand keinen*.", footnotes: ["o. in die Bresche", "℘ Kap. 13,5", "℘ 2Kö 14,26; Jes 59,16"] },
      { number: 31, text: "So gieße ich meinen Zorn über sie aus, im Feuer meines Grimms vernichte ich sie*, ihren Weg bringe ich auf ihren Kopf*, spricht der Herr, HERR*.", footnotes: ["℘ Offb 16,1", "℘ Kap. 7,3.8; 9,10; Spr 1,31; Jer 8,13", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Die beiden unzüchtigen Schwestern Ohola und Oholiba", footnotes: ["℘ Kap. 16"] },
      { number: 2, text: "Menschensohn, <da gab es> zwei Frauen, Töchter einer Mutter waren sie." },
      { number: 3, text: "Die hurten in Ägypten*, <bereits> in ihrer Jugend hurten sie; dort wurden ihre Brüste gedrückt, und dort betastete man ihren jungfräulichen Busen.", footnotes: ["℘ V. 19; Kap. 20,7.8"] },
      { number: 4, text: "Die Ältere hieß Ohola* und ihre Schwester Oholiba*. Und sie wurden mein und gebaren Söhne und Töchter. Und <was> ihre Namen <betrifft>: Samaria ist Ohola, und Jerusalem ist Oholiba.", footnotes: ["d. h. mein Zelt <ist> in ihr", "d. h. mein Zelt <ist> in ihr\n℘ Jer 3,7"] },
      { number: 5, text: "Und Ohola hurte von mir weg*. Und sie hatte Verlangen nach ihren Liebhabern, den kampftüchtigen Assyrern*,", footnotes: ["w. wählte hurerisch <Liebhaber> statt meiner", "w. nach den Assyrern, Kämpfern. — LXX: nach den Assyrern, den Nahen\n℘ Hos 5,13"] },
      { number: 6, text: "gekleidet in violetten Purpur, den Statthaltern und Befehlshabern, anmutige junge Männer* waren sie alle, Reiter, auf Pferden reitend.", footnotes: ["o. Auserlesene; d. h. wehrtüchtige kräftige Männer"] },
      { number: 7, text: "Und sie richtete ihre Hurereien auf sie. Die Auslese der Söhne Assur waren sie alle; und mit allen, nach denen sie Verlangen hatte, <und> mit all deren Götzen machte sie sich unrein." },
      { number: 8, text: "Auch ihre von Ägypten her <gewohnten> Hurereien* ließ sie nicht*; denn <schon> in ihrer Jugend hatten sie bei ihr gelegen und hatten ihren jungfräulichen Busen betastet und ihre Hurerei über sie ausgegossen.", footnotes: ["o. ihre Hurereien mit den Ägyptern", "℘ V. 19; Kap. 20,7.8"] },
      { number: 9, text: "Darum habe ich sie in die Hand ihrer Liebhaber gegeben, in die Hand der Söhne Assur, nach denen sie Verlangen hatte*.", footnotes: ["℘ 2Kö 15,29"] },
      { number: 10, text: "Die haben ihre Blöße aufgedeckt, ihre Söhne und ihre Töchter weggenommen, und sie selbst haben sie mit dem Schwert erschlagen, so dass sie zum Gerede bei den Frauen wurde, und haben Strafgerichte an ihr geübt." },
      { number: 11, text: "Und ihre Schwester Oholiba sah es, und sie trieb es mit ihrem Verlangen verderblicher als sie und mit ihren Hurereien <schlimmer> als ihre Schwester mit <ihren> Hurereien*.", footnotes: ["℘ Jer 3,6-11"] },
      { number: 12, text: "Sie bekam Verlangen nach den Söhnen Assur, Statthaltern und Befehlshabern, Kämpfern, prächtig gekleidet, Reitern, auf Pferden reitend; anmutige junge Männer* waren sie alle*.", footnotes: ["o. Auserlesene; d. h. wehrtüchtige kräftige Männer", "℘ Hos 2,7"] },
      { number: 13, text: "Und ich sah, dass sie sich unrein gemacht hatte: Dieselbe Art* hatten sie beide.", footnotes: ["w. Einen Weg"] },
      { number: 14, text: "Aber sie trieb ihre Hurereien <noch> weiter: Denn sie sah Männer in Zeichnung an der Wand, Bilder von Chaldäern, mit roter Farbe eingezeichnet*,", footnotes: ["℘ Jer 22,14"] },
      { number: 15, text: "gegürtet mit einem Gurt* an ihren Hüften, herabhängenden Turbanen auf ihren Köpfen, sie alle vom Aussehen hervorragender Kämpfer, ein Abbild der Söhne Babels, deren Geburtsland Chaldäa ist.", footnotes: ["o. Lendenschurz"] },
      { number: 16, text: "Und als ihre Augen sie sahen, bekam sie Verlangen nach ihnen, und sie sandte Boten zu ihnen nach Chaldäa*.", footnotes: ["℘ Jes 57,9"] },
      { number: 17, text: "Da kamen die Söhne Babels zu ihr zum Liebeslager und machten sie durch ihre Hurerei unrein. Doch als sie sich an ihnen unrein gemacht hatte, wandte sich ihre Seele jäh von ihnen ab." },
      { number: 18, text: "Und als sie <so> ihre Hurereien aufgedeckt hatte und ihre Blöße aufgedeckt hatte, da wandte sich meine Seele jäh von ihr ab, ebenso wie meine Seele sich von ihrer Schwester jäh abgewandt hatte*.", footnotes: ["℘ Jer 6,8"] },
      { number: 19, text: "Sie aber vermehrte <noch> ihre Hurereien, indem sie an die Tage ihrer Jugend dachte, als sie im Land Ägypten gehurt hatte." },
      { number: 20, text: "Und sie bekam Verlangen nach ihren* Liebhabern, deren Fleisch wie das Fleisch der Esel und deren Erguss wie der Erguss der Pferde ist.", footnotes: ["w. seinen; d. h. den Liebhabern aus Ägypten"] },
      { number: 21, text: "Und du sehntest dich nach der Schandtat* deiner Jugend, als man in Ägypten* deinen Busen betastete wegen deiner jugendlichen Brüste. —", footnotes: ["o. Unzucht", "w. von Ägypten her"] },
      { number: 22, text: "Darum, Oholiba, so spricht der Herr, HERR: Siehe, ich erwecke gegen dich deine Liebhaber, von denen deine Seele sich jäh abgewandt hat, und lasse sie von allen Seiten über dich kommen*:", footnotes: ["℘ Jer 6,22.23"] },
      { number: 23, text: "die Söhne Babels* und alle Chaldäer, Pekod und Schoa und Koa*, alle Söhne Assur mit ihnen, anmutige junge Männer*, Statthalter und Befehlshaber sind sie alle, hervorragende Kämpfer und Räte*, sie alle auf Pferden reitend.", footnotes: ["℘ Kap. 21,24-27", "Das sind babylonische Völkerschaften.", "o. Auserlesene; d. h. wehrtüchtige kräftige Männer", "w. Berufene (von der Gemeinde); das sind die Angesehenen"] },
      { number: 24, text: "Die kommen über dich von Norden*, <mit> Wagen und Rädern und Scharen von Völkern*; Langschild und Kleinschild und Helm richten sie ringsum gegen dich. Und ich übergebe ihnen das Gericht, und sie werden dich nach ihren Rechtssätzen richten*.", footnotes: ["so mit LXX; andere lesen: <mit> einem Heer; die Bedeutung des Wortes im Mas. T. ist bisher unerklärt", "w. mit einer Versammlung von Völkern", "℘ Jer 52,9-11"] },
      { number: 25, text: "Und ich bringe meinen Eifer über dich*, und sie werden im Grimm mit dir verfahren: Deine Nase und deine Ohren werden sie abschneiden, und was nach dir <übrig bleibt>*, wird durch das Schwert fallen; deine Söhne und deine Töchter werden sie wegnehmen, und was nach dir <übrig bleibt>*, wird durch das Feuer verzehrt werden.", footnotes: ["℘ Kap. 5,13", "w. was nach dir ist", "w. was nach dir ist"] },
      { number: 26, text: "Und sie werden dir deine Kleider ausziehen und deine prächtigen Geschmeide nehmen*.", footnotes: ["℘ 2Kö 24,13; Jes 39,6"] },
      { number: 27, text: "Und ich will ein Ende machen* deiner Schandtat* von dir und deiner Hurerei vom Land Ägypten her, so dass du deine Augen nicht mehr zu ihnen erheben und nicht mehr denken wirst an Ägypten*.", footnotes: ["w. ein Ende machen von dir weg", "o. Unzucht", "℘ Kap. 22,15"] },
      { number: 28, text: "Denn so spricht der Herr, HERR: Siehe, ich gebe dich in die Hand derer, die du hasst, in die Hand derer, von denen deine Seele sich jäh abgewandt hat." },
      { number: 29, text: "Und sie werden voller Hass mit dir verfahren und all dein Erworbenes wegnehmen und dich nackt und bloß zurücklassen*. Da sollen deine hurerische Blöße und deine Schandtat* und deine Hurereien aufgedeckt werden.", footnotes: ["℘ Kla 1,8.9", "o. Unzucht"] },
      { number: 30, text: "Das wird dir geschehen, weil du den Nationen nachgehurt, weil du dich mit ihren Götzen unrein gemacht hast*.", footnotes: ["℘ Jer 2,18.19"] },
      { number: 31, text: "Auf dem Weg deiner Schwester bist du gegangen*, so gebe ich ihren Becher in deine Hand*.", footnotes: ["℘ 2Kö 17,19", "℘ 2Kö 21,13"] },
      { number: 32, text: "So spricht der Herr, HERR: Du wirst den Becher deiner Schwester trinken, den tiefen und weiten — zum Gelächter und zum Spott wird sie* —, der so viel fasst.", footnotes: ["℘ Kap. 22,4.5; Kla 2,15.16"] },
      { number: 33, text: "Von Trunkenheit und Kummer wirst du voll werden; ein Becher des Entsetzens und der Verödung ist der Becher deiner Schwester Samaria." },
      { number: 34, text: "Und du wirst ihn trinken und ausschlürfen* und wirst seine Tonscherben benagen und deine Brüste zerreißen; denn ich habe geredet, spricht der Herr, HERR*. —", footnotes: ["℘ Ps 75,9", "w. ist der Ausspruch des Herrn, HERRN\n℘ Kap. 22,14"] },
      { number: 35, text: "Darum, so spricht der Herr, HERR: Weil du mich vergessen* und mich hinter deinen Rücken geworfen hast, so trage du auch deine Schandtat* und deine Hurereien!*", footnotes: ["℘ Kap. 22,12; Jer 2,7; 13,25; Hos 13,6", "o. Unzucht; vgl. V. 21", "℘ 4Mo 14,33.34"] },
      { number: 36, text: "Und der HERR sprach zu mir: Menschensohn, willst du die Ohola und die Oholiba richten? Dann halte ihnen ihre Gräuel vor!*", footnotes: ["℘ Kap. 20,4; Mi 3,8"] },
      { number: 37, text: "Denn sie haben Ehebruch getrieben, und Blut ist an ihren Händen, und mit ihren Götzen haben sie Ehebruch getrieben; und sogar ihre Kinder, die sie mir geboren hatten, haben sie ihnen zum Fraß durch <das Feuer> gehen lassen*.", footnotes: ["℘ Kap. 20,26.31; 3Mo 20,2-5; 2Kö 23,10"] },
      { number: 38, text: "Und dies haben sie mir noch <dazu> angetan: Sie haben am selben Tag mein Heiligtum unrein gemacht und meine Sabbate entweiht*.", footnotes: ["℘ Kap. 22,8.26"] },
      { number: 39, text: "Denn wenn sie ihre Söhne für ihre Götzen schlachteten, dann kamen sie am selben Tag in mein Heiligtum, es zu entweihen; und siehe, so haben sie es mitten in meinem Haus getrieben*.", footnotes: ["℘ Kap. 5,11; 2Kö 21,4-7"] },
      { number: 40, text: "Ja, sie haben sogar <Boten> zu Männern gesandt, die von fern her kommen sollten — zu denen ein Bote gesandt worden war; und siehe, sie kamen! —, für die du dich gebadet, deine Augen geschminkt und <dir> Schmuck angelegt hast*", footnotes: ["℘ 2Kö 9,30"] },
      { number: 41, text: "und dich auf ein prunkvolles Polster gesetzt hast*, vor dem ein Tisch bereitet war; und darauf hast du mein Räucherwerk und mein Öl gestellt*.", footnotes: ["℘ Jes 57,7-9", "℘ Hes 6,13"] },
      { number: 42, text: "Und mit lärmender Stimme sang man den Männern zu wegen der Menge der Menschen, die aus der Wüste gekommen waren*; und sie legten Armringe an ihre* Hände und <setzten> prachtvolle Kronen auf ihre Köpfe*.", footnotes: ["T. in Anlehnung an LXX; Mas. T.: Und der Lärm des Getümmels war sorglos in ihr; und zu den Männern wurden wegen der Menge der Menschen Trinker aus der Wüste gebracht", "d. h. der Frauen", "℘ Kap. 27,22"] },
      { number: 43, text: "Da sprach ich: <Noch immer> Ehebruch für die Verbrauchte? Jetzt treibt man ihre Hurereien, und sie <freut sich darüber>*.", footnotes: ["Mas. T. ist in V. 43 gestört. Die Üs., die auf Änderung des Textes verzichtet, bleibt unsicher."] },
      { number: 44, text: "Und man ging zu ihr ein, wie man zu einer Hure eingeht; so gingen sie ein zu Ohola und zu Oholiba, den unzüchtigen Frauen*.", footnotes: ["℘ Jer 3,8"] },
      { number: 45, text: "Aber gerechte Männer, die werden sie richten nach dem Recht für Ehebrecherinnen und nach dem Recht für solche, die Blut vergießen; denn sie sind Ehebrecherinnen, und Blut ist an ihren Händen*. —", footnotes: ["℘ Kap. 24,7; Jer 2,34; Kla 4,14"] },
      { number: 46, text: "Denn so spricht der Herr, HERR: Man führe eine Versammlung gegen sie herauf und gebe sie der Misshandlung und der Plünderung preis*!", footnotes: ["℘ Jer 17,3"] },
      { number: 47, text: "Und die Versammlung soll sie steinigen und sie mit ihren Schwertern zerhauen; ihre Söhne und ihre Töchter soll man erschlagen und ihre Häuser mit Feuer vernichten*!", footnotes: ["℘ Kap. 24,21; Jer 32,29"] },
      { number: 48, text: "Und so werde ich die Schandtat* aus dem Land wegschaffen, damit alle Frauen sich warnen lassen und nicht nach eurer Schandtat* handeln*.", footnotes: ["o. Unzucht; vgl. V. 21", "o. Unzucht; vgl. V. 21", "℘ 5Mo 13,12"] },
      { number: 49, text: "Und sie werden eure Schandtat* auf euch bringen, und die Sünden<, die ihr mit> euren Götzen <begangen habt,> werdet ihr tragen. Und ihr werdet erkennen, dass ich der Herr, HERR, bin.", footnotes: ["o. Unzucht; vgl. V. 21"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir im neunten Jahr, im zehnten Monat, am Zehnten des Monats*:", heading: "Der Kochtopf über dem Feuer", footnotes: ["℘ Kap. 8,1; Sach 8,19"] },
      { number: 2, text: "Menschensohn, schreibe dir den Namen des Tages auf, ebendieses Tages! An ebendiesem Tag wirft sich der König von Babel <mit seinem Heer> auf Jerusalem*.", footnotes: ["℘ 2Kö 25,1; Jer 39,1"] },
      { number: 3, text: "Und rede ein Gleichnis* zu dem widerspenstigen Haus*, und sage zu ihnen: So spricht der Herr, HERR: Setze den Topf auf*, setze <ihn> auf, und gieße auch Wasser hinein!", footnotes: ["℘ Kap. 17,2", "℘ Kap. 2,2-8", "℘ Kap. 11,3.7; Jer 1,13"] },
      { number: 4, text: "Lege seine <Fleisch>stücke zusammen hinein, lauter gute Stücke, Lende und Schulter; auserlesene Knochen fülle ein!" },
      { number: 5, text: "Nimm auserlesene Schafe, und schichte auch ringsherum die Holzstücke* darunter; lass seine <Fleisch>stücke sieden*; auch seine Knochen sollen darin kochen! —", footnotes: ["So hat wahrscheinlich in Entsprechung zu V. 10 der Text ursprünglich gelautet; Mas. T.: die Knochen", "So mit zwei hebr. Handschr.; Mas. T.: lass sein Sieden sieden, o. lass seine Siedestücke sieden"] },
      { number: 6, text: "Darum, so spricht der Herr, HERR: Wehe, Stadt der Blutschuld*! Topf, an dem sein Rost ist und dessen Rost nicht von ihm abgeht*! Stück für Stück leere ihn aus*, ohne dass darüber das Los gefallen ist.*", footnotes: ["℘ Kap. 22,2-4; Nah 3,1", "℘ Jer 2,22", "℘ Kap. 11,7-11", "o. Stück für Stück hat man sie (die Stadt) leergemacht, ohne dass über sie (die Bewohner) das Los gefallen ist."] },
      { number: 7, text: "Denn ihr Blut* ist in ihrer Mitte*; sie hat es auf den kahlen Felsen getan, sie hat es nicht auf die Erde gegossen, dass man es mit Staub bedecken könnte*.", footnotes: ["d. i. das Blut, das in der Stadt vergossen wurde", "℘ Kap. 23,45", "℘ 3Mo 17,13"] },
      { number: 8, text: "Um Zorn heraufzuführen, um Rache zu üben, habe ich ihr Blut auf den kahlen Felsen getan, damit es nicht bedeckt wird*. —", footnotes: ["℘ 2Kö 24,4; Jes 26,21"] },
      { number: 9, text: "Darum, so spricht der Herr, HERR: Wehe, Stadt der Blutschuld*! Auch ich werde den Holzstoß groß machen*.", footnotes: ["℘ Kap. 22,2-4; Nah 3,1", "℘ Kap. 21,2.3"] },
      { number: 10, text: "Häufe das Holz, zünde das Feuer an, koche das Fleisch gar, und schütte die Brühe weg*, und die Knochen sollen angebrannt werden!", footnotes: ["so mit LXX; Mas. T.: und lass salben den Salbentopf"] },
      { number: 11, text: "Und stelle ihn leer auf seine Kohlen, damit seine Bronze heiß wird und glüht und seine Unreinheit in ihm schmilzt, sein Rost abgeht*!", footnotes: ["℘ Kap. 22,15"] },
      { number: 12, text: "Vergebliche Mühe!* Sein vieler Rost geht nicht von ihm ab*. Ins Feuer mit seinem Rost!* —", footnotes: ["T.; Mas. T.: Mit Mühsal hat er müde gemacht.", "℘ Jer 6,29.30; 13,27; Offb 2,21", "o. <Auch> im Feuer <bleibt> sein Rost."] },
      { number: 13, text: "Wegen deiner schändlichen* Unreinheit, weil ich dich reinigte, du aber nicht rein wurdest, so wirst du <nun> von deiner Unreinheit nicht mehr rein werden*, bis ich meinen Grimm an dir gestillt habe*.", footnotes: ["o. unzüchtigen", "℘ Jer 6,29.30; 13,27; Offb 2,21", "℘ Kap. 5,13"] },
      { number: 14, text: "Ich, der HERR, habe geredet. Es kommt, und ich tue es*; ich lasse nicht nach; ich bin <deinetwegen> nicht betrübt* und lasse es mich nicht gereuen*. Nach deinen Wegen und nach deinen Taten richte ich* dich*, spricht der Herr, HERR*.", footnotes: ["℘ Kap. 17,24; 30,9", "w. nicht fließt (d. h. weint) <mein Auge>", "℘ Kap. 5,11; 1Sam 15,29; Jer 13,14", "so mit einigen hebr. Handschr.; Mas. T.: richten sie", "℘ Kap. 7,3.8", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 15, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Der Tod von Hesekiels Frau: keine Trauer über Jerusalem" },
      { number: 16, text: "Menschensohn, siehe, ich nehme die in deinen Augen Begehrenswerte* von dir weg durch plötzlichen Tod*. Du aber sollst nicht klagen und nicht weinen, und keine Träne soll dir kommen.", footnotes: ["o. die Lust deiner Augen", "o. durch einen Schlag"] },
      { number: 17, text: "Stöhne bewegungslos, Totenklage stell nicht an*; binde dir deinen Kopfbund um*, und zieh deine Schuhe an deine Füße!* Deinen Bart sollst du nicht verhüllen* und Brot der Trauer* nicht essen!", footnotes: ["℘ Jer 16,5-7", "℘ 3Mo 10,6", "℘ 2Sam 15,30", "℘ Mi 3,7", "so mit der aram. Üs. und Vulg.; Mas. T.: der Menschen"] },
      { number: 18, text: "Und ich redete zum Volk am Morgen, und am Abend starb meine Frau. Und ich tat am Morgen, wie mir befohlen war." },
      { number: 19, text: "Da sprach das Volk zu mir: Willst du uns nicht mitteilen, was uns das bedeuten soll, dass du <so> handelst*?", footnotes: ["℘ Kap. 12,9; 37,18"] },
      { number: 20, text: "Da sagte ich zu ihnen: Das Wort des HERRN geschah zu mir so:" },
      { number: 21, text: "Sage zum Haus Israel: So spricht der Herr, HERR: Siehe, ich entweihe mein Heiligtum*, den Stolz eurer Macht*, das in euren Augen Begehrenswerte* und das Verlangen eurer Seele*. Und eure Söhne und eure Töchter, die ihr zurückgelassen habt, werden durchs Schwert fallen*.", footnotes: ["℘ Kap. 7,22; 1Kö 9,7", "o. den Stolz eures Schutzes; d. h. den Schutz, auf den ihr stolz seid", "o. die Lust eurer/ihrer Augen", "℘ Ps 84,3", "℘ Kap. 23,47; Kla 2,1.21"] },
      { number: 22, text: "Dann werdet ihr tun, wie ich getan habe: den Bart werdet ihr nicht verhüllen und Brot der Trauer* nicht essen,", footnotes: ["so mit der aram. Üs. und Vulg.; Mas. T.: der Menschen"] },
      { number: 23, text: "und eure Kopfbunde werden auf euren Köpfen <bleiben> und eure Schuhe an euren Füßen. Ihr werdet nicht klagen und nicht weinen*, sondern werdet dahinschwinden in euren* Sünden* und seufzen einer zum andern hin.", footnotes: ["℘ Ps 78,64", "o. wegen eurer", "℘ Kap. 4,17; 33,10"] },
      { number: 24, text: "So wird Hesekiel für euch zum Wahrzeichen werden*; nach allem, was er getan hat, werdet ihr tun. Wenn es kommt, dann werdet ihr erkennen, dass ich der Herr, HERR, bin.", footnotes: ["℘ Kap. 4,3"] },
      { number: 25, text: "Und du, Menschensohn, siehe, an dem Tag, da ich ihre Zuflucht* wegnehme von ihnen, die Freude ihrer Pracht, das in ihren Augen Begehrenswerte* und die Sehnsucht ihrer Seelen, ihre Söhne und ihre Töchter;", footnotes: ["o. ihr Burgheiligtum", "o. die Lust eurer/ihrer Augen"] },
      { number: 26, text: "an jenem Tag wird ein Entkommener zu dir kommen, um es deine Ohren vernehmen zu lassen." },
      { number: 27, text: "An jenem Tag wird dein Mund geöffnet werden* vor dem Entkommenen, und du wirst reden und nicht mehr stumm sein. So sollst du ihnen zu einem Wahrzeichen werden*; und sie werden erkennen, dass ich der HERR bin.", footnotes: ["℘ Kap. 3,27; 33,22", "℘ Kap. 4,3"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Drohreden gegen Ammon, Moab, Edom und die Philister", footnotes: ["℘ V. 1-7: Kap. 21,33-37; Jer 49,1-6; Am 1,13-15; Zef 2,8-11"] },
      { number: 2, text: "Menschensohn, richte dein Gesicht gegen die Söhne Ammon*, und weissage über sie", footnotes: ["℘ Jer 25,21"] },
      { number: 3, text: "und sage zu den Söhnen Ammon: Hört das Wort des Herrn, HERRN! So spricht der Herr, HERR: Da du »Haha!« sagst über mein Heiligtum, weil es entweiht ist, und über das Land Israel, weil es verwüstet ist, und über das Haus Juda, weil sie in die Gefangenschaft gegangen sind*;", footnotes: ["℘ Kap. 26,2; Ps 35,21; Spr 17,5"] },
      { number: 4, text: "darum, siehe, werde ich dich den Söhnen des Ostens* zum Besitz geben, und sie werden ihre Zeltlager in dir aufschlagen und ihre Wohnungen in dir errichten; sie werden deine Früchte essen, und sie werden deine Milch trinken.", footnotes: ["℘ V. 10; Ri 6,3"] },
      { number: 5, text: "Und ich werde Rabba* zum Weideplatz der Kamele machen und die Söhne Ammon* zur Lagerstätte der Schafe*. Und ihr werdet erkennen, dass ich der HERR bin. —", footnotes: ["℘ Kap. 21,25", "℘ 2Sam 12,26", "℘ Jes 17,2; Zef 2,6"] },
      { number: 6, text: "Denn so spricht der Herr, HERR: Weil du in die Hände geklatscht und mit dem Fuß gestampft hast und dich von Herzen* mit all deiner Verachtung über das Land Israel gefreut hast*;", footnotes: ["w. mit der Seele", "℘ Kap. 35,15; Kla 1,7"] },
      { number: 7, text: "siehe, darum strecke ich meine Hand gegen dich aus und gebe dich den Nationen zur Beute, und ich rotte dich aus den Völkern aus und tilge dich aus den Ländern aus. Ich werde dich vernichten*, und du wirst erkennen, dass ich der HERR bin.", footnotes: ["℘ V. 10"] },
      { number: 8, text: "*So spricht der Herr, HERR: Weil Moab und Seïr* sagen: »Siehe, das Haus Juda ist wie alle Nationen*«;", footnotes: ["℘ V. 8-11: Jes 15; 16; Jer 48; Am 2,1-3; Zef 2,8-11", "℘ V. 12-14", "℘ 2Chr 32,19"] },
      { number: 9, text: "darum, siehe, werde ich die Berghänge* Moabs entblößen von den Städten, von seinen Städten ohne Ausnahme, der Zierde des Landes, Bet-Jeschimot*, Baal-Meon und bis nach Kirjatajim* hin*,", footnotes: ["w. die Schulter", "℘ 4Mo 33,49", "℘ Jos 13,17-20", "o. und Kirjatajim"] },
      { number: 10, text: "und ich gebe es den Söhnen des Ostens* zum Besitz zu den Söhnen Ammon hinzu*, damit an die Söhne Ammon nicht mehr gedacht wird unter den Nationen*.", footnotes: ["℘ V. 4", "so mit Umstellung des Verbs »ich gebe«; Mas. T.: 9 darum, siehe, werde ich die Berghänge Moabs öffnen . . . 10 den Söhnen des Ostens zu den Söhnen Ammons hinzu und werde <es ihnen> geben zum Besitz", "℘ V. 7"] },
      { number: 11, text: "So werde ich an Moab Strafgerichte üben*; und sie werden erkennen, dass ich der HERR bin.", footnotes: ["℘ Jer 25,21"] },
      { number: 12, text: "*So spricht der Herr, HERR: Weil Edom* mit Rachsucht gegen das Haus Juda gehandelt und sie sich sehr schuldig gemacht haben, als sie sich an ihnen rächten*;", footnotes: ["℘ V. 12-14: Kap. 35; (Jes 21,11.12); Jes 34,5-17; Jer 49,7-22; Am 1,11.12; Ob", "℘ V. 8; Kap. 32,29; 36,5", "℘ 2Chr 28,17; Ps 137,7; Joe 4,19"] },
      { number: 13, text: "darum, so spricht der Herr, HERR, werde ich meine Hand gegen Edom ausstrecken und Menschen und Vieh aus ihm ausrotten; und ich werde es von Teman an zur Trümmerstätte machen*, und bis nach Dedan* hin werden sie durchs Schwert fallen*.", footnotes: ["℘ Mal 1,3.4", "℘ Kap. 27,15.20", "Mit Änderung der masoretischen Zeichensetzung üs. andere: und ich werde es zur Trümmerstätte machen; von Teman bis nach Dedan werden sie durchs Schwert fallen."] },
      { number: 14, text: "Und ich werde meine Rache an Edom in die Hand meines Volkes Israel legen, und sie werden an Edom handeln nach meinem Zorn und nach meinem Grimm*. Und sie werden meine Rache erkennen*, spricht der Herr, HERR*.", footnotes: ["℘ Jes 11,14", "℘ V. 17; 5Mo 32,41-43; Jes 63,4; Jer 51,36; Offb 6,10", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 15, text: "*So spricht der Herr, HERR: Weil die Philister mit Rachsucht gehandelt und sich rachsüchtig gerächt haben mit Verachtung aus <vollem> Herzen* zur Zerstörung in ewiger Feindschaft*;", footnotes: ["℘ V. 15-17: Jes 14,28-32; Jer 47; Am 1,6-8; Zef 2,4-7; Sach 9,5-7", "w. mit der Seele", "℘ 2Chr 28,18; Ps 83,5.8"] },
      { number: 16, text: "darum, so spricht der Herr, HERR: Siehe, ich strecke meine Hand gegen die Philister aus und rotte die Kreter* aus und tilge den Rest an der Küste des Meeres aus.", footnotes: ["℘ 1Sam 30,14"] },
      { number: 17, text: "Und ich werde mit grimmigen Züchtigungen große Rache an ihnen üben. Und sie werden erkennen, dass ich der HERR bin, wenn ich meine Rache über sie bringe*.", footnotes: ["℘ V. 14; Joe 4,4.7"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "*Und es geschah im elften Jahr, am Ersten des Monats*, da geschah das Wort des HERRN zu mir so:", heading: "Drohrede gegen Tyrus", footnotes: ["℘ Kap. 27; 28,1-19; Jes 23; Am 1,9.10; Sach 9,2-4", "℘ Kap. 8,1"] },
      { number: 2, text: "Menschensohn, weil Tyrus über Jerusalem sagt: »Haha! Zerbrochen ist das Tor der Völker; es fällt mir zu; *ich werde erfüllt, sie ist verwüstet*!«;", footnotes: ["LXX und die aram. Üs. lesen: sie, die Fülle hatte, ist verwüstet", "LXX und die aram. Üs. lesen: sie, die Fülle hatte, ist verwüstet\n℘ Kap. 25,3.6; Ps 40,16; Kla 1,1"] },
      { number: 3, text: "darum, so spricht der Herr, HERR: Siehe, ich will an dich, Tyrus*! Und ich werde viele Nationen gegen dich heraufführen, wie das Meer seine Wellen heraufführt*.", footnotes: ["℘ Jer 25,22; Joe 4,4", "℘ Jer 51,42"] },
      { number: 4, text: "Und sie werden die Mauern von Tyrus zerstören und seine Türme abbrechen; und ich werde seine Erde von ihm wegfegen und es zum kahlen Felsen machen." },
      { number: 5, text: "Ein Trockenplatz für Netze soll es werden mitten im Meer*, denn ich habe geredet, spricht der Herr, HERR*, und es wird den Nationen zur Beute werden.", footnotes: ["Tyrus lag auf einer Insel unweit des Festlandes.", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 6, text: "Und seine Töchter, die auf dem Feld sind*, sollen mit dem Schwert erschlagen werden. Und sie werden erkennen, dass ich der HERR bin.", footnotes: ["Das sind seine Tochterstädte auf dem Festland."] },
      { number: 7, text: "Denn so spricht der Herr, HERR: Siehe, ich lasse Nebukadnezar, den König von Babel, den König der Könige*, von Norden her über Tyrus kommen*, mit Pferden und Wagen und Reitern und einem Aufgebot und mit viel Volk.", footnotes: ["℘ Esr 7,12; Dan 2,37", "℘ Kap. 29,18"] },
      { number: 8, text: "Deine Töchter wird er auf dem Feld mit dem Schwert erschlagen. Und er wird Belagerungstürme gegen dich aufstellen und einen Belagerungswall gegen dich aufschütten und Langschilde gegen dich aufrichten" },
      { number: 9, text: "und den Stoß seines Mauerbrechers gegen deine Mauern richten und deine Türme mit seinen Brecheisen niederreißen." },
      { number: 10, text: "Von der Menge seiner Pferde wird dich ihr Staub bedecken; vor dem Lärm der Reiter und Räder und Wagen werden deine Mauern erbeben, wenn er in deine Tore einzieht, wie man in eine Stadt voller Breschen einzieht*.", footnotes: ["w. wie die Einmärsche in eine aufgebrochene Stadt"] },
      { number: 11, text: "Mit den Hufen seiner Pferde wird er alle deine Straßen zerstampfen; dein Volk wird er mit dem Schwert erschlagen, und die Gedenksteine* deiner Macht* werden zu Boden sinken.", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden", "o. deines Schutzes; d.h: die Gedenksteine, die dich schützen sollen"] },
      { number: 12, text: "Und sie werden dein Vermögen rauben und deinen Handelsgewinn plündern und deine Mauern abbrechen und deine prächtigen Häuser niederreißen; und deine Steine und dein Holz und deinen Schutt werden sie mitten ins Wasser schütten." },
      { number: 13, text: "Und ich werde das Getön deiner Lieder zum Schweigen bringen*, und der Klang deiner Zithern wird nicht mehr gehört werden*.", footnotes: ["w. ruhen machen", "℘ Jes 24,8; Offb 18,22"] },
      { number: 14, text: "Und ich werde dich zum kahlen Felsen machen; ein Trockenplatz für Netze sollst du werden, du wirst nicht wieder aufgebaut werden. Denn ich, der HERR, habe geredet, spricht der Herr, HERR*.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 15, text: "So spricht der Herr, HERR, zu Tyrus: Werden nicht vom Dröhnen deines Sturzes, wenn der Durchbohrte stöhnt, wenn in deiner Mitte gemordet wird, die Inseln erbeben*?", footnotes: ["℘ Jer 49,21"] },
      { number: 16, text: "Und alle Fürsten des Meeres werden von ihren Thronen herabsteigen und ihre Mäntel ablegen und ihre buntgewirkten Kleider ausziehen. In Schrecken werden sie sich kleiden, werden auf der Erde sitzen, immer wieder erzittern und sich über dich entsetzen*.", footnotes: ["℘ Kap. 32,10; Offb 18,10"] },
      { number: 17, text: "Und sie werden ein Klagelied über dich erheben* und zu dir sagen: Wie bist du verloren gegangen, vom Meer verschwunden*, du berühmte Stadt, die mächtig auf dem Meer war, sie und ihre Bewohner, die allen, die dort wohnten, ihren Schrecken einflößte*.", footnotes: ["℘ Kap. 19,1; 32,2.16", "so mit LXX; Mas. T.: du von den Meeren her Bewohnte", "d. h. den Meeresbewohnern; andere üs. mit geringfügiger Änderung: die durch alle ihre Bewohner Schrecken einflößte\n℘ Kap. 32,23"] },
      { number: 18, text: "Nun erzittern die Inseln am Tag deines Sturzes; und entsetzt sind die Inseln im Meer wegen deines Endes*.", footnotes: ["℘ Kap. 31,15.16"] },
      { number: 19, text: "Denn so spricht der Herr, HERR: Wenn ich dich zu einer verwüsteten Stadt mache, den Städten gleich, die nicht <mehr> bewohnt werden; wenn ich die Flut über dich heraufsteigen lasse und dich die gewaltigen Wasser bedecken," },
      { number: 20, text: "dann lasse ich dich hinabfahren mit denen, die in die Grube hinabfahren* zum Volk der Urzeit, und lasse dich in den Tiefen <unter> der Erde wohnen, in den Trümmerstätten* von der Vorzeit her, mit denen, die in die Grube hinabgefahren sind, damit du nicht <mehr> bewohnt wirst *und erstehst* im Land der Lebenden.", footnotes: ["℘ Kap. 32,18.24", "so mit einigen hebr. Handschr.; Mas. T.: gleich den Trümmerstätten", "so mit LXX; Mas. T.: und ich werde Zierde geben", "so mit LXX; Mas. T.: und ich werde Zierde geben"] },
      { number: 21, text: "<Tödlichen> Schrecknissen gebe ich dich preis; und du wirst nicht mehr sein, und du wirst gesucht, aber nicht wiedergefunden werden für ewig*, spricht der Herr, HERR*.", footnotes: ["℘ Ps 37,36; Offb 18,21", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Klagelied über den Untergang der Stadt Tyrus", footnotes: ["℘ Kap. 26; 28,1-19; Jes 23; Am 1,9.10; Sach 9,2-4"] },
      { number: 2, text: "Und du, Menschensohn, erhebe ein Klagelied* über Tyrus,", footnotes: ["℘ V. 32; Kap. 19,1; 32,2.16; Jer 9,16-19"] },
      { number: 3, text: "und sage zu Tyrus, das an den Zugängen zum Meer wohnt und Handel treibt mit den Völkern nach vielen Inseln* hin: So spricht der Herr, HERR: Tyrus, du sagst: Ich bin von vollkommener Schönheit*!", footnotes: ["Das hebr. Wort bedeutet sowohl Insel als auch Küstengebiet.", "o. du sagst: Ein Schiff von vollkommener Schönheit <bin ich>"] },
      { number: 4, text: "Dein Gebiet ist im Herzen der Meere; deine Bauleute haben deine Schönheit vollkommen gemacht." },
      { number: 5, text: "Aus Wacholder vom Senir* bauten sie dir <auf beiden Seiten> alle Planken; sie nahmen Zedern vom Libanon*, um auf dir einen Mast zu machen;", footnotes: ["Der amoritische Name des Hermon; gemeint ist hier der Antilibanon.\n℘ 5Mo 3,9", "℘ 2Chr 2,7"] },
      { number: 6, text: "aus Eichen von Baschan machten sie deine Ruder; dein Deck* machten sie aus Elfenbein, <eingefasst> in Zypressen von den Inseln der Kittäer*.", footnotes: ["w. dein Brett; manche nehmen an, dass damit die Kajütenwand gemeint ist", "hebr. Kittim; d. i. Zyprier; dann allgemeine Benennung der Bewohner der Inseln und Küstenländer des Mittelmeeres\n℘ 1Mo 10,4; Jer 2,10; Dan 11,30"] },
      { number: 7, text: "Byssus in Buntwirkerei aus Ägypten* war dein Segel, um dir als Flagge zu dienen; violetter und roter Purpur von den Inseln Elischas* war dein Kajütendach*.", footnotes: ["℘ Spr 7,16", "℘ 1Chr 1,7", "T.; Mas. T.: war das, was dich bedeckte"] },
      { number: 8, text: "Die Bewohner von Sidon und Arwad* waren deine Ruderer; deine Weisen, Tyrus, waren in dir, sie waren deine Matrosen;", footnotes: ["d. i. eine phönizische Stadt nördlich von Sidon\n℘ 1Mo 10,15.18"] },
      { number: 9, text: "die Ältesten von Gebal* und seine Weisen waren in dir als Ausbesserer deiner Lecks. Alle Schiffe des Meeres und ihre Seeleute waren in dir, um deine Tauschwaren einzutauschen.", footnotes: ["d. i. ein anderer Name für Byblos, eine phönizische Küstenstadt\n℘ Jos 13,5; Ps 83,8"] },
      { number: 10, text: "<Söldner aus> Paras und Lud und Put* waren in deinem Heer als deine Kriegsleute; Schild und Helm hängten sie in dir auf, die verliehen dir Glanz.", footnotes: ["℘ Kap. 30,5; 38,5; Jer 46,9"] },
      { number: 11, text: "Die Söhne Arwads waren mit deinem Heer auf deinen Mauern ringsum, und die Gammaditer* waren auf deinen Türmen; ihre Schilde hängten sie ringsum an deinen Mauern auf. Die machten deine Schönheit vollkommen.", footnotes: ["d. i. ein unbekannter Volksstamm; LXX und die syr. Üs. lesen: Wächter"] },
      { number: 12, text: "Tarsis* war dein Aufkäufer wegen der Fülle an allem Besitz; für Silber, Eisen, Zinn und Blei gaben sie deine Waren.", footnotes: ["Niederlassung der Tyrer in Südspanien, berühmt durch ihre Silberbergwerke.\n℘ Kap. 38,13; 1Kö 10,22; 2Chr 9,21"] },
      { number: 13, text: "Jawan*, Tubal und Meschech* waren Händler für dich; <für> Menschenseelen* und bronzene Geräte gaben sie deine Tauschware*.", footnotes: ["d. i. Griechenland\n℘ 1Mo 10,2; Jes 66,19", "Tubal und Meschech waren ursprünglich Völkerstämme zwischen dem Schwarzen und dem Kaspischen Meer.\n℘ Kap. 32,26; 38,2.3", "Gemeint sind Sklaven.", "℘ Joe 4,6; Offb 18,12.13"] },
      { number: 14, text: "Aus dem Haus Togarma*: <Für Zug>pferde, Reitpferde und Maultiere gaben sie deine Waren.", footnotes: ["wahrscheinlich Armenien\n℘ Kap. 38,6; 1Mo 10,3"] },
      { number: 15, text: "Die Söhne Dedans* waren deine Händler. Viele Inseln* waren Aufkäufer in deinem Dienst*: Elefantenzähne* und Ebenholz erstatteten sie dir als Abgabe.", footnotes: ["LXX: Rhodos'\n℘ Kap. 25,13; 1Mo 10,7; 25,3", "Das hebr. Wort bedeutet sowohl Insel als auch Küstengebiet.", "w. waren die Aufkäuferschaft deiner Hand", "w. Elfenbeinhörner\n℘ Kap. 38,13; 1Kö 10,22; 2Chr 9,21"] },
      { number: 16, text: "Edom* war Aufkäufer für dich wegen der Fülle deiner Erzeugnisse; für Rubin, roten Purpur und Buntwirkerei und Byssus und Korallen und Edelsteine gaben sie deine Waren*.", footnotes: ["so mit 25 hebr. Handschr., einer griech. und der syr. Üs.; Mas. T.: Aram", "so mit einigen hebr. Handschr. und LXX; Mas. T.: gaben sie um deine Waren"] },
      { number: 17, text: "Juda und das Land Israel, sie waren deine Händler; für Weizen* <aus> Minnit* und Feigen* und Honig und Öl und Balsam* gaben sie deine Tauschware.", footnotes: ["℘ 1Kö 5,25", "℘ Ri 11,33", "so mit 3 hebr. Handschr.; andere ändern in »Wachs«; die Bedeutung des Wortes im Mas. T. ist unbekannt", "℘ 1Mo 43,11; Jer 8,22"] },
      { number: 18, text: "Damaskus* war dein Aufkäufer wegen der Fülle deiner Erzeugnisse, wegen der Fülle an allem Besitz, gegen Wein von Helbon und Wolle von Zachar.", footnotes: ["℘ Jes 7,8"] },
      { number: 19, text: "*Und Wein gaben sie für deine Ware; bearbeitetes Eisen*, Zimtblüten und Würzrohr* waren da für deine Tauschware.", footnotes: ["so mit LXX; Mas. T.: Wedan (o. Und Dan) und Jawan aus Usal gaben für deine Ware. Bearbeitetes Eisen", "so mit LXX; Mas. T.: Wedan (o. Und Dan) und Jawan aus Usal gaben für deine Ware. Bearbeitetes Eisen", "℘ 2Mo 30,23; Spr 7,17; Hl 4,14"] },
      { number: 20, text: "Dedan* war deine Händlerin mit Satteldecken zum Reiten.", footnotes: ["℘ Kap. 25,13; 1Mo 10,7; 25,3"] },
      { number: 21, text: "Arabien und alle Fürsten von Kedar*, sie waren Aufkäufer in deinem Dienst*; für Lämmer und Widder und Böcke*, für sie waren sie deine Aufkäufer.", footnotes: ["Das sind arabische Beduinenstämme zwischen dem peträischen Arabien und Babylonien.\n℘ 1Mo 25,13; Hl 1,5; Jes 42,11; Jer 2,10", "w. Aufkäufer deiner Hand", "℘ 2Chr 17,11; Spr 27,26; Jes 60,7"] },
      { number: 22, text: "Die Kaufleute von Saba und Ragma* waren deine Händler; für das Beste von allem Balsam und für allerlei Edelsteine und Gold gaben sie deine Waren*.", footnotes: ["℘ 1Mo 10,7; Joe 4,8", "℘ Kap. 23,42; 1Kö 10,1.2"] },
      { number: 23, text: "Haran* und Kanne* und Eden*, die Händler von Saba*, <dazu> Assur <und> ganz Medien* waren deine Händlerschaft.", footnotes: ["℘ 2Kö 19,12", "℘ 1Mo 10,10", "℘ 1Mo 10,10", "℘ 1Mo 10,28", "so mit anderer Wortabtrennung in Anlehnung an die aram. Üs.; Mas. T.: Kilmad"] },
      { number: 24, text: "Sie waren deine Händler für Prachtgewänder, für Mäntel aus violettem Purpur und Buntwirkerei und für Teppiche aus zweifarbigem Gewebe, für gewundene und feste Seile auf deinem Markt." },
      { number: 25, text: "Die Schiffe von Tarsis waren deine Karawanen <für> deine Tauschware. Und du wurdest <mit Reichtum> angefüllt und sehr herrlich im Herzen der Meere." },
      { number: 26, text: "*Deine Ruderer führten dich über gewaltige Wasser; der Ostwind <aber> zerbrach dich im Herzen der Meere*.", footnotes: ["℘ V. 26-36: vgl. Offb 18,9-19", "℘ Ps 48,8"] },
      { number: 27, text: "Dein Besitz und deine Waren, deine Tauschwaren, deine Seeleute und deine Matrosen, die Ausbesserer deiner Lecks und die, die deine Tauschwaren eintauschten, und alle deine Kriegsleute, die in dir sind, und dein ganzes Aufgebot*, das in deiner Mitte ist, werden ins Herz der Meere fallen am Tag deines Sturzes.", footnotes: ["so mit den meisten hebr. Handschr., LXX, der syr. und aram. Üs.; Mas. T.: und mit deinem ganzen Aufgebot"] },
      { number: 28, text: "Von dem lauten Geschrei deiner Matrosen werden die Weidegebiete* erbeben.", footnotes: ["d. i. das zur Stadt gehörige Weideland"] },
      { number: 29, text: "Und alle, die das Ruder führen, die Seeleute, alle Matrosen des Meeres werden von ihren Schiffen herabsteigen, werden an Land bleiben" },
      { number: 30, text: "und werden ihre Stimme über dich hören lassen und bitter schreien; und sie werden Staub auf ihre Köpfe werfen*, sich in der Asche wälzen*.", footnotes: ["℘ Hi 2,12", "℘ Est 4,1.3; Jer 6,26"] },
      { number: 31, text: "Und sie werden sich deinetwegen eine Glatze scheren und sich Sacktuch umgürten und werden deinetwegen weinen in Bitterkeit der Seele mit bitterer Totenklage*.", footnotes: ["℘ Joe 1,13"] },
      { number: 32, text: "Und sie werden ein Klagelied* über dich erheben in ihrem Jammern und werden über dich klagen: *Wer ist wie Tyrus, wie die Vernichtete* mitten im Meer!", footnotes: ["℘ V. 2", "Die aram. und syr. Üs. lesen: Wer war Tyrus gleich", "Die aram. und syr. Üs. lesen: Wer war Tyrus gleich"] },
      { number: 33, text: "Als deine Waren von den Meeren herkamen, sättigtest du viele Völker; mit der Menge deiner Besitztümer und deiner Tauschwaren hast du die Könige der Erde reich gemacht." },
      { number: 34, text: "Jetzt bist du zerbrochen*, von den Meeren <verschwunden> in den Tiefen des Wassers, und deine Tauschwaren und dein ganzes Aufgebot in deiner Mitte ist gesunken.", footnotes: ["so mit den alten Üs.; Mas. T.: Zur Zeit der Zerbrochenen <bist du>"] },
      { number: 35, text: "Alle Bewohner der Inseln entsetzen sich über dich, und ihren Königen stehen die Haare zu Berge, ihre Gesichter sind verstört." },
      { number: 36, text: "Die Aufkäufer unter den Völkern pfeifen* über dich. Zum Schrecken* bist du geworden und bist dahin auf ewig.", footnotes: ["o. zischen; als Ausdruck der Verachtung oder Furcht", "w. Schrecknisse"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Drohrede und Klagelied über den Fürsten von Tyrus", footnotes: ["℘ V. 1-19: Kap. 26; 27; Jes 23; Am 1,9.10; Sach 9,2-4"] },
      { number: 2, text: "Menschensohn, sage zum Fürsten von Tyrus*: So spricht der Herr, HERR: Weil dein Herz hoch hinaus will und du sagst: »Gott bin ich*, den Wohnsitz der Götter bewohne ich im Herzen der Meere!«, während du <doch nur> ein Mensch bist und nicht Gott*; du aber erhebst dein Herz, als wäre es Gottes Herz* —", footnotes: ["℘ Mt 11,21", "℘ Jes 14,14; Dan 11,36; Apg 12,22; 2Thes 2,4", "℘ Ps 9,21; Jes 31,3", "w. du aber machst dein Herz wie das Herz Gottes\n℘ Kap. 29,3.9"] },
      { number: 3, text: "siehe, du bist weiser als Daniel, nichts Verborgenes ist dunkel für dich*;", footnotes: ["℘ Dan 5,11"] },
      { number: 4, text: "durch deine Weisheit und durch deinen Verstand hast du dir Reichtum* erworben und hast Gold und Silber in deine Schatzkammern geschafft*;", footnotes: ["o. Macht", "℘ Dan 5,11"] },
      { number: 5, text: "durch die Größe deiner Weisheit hast du mit deinem Handel deinen Reichtum vermehrt, dein Herz wollte wegen deines Reichtums hoch hinaus* —;", footnotes: ["℘ V. 17; 5Mo 8,17; 2Kö 14,10; Ps 62,11"] },
      { number: 6, text: "darum, so spricht der Herr, HERR: Weil du dein Herz erhebst, als wäre es Gottes Herz*,", footnotes: ["w. Weil du dein Herz machst wie das Herz Gottes"] },
      { number: 7, text: "darum, siehe, ich bringe Fremde über dich, die gewalttätigsten Nationen*, die werden ihre Schwerter ziehen gegen die Schönheit deiner Weisheit und werden deinen Glanz entweihen*.", footnotes: ["℘ Kap. 32,12", "℘ Kap. 30,10.11; 31,12"] },
      { number: 8, text: "In die Grube werden sie dich hinabfahren lassen, und du wirst den Tod eines Erschlagenen sterben im Herzen der Meere." },
      { number: 9, text: "Wirst du dann angesichts deiner Mörder auch noch sagen: »Gott bin ich!«, während du <doch nur> ein Mensch bist und nicht Gott, in der Hand derer, die dich durchbohren*?", footnotes: ["so mit einer hebr. Handschriftengruppe; Mas. T.: die dich entweihen\n℘ Ps 82,7"] },
      { number: 10, text: "Den Tod* von Unbeschnittenen wirst du sterben durch die Hand der Fremden*; denn ich habe geredet, spricht der Herr, HERR*.", footnotes: ["Im Hebr. steht die Mehrzahl zum Ausdruck der Verstärkung.", "℘ Kap. 32,19.21", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 11, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 12, text: "Menschensohn, erhebe ein Klagelied über den König von Tyrus und sage ihm: So spricht der Herr, HERR: Du warst das vollendete Siegel*, voller Weisheit und vollkommen an Schönheit,", footnotes: ["So konnte der Text vor der Vokalisierung durch die Masoreten verstanden werden. Mas. T.: der vollendete Versiegelnde"] },
      { number: 13, text: "du warst in Eden*, dem Garten Gottes*; aus Edelsteinen jeder <Art> war deine Decke: Karneol, Topas und Jaspis, Türkis, Onyx und Nephrit, Saphir, Rubin und Smaragd; und Arbeit in Gold waren deine Ohrringe* und deine Perlen* an dir; am Tag, als du geschaffen wurdest, wurden sie bereitet.", footnotes: ["℘ 1Mo 2,8", "℘ Kap. 31,8.9", "Die Bedeutung des Wortes ist unsicher. Die Üs. hat versucht, sich ihr vom Textzusammenhang her zu nähern.", "Die Bedeutung des Wortes ist unsicher. Die Üs. hat versucht, sich ihr vom Textzusammenhang her zu nähern."] },
      { number: 14, text: "Du warst ein mit ausgebreiteten <Flügeln>* schirmender Cherub*, und ich hatte dich <dazu> gemacht*; du warst auf Gottes heiligem Berg*, mitten unter feurigen Steinen gingst du einher.", footnotes: ["o. ein glänzender", "℘ Kap. 10,18", "Vor der Vokalisierung durch die Masoreten ließ sich auch lesen: Einem glänzenden, schirmenden Cherub hatte ich dich zugesellt", "℘ Jes 14,13"] },
      { number: 15, text: "Vollkommen warst du in deinen Wegen von dem Tag an, als du geschaffen wurdest, bis sich Unrecht an dir fand*.", footnotes: ["℘ Pred 7,29"] },
      { number: 16, text: "Durch die Menge deines Handels fülltest du* dein Inneres mit Gewalttat und sündigtest. Und ich verstieß dich vom Berg Gottes* und trieb dich ins Verderben, du schirmender Cherub*, aus der Mitte der feurigen Steine.", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: füllten sie", "℘ Ob 3.4", "Vor der Vokalisierung durch die Masoreten ließ sich auch lesen: und der beschirmende Cherub trieb dich ins Verderben"] },
      { number: 17, text: "Dein Herz wollte hoch hinaus wegen deiner Schönheit, du hast deine Weisheit zunichte gemacht um deines Glanzes willen. Ich habe dich zu Boden geworfen*, habe dich vor Königen dahingegeben, damit sie ihre Lust an dir sehen.", footnotes: ["℘ Spr 16,18; Jes 26,5"] },
      { number: 18, text: "Durch die Menge deiner Sünden, in der Unredlichkeit deines Handels, hast du deine Heiligtümer entweiht. Darum habe ich aus deiner Mitte ein Feuer ausgehen lassen, das hat dich verzehrt*, und ich habe dich zu Asche auf der Erde gemacht vor den Augen aller, die dich sehen.", footnotes: ["℘ Jes 66,16; Mal 3,19"] },
      { number: 19, text: "Alle, die dich kennen unter den Völkern, entsetzen sich über dich; ein Schrecken bist du geworden und bist dahin auf ewig!" },
      { number: 20, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Drohrede gegen Sidon — Die zukünftige Heilszeit für Israel" },
      { number: 21, text: "Menschensohn, richte dein Gesicht gegen Sidon* und weissage über es,", footnotes: ["℘ Jos 19,28; Jes 23,4; Jer 25,22; Joe 4,4; Sach 9,2; Mt 11,21"] },
      { number: 22, text: "und sage: So spricht der Herr, HERR: Siehe, ich will an dich, Sidon, und will mich in deiner Mitte verherrlichen*; und sie werden erkennen, dass ich der HERR bin, wenn ich Strafgerichte an ihm übe und mich an ihm als heilig erweise*.", footnotes: ["℘ Kap. 39,13; 2Mo 14,4.17", "℘ Kap. 20,41; 36,23; 38,23; Jes 5,16"] },
      { number: 23, text: "Und ich werde die Pest hineinsenden und Blut auf seine Straßen; und Erschlagene werden in seiner Mitte fallen durch das Schwert, <das> von allen Seiten über es <kommt>*. Und sie werden erkennen, dass ich der HERR bin. —", footnotes: ["℘ Kap. 5,17; 21,14-16; 30,4; 32,30"] },
      { number: 24, text: "Und für das Haus Israel soll es nicht mehr einen stechenden Dorn und einen schmerzenden Stachel geben* von allen <Nachbarn> um sie her, die sie verachten. Und sie werden erkennen, dass ich der Herr, HERR, bin.", footnotes: ["℘ 4Mo 33,55"] },
      { number: 25, text: "So spricht der Herr, HERR: Wenn ich das Haus Israel aus den Völkern sammle, unter die sie zerstreut worden sind*, und ich mich an ihnen vor den Augen der Nationen als heilig erweise*, dann werden sie in ihrem Land wohnen, das ich meinem Knecht Jakob gegeben habe*.", footnotes: ["℘ Kap. 11,17", "℘ Kap. 20,41; 36,23; 38,23; Jes 5,16", "℘ Kap. 36,28; 37,25; 1Mo 28,13"] },
      { number: 26, text: "Und sie werden in Sicherheit darin wohnen* und Häuser bauen und Weinberge pflanzen; und sie werden in Sicherheit wohnen*, wenn ich Strafgerichte geübt habe an allen, die sie verachteten aus ihrer Umgebung*. Und sie werden erkennen, dass ich der HERR bin, ihr Gott.", footnotes: ["℘ Kap. 34,25-28; Jer 32,37; Hos 11,11", "℘ Kap. 20,41; 36,23; 38,23; Jes 5,16", "℘ Jer 12,14"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "*Im zehnten Jahr, im zehnten <Monat>, am Zwölften des Monats*, geschah das Wort des HERRN zu mir so:", heading: "Drohrede gegen Ägypten und Ankündigung späterer Wiederherstellung — Ägypten als ausgleichenden Lohn für Nebukadnezars mühevolle Belagerung von Tyrus", footnotes: ["℘ Kap. 30; 31; 32; Jes 19; 20; Jer 43,8-13; 46,1-26", "℘ V. 17; Kap. 8,1"] },
      { number: 2, text: "Menschensohn, richte dein Gesicht gegen den Pharao, den König von Ägypten, und weissage über ihn und über ganz Ägypten*.", footnotes: ["℘ Jer 25,17.19; 44,30"] },
      { number: 3, text: "Rede und sage: So spricht der Herr, HERR: Siehe, ich will an dich, Pharao, König von Ägypten, du großes Seeungeheuer*, das inmitten seiner Ströme* liegt, das da sagt: »Mein Strom gehört mir, und ich selbst habe ihn mir gemacht*.«", footnotes: ["℘ Jes 27,1", "Das hebr. Wort bezeichnet stets die Arme und Kanäle des Nil.", "℘ Kap. 28,2; Dan 4,27; Am 6,13"] },
      { number: 4, text: "Ich lege Haken in deine Kinnbacken* und lasse die Fische deiner Ströme* an deinen Schuppen haften und ziehe dich aus deinen Strömen herauf mit allen Fischen deiner Ströme, die an deinen Schuppen haften.", footnotes: ["℘ Kap. 38,4; Jes 37,29", "Das hebr. Wort bezeichnet stets die Arme und Kanäle des Nil."] },
      { number: 5, text: "Und ich werfe dich in die Wüste, dich und alle Fische deiner Ströme*; auf die Fläche des Feldes wirst du fallen. Du wirst nicht aufgelesen und nicht eingesammelt*: den Tieren der Erde und den Vögeln des Himmels gebe ich dich zum Fraß*,", footnotes: ["Das hebr. Wort bezeichnet stets die Arme und Kanäle des Nil.", "℘ Jer 25,33", "℘ Kap. 39,17-20"] },
      { number: 6, text: "und alle Bewohner von Ägypten werden erkennen, dass ich der HERR bin. Weil du dem Haus Israel eine Stütze aus Schilfrohr gewesen bist* —", footnotes: ["so mit LXX, Vulg. und der syr. Üs.; Mas. T.: Weil sie . . . eine Stütze aus Schilfrohr gewesen sind\n℘ Kap. 17,17; 2Kö 18,21; Kla 4,17"] },
      { number: 7, text: "wenn sie dich mit der Hand fassten, knicktest du ein und rissest ihnen die ganze Schulter* auf; und wenn sie sich auf dich lehnten, zerbrachst du und ließest ihnen allen die Hüften wanken* —;", footnotes: ["LXX und die syr. Üs. lesen: die ganze Hand", "so mit der syr. Üs.; Mas. T.: ließest alle ihre Hüften fest stehen\n℘ Jes 20,5.6; 30,3; Nah 3,9.10"] },
      { number: 8, text: "darum, so spricht der Herr, HERR: Siehe, ich bringe das Schwert über dich und rotte aus dir Menschen und Vieh aus;" },
      { number: 9, text: "und das Land Ägypten wird zur Einöde und Trümmerstätte werden. Und sie werden erkennen, dass ich der HERR bin. Weil du sagst*: »Der Strom* gehört mir, und ich selbst habe ihn gemacht«*;", footnotes: ["so mit LXX, Vulg. und der syr. Üs.; Mas. T.: Weil er sagt", "Das hebr. Wort bezeichnet stets die Arme und Kanäle des Nil.", "℘ Kap. 28,2; Dan 4,27; Am 6,13"] },
      { number: 10, text: "darum, siehe, will ich an dich und an deine Ströme*; und ich mache das Land Ägypten zu Trümmerstätten der Verwüstung, <zur> Einöde, von Migdol* <bis nach> Syene*, bis an die Grenze von Kusch*.", footnotes: ["Das hebr. Wort bezeichnet stets die Arme und Kanäle des Nil.", "d. i. eine Grenzbefestigung an der Nordostgrenze des Nildeltas\n℘ Jer 44,1", "d. i. ein Ort in der Nähe des jetzigen Assuan", "℘ Joe 4,19"] },
      { number: 11, text: "Der Fuß eines Menschen wird es nicht durchwandern, und der Fuß eines Tieres wird es nicht durchwandern, und es wird vierzig Jahre <lang> nicht bewohnt sein*.", footnotes: ["℘ Jer 25,11; Dan 9,2"] },
      { number: 12, text: "Und ich mache das Land Ägypten zu einer Einöde mitten unter verödeten Ländern, und seine Städte werden mitten unter zertrümmerten Städten eine Einöde sein, vierzig Jahre <lang>; und ich werde die Ägypter unter die Nationen versprengen und sie in die Länder zerstreuen. —" },
      { number: 13, text: "Denn so spricht der Herr, HERR: Am Ende von vierzig Jahren werde ich die Ägypter aus den Völkern sammeln, wohin sie versprengt wurden*;", footnotes: ["℘ Jer 46,26"] },
      { number: 14, text: "und ich werde das Geschick Ägyptens wenden und sie in das Land Patros*, in das Land ihrer Herkunft, zurückbringen, und dort werden sie ein niedriges Königreich sein*.", footnotes: ["d. i. Oberägypten\n℘ Jes 11,11; Jer 44,1", "℘ Sach 10,11"] },
      { number: 15, text: "Und es wird niedriger sein als die <anderen> Königreiche und sich nicht mehr über die Nationen erheben; und ich will sie vermindern, so dass sie nicht mehr über die Nationen herrschen*.", footnotes: ["℘ Sach 10,11"] },
      { number: 16, text: "Und sie sollen* für das Haus Israel nicht mehr zum <Anlass für falsches> Vertrauen werden, das Schuld in Erinnerung bringt, wenn die Israeliten* sich zu ihnen hinwenden*. Und sie werden erkennen, dass ich der Herr, HERR, bin.", footnotes: ["so mit den alten Üs.; Mas. T.: es soll", "w. sie", "℘ Jes 36,6; Kla 4,17"] },
      { number: 17, text: "Und es geschah im 27. Jahr, im ersten <Monat>, am Ersten des Monats*, da geschah das Wort des HERRN zu mir so:", footnotes: ["℘ V. 1"] },
      { number: 18, text: "Menschensohn, Nebukadnezar, der König von Babel, hat sein Heer eine schwere Arbeit tun lassen gegen Tyrus*. Jeder Kopf ist kahl geworden, und jede Schulter ist blank gescheuert; aber Lohn ist ihm und seinem Heer von Tyrus nicht zuteilgeworden für die Arbeit, die er gegen es geleistet hat.", footnotes: ["℘ Kap. 26,7"] },
      { number: 19, text: "Darum, so spricht der Herr, HERR: Siehe, ich gebe Nebukadnezar, dem König von Babel, das Land Ägypten; und er wird seinen Prunk* wegtragen und seinen Raub rauben und seine Beute erbeuten; das wird der Lohn für sein Heer sein.", footnotes: ["o. Reichtum"] },
      { number: 20, text: "Als seinen Lohn, für den er gearbeitet hat, habe ich ihm das Land Ägypten gegeben, weil sie für mich gearbeitet haben, spricht der Herr, HERR*. —", footnotes: ["w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 21, text: "An jenem Tag werde ich dem Haus Israel ein Horn hervorsprossen lassen*, und dir gebe ich Freimut zum Reden* in ihrer Mitte; und sie werden erkennen, dass ich der HERR bin.", footnotes: ["℘ Ps 132,17", "w. dir gebe ich ein Auftun des Mundes"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Weitere Aussprüche zum bevorstehenden Gericht über Ägypten", footnotes: ["℘ Kap. 29; 31; 32; Jes 19; 20; Jer 43,8-13; 46,1-26"] },
      { number: 2, text: "Menschensohn, weissage und sage: So spricht der Herr, HERR: Heult! Wehe, der Tag!" },
      { number: 3, text: "Denn nahe ist der Tag*; ja, nahe ist der Tag des HERRN*, ein Tag des Gewölks*; <Gerichts>zeit der Nationen wird er sein*.", footnotes: ["℘ Kap. 7,7; Jes 13,6; Ob 15", "℘ Sach 10,11", "℘ Kap. 34,12", "℘ Jer 25,31"] },
      { number: 4, text: "Und das Schwert kommt gegen Ägypten*; und Zittern herrscht in Kusch*, wenn der Erschlagene in Ägypten fällt und man seinen Prunk* wegnimmt und <wenn> seine Grundfesten niedergerissen werden.", footnotes: ["℘ Kap. 28,23", "℘ Jes 20,3.4; Zef 2,12", "o. Reichtum"] },
      { number: 5, text: "Kusch* und Put und Lud* und das ganze <Völker>gemisch* und Kub und die Söhne des Bundeslandes werden mit ihnen durchs Schwert fallen*.", footnotes: ["℘ 2Chr 12,3", "℘ Kap. 27,10; Jer 46,9; Nah 3,9", "℘ Jer 25,20.24", "℘ Zef 2,12"] },
      { number: 6, text: "So spricht der HERR: Da werden <alle>, die Ägypten stützen, fallen, und herabstürzen wird der Stolz seiner Macht; von Migdol* bis nach Syene* werden sie darin durchs Schwert fallen, spricht der Herr, HERR*.", footnotes: ["d. i. eine Grenzbefestigung an der Nordostgrenze des Nildeltas", "d. i. ein Ort in der Nähe des jetzigen Assuan", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 7, text: "Und sie werden zur Wüste mitten unter verwüsteten Ländern, und seine Städte werden mitten unter verödeten Städten sein." },
      { number: 8, text: "Und sie werden erkennen, dass ich der HERR bin, wenn ich Feuer an Ägypten lege und alle seine Helfer zerschmettert werden*.", footnotes: ["℘ Ps 46,10"] },
      { number: 9, text: "An jenem Tag werden Boten in Schiffen ausfahren von mir, um das sichere Kusch aufzuschrecken*; und Zittern wird unter ihnen herrschen am Tag Ägyptens. Denn siehe, es kommt!*", footnotes: ["℘ Jes 18,1.2", "℘ Kap. 24,14; 33,33; Hab 2,3"] },
      { number: 10, text: "So spricht der Herr, HERR: Ja, ich werde den Prunk* Ägyptens wegschaffen durch die Hand Nebukadnezars, des Königs von Babel*.", footnotes: ["o. Reichtum", "℘ Jer 43,11"] },
      { number: 11, text: "Er und sein Volk mit ihm, die gewalttätigsten Nationen*, werden herangeführt werden, um das Land zu verheeren; und sie werden ihre Schwerter gegen Ägypten ziehen und das Land mit Erschlagenen füllen.", footnotes: ["℘ Kap. 28,7"] },
      { number: 12, text: "Und ich werde die Ströme* zum trockenen Land machen und das Land in die Hand böser <Menschen> verkaufen und das Land und seine Fülle durch die Hand Fremder verwüsten. Ich, der HERR, habe geredet.", footnotes: ["s. Anm. zu Kap. 29,3"] },
      { number: 13, text: "So spricht der Herr, HERR: Ja, ich werde die Götzen* zugrunde richten und die Götzen* aus Nof* wegschaffen*, und der Fürst aus dem Land Ägypten wird <bald> nicht mehr sein; und ich werde Furcht in das Land Ägypten bringen.", footnotes: ["w. die Nichtse; die syr. Üs. liest: die Gewalthaber", "w. die Nichtse; die syr. Üs. liest: die Gewalthaber", "d. i. Memfis, eine bedeutende Stadt Unterägyptens", "℘ Jer 10,11; 46,19"] },
      { number: 14, text: "Und ich werde Patros* verwüsten, Feuer an Zoan* legen und Strafgerichte üben an No*.", footnotes: ["d. i. Oberägypten", "d. i. eine Stadt am zweiten östlichen Nilarm, die eine Zeit lang Königsresidenz war", "d. i. Theben, die Hauptstadt Oberägyptens\n℘ Jer 46,25"] },
      { number: 15, text: "Und ich werde meinen Grimm ausgießen über Sin*, das Bollwerk Ägyptens; und den Prunk* von No* werde ich ausrotten.", footnotes: ["von Vulg. mit Pelusium gleichgesetzt, im Nordosten des Deltas", "o. Reichtum", "d. i. Theben, die Hauptstadt Oberägyptens"] },
      { number: 16, text: "Und ich werde Feuer an Ägypten legen; Sin wird sich in Krämpfen winden, und No wird aufgebrochen werden, und Nof — Gegner bei Tage!" },
      { number: 17, text: "Die jungen Männer von On* und Pi-Beseth* werden durchs Schwert fallen, und sie selbst werden in die Kriegsgefangenschaft gehen.", footnotes: ["so mit LXX und Vulg.; Mas. T.: Awan; On (griech. Heliopolis) war der Hauptsitz des Sonnendienstes\n℘ 1Mo 41,45; Jer 43,13; Am 1,5", "ägypt. Pa-Bast (Bubastis), wo die Gottheit Bast verehrt wurde"] },
      { number: 18, text: "Und zu Tachpanhes* wird der Tag sich verfinstern*, wenn ich dort die Jochstäbe* Ägyptens zerbreche und der Stolz seiner Macht darin ein Ende nimmt. Gewölk wird es bedecken, und seine Tochterstädte werden in die Kriegsgefangenschaft gehen.", footnotes: ["d. i. eine Grenzfestung gegen Syrien und Palästina, in der Nähe von Pelusium; vgl. Jer 43,7—9; 44,1\n℘ Jer 43,7; 44,1", "so mit den meisten hebr. Handschr.; Mas. T.: wird der Tag ausbleiben", "LXX und Vulg. lesen: die Zepter"] },
      { number: 19, text: "So werde ich Strafgerichte an Ägypten üben; und sie werden erkennen, dass ich der HERR bin." },
      { number: 20, text: "Und es geschah im elften Jahr, im ersten <Monat>, am Siebten des Monats*, da geschah das Wort des HERRN zu mir so:", footnotes: ["℘ Kap. 8,1"] },
      { number: 21, text: "Menschensohn, den Arm des Pharao, des Königs von Ägypten, habe ich zerbrochen*; und siehe, er ist nicht verbunden worden, <ihm> Heilung zu verschaffen, indem man einen Verband angelegt hätte, ihn zu verbinden*, um ihn zu stärken, damit er das Schwert fassen kann*. —", footnotes: ["℘ 2Kö 24,7; Jer 48,25", "℘ Jer 46,11", "T.; Mas. T.: damit er stark werde, das Schwert zu fassen"] },
      { number: 22, text: "Darum, so spricht der Herr, HERR: Siehe, ich will an den Pharao, den König von Ägypten, und zerbreche seine Arme, den starken und den zerbrochenen, und lasse das Schwert seiner Hand entfallen." },
      { number: 23, text: "Und ich versprenge die Ägypter unter die Nationen und zerstreue sie in die Länder." },
      { number: 24, text: "Und ich stärke die Arme des Königs von Babel und gebe mein Schwert in seine Hand*; die Arme des Pharao aber zerbreche ich, dass er wie ein <vom Schwert> Durchbohrter vor ihm ächzen wird*.", footnotes: ["℘ Jer 27,6-8", "w. dass er das Ächzen eines Durchbohrten ächzen wird"] },
      { number: 25, text: "Und ich stärke die Arme des Königs von Babel, aber die Arme des Pharao werden sinken. Und sie werden erkennen, dass ich der HERR bin, wenn ich mein Schwert in die Hand des Königs von Babel gebe und er es gegen das Land Ägypten ausstreckt." },
      { number: 26, text: "Und ich werde die Ägypter unter die Nationen versprengen und sie in die Länder zerstreuen; und sie werden erkennen, dass ich der HERR bin." },
    ]},
    { number: 31, verses: [
      { number: 1, text: "*Und es geschah im elften Jahr, im dritten <Monat>, am Ersten des Monats*, da geschah das Wort des HERRN zu mir so:", heading: "Größe und Sturz des Pharao", footnotes: ["℘ Kap. 29; 30; 32; Jes 19; 20; Jer 43,8-13; 46,1-26", "℘ Kap. 8,1"] },
      { number: 2, text: "Menschensohn, sage zum Pharao, dem König von Ägypten, und zu seinem Prunk*: Wem gleichst du in deiner Größe?", footnotes: ["o. zu seiner lärmenden Menge; o. zu seinem Reichtum"] },
      { number: 3, text: "Siehe, eine Zypresse,* eine Zeder auf dem Libanon, mit schönen Zweigen — ein Schatten spendender Wald — und von hohem Wuchs; und zwischen den Wolken war ihr Wipfel*.", footnotes: ["So hat der Text vielleicht ursprünglich gelautet. Mas. T.: Siehe, Assur war", "℘ Dan 4,7"] },
      { number: 4, text: "Das Wasser zog sie groß, die Flut ließ sie hoch aufwachsen. Ihre Ströme hatte sie* ausgehen lassen* rings um ihre Pflanzung, und sie hatte ihre Kanäle ausgesandt zu allen Bäumen des Feldes.", footnotes: ["d. i. die Flut", "so mit LXX; Mas. T. lässt sich nicht sinnvoll übersetzen"] },
      { number: 5, text: "Darum war ihr Wuchs höher als alle Bäume des Feldes; und ihre Zweige wurden zahlreich und ihre Äste lang von den vielen Wassern, als sie <ihre Zweige> ausbreitete." },
      { number: 6, text: "In ihren Zweigen nisteten alle Vögel des Himmels*, und unter ihren Ästen warfen alle Tiere des Feldes <ihre Jungen>; und in ihrem Schatten wohnten all die vielen Nationen*.", footnotes: ["℘ Ps 104,17", "℘ Kap. 17,23"] },
      { number: 7, text: "Und sie war schön in ihrer Größe und in der Länge ihrer Zweige; denn ihre Wurzel war an vielen Wassern." },
      { number: 8, text: "Die Zedern kamen ihr nicht gleich im Garten Gottes*, die <Zweige der> Wacholder waren nicht zu vergleichen mit* ihren Zweigen, und die <Äste der> Platanen waren nicht wie ihre Äste; kein Baum im Garten Gottes* glich ihr in ihrer Schönheit.", footnotes: ["℘ Kap. 28,13", "w. glichen nicht", "℘ Sach 10,11"] },
      { number: 9, text: "Ich hatte sie schön gemacht in der Menge ihrer Zweige; und alle Bäume Edens, die im Garten Gottes waren, beneideten sie." },
      { number: 10, text: "Darum, so hat der Herr, HERR gesprochen: Weil sie hoch geworden ist* an Wuchs und sie ihren Wipfel bis zwischen die Wolken streckte und ihr Herz sich wegen ihrer Höhe erhob*,", footnotes: ["so mit der syr. Üs. und Vulg.; Mas. T.: Weil du hoch geworden bist", "℘ Dan 5,20"] },
      { number: 11, text: "so werde ich sie in die Hand des Mächtigen der Nationen geben. Nach ihrer Gottlosigkeit soll er mit ihr handeln; ich habe sie verstoßen*.", footnotes: ["℘ Mt 23,12"] },
      { number: 12, text: "Und Fremde, die gewalttätigsten Nationen*, hieben sie um und warfen sie hin; auf die Berge und in alle Täler fielen ihre Zweige, und ihre Äste wurden zerbrochen in allen Bachrinnen des Landes. Und alle Völker der Erde zogen aus ihrem Schatten weg* und ließen sie liegen*;", footnotes: ["℘ Kap. 28,7", "w. zogen . . . herab", "℘ Dan 4,11; Nah 3,18"] },
      { number: 13, text: "auf ihrem gefällten Stamm* ließen sich alle Vögel des Himmels nieder, und auf ihren Ästen waren alle Tiere des Feldes*,", footnotes: ["Das Wort bedeutet auch »Aas« o. »Kadaver«.", "℘ Jes 18,6"] },
      { number: 14, text: "damit keine Bäume am Wasser sich <mehr> erheben mit ihrem Wuchs und ihren Wipfel bis zwischen die Wolken strecken und *keine wassertrinkenden <Bäume> sich auf sich selbst stellen in ihrer Höhe*. Denn sie alle sind dem Tod preisgegeben, hin zum Land der Tiefe, mitten unter den Menschenkindern, zu denen, die in die Grube hinabgefahren sind.", footnotes: ["so mit vielen hebr. Handschr., LXX und der aram. Üs.; Mas. T.: und ihre Bäume (o. ihre Gewaltigen, o. ihre Götter) nicht in ihrer Höhe dastehen, die, die Wasser trinken", "so mit vielen hebr. Handschr., LXX und der aram. Üs.; Mas. T.: und ihre Bäume (o. ihre Gewaltigen, o. ihre Götter) nicht in ihrer Höhe dastehen, die, die Wasser trinken\n℘ Ps 76,13"] },
      { number: 15, text: "So spricht der Herr, HERR: Am Tag, als sie in den Scheol hinabfuhr, habe ich um ihretwillen die Tiefe* in Trauer versetzt, ich habe <sie> verhüllt und ihre Ströme zurückgehalten; die großen Wasser wurden gehemmt, und den Libanon hüllte ich in Trauer um ihretwillen, alle Bäume des Feldes wurden um ihretwillen ohnmächtig*.", footnotes: ["o. die Flut; dasselbe Wort wie 1Mo 1,2", "℘ Kap. 26,16-18"] },
      { number: 16, text: "Vom Getöse ihres Falls ließ ich die Nationen erbeben, als ich sie in den Scheol hinabfahren ließ mit denen, die in die Grube hinabfahren. Und alle Bäume Edens, das Auserlesene und Beste des Libanon, alle Wassertrinkenden trösteten sich im Land der Tiefe*.", footnotes: ["℘ Jes 14,8-19"] },
      { number: 17, text: "Auch sie fuhren mit ihr in den Scheol hinab zu den vom Schwert Erschlagenen, *und es kamen um, die in ihrem Schatten wohnten*, mitten unter den Nationen*.", footnotes: ["so in Anlehnung an LXX; Mas. T.: und ihr Arm — sie wohnten in ihrem Schatten", "so in Anlehnung an LXX; Mas. T.: und ihr Arm — sie wohnten in ihrem Schatten", "℘ Kla 4,20"] },
      { number: 18, text: "Wem gleichst du* so an Herrlichkeit und an Größe unter den Bäumen Edens? So wirst du mit den Bäumen Edens hinabgestürzt werden ins Land der Tiefe. Mitten unter den Unbeschnittenen wirst du liegen, bei den vom Schwert Erschlagenen. Das ist der Pharao und sein ganzer Prunk*, spricht der Herr, HERR*.", footnotes: ["vgl. V. 2", "o. seine ganze lärmende Menge; o. sein ganzer Reichtum", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "*Und es geschah im zwölften Jahr, im zwölften Monat, am Ersten des Monats*, da geschah das Wort des HERRN zu mir so:", heading: "Klagelied über den Pharao — Pharao im Scheol", footnotes: ["℘ Kap. 29; 30; 31; Jes 19; 20; Jer 43,8-13; 46,1-26", "℘ V. 17; Kap. 8,1"] },
      { number: 2, text: "Menschensohn, erhebe ein Klagelied* über den Pharao, den König von Ägypten, und sage zu ihm: Einem Junglöwen unter den Nationen* bist du gleich geworden*; und doch warst du wie ein Seeungeheuer in den Meeren* und sprudeltest mit deinen Nüstern* und trübtest das Wasser mit deinen Füßen und wühltest ihre Ströme auf*.", footnotes: ["℘ V. 16; Kap. 26,17; 27,2", "w. der Nationen", "℘ Kap. 19,3; Spr 30,30", "Gemeint ist das Krokodil im Nil.", "So hat der Text vielleicht ursprünglich gelautet. Mas. T.: sprudeltest in deinen Strömen", "℘ Hi 41,23"] },
      { number: 3, text: "So spricht der Herr, HERR: Daher werde ich mein Fangnetz über dich ausspannen durch eine Schar vieler Völker, und man wird dich in meinem Garn heraufziehen*.", footnotes: ["℘ Kap. 12,13; Pred 9,12"] },
      { number: 4, text: "Und ich werfe dich auf das Land, schleudere dich auf das freie Feld; und ich mache, dass sich alle Vögel des Himmels auf dir niederlassen und sich die Tiere der ganzen Erde von dir sättigen*.", footnotes: ["℘ Kap. 39,4"] },
      { number: 5, text: "Und ich lege dein Fleisch auf die Berge und fülle die Täler mit deinem Aas*.", footnotes: ["w. mit deinem Leichenhaufen"] },
      { number: 6, text: "Und ich tränke das Land mit deinem Ausfluss von deinem Blut auf den Bergen, und die Bachrinnen werden mit dir angefüllt sein*.", footnotes: ["℘ Kap. 35,8; Jes 34,3; Offb 16,6"] },
      { number: 7, text: "Und ich werde, wenn ich dich auslösche, den Himmel bedecken und seine Sterne verdunkeln; ich werde die Sonne mit Gewölk bedecken, und der Mond wird sein Licht nicht scheinen lassen*.", footnotes: ["℘ 2Mo 10,22; Jes 13,10; Offb 6,12; 8,12"] },
      { number: 8, text: "Alle leuchtenden Lichter* am Himmel werde ich deinetwegen verdunkeln, und ich werde Finsternis über dein Land bringen*, spricht der Herr, HERR*.", footnotes: ["w. alle Lichtträger von Licht", "℘ 2Mo 10,22; Jes 13,10; Offb 6,12; 8,12", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 9, text: "Und ich werde das Herz vieler Völker beunruhigen, wenn ich deinen Zusammenbruch* über die Nationen kommen lasse*, in Länder, die du nicht gekannt hast.", footnotes: ["LXX: deine Kriegsgefangenen", "℘ 2Mo 15,14; Offb 18,10"] },
      { number: 10, text: "Und ich werde vielen Völkern deinetwegen Entsetzen einflößen, und ihren Königen werden deinetwegen die Haare zu Berge stehen, wenn ich mein Schwert vor ihnen schwinge*; und sie werden immer wieder erzittern, jeder um sein Leben, am Tag deines Falls*. —", footnotes: ["℘ 5Mo 32,41", "℘ Kap. 26,16"] },
      { number: 11, text: "Denn so spricht der Herr, HERR: Das Schwert des Königs von Babel wird über dich kommen*.", footnotes: ["℘ Jer 46,26"] },
      { number: 12, text: "Durch die Schwerter von Helden werde ich deine Menge* fällen; die Gewalttätigsten der Nationen sind sie alle*; und sie werden den Hochmut Ägyptens zerstören, und sein ganzer Prunk* wird ausgetilgt*.", footnotes: ["o. deinen Prunk, o. Reichtum", "℘ Kap. 28,7", "o. sein ganzer Reichtum; o. seine ganze lärmende Menge", "℘ V. 18; Jer 46,12"] },
      { number: 13, text: "Und ich werde all sein Vieh an den vielen Wassern* zugrunde richten, so dass der Fuß des Menschen sie nicht mehr trübt, noch die Klauen des Viehs sie trüben.", footnotes: ["w. von den vielen Wassern hinweg"] },
      { number: 14, text: "Dann werde ich ihre Wasser klären* und ihre Flüsse wie Öl fließen lassen, spricht der Herr, HERR*. —", footnotes: ["w. sich setzen lassen", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 15, text: "Wenn ich das Land Ägypten zu einer Einöde mache und wenn das Land ohne seine Fülle verwüstet daliegt, wenn ich alle, die darin wohnen, schlage, dann werden sie erkennen, dass ich der HERR bin." },
      { number: 16, text: "Das ist ein Klagelied, und man soll es als Klagelied singen, die Töchter der Nationen sollen es als Klagelied singen; sie sollen es als Klagelied singen über Ägypten und über seinen ganzen Prunk*, spricht der Herr, HERR*.", footnotes: ["o. seine ganze lärmende Menge; o. seinen ganzen Reichtum", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 17, text: "Und es geschah im zwölften Jahr, am Fünfzehnten des Monats*, da geschah das Wort des HERRN zu mir so:", footnotes: ["℘ V. 1"] },
      { number: 18, text: "Menschensohn, wehklage über den Prunk* Ägyptens, und stürze ihn hinab, Ägypten* und die Töchter mächtiger Nationen, in das Land der Tiefen*, zu denen, die in die Grube hinabgefahren sind!*", footnotes: ["o. die lärmende Menge; o. den Reichtum", "w. über es. — Andere üs. mit Streichung eines Buchstabens: du", "o. in die Tiefen <unter> der Erde", "℘ V. 12; Kap. 26,20"] },
      { number: 19, text: "Wen übertriffst du <jetzt noch> an Anmut? Fahr hinab, und lege dich zu den Unbeschnittenen!*", footnotes: ["℘ Kap. 28,10"] },
      { number: 20, text: "Mitten unter den vom Schwert Erschlagenen sollen sie fallen! Das Schwert ist <ihnen> bestimmt. Schleppt mit Ägypten* auch seinen ganzen Prunk* herbei!", footnotes: ["w. mit ihm", "o. seine ganze lärmende Menge; o. seinen ganzen Reichtum"] },
      { number: 21, text: "Es reden mit ihm die gewaltigen Helden mitten aus dem Scheol, mit <ihm und> seinen Helfern. Sie sind hinabgefahren, sie liegen da, die Unbeschnittenen, die vom Schwert Erschlagenen*.", footnotes: ["℘ Jes 14,9.10"] },
      { number: 22, text: "Dort ist Assur* und sein ganzes Aufgebot rings um sein Grab her*: sie alle, Erschlagene, durchs Schwert Gefallene,", footnotes: ["℘ Jes 14,25; Nah 3,18", "T. entsprechend V. 23b und 24a; Mas. T.: rings um ihn her seine Gräber"] },
      { number: 23, text: "<Assur,> dem seine Gräber in der tiefsten Grube gegeben worden sind, und sein Aufgebot ist rings um sein Grab her <begraben>. Sie alle sind Erschlagene, durchs Schwert Gefallene, die <einst> Schrecken verbreiteten im Land der Lebenden*.", footnotes: ["℘ Kap. 26,17; Jes 14,16.17"] },
      { number: 24, text: "Dort ist Elam* und sein ganzer Prunk* rings um sein Grab her*, sie alle, Erschlagene, durchs Schwert Gefallene, die als Unbeschnittene ins Land der Tiefen* hinabgefahren sind, die <einst> ihren Schrecken verbreitet hatten im Land der Lebenden; und sie tragen ihre Schmach mit denen, die in die Grube hinabgefahren sind.", footnotes: ["d. i. die persische Provinz, deren Hauptstadt Susa war\n℘ Jer 49,34-38", "o. seine ganze Menge; o. sein ganzer Reichtum", "T. entsprechend V. 23b und 24a; Mas. T.: rings um ihn her seine Gräber", "o. in die Tiefen <unter> der Erde"] },
      { number: 25, text: "Mitten unter Erschlagenen hat man ihm ein Lager gegeben mit seinem ganzen Prunk* rings um sein Grab her*. Sie alle sind Unbeschnittene, vom Schwert Erschlagene, weil <einst> ihr Schrecken verbreitet war im Land der Lebenden; und sie tragen <nun> ihre Schmach mit denen, die in die Grube hinabgefahren sind. Mitten unter Erschlagene ist er gelegt.", footnotes: ["o. mit seiner ganzen Menge; o. mit seinem ganzen Reichtum", "T. entsprechend V. 23b und 24a; Mas. T.: rings um ihn her seine Gräber"] },
      { number: 26, text: "Dort ist Meschech-Tubal* und sein ganzer Prunk*; rings um sein Grab her*, sie alle, Unbeschnittene, sie sind vom Schwert erschlagen, weil sie ihren Schrecken verbreitet hatten im Land der Lebenden.", footnotes: ["℘ Kap. 27,13", "o. seine ganze Menge; o. sein ganzer Reichtum", "T. entsprechend V. 23b und 24a; Mas. T.: rings um ihn her seine Gräber"] },
      { number: 27, text: "Und sie liegen nicht bei den Helden, die in der Vorzeit gefallen sind*, die in den Scheol hinabfuhren mit ihren Kriegswaffen und die ihre Schwerter unter ihre Häupter legten und deren Schilde* auf ihren Gebeinen liegen; denn der Schrecken vor den Helden* <hatte einst> im Land der Lebenden* <geherrscht>. —", footnotes: ["so mit LXX und der alten lat. Üs.; Mas. T.: bei den Helden, die von den Unbeschnittenen <getrennt> gefallen sind", "So lautete der Text vielleicht ursprünglich. Mas. T.: deren Sünden", "w. der Schrecken der Helden", "℘ Kap. 26,17; Jes 14,16.17"] },
      { number: 28, text: "Auch du<, Ägypten,> wirst mitten unter Unbeschnittenen zerschmettert werden und bei den vom Schwert Erschlagenen liegen." },
      { number: 29, text: "Dort ist Edom*, seine Könige und all seine Fürsten, die in ihrer Heldenkraft zu den vom Schwert Erschlagenen gelegt wurden; sie liegen bei den Unbeschnittenen und bei denen, die in die Grube hinabgefahren sind.", footnotes: ["℘ Kap. 25,12-14"] },
      { number: 30, text: "Dort sind die Fürsten des Nordens insgesamt* und alle Sidonier*, die zu den Erschlagenen hinabgefahren sind <und> trotz ihres Schreckens<, den sie einflößten,> in ihrer Heldenkraft zuschanden geworden sind; und sie liegen als Unbeschnittene bei den vom Schwert Erschlagenen und tragen ihre Schmach mit denen, die in die Grube hinabgefahren sind.", footnotes: ["℘ Kap. 38,6.15; Jer 25,26", "℘ Kap. 28,21-23"] },
      { number: 31, text: "Sie <alle> wird der Pharao sehen und sich über seinen ganzen Prunk* trösten. Vom Schwert Erschlagene sind der Pharao und sein ganzes Heer, spricht der Herr, HERR*.", footnotes: ["o. mit seiner ganzen Menge; o. mit seinem ganzen Reichtum", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 32, text: "Denn ich habe Schrecken vor ihm verbreitet im Land der Lebenden; und so wird er sich mitten unter Unbeschnittene legen mit den vom Schwert Erschlagenen, der Pharao und sein ganzer Prunk*, spricht der Herr, HERR*.", footnotes: ["o. seine ganze Menge; o. sein ganzer Reichtum", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Hesekiel als Wächter und Tröster: die Freiheit zur Umkehr", footnotes: ["℘ V. 1-20: Kap. 3,16-21"] },
      { number: 2, text: "Menschensohn, rede zu den Söhnen deines Volkes*, und sage zu ihnen: Wenn ich das Schwert über ein Land bringe*, und das Volk des Landes nimmt einen Mann aus seiner Gesamtheit und setzt ihn sich als Wächter ein,", footnotes: ["℘ Kap. 3,11", "℘ Kap. 14,17"] },
      { number: 3, text: "und er sieht das Schwert über das Land kommen und stößt ins Horn und warnt das Volk*,", footnotes: ["℘ Am 3,6"] },
      { number: 4, text: "wenn <dann> einer den Schall des Horns hört, sich aber nicht warnen lässt*, und das Schwert kommt und rafft ihn weg: so wird sein Blut auf seinem Kopf bleiben.", footnotes: ["℘ Jer 25,3; Sach 1,4"] },
      { number: 5, text: "Er hat den Schall des Horns gehört, hat sich aber nicht warnen lassen; sein Blut wird auf ihm bleiben. Doch hat er sich warnen lassen, so hat er seine Seele gerettet." },
      { number: 6, text: "Wenn aber der Wächter das Schwert kommen sieht, und er stößt nicht ins Horn, und das Volk wird nicht gewarnt, und das Schwert kommt und rafft von ihnen eine Seele weg: so wird dieser um seiner Schuld willen weggerafft; aber sein Blut werde ich von der Hand des Wächters fordern*.", footnotes: ["℘ Jer 14,15"] },
      { number: 7, text: "Dich nun, Menschensohn, habe ich als Wächter für das Haus Israel eingesetzt*. Du sollst das Wort aus meinem Mund hören und sie vor mir warnen.", footnotes: ["℘ Jes 21,11; Hab 2,1"] },
      { number: 8, text: "Wenn ich zu dem Gottlosen sage: »Du Gottloser, du musst sterben!«*, du aber redest nicht, um den Gottlosen vor seinem Weg zu warnen; so wird er, der Gottlose, um seiner Schuld willen sterben; aber sein Blut werde ich von deiner Hand fordern.", footnotes: ["℘ Kap. 18,4"] },
      { number: 9, text: "Wenn du jedoch den Gottlosen vor seinem Weg warnst, damit er von ihm umkehrt, er aber von seinem Weg nicht umkehrt, so wird er um seiner Schuld willen sterben*; du aber hast deine Seele gerettet*.", footnotes: ["℘ Spr 15,10; Joh 8,24", "℘ Apg 20,26.31"] },
      { number: 10, text: "*Und du, Menschensohn, sage zum Haus Israel: So sprecht ihr und sagt: Unsere Vergehen und unsere Sünden sind auf uns, und in ihnen schwinden wir dahin*. Wie könnten wir leben?*", footnotes: ["℘ V. 10-20: Kap. 18,19-32", "℘ Kap. 24,23; 3Mo 26,39", "℘ 2Chr 34,24; Esr 9,15"] },
      { number: 11, text: "Sage zu ihnen: So wahr ich lebe, spricht der Herr, HERR*: Wenn ich Gefallen habe am Tod des Gottlosen*! Wenn nicht vielmehr daran, dass der Gottlose von seinem Weg umkehrt und lebt*!* Kehrt um, kehrt um von euren bösen Wegen! Ja, warum wollt ihr sterben, Haus Israel?", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde. Der Schwur meint: Niemals habe ich Gefallen am Tod des Gottlosen.", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde. Der Schwur meint: Niemals habe ich Gefallen am Tod des Gottlosen.", "℘ Ps 51,15; Kla 3,33; Jes 21,12; Jer 44,7.8"] },
      { number: 12, text: "Und du, Menschensohn, sage zu den Söhnen deines Volkes: Die Gerechtigkeit des Gerechten wird ihn nicht retten am Tag seines Vergehens; und die Gottlosigkeit des Gottlosen — er wird durch sie nicht stürzen an dem Tag, da er von seiner Gottlosigkeit umkehrt*. Und <die Gerechtigkeit des> Gerechten — er wird durch sie nicht leben können an dem Tag, da er sündigt*.", footnotes: ["℘ 2Chr 7,14", "℘ Jer 18,8-10"] },
      { number: 13, text: "Wenn ich dem Gerechten sage: »Leben soll er!«, und er verlässt sich auf seine Gerechtigkeit und tut Unrecht, so wird all seiner gerechten Taten* nicht gedacht werden, sondern um seines Unrechts willen, das er getan hat, deswegen wird er sterben*.", footnotes: ["w. Gerechtigkeiten", "℘ Jak 2,10"] },
      { number: 14, text: "Wenn ich aber zum Gottlosen sage: »Sterben musst du!«, und er kehrt von seiner Sünde um und übt Recht und Gerechtigkeit," },
      { number: 15, text: "<so dass> der Gottlose das Pfand zurückgibt*, Geraubtes erstattet*, in den Ordnungen, <die> zum Leben <führen>, lebt*, ohne Unrecht zu tun, so soll er am Leben bleiben, er soll nicht sterben*.", footnotes: ["℘ Kap. 18,7", "℘ 2Mo 21,37; 3Mo 5,21-24", "w. geht", "℘ Kap. 20,11"] },
      { number: 16, text: "All seiner Sünden, die er begangen hat, soll ihm nicht gedacht werden*; Recht und Gerechtigkeit hat er geübt; er soll am Leben bleiben*.", footnotes: ["℘ Ps 103,9; Mi 7,18", "℘ Kap. 20,11"] },
      { number: 17, text: "Und die Söhne deines Volkes sagen: Der Weg des Herrn ist nicht recht, wo doch ihr eigener Weg nicht recht ist." },
      { number: 18, text: "Wenn der Gerechte von seiner Gerechtigkeit umkehrt und Unrecht tut, so wird er deswegen sterben*.", footnotes: ["℘ 2Petr 2,20-22"] },
      { number: 19, text: "Und wenn der Gottlose von seiner Gottlosigkeit umkehrt und Recht und Gerechtigkeit übt, so wird er um ihretwillen leben." },
      { number: 20, text: "Ihr aber sagt: Der Weg des Herrn ist nicht recht. Ich werde euch richten, jeden nach seinen Wegen, Haus Israel*.", footnotes: ["℘ Ps 62,13; 2Kor 5,10; Offb 22,12"] },
      { number: 21, text: "Und es geschah im zwölften Jahr unserer Wegführung, im zehnten <Monat>, am Fünften des Monats*, da kam ein Entkommener aus Jerusalem zu mir und sagte: Die Stadt ist geschlagen*!", heading: "Nachricht vom Fall Jerusalems", footnotes: ["℘ Kap. 1,2", "℘ Kap. 40,1; Jer 39,2"] },
      { number: 22, text: "Und die Hand des HERRN war am Abend über mich gekommen* vor der Ankunft des Entkommenen, und er* hatte meinen Mund geöffnet auf <den Augenblick> hin, als jener am Morgen zu mir hereinkam. So wurde mein Mund <wieder> geöffnet, und ich war nicht mehr stumm*.", footnotes: ["℘ Kap. 1,3", "d. h. der HERR", "℘ Kap. 3,27; 24,25-27"] },
      { number: 23, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Keine Bereitschaft zur Umkehr — in Jerusalem wie in Babylon" },
      { number: 24, text: "Menschensohn, die Bewohner jener Trümmerstätten im Land Israel sagen: Abraham war ein Einzelner*, und er nahm das Land in Besitz; wir aber sind viele, uns ist das Land <erst recht> zum Besitz gegeben*!", footnotes: ["℘ Jes 51,2", "℘ Kap. 11,15; 1Mo 17,8; Neh 9,8"] },
      { number: 25, text: "Darum sage zu ihnen: So spricht der Herr, HERR: Ihr esst <euer Opferfleisch> mit dem Blut* und erhebt eure Augen zu euren Götzen* und vergießt Blut*! Da solltet ihr das Land besitzen?*", footnotes: ["℘ 1Mo 9,4; 3Mo 7,26.27", "℘ Kap. 18,6.12", "℘ Kap. 22,3; 36,18", "℘ Jer 7,9-15"] },
      { number: 26, text: "Ihr verlasst euch* auf euer Schwert, verübt Gräuel und macht ein jeder die Frau seines Nächsten unrein*! Da solltet ihr das Land besitzen?*", footnotes: ["w. Ihr stellt euch", "℘ Kap. 22,11; 4Mo 5,13", "℘ Jer 7,9-15"] },
      { number: 27, text: "So sollst du zu ihnen sagen: So spricht der Herr, HERR: So wahr ich lebe, wenn nicht <alle,> die in den Trümmerstätten <leben,> durchs Schwert fallen*, und <wenn ich nicht jeden,> der auf dem freien Feld ist, den wilden Tieren hingebe, dass sie ihn fressen*; und <wenn nicht> die, die in den Festungen und in den Höhlen sind, an der Pest sterben*!*", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ Kap. 5,17; 6,11"] },
      { number: 28, text: "Und ich mache das Land zur Öde und zum Grausen*, und der Stolz seiner Macht* wird ein Ende haben*; und die Berge Israels werden wüst daliegen, so dass niemand darüber hinwandert.", footnotes: ["℘ Kap. 6,14", "o. der Stolz eures Schutzes; d. h. der Schutz, auf den ihr stolz seid", "℘ Kap. 7,24; 3Mo 26,19"] },
      { number: 29, text: "Und sie werden erkennen, dass ich der HERR bin, wenn ich das Land zur Öde und zum Grausen mache wegen all ihrer Gräuel, die sie verübt haben*.", footnotes: ["℘ Kap. 5,9; 7,4; 15,7.8"] },
      { number: 30, text: "Und du, Menschensohn, die Söhne deines Volkes reden über dich an den Wänden und in den Türen der Häuser; und einer redet mit dem anderen, jeder mit seinem Bruder, und sagt: Kommt doch und hört, was das für ein Wort ist, das vom HERRN ausgeht." },
      { number: 31, text: "Und sie kommen zu dir, wie <eben> Volk zusammenkommt, und sitzen vor dir als mein Volk und hören deine Worte, aber sie tun sie nicht*, denn Liebesverlangen ist in ihrem Mund*; <danach> handeln sie, ihr Herz läuft ihrem unrechten Gewinn nach.", footnotes: ["℘ Jes 42,20; Jer 42,21; Jak 1,22-24", "LXX und die syr. Üs. lesen: denn Lügen sind in ihrem Mund"] },
      { number: 32, text: "Und siehe, du bist ihnen wie <einer, der> ein Liebeslied* <singt>, der eine schöne Stimme hat und gut zu spielen versteht; und sie hören deine Worte, doch sie tun sie nicht*.", footnotes: ["w. ein Lied des Liebesverlangens", "℘ Jes 42,20; Jer 42,21; Jak 1,22-24"] },
      { number: 33, text: "Wenn es aber kommt — siehe, es kommt!* —, so werden sie erkennen, dass ein Prophet in ihrer Mitte war*.", footnotes: ["℘ Kap. 30,9; 39,8", "℘ Kap. 2,5; 1Sam 3,20; Jer 28,9"] },
    ]},
    { number: 34, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Die schlechten Hirten Israels und Gott, der gute Hirte seines Volkes", footnotes: ["℘ V. 1-10: Jer 23,1.2; Sach 11,15-17"] },
      { number: 2, text: "Menschensohn, weissage über die Hirten Israels, weissage und sprich zu ihnen, den Hirten: So spricht der Herr, HERR: Wehe den Hirten Israels, die sich selbst weiden! Sollen die Hirten nicht die Herde* weiden?*", footnotes: ["o. die Schafe", "℘ Ps 78,72; Jes 56,11; 1Petr 5,1.2"] },
      { number: 3, text: "Die Milch* genießt ihr, und mit der Wolle kleidet ihr euch, das fette Vieh schlachtet ihr — die Herde weidet ihr nicht*.", footnotes: ["so mit LXX und Vulg.; Mas. T.: Das Fett", "℘ Mi 3,1-3; Sach 11,5; Joh 10,1.8"] },
      { number: 4, text: "Die Schwachen habt ihr nicht gestärkt und das Kranke nicht geheilt und das Gebrochene nicht verbunden und das Versprengte nicht zurückgebracht und das Verlorene nicht gesucht*, *sondern mit Härte habt ihr über sie geherrscht und* mit Gewalt*.", footnotes: ["℘ Lk 15,4", "Andere üs. mit LXX: und das Starke habt ihr niedergetreten", "Andere üs. mit LXX: und das Starke habt ihr niedergetreten", "℘ Kap. 19,6.7"] },
      { number: 5, text: "Und sie zerstreuten sich, weil sie ohne Hirten waren*, und wurden allen Tieren des Feldes zum Fraß*. So zerstreuten sich", footnotes: ["℘ 1Kö 22,17; Sach 10,2; Mt 9,36", "℘ Jer 12,9.10"] },
      { number: 6, text: "<und> irrten umher meine Schafe. Auf allen Bergen und auf jedem hohen Hügel und über das ganze Land hin sind meine Schafe zerstreut worden*, und da ist niemand, der <nach ihnen> fragt, und niemand, der <sie> sucht*. —", footnotes: ["℘ Ps 119,176; Jer 10,21; 50,6; 1Petr 2,25", "℘ Jes 51,18; Joh 10,12"] },
      { number: 7, text: "Darum, ihr Hirten, hört das Wort des HERRN!" },
      { number: 8, text: "So wahr ich lebe, spricht der Herr, HERR*: Fürwahr, weil meine Schafe zum Raub und meine Schafe allen Tieren des Feldes zum Fraß geworden sind, weil kein Hirte da war und meine Hirten nicht nach meinen Schafen fragten und die Hirten sich selbst weideten, nicht aber meine Schafe weideten*,", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "℘ Jud 12"] },
      { number: 9, text: "darum, ihr Hirten, hört das Wort des HERRN!" },
      { number: 10, text: "So spricht der Herr, HERR: Siehe, ich will an die Hirten, und ich werde meine Schafe von ihrer Hand fordern und will ihnen ein Ende machen, dass sie nicht <länger meine> Schafe weiden. Und die Hirten sollen nicht mehr sich selbst weiden; und ich werde meine Schafe aus ihrem Rachen retten, dass sie ihnen nicht mehr zum Fraß seien*.", footnotes: ["℘ Kap. 13,23"] },
      { number: 11, text: "*Denn so spricht der Herr, HERR: Siehe, ich bin es, und ich will nach meinen Schafen fragen und mich ihrer annehmen*.", footnotes: ["℘ V. 11-19: Jer 23,3.4", "℘ Sach 10,3; Mt 18,12; Lk 15,4"] },
      { number: 12, text: "Wie ein Hirte sich seiner Herde annimmt am Tag, da er unter seinen zerstreuten* Schafen ist, so werde ich mich meiner Schafe annehmen und werde sie retten aus allen Orten, wohin sie zerstreut worden sind* am Tag des Gewölks und des Wolkendunkels*.", footnotes: ["T.; Mas. T.: seinen eingeteilten, o. seinen abgesonderten", "℘ Jer 31,10", "℘ Kap. 30,3; Sach 9,16"] },
      { number: 13, text: "Und ich werde sie herausführen aus den Völkern und sie aus den Ländern sammeln und sie in ihr Land kommen lassen*; und ich werde sie weiden auf den Bergen Israels, an den Bachrinnen und an allen Wohnplätzen des Landes*.", footnotes: ["℘ Kap. 11,17; 36,24; 37,21; Jer 30,3", "℘ Jes 49,9; Jer 33,12; 50,19; Mi 2,12; 7,14"] },
      { number: 14, text: "Auf guter Weide werde ich sie weiden, und auf den hohen Bergen Israels wird ihr Weideplatz sein; dort, auf den Bergen Israels werden sie auf gutem Weideplatz lagern und fette Weide beweiden*.", footnotes: ["℘ Ps 23,1.2; Jer 31,14"] },
      { number: 15, text: "Ich selbst will meine Schafe weiden, und ich selbst will sie lagern*, spricht der Herr, HERR*.", footnotes: ["℘ Hi 34,29; Jes 40,11", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 16, text: "Das Verlorene will ich suchen* und das Versprengte zurückbringen, und das Gebrochene will ich verbinden, und das Kranke will ich stärken*; das Fette aber und das Starke werde ich austilgen*; mit <meinem> Recht werde ich sie weiden*.", footnotes: ["℘ Lk 15,5", "℘ Mi 4,6.7; Mt 9,12; Joh 10,11", "LXX, Vulg. und syr. Üs. lesen: werde ich behüten; 2 hebr. Handschr. lesen: werde ich behüten lassen\n℘ Am 4,1.2", "℘ Ps 72,2-4; Jer 23,5.6; Mi 5,3"] },
      { number: 17, text: "Und ihr, meine Herde, so spricht der Herr, HERR: Siehe, ich werde richten zwischen Schaf und Schaf, den Widdern und den Böcken*.", footnotes: ["℘ Kap. 20,36-38; Sach 10,3; Mt 25,33"] },
      { number: 18, text: "Ist es euch zu wenig: die gute Weide weidet ihr ab, und den Rest eurer Weide zerstampft ihr mit euren Füßen, das klare Wasser trinkt ihr, und das restliche trübt ihr mit euren Füßen*?", footnotes: ["℘ Jes 32,6"] },
      { number: 19, text: "Und meine Schafe sollen abweiden, was eure Füße zerstampft haben, und trinken, was eure Füße getrübt haben?" },
      { number: 20, text: "Darum, so spricht der Herr, HERR, zu ihnen: Siehe, ich bin es, und ich werde richten zwischen fettem Schaf und magerem Schaf*.", footnotes: ["℘ Kap. 20,38"] },
      { number: 21, text: "Weil ihr all die Schwachen mit Seite und Schulter verdrängt und mit euren Hörnern stoßt, bis ihr sie nach draußen zerstreut habt*,", footnotes: ["℘ Am 5,11; Mi 7,3"] },
      { number: 22, text: "so will ich meine Schafe retten, damit sie nicht mehr zum Raub werden; und ich werde richten zwischen Schaf und Schaf*.", footnotes: ["℘ Kap. 20,38"] },
      { number: 23, text: "Und ich werde einen Hirten über sie einsetzen, der wird sie weiden: meinen Knecht David, der wird sie weiden, und der wird ihr Hirte sein*.", footnotes: ["w. ihnen zum Hirten werden\n℘ Ps 78,71; Jer 3,15; 1Petr 2,25; Offb 7,17"] },
      { number: 24, text: "Und ich, der HERR, werde ihnen Gott sein*, und mein Knecht David wird Fürst in ihrer Mitte sein*. Ich, der HERR, habe geredet.", footnotes: ["℘ Kap. 20,5.7; 2Mo 29,45; Jer 31,1.33", "℘ Kap. 37,24; Jer 30,9"] },
      { number: 25, text: "Und ich werde einen Bund des Friedens mit ihnen* schließen* und werde die bösen Tiere aus dem Land austilgen*; und in der Wüste werden sie sicher wohnen und in den Wäldern schlafen <können>*.", footnotes: ["o. für sie", "℘ Kap. 37,26; Jes 54,10; 55,3; 61,8", "℘ Kap. 38,8; 39,26; 3Mo 26,6; Hi 5,23; Spr 3,24; Jes 35,9; Jer 23,4; Hos 2,20", "℘ Ps 78,71; Jer 3,15; 1Petr 2,25; Offb 7,17"] },
      { number: 26, text: "Und ich werde sie und die Umgebungen meines Hügels zum Segen machen*; und ich werde den Regen fallen lassen zu seiner Zeit, Regengüsse des Segens werden es sein*.", footnotes: ["℘ Sach 8,13", "℘ 1Mo 9,16; Ps 84,7; Joe 2,23; Sach 10,1"] },
      { number: 27, text: "Und der Baum des Feldes wird seine Frucht geben, und das Land wird seinen Ertrag geben*; und sie werden in ihrem Land sicher sein*. Und sie werden erkennen, dass ich der HERR bin, wenn ich die Stangen ihres Joches zerbreche und sie aus der Hand derer rette, die sie knechteten*.", footnotes: ["℘ Kap. 36,8.30; 3Mo 26,4; Sach 8,12", "℘ Kap. 38,8; 39,26; 3Mo 26,6; Hi 5,23; Spr 3,24; Jes 35,9; Jer 23,4; Hos 2,20", "℘ Kap. 28,25.26; 3Mo 26,13; Jer 30,8; Lk 1,71"] },
      { number: 28, text: "Und sie werden den Nationen nicht mehr zum Raub werden, und die wilden Tiere der Erde werden sie nicht mehr fressen; sondern sie werden in Sicherheit wohnen, und niemand wird sie aufschrecken*.", footnotes: ["℘ Hi 11,19; Ps 4,9; Jes 32,18; Jer 30,10; Zef 3,13; Sach 8,12"] },
      { number: 29, text: "Und ich werde ihnen eine Pflanzung zum Ruhm* erstehen lassen, und sie werden nicht mehr durch Hunger im Land weggerafft werden und die Schmähung der Nationen nicht mehr ertragen <müssen>*.", footnotes: ["w. zum Namen. — LXX, die alte lat. und die syr. Üs. lesen: eine Pflanzung des Friedens", "℘ Kap. 36,6.15.30"] },
      { number: 30, text: "Und sie werden erkennen, dass ich, der HERR, ihr Gott, mit ihnen bin und dass sie, das Haus Israel, mein Volk sind, spricht der Herr, HERR*.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 31, text: "Und ihr, meine Herde, ihr Menschen seid die Herde meiner Weide*; ich <aber> bin euer Gott, spricht der Herr, HERR*.", footnotes: ["℘ Ps 100,3", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 35, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Unheil für das Gebirge Edom, Heil für die Berge Israels", footnotes: ["℘ Kap. 25,12-14; (Jes 21,11.12); Jes 34,5-17; Jer 49,7-22; Am 1,11.12; Ob"] },
      { number: 2, text: "Menschensohn, richte dein Gesicht gegen das Gebirge Seïr*, und weissage über es", footnotes: ["℘ 5Mo 2,5"] },
      { number: 3, text: "und sage zu ihm: So spricht der Herr, HERR: Siehe, ich will an dich, Gebirge Seïr; und ich strecke meine Hand gegen dich aus und mache dich zum Entsetzen* und Grausen*;", footnotes: ["o. zum Ödland", "℘ Joe 4,19"] },
      { number: 4, text: "deine Städte mache ich zur Trümmerstätte, und du selbst wirst Ödland sein*. Und du wirst erkennen, dass ich der HERR bin.", footnotes: ["℘ Joe 4,19"] },
      { number: 5, text: "Weil du eine beständige Feindschaft hegtest und die Söhne Israel der Gewalt des Schwertes preisgabst zur Zeit ihres Unglücks, zur Zeit der endgültigen Strafe*;", footnotes: ["w. der Strafe des Endes, o. der Schuld des Endes; d. hieße: der Schuld, die das Ende herbeiführt"] },
      { number: 6, text: "darum, so wahr ich lebe, spricht der Herr, HERR*, ja, ich mache dich zu Blut, und Blut wird dich verfolgen*; weil du Blut nicht gehasst hast*, soll Blut dich verfolgen.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "℘ Ps 109,17; Offb 16,6", "LXX: Wahrlich, du hast dich mit Blut schuldig gemacht"] },
      { number: 7, text: "Und ich mache das Gebirge Seïr zum Entsetzen* und Grausen* und rotte den, der hinzieht und zurückkehrt aus ihm, aus.", footnotes: ["o. zum Ödland", "℘ Mal 1,3"] },
      { number: 8, text: "Und seine Berge fülle ich mit seinen Erschlagenen an. Auf deinen Hügeln und in deinen Tälern und in allen deinen Bachrinnen sollen vom Schwert Erschlagene fallen*.", footnotes: ["℘ Kap. 32,5.6"] },
      { number: 9, text: "Zu ewigen Einöden mache ich dich, und deine Städte sollen nicht mehr bewohnt werden*. Und ihr werdet erkennen, dass ich der HERR bin.", footnotes: ["℘ Kap. 6,14"] },
      { number: 10, text: "Weil du sagst: Die beiden Nationen und die beiden Länder gehören mir, und ich nehme sie in Besitz*, wo doch der HERR dort war*;", footnotes: ["so mit den alten Üs.; Mas. T.: wir nehmen es in Besitz\n℘ Kap. 36,2.5", "℘ Kap. 48,35; 4Mo 35,34; Ps 83,13"] },
      { number: 11, text: "darum, so wahr ich lebe, spricht der Herr, HERR*, werde ich <an dir> handeln nach deinem Zorn und nach deiner Eifersucht, mit denen du aus Hass* gegen sie gehandelt hast*; und ich werde mich ihnen* zu erkennen geben, wenn ich dich gerichtet habe.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "w. aus deinem Hass", "℘ Jak 2,13", "LXX: dir"] },
      { number: 12, text: "Und du wirst erkennen, dass ich, der HERR, alle deine Lästerungen gehört habe, die du gegen die Berge Israels ausgesprochen hast*, indem du sagtest: Sie liegen verwüstet da, uns sind sie zum Fraß gegeben.", footnotes: ["℘ Ps 79,12; Zef 2,8"] },
      { number: 13, text: "Und ihr habt mit eurem Mund gegen mich großgetan und eure Worte gegen mich überreichlich gemacht*; ich habe es gehört*.", footnotes: ["℘ Ps 74,18", "℘ 4Mo 12,2; Ps 94,9; Jes 37,29"] },
      { number: 14, text: "So spricht der Herr, HERR: Wie du dich gefreut hast*, <dass> das ganze Land eine Einöde war, <so> will ich dir tun.", footnotes: ["w. Wie die Freude\n℘ Jes 14,7.8"] },
      { number: 15, text: "Wie du deine Freude hattest an dem Erbteil des Hauses Israel, weil es verwüstet war*, ebenso werde ich dir tun: eine Einöde sollst du werden, Gebirge Seïr und ganz Edom insgesamt!* Und sie werden erkennen, dass ich der HERR bin.", footnotes: ["℘ Kap. 25,6", "℘ Kap. 36,5; Kla 4,21"] },
    ]},
    { number: 36, verses: [
      { number: 1, text: "Und du, Menschensohn, weissage über die Berge Israels und sprich: Berge Israels, hört das Wort des HERRN!*", footnotes: ["℘ Kap. 6,2.3"] },
      { number: 2, text: "So spricht der Herr, HERR: Weil der Feind über euch sagt: »Haha!« und: »Die ewigen Höhen, sie sind uns zum Besitz geworden*!«;", footnotes: ["℘ Kap. 35,10; Ps 83,13"] },
      { number: 3, text: "darum weissage und sprich: So spricht der Herr, HERR: Deshalb, ja, deshalb, weil man euch verwüstet und euch nachstellt* von allen Seiten her, so dass ihr dem Rest der Nationen zum Besitz geworden und ins Gerede der Zunge und ins Geschwätz der Leute gekommen seid*,", footnotes: ["w. nach euch schnappt", "℘ Ps 79,4"] },
      { number: 4, text: "darum, ihr Berge Israels, hört das Wort des Herrn, HERRN! So spricht der Herr, HERR, zu den Bergen und zu den Hügeln, zu den Bachrinnen und zu den Tälern, zu den wüst daliegenden Trümmerstätten und zu den verlassenen Städten, die für den Rest der Nationen ringsum zur Plünderung und zum Spott geworden sind;" },
      { number: 5, text: "darum, so spricht der Herr, HERR: Wahrlich, im Feuer meines Eifers habe ich gegen den Rest der Nationen geredet* und gegen Edom insgesamt*, die sich mein Land zum Besitz gemacht haben mit der ganzen <Schaden>freude des Herzens, mit Verachtung der Seele, um sein Weideland zur Plünderung <zu haben>*!", footnotes: ["℘ Kap. 38,19; Sach 1,14", "℘ Kap. 25,12-14; Jes 34,2.5", "℘ Kap. 35,10-12.15; Jer 12,14"] },
      { number: 6, text: "Darum weissage über das Land Israel, und sage zu den Bergen und zu den Hügeln, zu den Bachrinnen und zu den Tälern: So spricht der Herr, HERR: Siehe, in meinem Eifer und in meinem Grimm habe ich geredet, weil ihr die Schmach der Nationen getragen habt*.", footnotes: ["℘ Kap. 34,29; 38,18; Ps 123,3.4"] },
      { number: 7, text: "Darum, so spricht der Herr, HERR: Ich, ich habe meine Hand <zum Schwur> erhoben: Wenn die Nationen, die rings um euch her sind, ihre Schmach nicht selbst tragen*!", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.\n℘ Ps 79,12"] },
      { number: 8, text: "Ihr aber, Berge Israels, ihr werdet für mein Volk Israel eure Zweige treiben und eure Frucht tragen*, denn sie sind nahe daran zu kommen.", footnotes: ["℘ Kap. 34,26.27; Joe 2,22-25"] },
      { number: 9, text: "Denn siehe, ich werde zu euch <kommen,> und ich will mich zu euch wenden, und ihr werdet bebaut und besät werden*.", footnotes: ["℘ V. 34; Sach 8,12"] },
      { number: 10, text: "Und ich werde die Menschen auf euch vermehren, das ganze Haus Israel insgesamt; und die Städte werden <wieder> bewohnt sein und die Trümmerstätten aufgebaut werden*.", footnotes: ["℘ V. 33.38; Kap. 37,26; Neh 3,34"] },
      { number: 11, text: "Und ich werde Menschen und Vieh auf euch vermehren, und sie werden sich vermehren und fruchtbar sein*; und ich werde euch bewohnt sein lassen wie in euren früheren Zeiten und werde euch Gutes tun mehr als in euren Anfängen*. Und ihr werdet erkennen, dass ich der HERR bin.", footnotes: ["℘ Jer 23,4; 31,27; Hos 2,1.25; Sach 2,8", "℘ 5Mo 30,5; Jer 30,18-20; Am 9,11"] },
      { number: 12, text: "Und ich werde Menschen, mein Volk Israel, auf euch gehen lassen, und sie werden dich in Besitz nehmen, und du wirst ihnen zum Erbe sein*; und du wirst sie nicht mehr länger kinderlos machen*. —", footnotes: ["℘ Jes 65,9; Ob 17-20", "℘ 4Mo 13,32"] },
      { number: 13, text: "So spricht der Herr, HERR: Weil sie zu euch sagen: Eine Menschenfresserin* bist du und hast deine Nation kinderlos gemacht*,", footnotes: ["Die Anrede bezieht sich auf das Land Israel.", "℘ 4Mo 13,32"] },
      { number: 14, text: "darum wirst du nicht mehr Menschen fressen und wirst deine Nation nicht mehr kinderlos machen*, spricht der Herr, HERR*.", footnotes: ["Der Text, den die Masoreten vorfanden: und wirst deine Nation nicht mehr zum Stürzen bringen", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 15, text: "Und ich will dich nicht mehr die Schmähung der Nationen hören lassen, und das Höhnen der Völker sollst du nicht mehr ertragen <müssen>*; und du sollst deine Nation nicht mehr kinderlos machen*, spricht der Herr, HERR*.", footnotes: ["℘ Kap. 34,29; 38,18; Ps 123,3.4", "Der Text, den die Masoreten vorfanden: und wirst deine Nation nicht mehr zum Stürzen bringen\n℘ Jes 65,19; Zef 3,15", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 16, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Gottes Treue schenkt Israel neues Leben" },
      { number: 17, text: "Menschensohn, als das Haus Israel <noch> in seinem Land wohnte, da machten sie es unrein durch ihren Weg und durch ihre Taten*, wie die Unreinheit der Absonderung* war ihr Weg vor mir*.", footnotes: ["℘ 3Mo 18,24-28; Ps 106,39", "o. Ausscheidung; d. i. die Monatsregel; vgl. 3Mo 12,2; 15,19ff", "℘ 3Mo 15,19"] },
      { number: 18, text: "Da goss ich meinen Grimm über sie aus wegen des Blutes, das sie im Lande vergossen*, und weil sie es mit ihren Götzen unrein gemacht hatten*.", footnotes: ["℘ Kap. 33,25", "℘ Kap. 16,36.38; 39,23; Jer 16,18"] },
      { number: 19, text: "Und ich versprengte sie unter die Nationen, und sie wurden in die Länder zerstreut*; nach ihrem Weg und nach ihren Taten richtete ich sie*.", footnotes: ["℘ Kap. 22,15; Am 9,9; Mi 2,10", "℘ Kap. 18,30; Röm 2,6"] },
      { number: 20, text: "So kamen sie zu den Nationen, <aber> wohin sie <auch> kamen, da entweihten sie meinen heiligen Namen*, indem man von ihnen sagte: »Das Volk des HERRN sind diese, und aus seinem Land haben sie hinausziehen <müssen>.*«", footnotes: ["℘ 2Sam 12,14; Jes 52,5", "℘ Jer 33,24"] },
      { number: 21, text: "Da tat es mir leid um meinen heiligen Namen*, den das Haus Israel unter den Nationen entweiht hatte, wohin sie <auch> kamen.", footnotes: ["℘ Kap. 20,9.14.22; Jes 48,9"] },
      { number: 22, text: "Darum sage zum Haus Israel: So spricht der Herr, HERR: Nicht um euretwillen handle ich, Haus Israel*, sondern um meines heiligen Namens willen*, den ihr entweiht habt unter den Nationen, zu denen ihr gekommen seid*.", footnotes: ["℘ V. 32; 5Mo 9,5.6", "℘ Kap. 20,9.44; 2Kö 19,34; Ps 115,1; Jes 43,25; Dan 9,18", "℘ Kap. 16,61; 39,25; Röm 2,24"] },
      { number: 23, text: "Und ich werde meinen großen, unter den Nationen entweihten Namen heiligen*, den ihr mitten unter ihnen entweiht habt. Und die Nationen werden erkennen, dass ich der HERR bin, spricht der Herr, HERR*, wenn ich mich vor ihren Augen an euch als heilig erweise*.", footnotes: ["℘ Kap. 28,22.25; 38,23; Lk 11,2", "w. ist der Ausspruch des Herrn, HERRN", "℘ Kap. 20,41"] },
      { number: 24, text: "Und ich werde euch aus den Nationen holen und euch aus allen Ländern sammeln und euch in euer Land bringen*.", footnotes: ["℘ Kap. 34,13; 37,12; 38,8; 5Mo 30,3.4; Ps 107,3; Jes 43,6; Jer 32,37"] },
      { number: 25, text: "Und ich werde reines Wasser auf euch sprengen*, und ihr werdet rein sein*; von all euren Unreinheiten und von all euren Götzen werde ich euch reinigen*.", footnotes: ["℘ Hebr 10,22", "℘ Ps 51,9", "℘ Kap. 16,9; 3Mo 16,30; Mi 5,12; Sach 13,1"] },
      { number: 26, text: "Und ich werde euch ein neues Herz geben* und einen neuen Geist in euer Inneres geben; und ich werde das steinerne Herz aus eurem Fleisch wegnehmen und euch ein fleischernes Herz geben*.", footnotes: ["℘ Kap. 11,19.20; 1Sam 10,9; Joh 3,5", "℘ V. 32; 5Mo 9,5.6"] },
      { number: 27, text: "Und ich werde meinen Geist in euer Inneres geben*; und ich werde machen, dass ihr in meinen Ordnungen lebt und meine Rechtsbestimmungen bewahrt und tut*.", footnotes: ["℘ Kap. 37,14; 39,29; Jes 44,3; 1Kor 3,16", "℘ Kap. 37,24; 5Mo 30,8; Jer 32,40; Eph 2,10"] },
      { number: 28, text: "Und ihr werdet in dem Land wohnen, das ich euren Vätern gegeben habe*, und ihr werdet mir zum Volk, und ich, ich werde euch zum Gott sein*.", footnotes: ["℘ Kap. 28,25", "℘ Kap. 37,23.27; Jer 24,7; 30,22; 31,1; Hebr 8,10"] },
      { number: 29, text: "Und ich werde euch befreien von all euren Unreinheiten*. Und ich werde das Getreide herbeirufen und es vermehren und keine Hungersnot <mehr> auf euch bringen*;", footnotes: ["℘ Kap. 37,23; Röm 11,26", "℘ Jes 65,23; Hos 2,23.24; Joe 2,19"] },
      { number: 30, text: "und ich werde die Frucht des Baumes und den Ertrag des Feldes vermehren*, damit ihr nicht mehr das Höhnen <wegen> einer Hungersnot hinnehmen <müsst> unter den Nationen*.", footnotes: ["℘ Kap. 34,27; Ps 85,13", "℘ Jer 31,12; Joe 2,19"] },
      { number: 31, text: "Und ihr werdet an eure bösen Wege denken und an eure Taten, die nicht gut waren, und werdet an euch selbst Ekel empfinden wegen eurer Sünden und wegen eurer Gräuel*.", footnotes: ["℘ Kap. 6,9; 20,43"] },
      { number: 32, text: "Nicht um euretwillen tue ich es, spricht der Herr, HERR*, das sollt ihr wissen*. Schämt euch und werdet beschämt vor euren Wegen, Haus Israel!", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "℘ V. 22; Kap. 16,61"] },
      { number: 33, text: "So spricht der Herr, HERR: An dem Tag, da ich euch von all euren Sünden reinige, da werde ich die Städte bewohnt sein lassen, und die Trümmerstätten sollen aufgebaut werden*.", footnotes: ["℘ V. 10; Neh 3,34; Sach 8,8"] },
      { number: 34, text: "Und das verwüstete Land soll bebaut werden*, statt dass es als Einöde daliegt vor den Augen jedes Vorüberziehenden*.", footnotes: ["℘ V. 9", "℘ Kap. 5,14"] },
      { number: 35, text: "Und man wird sagen: Dieses Land da, das verwüstete, ist wie der Garten Eden geworden*, und die verödeten und verwüsteten und niedergerissenen Städte sind befestigt und bewohnt*.", footnotes: ["℘ Jes 51,3", "℘ Jes 62,4; Jer 23,8; 33,9-13"] },
      { number: 36, text: "Und die Nationen, die rings um euch her übrig bleiben, werden erkennen, dass ich, der HERR, das Niedergerissene aufbaue, das Verwüstete bepflanze*. Ich, der HERR, habe geredet, ich werde es auch tun*.", footnotes: ["℘ Jer 32,41", "℘ Kap. 17,24; Ps 126,2"] },
      { number: 37, text: "So spricht der Herr, HERR: Auch noch darin werde ich mich vom Haus Israel bitten* lassen, es für sie zu tun: Ich werde sie zahlreich werden lassen an Menschen wie eine Herde*.", footnotes: ["w. suchen", "℘ 5Mo 30,5; Jer 30,19; Mi 2,12"] },
      { number: 38, text: "Wie Opferschafe*, wie die Schafe von Jerusalem zu seinen Festzeiten*, so werden die verödeten Städte voller Menschenherden sein. Und sie werden erkennen, dass ich der HERR bin.", footnotes: ["w. Wie Schafe der Weihegabe", "℘ Kap. 46,9; 5Mo 16,16"] },
    ]},
    { number: 37, verses: [
      { number: 1, text: "Die Hand des HERRN kam über mich*, und er führte mich im Geist* des HERRN hinaus* und ließ mich nieder mitten im Tal*; und dieses war voller Gebeine.", heading: "Die Vision von den Totengebeinen", footnotes: ["℘ Kap. 8,1", "hebr. ruach; das Wort hat in diesem Kapitel die Bedeutungen »Geist«, »Lebensodem« und »Wind«", "℘ Kap. 11,24; Offb 1,10", "w. mitten in der Talebene"] },
      { number: 2, text: "Und er führte mich ringsherum an ihnen vorüber; und siehe, es waren sehr viele auf der Fläche des Tales, und siehe, sie waren sehr vertrocknet." },
      { number: 3, text: "Und er sprach zu mir: Menschensohn, werden diese Gebeine <wieder> lebendig*? Und ich sagte: Herr, HERR, du weißt es*.", footnotes: ["℘ Ps 88,11", "℘ Apg 26,8"] },
      { number: 4, text: "Da sprach er zu mir: Weissage über diese Gebeine und sage zu ihnen: Ihr vertrockneten Gebeine, hört das Wort des HERRN!" },
      { number: 5, text: "So spricht der Herr, HERR, zu diesen Gebeinen: Siehe, ich bringe Odem* in euch, dass ihr <wieder> lebendig werdet*.", footnotes: ["hebr. ruach; das Wort hat in diesem Kapitel die Bedeutungen »Geist«, »Lebensodem« und »Wind«", "℘ 1Mo 2,7; Ps 104,30; Jes 26,19"] },
      { number: 6, text: "Und ich lege Sehnen an euch und lasse Fleisch über euch wachsen und überziehe euch mit Haut, und ich gebe Odem* in euch, dass ihr <wieder> lebendig werdet*. Und ihr werdet erkennen, dass ich der HERR bin.", footnotes: ["hebr. ruach; das Wort hat in diesem Kapitel die Bedeutungen »Geist«, »Lebensodem« und »Wind«", "℘ 1Mo 2,7; Ps 104,30; Jes 26,19"] },
      { number: 7, text: "Und ich weissagte, wie mir befohlen war. Da entstand ein Geräusch, als ich weissagte, und siehe, ein Getöse; und die Gebeine rückten zusammen, Gebein an Gebein*.", footnotes: ["w. ein Gebein an sein <anderes> Gebein"] },
      { number: 8, text: "Und ich sah, und siehe, <es entstanden> Sehnen an ihnen, und Fleisch wuchs, und Haut zog sich über sie* oben darüber; aber es war <noch> kein Odem* in ihnen.", footnotes: ["so mit LXX, der syr. Üs. und Vulg.; Mas. T.: und er zog Haut über sie", "hebr. ruach; das Wort hat in diesem Kapitel die Bedeutungen »Geist«, »Lebensodem« und »Wind«"] },
      { number: 9, text: "Und er sprach zu mir: Weissage dem Odem*, weissage, Menschensohn, und sprich zu dem Odem: So spricht der Herr, HERR: Komm von den vier Winden* her*, du Odem*, und hauche diese Erschlagenen an, dass sie <wieder> lebendig werden!", footnotes: ["hebr. ruach; das Wort hat in diesem Kapitel die Bedeutungen »Geist«, »Lebensodem« und »Wind«", "hebr. ruach; das Wort hat in diesem Kapitel die Bedeutungen »Geist«, »Lebensodem« und »Wind«", "℘ Offb 7,1", "hebr. ruach; das Wort hat in diesem Kapitel die Bedeutungen »Geist«, »Lebensodem« und »Wind«"] },
      { number: 10, text: "Da weissagte ich, wie er mir befohlen hatte; und der Odem* kam in sie, und sie wurden <wieder> lebendig und standen auf ihren Füßen*, ein sehr, sehr großes Heer.", footnotes: ["hebr. ruach; das Wort hat in diesem Kapitel die Bedeutungen »Geist«, »Lebensodem« und »Wind«", "℘ Offb 11,11"] },
      { number: 11, text: "Und er sprach zu mir: Menschensohn, diese Gebeine, sie sind das ganze Haus Israel. Siehe, sie sagen: Unsere Gebeine sind vertrocknet, und unsere Hoffnung ist verloren; es ist aus mit uns*.", footnotes: ["w. wir sind abgeschnitten <vom Leben>\n℘ Hi 17,15; Ps 31,23; 88,5.6; Kla 3,18"] },
      { number: 12, text: "Darum weissage und sprich zu ihnen: So spricht der Herr, HERR: Siehe, ich öffne eure Gräber* und lasse euch aus euren Gräbern heraufkommen als mein Volk und bringe euch ins Land Israel*.", footnotes: ["℘ Hos 13,14; Mt 27,52.53", "℘ Kap. 36,24; Jes 11,11"] },
      { number: 13, text: "Und ihr werdet erkennen, dass ich der HERR bin, wenn ich eure Gräber öffne und euch aus euren Gräbern heraufkommen lasse als mein Volk." },
      { number: 14, text: "Und ich gebe meinen Geist in euch*, dass ihr lebt, und werde euch in euer Land setzen. Und ihr werdet erkennen, dass ich, der HERR, geredet und es getan habe*, spricht der HERR*.", footnotes: ["℘ Kap. 36,27; Jes 32,15", "℘ Kap. 17,24", "w. ist der Ausspruch des HERRN"] },
      { number: 15, text: "Und das Wort des HERRN geschah zu mir so:", heading: "Gottes neuer Bund mit Israel: ein Reich, ein König, ein Gott" },
      { number: 16, text: "Und du, Menschensohn, nimm dir ein <Stück> Holz und schreibe darauf*: *»Für Juda und für die Söhne Israel, seine Gefährten.*«* Und nimm <noch> ein anderes <Stück> Holz und schreibe darauf: *»Für Josef, das Holz Ephraims und das ganze Haus Israel, seine Gefährten.*«*", footnotes: ["℘ 4Mo 17,17", "o. »Juda« und »die Söhne Israel, seine Gefährten«; als Inschrift gedacht wie Jes 8,1", "℘ 2Chr 11,12", "o. »Juda« und »die Söhne Israel, seine Gefährten«; als Inschrift gedacht wie Jes 8,1", "o. »Josef, Holz Ephraims« und »das ganze Haus Israel, seine Gefährten«; als Inschrift gedacht wie Jes 8,1", "℘ 1Kö 12,19", "o. »Josef, Holz Ephraims« und »das ganze Haus Israel, seine Gefährten«; als Inschrift gedacht wie Jes 8,1"] },
      { number: 17, text: "Und füge sie dir zusammen, eins zum andern, zu einem Holz, so dass sie eins werden in deiner Hand!" },
      { number: 18, text: "Und wenn die Söhne deines Volkes zu dir sagen: »Willst du uns nicht mitteilen, was dir dies bedeutet?«*,", footnotes: ["℘ Kap. 24,19"] },
      { number: 19, text: "so rede zu ihnen: So spricht der Herr, HERR: Siehe, ich nehme das Holz Josefs, das in der Hand Ephraims ist, und die Stämme Israels, seine Gefährten; und ich lege auf es das Holz Judas* und mache sie zu einem Holz, so dass sie eins werden in meiner Hand*.", footnotes: ["T.; Mas. T.: und lege sie auf es, das Holz Judas", "℘ Jer 3,18"] },
      { number: 20, text: "Und die Hölzer, auf die du geschrieben hast, sollen in deiner Hand sein vor ihren Augen." },
      { number: 21, text: "Und rede zu ihnen: So spricht der Herr, HERR: Siehe, ich nehme die Söhne Israel aus den Nationen heraus, wohin sie gezogen sind, und ich sammle sie von allen Seiten und bringe sie in ihr Land*.", footnotes: ["℘ Kap. 34,13; 39,28; Jer 16,15; 23,3; 31,16.17; Zef 3,20"] },
      { number: 22, text: "Und ich mache sie zu einer Nation* im Land, auf den Bergen Israels, und ein einziger König wird für sie alle zum König sein; und sie sollen nicht mehr zu zwei Nationen werden und sollen sich künftig nicht mehr in zwei Königreiche teilen*.", footnotes: ["℘ Jes 11,13", "℘ Mi 5,2; Sach 11,14; Apg 1,6"] },
      { number: 23, text: "Und sie werden sich nicht mehr unrein machen mit ihren Götzen und mit ihren Scheusalen und mit all ihren Vergehen*. Und ich werde sie retten aus all ihren Treulosigkeiten, mit denen* sie gesündigt haben, und werde sie reinigen; und sie werden mir zum Volk und ich werde ihnen zum Gott sein*.", footnotes: ["℘ Kap. 11,18; 36,25-29", "So liest eine griech. Üs.; Mas. T.: aus all ihren Wohnsitzen, in denen", "℘ Kap. 11,20; 36,28; 2Kor 6,16; Offb 21,3"] },
      { number: 24, text: "Und mein Knecht David wird König über sie sein, und sie werden alle einen Hirten haben*; und sie werden in meinen Rechtsbestimmungen leben und meine Ordnungen bewahren und sie tun*.", footnotes: ["℘ Kap. 34,23.24; Hos 3,5", "℘ Kap. 36,27; 5Mo 6,1; Jer 32,39"] },
      { number: 25, text: "Und sie werden in dem Land wohnen, das ich meinem Knecht Jakob gegeben habe*, in dem eure Väter gewohnt haben; und sie werden darin wohnen, sie und ihre Kinder und ihre Kindeskinder, bis in Ewigkeit; und mein Knecht David wird ihr Fürst sein für ewig*.", footnotes: ["℘ Kap. 28,25", "℘ 1Mo 48,4; 2Sam 7,13.16; Jes 60,21; Joe 4,20; Am 9,15"] },
      { number: 26, text: "Und ich schließe mit ihnen einen Bund des Friedens, ein ewiger Bund wird es mit ihnen sein*; den gebe ich ihnen und lasse sie zahlreich werden* und setze mein Heiligtum in ihre Mitte für ewig*.", footnotes: ["So lesen einige hebr. Handschr., LXX, die syr. und aram. Üs.; Mas. T.: ein Bund des Friedens werden sie sein\n℘ Kap. 16,60; 34,25; Jer 31,31", "℘ Kap. 36,10.37", "℘ Kap. 43,7; 48,35; 2Mo 15,17; 25,8; 3Mo 26,11.12; Zef 3,15"] },
      { number: 27, text: "Und meine Wohnung wird über ihnen sein; und ich werde ihnen zum Gott und sie werden mir zum Volk sein*.", footnotes: ["℘ Kap. 11,20; 36,28; 2Kor 6,16; Offb 21,3"] },
      { number: 28, text: "Und die Nationen werden erkennen, dass ich der HERR bin, der Israel heiligt*, wenn mein Heiligtum für ewig* in ihrer Mitte ist.", footnotes: ["℘ Kap. 20,12; Joh 17,17.19", "℘ Kap. 43,7; 48,35; 2Mo 15,17; 25,8; 3Mo 26,11.12; Zef 3,15"] },
    ]},
    { number: 38, verses: [
      { number: 1, text: "*Und das Wort des HERRN geschah zu mir so:", heading: "Drohrede gegen Gog aus Magog und das furchtbare Gericht über ihn", footnotes: ["℘ Kap. 39,1-24"] },
      { number: 2, text: "Menschensohn, richte dein Gesicht gegen Gog <zum> Land Magog*, <gegen> den Fürsten von Rosch, Meschech und Tubal*, und weissage über ihn", footnotes: ["℘ 1Mo 10,2; Offb 20,8", "o. Hauptfürst(en) von Meschech und Tubal\n℘ Kap. 27,13"] },
      { number: 3, text: "und sprich: So spricht der Herr, HERR: Siehe, ich will an dich, Gog, Fürst von Rosch, Meschech und Tubal*.", footnotes: ["o. Hauptfürst(en) von Meschech und Tubal"] },
      { number: 4, text: "Und ich lenke dich herum und lege Haken in deine Kinnbacken*; und ich führe dich heraus und dein ganzes Heer, Pferde und Reiter, sie alle prächtig gekleidet, ein großes Aufgebot mit Langschild und Kleinschild, schwertführend sie alle:", footnotes: ["℘ Kap. 29,4; 2Kö 19,28; Jes 37,29"] },
      { number: 5, text: "<Söldner aus> Paras, Kusch und Put* mit ihnen, sie alle <mit> Kleinschild und Helm,", footnotes: ["℘ Kap. 27,10"] },
      { number: 6, text: "Gomer* und alle seine Scharen, das Haus Togarma* im äußersten Norden und alle seine Scharen, viele Völker mit dir*.", footnotes: ["℘ 1Mo 10,2; Offb 20,8", "℘ Kap. 27,14", "℘ Kap. 32,30"] },
      { number: 7, text: "Rüste dich, und rüste dir <alles> zu, du und dein ganzes Aufgebot, das zu dir hin aufgeboten ist, und steh mir* zur Verfügung!", footnotes: ["so mit LXX; Mas. T.: ihnen"] },
      { number: 8, text: "Nach vielen Tagen sollst du aufgeboten werden*; am Ende der Jahre sollst du in ein Land kommen*, das vom Schwert wiederhergestellt, das aus vielen Völkern gesammelt ist, auf die Berge Israels, die für lange Zeit* zur Trümmerstätte geworden waren; das ist aus den Völkern herausgeführt worden, und sie wohnen in Sicherheit allesamt*.", footnotes: ["o. sollst du Befehl erhalten; o. sollst du heimgesucht werden\n℘ Jes 8,9", "℘ Kap. 36,24", "w. die beständig", "℘ Kap. 34,25.28"] },
      { number: 9, text: "Und du wirst hinaufziehen, wie ein Sturm herankommen, wirst sein wie eine Wolke, das Land zu bedecken, du und alle deine Scharen und viele Völker mit dir*.", footnotes: ["℘ Dan 11,40"] },
      { number: 10, text: "So spricht der Herr, HERR: Und es wird geschehen an jenem Tag, da werden Dinge in deinem Herzen aufsteigen, und du wirst einen bösen Plan schmieden*", footnotes: ["w. planen\n℘ Ps 83,4-6"] },
      { number: 11, text: "und sagen: Ich will hinaufziehen gegen ein offenes Land, will über die kommen, die sich ruhig verhalten, in Sicherheit wohnen* — sie alle wohnen <ja> ohne Mauern, auch Riegel und Tore haben sie nicht* —,", footnotes: ["℘ 5Mo 12,10", "℘ Jer 49,31; Sach 2,8"] },
      { number: 12, text: "um Raub zu rauben und Beute zu erbeuten, um deine Hand zu kehren gegen die <wieder> bewohnten Trümmerstätten und gegen ein Volk, das aus den Nationen gesammelt ist, das Viehbesitz und <andere> Habe erworben hat, <Leute,> die den Mittelpunkt der Erde bewohnen*.", footnotes: ["w. auf dem Nabel der Erde wohnen"] },
      { number: 13, text: "Saba und Dedan und die Aufkäufer von Tarsis* und all seine Händler* werden zu dir sagen: Kommst du, um Raub zu rauben? Hast du dein <Kriegs>aufgebot aufgeboten, um Beute zu erbeuten, um Silber und Gold davonzutragen, um Vieh und <andere> Habe wegzunehmen, um einen großen Raub zu rauben?", footnotes: ["℘ Kap. 27,12", "T.; Mas. T.: seine Junglöwen"] },
      { number: 14, text: "Darum weissage, Menschensohn, und sage zu Gog: So spricht der Herr, HERR: Wirst du dich an jenem Tag, wenn mein Volk Israel in Sicherheit wohnt, nicht aufmachen*", footnotes: ["so mit LXX; Mas. T.: Wirst du es an jenem Tag . . . nicht erkennen"] },
      { number: 15, text: "und von deinem Ort kommen, vom äußersten Norden her, du und viele Völker mit dir — die alle auf Pferden reiten, ein großes Aufgebot und ein zahlreiches Heer —," },
      { number: 16, text: "und wirst gegen mein Volk Israel heraufziehen wie eine Wolke, um das Land zu bedecken? Am Ende der Tage wird es geschehen*, dass ich dich über mein Land kommen lasse, damit die Nationen mich erkennen, wenn ich mich an dir, Gog, vor ihren Augen als heilig erweise*.", footnotes: ["℘ Dan 10,14; Mi 4,1", "℘ Kap. 20,41; 2Mo 14,4"] },
      { number: 17, text: "So spricht der Herr, HERR: Bist du <nicht> der, von dem ich in vergangenen Tagen geredet habe durch meine Knechte, die Propheten Israels, die in jenen Tagen jahre<lang> weissagten, dass ich dich über sie kommen lassen würde?*", footnotes: ["℘ Mi 4,11"] },
      { number: 18, text: "Und an jenem Tag wird es geschehen, an dem Tag, wenn Gog in das Land Israel kommt, spricht der Herr, HERR*, da wird mein Grimm in meiner Nase aufsteigen*.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "℘ Kap. 36,6"] },
      { number: 19, text: "Und in meinem Eifer, im Feuer meiner Zornglut habe ich geredet*: Wenn an jenem Tag nicht ein großes Beben im Land Israel sein wird*!", footnotes: ["℘ Kap. 36,5", "s. Anm. zu Kap. 36,7"] },
      { number: 20, text: "Und vor mir werden beben die Fische des Meeres und die Vögel des Himmels und die Tiere des Feldes und alle Kriechtiere, die auf dem Erdboden kriechen, und alle Menschen, die auf der Fläche des Erdbodens sind; und die Berge werden niedergerissen werden, und die Felsstufen* werden einstürzen, und jede Mauer wird zu Boden fallen*.", footnotes: ["Gemeint sind wohl Felsenterrassen, die durch Mauern am Hang abgestützt sind.", "℘ Jer 4,24-26; Nah 1,5; Offb 11,13"] },
      { number: 21, text: "Und ich rufe auf meinem ganzen Gebirge das Schwert über ihn herbei, spricht der Herr, HERR*; da wird das Schwert des einen gegen den anderen <gerichtet> sein*.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "℘ Hag 2,22; Sach 14,13"] },
      { number: 22, text: "Und ich werde ins Gericht mit ihm gehen* durch Pest und durch Blut*. Und einen überschwemmenden Regen und Hagelsteine, Feuer und Schwefel lasse ich auf ihn regnen und auf seine Scharen und auf die vielen Völker, die mit ihm sind*.", footnotes: ["w. vor Gericht gehen", "℘ Offb 8,7", "℘ Ps 11,6; Jes 29,6; 66,16; Sach 14,12; Offb 16,21; 20,9"] },
      { number: 23, text: "Und ich werde mich groß und heilig erweisen* und werde mich kundtun vor den Augen vieler Nationen*. Und sie werden erkennen, dass ich der HERR bin.", footnotes: ["℘ Kap. 20,41; 2Mo 14,4", "℘ Kap. 28,22.25; Jes 25,3"] },
    ]},
    { number: 39, verses: [
      { number: 1, text: "*Und du, Menschensohn, weissage über Gog und sprich: So spricht der Herr, HERR: Siehe, ich will an dich, Gog, Fürst von Rosch, Meschech und Tubal*.", heading: "Nochmalige Ankündigung des Gerichts über Gog und der Vernichtung seiner Heeresmacht", footnotes: ["℘ Kap. 38", "o. Hauptfürst von Meschech und Tubal"] },
      { number: 2, text: "Und ich werde dich herumlenken und dich gängeln und dich heraufziehen lassen vom äußersten Norden her und dich auf die Berge Israels bringen." },
      { number: 3, text: "Und ich werde dir den Bogen aus deiner linken Hand schlagen und deine Pfeile aus deiner rechten Hand fallen lassen*.", footnotes: ["℘ Ps 46,10; 76,4"] },
      { number: 4, text: "Auf den Bergen Israels wirst du fallen, du und alle deine Scharen und die Völker, die mit dir sind; den Raubvögeln aller Art* und den Tieren des Feldes habe ich dich zum Fraß gegeben*;", footnotes: ["w. den Raubvögeln jeder Schwinge", "℘ Kap. 32,4.5; Offb 19,17"] },
      { number: 5, text: "auf dem freien Feld* sollst du fallen. Denn ich habe <es> geredet*, spricht der Herr, HERR*.", footnotes: ["w. auf der Fläche des Feldes", "℘ Jes 24,21", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 6, text: "Und ich sende Feuer gegen Magog und gegen die, die auf den Inseln* sicher wohnen*. Und sie werden erkennen, dass ich der HERR bin.", footnotes: ["d. h. den Inseln und Küstenländern des Mittelmeeres", "℘ Offb 20,9"] },
      { number: 7, text: "Und ich werde meinen heiligen Namen kundtun mitten in meinem Volk Israel und werde meinen heiligen Namen nicht mehr entweihen lassen. Und die Nationen werden erkennen, dass ich der HERR bin, der heilig ist in Israel." },
      { number: 8, text: "Siehe, es kommt* und wird geschehen, spricht der Herr, HERR*. Das ist der Tag, von dem ich geredet habe*.", footnotes: ["℘ Kap. 33,33", "w. ist der Ausspruch des Herrn, HERRN", "℘ Jes 46,10"] },
      { number: 9, text: "Und die Bewohner der Städte Israels werden hinausgehen und werden Feuer machen und heizen mit Waffen, und zwar <mit> Kleinschilden und Langschilden, mit Bogen und Pfeilen, mit Handkeulen und Lanzen; und sie werden damit sieben Jahre lang Feuer machen." },
      { number: 10, text: "Und sie werden kein Holz vom Feld sammeln noch aus den Wäldern schlagen, sondern werden mit den Waffen Feuer machen. Und sie werden ihre Räuber berauben und ihre Plünderer plündern*, spricht der Herr, HERR*.", footnotes: ["℘ Sach 14,14", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 11, text: "Und an jenem Tag wird es geschehen, da werde ich dem Gog einen Ort geben, wo in Israel ein Grab <für ihn> ist: das Tal Abarim*, östlich vom Meer*; und es wird den Durchreisenden <den Weg> versperren. Und dort werden sie Gog und seinen ganzen Prunk* begraben, und sie werden es nennen: »Tal Hamon Gog*«.", footnotes: ["d. h. Tal der Durchreisenden", "d. i. das Tote Meer; der angrenzende Teil des moabitischen Hochlandes heißt »Abarim«", "o. seine ganze lärmende Menge; o. seinen ganzen Reichtum", "d. h. Tal des Prunkes Gogs"] },
      { number: 12, text: "Und das Haus Israel wird sie begraben, um das Land zu reinigen*, sieben Monate lang;", footnotes: ["℘ 4Mo 19,16"] },
      { number: 13, text: "und das ganze Volk des Landes wird <sie> begraben, und es wird ihnen zum Ruhm* sein am Tag, da ich mich verherrliche*, spricht der Herr, HERR*.", footnotes: ["w. zum Namen", "℘ Kap. 28,22", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 14, text: "Und sie werden Männer mit einem beständigen Auftrag* aussondern, *die im Land umherziehen <und> mit den Durchreisenden die auf der Fläche des Landes Übriggebliebenen begraben*, um es zu reinigen. Am Ende der sieben Monate sollen sie es durchsuchen.", footnotes: ["w. beständige Männer", "so versteht die aram. Üs. den Satz; Mas. T.: die im Land umherziehen <und> die Durchreisenden, <das sind> die auf der Fläche des Landes Übriggebliebenen, begraben; LXX überliefert nicht »die Durchreisenden«", "so versteht die aram. Üs. den Satz; Mas. T.: die im Land umherziehen <und> die Durchreisenden, <das sind> die auf der Fläche des Landes Übriggebliebenen, begraben; LXX überliefert nicht »die Durchreisenden«"] },
      { number: 15, text: "Ziehen nun die Umherziehenden im Land umher und es sieht jemand Menschengebein, dann soll er ein Mal daneben errichten, bis die Totengräber es im »Tal Hamon Gog*« begraben haben.", footnotes: ["d. h. Tal des Prunkes Gogs"] },
      { number: 16, text: "Und auch der Name einer Stadt <lautet> Hamona*. So werden sie das Land reinigen*.", footnotes: ["d. h. Prunk, o. lärmende Menge", "℘ 4Mo 19,16"] },
      { number: 17, text: "Und du, Menschensohn, so spricht der Herr, HERR: Sage zu den Vögeln aller Art* und zu allen Tieren des Feldes: Versammelt euch und kommt, sammelt euch von allen Seiten her zu meinem Schlachtopfer, das ich für euch schlachte, einem großen Schlachtopfer auf den Bergen Israels, und fresst Fleisch und trinkt Blut!*", footnotes: ["w. Vögeln jeder Schwinge", "℘ Kap. 29,5; Jer 46,10; Zef 1,7"] },
      { number: 18, text: "Fleisch von Helden sollt ihr fressen, und Blut von Fürsten der Erde sollt ihr trinken: Widder, Lämmer und Böcke, Stiere, Mastvieh aus Baschan sind sie alle*.", footnotes: ["℘ Jes 34,6.7; Offb 19,18"] },
      { number: 19, text: "Und Fett sollt ihr fressen bis zur Sättigung und Blut trinken bis zur Trunkenheit von meinem Schlachtopfer, das ich für euch geschlachtet habe." },
      { number: 20, text: "Und ihr sollt euch an meinem Tisch sättigen mit Pferden und Reittieren, mit Helden und allerlei Kriegsleuten, spricht der Herr, HERR*.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 21, text: "Und ich werde meine Herrlichkeit unter den Nationen erweisen*; und alle Nationen werden mein Gericht sehen, das ich gehalten habe, und meine Hand, die ich an sie gelegt habe*.", footnotes: ["w. unter die Nationen bringen\n℘ Mal 1,5", "℘ Ps 94,10; Jes 37,20"] },
      { number: 22, text: "Und das Haus Israel wird erkennen, dass ich der HERR, ihr Gott bin, von jenem Tag an und in alle Zukunft*.", footnotes: ["w. und fernerhin"] },
      { number: 23, text: "Und die Nationen werden erkennen, dass das Haus Israel um seiner Schuld willen gefangen weggezogen ist, weil sie treulos an mir handelten* und ich mein Angesicht vor ihnen verborgen* und sie in die Hand ihrer Bedränger gegeben habe, so dass sie allesamt durchs Schwert gefallen sind*.", heading: "Verheißung: Gott wird Israel für immer im Land wohnen lassen", footnotes: ["℘ Kap. 36,18; Kla 1,8", "℘ 5Mo 31,17.18; Jes 59,2", "℘ Esr 9,7"] },
      { number: 24, text: "Nach ihrer Unreinheit und nach ihren Verbrechen habe ich mit ihnen gehandelt und habe mein Angesicht vor ihnen verborgen*. —", footnotes: ["℘ 5Mo 31,17.18; Jes 59,2"] },
      { number: 25, text: "Darum, so spricht der Herr, HERR: Jetzt wende ich das Geschick Jakobs* und erbarme mich über das ganze Haus Israel* und eifere für meinen heiligen Namen*.", footnotes: ["℘ Jer 29,14; 32,37", "℘ Jes 14,1; Röm 11,26", "℘ Kap. 36,21-23"] },
      { number: 26, text: "Und sie werden ihre Schmach tragen und all ihre Untreue*, mit der sie treulos an mir gehandelt haben, wenn sie in ihrem Land sicher wohnen und niemand <sie> aufschreckt*,", footnotes: ["℘ Kap. 15,8; 20,27", "℘ Kap. 34,25"] },
      { number: 27, text: "wenn ich sie aus den Völkern zurückgebracht und sie aus den Ländern ihrer Feinde gesammelt habe und mich so an ihnen als heilig erweise vor den Augen der vielen Nationen*.", footnotes: ["℘ Kap. 20,41"] },
      { number: 28, text: "Und sie werden erkennen, dass ich der HERR, ihr Gott bin, da ich sie <zwar gefangen> zu den Nationen weggeführt habe, sie aber <wieder> in ihr Land sammle* und keinen mehr von ihnen dort zurücklasse*.", footnotes: ["℘ Kap. 37,21; 5Mo 30,3.4", "℘ Am 9,9"] },
      { number: 29, text: "Und ich werde mein Angesicht nicht mehr vor ihnen verbergen*, wenn* ich meinen Geist über das Haus Israel ausgegossen habe*, spricht der Herr, HERR.", footnotes: ["℘ Jes 54,8; Mi 7,19", "o. weil", "℘ Kap. 36,26.27; Jes 59,21; Joe 3,1; Sach 12,10"] },
    ]},
    { number: 40, verses: [
      { number: 1, text: "Im 25. Jahr unserer Wegführung*, im Anfang des Jahres, am Zehnten des Monats*, im 14. Jahr, nachdem die Stadt geschlagen war*, an ebendiesem Tag kam die Hand des HERRN über mich*, und er brachte mich dorthin;", heading: "Vision vom zukünftigen Tempel: Vorhöfe, Tore, Hallen", footnotes: ["℘ Kap. 1,2.3", "℘ 2Mo 12,3; 40,2", "℘ Kap. 33,21", "℘ 5Mo 31,17.18; Jes 59,2"] },
      { number: 2, text: "in Gotteserscheinungen* brachte er mich in das Land Israel, und er ließ mich nieder auf einen sehr hohen Berg*; und auf ihm, im Süden, war <etwas> wie der Bau einer Stadt*.", footnotes: ["℘ Kap. 8,3", "℘ Jes 2,2", "℘ Offb 21,10"] },
      { number: 3, text: "Und er brachte mich dorthin; und siehe, da war ein Mann, dessen Aussehen wie das Aussehen von Bronze* war; und in seiner Hand war eine leinene Schnur und eine Messrute*; und er stand im Tor.", footnotes: ["℘ Kap. 8,2", "℘ Kap. 47,3; Offb 11,1"] },
      { number: 4, text: "Und der Mann redete zu mir: Menschensohn, sieh mit deinen Augen, und höre mit deinen Ohren, und richte dein Herz auf alles, was ich dir zeigen werde*! Denn damit ich es dir zeige, bist du hierher gebracht worden. Berichte dem Haus Israel alles, was du siehst!*", footnotes: ["℘ Kap. 44,5", "℘ Kap. 43,10.11"] },
      { number: 5, text: "Und siehe, eine Mauer <umgab> von außen den Tempel<bezirk> ringsherum*; und in der Hand des Mannes war eine Messrute von sechs Ellen, <die Elle> als eine <gewöhnliche> Elle und eine Handbreit <gerechnet>*. Und er maß die Breite des Baues*: eine Rute; und die Höhe: eine Rute.", footnotes: ["℘ Kap. 42,20", "Die von Hesekiel beschriebene Großelle betrug 7 Handbreiten; das sind etwa 52,5 cm. Entsprechend war die Messrute etwa 3,15 m lang.\n℘ Kap. 43,13", "Gemeint ist die Dicke der Außenmauer."] },
      { number: 6, text: "Und er ging in das Tor hinein, dessen Vorderseite in östliche Richtung <weist>*, und stieg dessen Stufen hinauf. Und er maß die Schwelle des Tores: eine Rute tief, und zwar die erste Schwelle: eine Rute tief;", footnotes: ["℘ Kap. 11,1; 42,15; 47,1"] },
      { number: 7, text: "und das Dienstzimmer*: eine Rute lang und eine Rute tief; und <den Raum> zwischen den Dienstzimmern: fünf Ellen; und die Schwelle des Tores zur Vorhalle des Tores auf der Innenseite*: eine Rute.", footnotes: ["für die Torwache", "d. h. die zweite Schwelle am Ausgang des Torgebäudes in den äußeren Vorhof"] },
      { number: 8, text: "Und er maß die Vorhalle des Tores auf der Innenseite: eine Rute;" },
      { number: 9, text: "und er maß die Vorhalle des Tores: acht Ellen; und ihre Pfeiler: zwei Ellen <dick>. Und die Vorhalle des Tores lag auf der Innenseite." },
      { number: 10, text: "Und die Dienstzimmer des Osttores*: drei auf dieser und drei auf jener Seite; ein Maß hatten alle drei und ein Maß die Pfeiler auf dieser und auf jener Seite.", footnotes: ["d. h. des östlichen Torgebäudes (V. 6)"] },
      { number: 11, text: "Und er maß die lichte Weite der Toröffnung: zehn Ellen; <und> die <volle> Breite des Tores: dreizehn Ellen." },
      { number: 12, text: "Und eine Abgrenzung <befand sich> vor den Dienstzimmern, von einer Elle <auf dieser Seite>; und eine Elle war die Abgrenzung auf jener Seite. Und jedes Dienstzimmer <maß> sechs Ellen auf dieser und sechs Ellen auf jener Seite." },
      { number: 13, text: "Und er maß das Tor vom Dach<ansatz> eines Dienstzimmers bis zum Dach<ansatz> des anderen: 25 Ellen Breite, <wobei der eine> Eingang gegenüber dem <anderen> Eingang lag*.", footnotes: ["d. i. die Breite des ganzen Torgebäudes, die an beiden Seiten des Torweges befindlichen Wachzimmer inbegriffen"] },
      { number: 14, text: "Und er maß die Vorhalle: 20 Ellen. Die Vorhalle stieß ringsherum an das Tor des Vorhofs.*", footnotes: ["Die Üs. ist ein Versuch, in Anlehnung an LXX dem Vers einen Sinn abzugewinnen. Mas. T.: Und er machte die Pfeiler: sechzig Ellen und beim Pfeiler des Vorhofs das Tor ringsherum."] },
      { number: 15, text: "Und von der Vorderseite des Eingangstores bis zur Vorderseite der Vorhalle des Tores innen* <waren es> 50 Ellen*.", footnotes: ["w. des inneren Tores. — Gemeint ist der dem Tempelplatz zugewandte Abschluss des Torhauses.", "Das war die Länge oder Tiefe des ganzen Osttorgebäudes."] },
      { number: 16, text: "Und gerahmte* Fenster* waren an den Dienstzimmern, und <zwar> an ihren Pfeilern, inwendig im Tor<haus>, ringsherum, und ebenso waren an seiner Vorhalle inwendig Fenster ringsherum*; und an den Pfeilern waren Palmen*.", footnotes: ["o. vergitterte", "℘ Kap. 41,26; 1Kö 6,4", "So lautete der Text wohl ursprünglich. Mas. T.: und ebenso an seinen Vorhallen; so waren inwendig Fenster ringsherum", "℘ Kap. 41,18; 1Kö 6,29.32"] },
      { number: 17, text: "Und er brachte mich in den äußeren Vorhof hinein*. Und siehe, da waren Zellen* und ein Steinpflaster ringsum für den Vorhof angelegt; dreißig Zellen waren auf dem Steinpflaster.", footnotes: ["℘ Kap. 42,1; 46,21; Offb 11,2", "℘ 1Kö 6,5"] },
      { number: 18, text: "Und das Steinpflaster <schloss sich> seitlich an die Tore <an>, entsprechend der Tiefe der Tore*. <Das ist> das untere* Steinpflaster.", footnotes: ["d. h. die Breite des Pflasters innerhalb der Mauer um den Tempelbezirk entsprach der Tiefe der Torgebäude des äußeren Vorhofs", "Der äußere Vorhof lag tiefer als der innere."] },
      { number: 19, text: "Und er maß den Abstand* von der Vorderseite des unteren Tores <bis an die> Vorderseite des inneren Tores, das* nach außen <wies>: 100 Ellen. <So war es> an der Ostseite; und <nun> zur Nordseite:", footnotes: ["w. die Breite", "so mit LXX; Mas. T.: des inneren Hofes, der"] },
      { number: 20, text: "Und siehe, da war im äußeren Vorhof ein Tor, dessen Vorderseite in nördliche Richtung <wies>*. Er maß seine Länge und seine Breite.", footnotes: ["so mit LXX; im Mas. T. fehlt »Und siehe«"] },
      { number: 21, text: "Und seine Dienstzimmer — drei auf dieser und drei auf jener Seite — und seine Pfeiler und seine Vorhalle entsprachen dem Maß des ersten Tores: 50 Ellen seine Länge und 25 Ellen die Breite." },
      { number: 22, text: "Und seine Fenster und seine Vorhalle und seine Palmen waren nach dem Maß des Tores, dessen Vorderseite in östliche Richtung <wies>; und auf sieben Stufen stieg man zu ihm hinauf, und seine Vorhalle <lag> nach innen zu*.", footnotes: ["so mit LXX; Mas. T.: »vor ihnen«, das hieße: vor den Stufen"] },
      { number: 23, text: "Und ein Tor zum inneren Vorhof war dem Tor gegenüber im Norden wie im Osten; und er maß von Tor zu Tor 100 Ellen." },
      { number: 24, text: "Dann führte er mich in südliche Richtung. Und siehe, da war ein Tor in südlicher Richtung; und er maß seine Pfeiler und seine Vorhalle — <sie waren> wie die vorigen* Maße.", footnotes: ["w. wie jene"] },
      { number: 25, text: "Und Fenster hatte das Tor* und seine Vorhalle ringsherum wie die vorigen* Fenster. Die Länge <betrug> fünfzig Ellen und die Breite 25 Ellen.", footnotes: ["w. hatte es", "w. wie jene"] },
      { number: 26, text: "Und sieben Stufen <bildeten> seinen Aufgang, und seine Vorhalle <lag> nach innen zu*; und es hatte Palmen an seinen Pfeilern, eine auf dieser und eine auf jener Seite.", footnotes: ["so mit LXX; Mas. T.: »vor ihnen«, das hieße: vor den Stufen"] },
      { number: 27, text: "Und ein Tor hatte der innere Vorhof in südlicher Richtung; und er maß vom <äußeren> Tor zum <inneren> Tor in der Südrichtung: 100 Ellen." },
      { number: 28, text: "Und er brachte mich durch das Südtor in den inneren Vorhof*. Und er maß das Südtor — wie die vorigen* Maße <waren seine Maße> —", footnotes: ["℘ 2Mo 27,9; 1Kö 6,36", "w. wie jene"] },
      { number: 29, text: "und seine Dienstzimmer und seine Pfeiler und seine Vorhalle: <sie waren> wie die vorigen* Maße. Und Fenster hatte das Tor* und seine Vorhalle ringsherum. Die Länge <betrug> 50 Ellen und die Breite 25 Ellen.", footnotes: ["w. wie jene", "w. hatte es"] },
      { number: 30, text: "Und Vorhallen waren ringsherum, die Länge 25 Ellen und die Breite fünf Ellen." },
      { number: 31, text: "Und seine Vorhalle <lag> zum äußeren Vorhof hin; und Palmen waren an seinen Pfeilern; und acht Stufen <bildeten> seinen Aufgang. —" },
      { number: 32, text: "Und er brachte mich in den inneren Vorhof auf die Ostseite*. Und er maß das Tor — wie die vorigen* Maße <waren seine Maße> —", footnotes: ["w. in östliche Richtung", "w. wie jene"] },
      { number: 33, text: "und seine Dienstzimmer und seine Pfeiler und seine Vorhalle: <sie waren> wie die vorigen* Maße. Und Fenster hatte das Tor* und seine Vorhalle ringsherum. Die Länge <betrug> 50 Ellen und die Breite 25 Ellen.", footnotes: ["w. wie jene", "w. hatte es"] },
      { number: 34, text: "Und seine Vorhalle <lag> zum äußeren Vorhof hin; und Palmen waren an seinen Pfeilern auf dieser und auf jener Seite; und acht Stufen <bildeten> seinen Aufgang. —" },
      { number: 35, text: "Und er brachte mich zum Nordtor. Und er maß — wie die vorigen* Maße <waren ihre Maße> —", footnotes: ["w. wie jene"] },
      { number: 36, text: "seine Dienstzimmer, seine Pfeiler und seine Vorhalle. Und Fenster hatte es ringsherum. Die Länge <betrug> fünfzig Ellen und die Breite 25 Ellen." },
      { number: 37, text: "Und seine Vorhalle* <lag> zum äußeren Vorhof hin; und Palmen waren an seinen Pfeilern auf dieser und auf jener Seite; und acht Stufen <bildeten> seinen Aufgang.", footnotes: ["So lesen LXX und Vulg.; Mas. T.: seine Pfeiler"] },
      { number: 38, text: "Und da war eine Zelle, und ihre Türöffnung <führte> in die Vorhalle des Tores*; dort spülte man das Brandopfer ab*.", footnotes: ["so in Anlehnung an LXX; Mas. T.: ihre Türöffnung war an den Pfeilern der Tore", "℘ 3Mo 1,9.13"] },
      { number: 39, text: "Und in der Vorhalle des Tores waren zwei Tische auf dieser und zwei Tische auf jener Seite, um auf ihnen das Brandopfer* und das Sündopfer* und das Schuldopfer* zu schlachten.", footnotes: ["℘ 3Mo 1,3", "℘ 3Mo 4,3", "℘ 3Mo 5,15; 7,2"] },
      { number: 40, text: "Und an der Seitenwand, außerhalb der Vorhalle*, am Eingang des Nordtores, <standen> zwei Tische; und an der anderen Seitenwand* der Vorhalle des Tores <standen ebenfalls> zwei Tische,", footnotes: ["So lautete der Text wohl ursprünglich. Mas. T.: außen beim Aufstieg", "w. an der Schulter"] },
      { number: 41, text: "vier Tische auf dieser und vier Tische auf jener Seite an der Seitenwand* des Tores: acht Tische, auf denen man schlachtet.", footnotes: ["w. an der Schulter"] },
      { number: 42, text: "Und die vier Tische für das Brandopfer <bestanden> aus Quadersteinen, anderthalb Ellen lang und anderthalb Ellen breit und eine Elle hoch; auf sie legte man die Geräte, mit denen man das Brandopfer und das Schlachtopfer schlachtete." },
      { number: 43, text: "Und <ihre> Gabelhaken*, eine Handbreit lang, waren im <Tor>haus ringsherum befestigt; und auf die Tische <kam> das Opferfleisch.", footnotes: ["Das sind Pflöcke zum Aufhängen des Opferfleisches, andere verstehen das Wort als »Abstellplatten«."] },
      { number: 44, text: "Und außen am inneren Tor <befanden sich> zwei Zellen* im inneren Vorhof: eine an der Seitenwand* des Nordtores, dessen Vorderseite in südlicher Richtung <liegt, und> eine an der Seitenwand* des Südtores*, <dessen> Vorderseite in nördlicher Richtung <liegt>.", footnotes: ["so mit LXX; Mas. T.: waren die Zellen der Sänger", "w. an der Schulter", "w. an der Schulter", "so mit LXX; Mas. T.: des Osttores"] },
      { number: 45, text: "Und er redete zu mir: Diese Zelle, deren Vorderseite in südlicher Richtung <liegt>, ist für die Priester, die den Dienst am Tempelhaus versehen*.", footnotes: ["℘ 4Mo 3,27-32"] },
      { number: 46, text: "Und die Zelle, deren Vorderseite in nördlicher Richtung <liegt>, ist für die Priester, die den Dienst am Altar versehen*. Das sind die Söhne Zadoks, diejenigen von den Söhnen Levis, die dem HERRN nahen, um ihm zu dienen*.", footnotes: ["℘ 3Mo 6,2-6", "℘ Kap. 43,19; 44,15.16; 1Kö 2,35"] },
      { number: 47, text: "Und er maß den Vorhof: ein Viereck von 100 Ellen Länge und 100 Ellen Breite. Und der Altar <stand> vor dem Tempelhaus*.", footnotes: ["℘ 2Mo 40,29"] },
      { number: 48, text: "Und er brachte mich in die Vorhalle* des Tempelhauses hinein. Und er maß den Pfeiler* der Vorhalle: fünf Ellen auf dieser und fünf Ellen auf jener Seite; und die Breite des Toreingangs: *vierzehn Ellen; und die Seitenwände des Tores <maßen>* drei Ellen auf dieser und drei Ellen auf jener Seite.", footnotes: ["℘ 1Kö 6,3", "d. h. das Pfeilerwerk: zwei Pfeiler von je fünf Ellen Breite", "so mit LXX; im Mas. T. fehlt diese Angabe", "so mit LXX; im Mas. T. fehlt diese Angabe"] },
      { number: 49, text: "Die Breite der Vorhalle <betrug> 20 Ellen und die Tiefe zwölf* Ellen, und auf zehn Stufen stieg man zu ihr hinauf*. Und Säulen* waren an den Pfeilern, eine auf dieser und eine auf jener Seite.", footnotes: ["so mit LXX; Mas. T.: elf", "so mit LXX; Mas. T.: und <war> an den Stufen, auf denen man zu ihr hinaufstieg", "℘ 1Kö 7,21"] },
    ]},
    { number: 41, verses: [
      { number: 1, text: "*Und er brachte mich in den Tempelraum hinein. Und er maß die Pfeiler: sechs Ellen Tiefe auf dieser und sechs Ellen Tiefe auf jener Seite, die Tiefe der Pfeiler*.", heading: "Vision vom zukünftigen Tempel; besonders die inneren Räume", footnotes: ["℘ 1Kö 6,1-20; Sach 6,12.13", "So lautete der Text wohl ursprünglich; Mas. T.: die Tiefe des Zeltes; in einer hebr. Handschr. und in LXX fehlen diese Wörter."] },
      { number: 2, text: "Und die Breite des Eingangs <betrug> zehn Ellen, und die Seitenwände* des Eingangs <maßen> fünf Ellen auf dieser und fünf Ellen auf jener Seite. Und er maß seine* Tiefe: 40 Ellen; und die Breite: 20 Ellen.", footnotes: ["w. Schultern", "d. i. des Tempelraums"] },
      { number: 3, text: "Und er ging nach innen* hinein. Und er maß den Pfeiler des Eingangs*: zwei Ellen; und den Eingang: sechs Ellen; und die Seitenwände* des Eingangs: sieben Ellen.", footnotes: ["d. i. das Allerheiligste", "d. h. das Pfeilerwerk des Eingangs", "so in Anlehnung an LXX; Mas. T.: die Breite"] },
      { number: 4, text: "Und er maß seine* Tiefe: 20 Ellen; und die Breite: 20 Ellen gegen den Tempelraum hin*; und er sprach zu mir: Das ist das Allerheiligste.", footnotes: ["d. i. das Allerheiligste", "℘ Offb 21,16"] },
      { number: 5, text: "Und er maß die Wand des Tempelhauses: sechs Ellen; und die Breite des Anbaues*: vier Ellen, rings um das Tempelhaus herum.", footnotes: ["Das hebr. Wort, das hier mit »Anbau« üs. wird und im Folgenden mit »Seitenkammer« (vgl. die Beschreibung der Arche), bedeutet w. »Rippe« und bezeichnet einen in verschiedene Kammern unterteilten, mehrgeschossigen Anbau, der um den Tempel herumlief."] },
      { number: 6, text: "Und die Seitenkammern, Seitenkammer über Seitenkammer, dreimal, <insgesamt>* 30; und Absätze <befanden sich> an der Wand des Tempelhauses für die <Deckenbalken der> Seitenkammern ringsherum, um als Auflager zu dienen; doch waren keine Auflager in der Wand des Tempelhauses* <selber>.", footnotes: ["Andere nehmen an: <jeweils>", "Die Mauer des Hauses hatte bei jedem Stockwerk einen Absatz, um dessen Breite sie zurücktrat."] },
      { number: 7, text: "Und <es gab> eine Erweiterung durch den* Umgang<, der> an den Seitenkammern nach oben hinauf<führte>; denn das Tempelhaus war nach oben umbaut*, <ganz> bis nach oben hinauf, rings um das Tempelhaus herum, wodurch das Tempelhaus bis nach oben hin eine Verbreiterung hatte*. So stieg man vom untersten* <Stockwerk> zum obersten hinauf über das mittlere.", footnotes: ["So lautete der Text wohl ursprünglich. Mas. T.: und einen", "w. umgeben", "nämlich durch den »Umgang« (eine Rampe o. Treppe), der um die gesamten Tempelanbauten herumführte", "so mit LXX und der syr. Üs.; Mas. T.: So stieg das unterste"] },
      { number: 8, text: "Und ich sah am Haus ein Hochpflaster* ringsherum, die Unterbauten der Seitenkammern, eine volle Rute von sechs Ellen <in> Terrassenhöhe*.", footnotes: ["So konnte der Text vor der Vokalisierung durch die Masoreten gelesen werden. Mas. T.: eine Erhöhung", "w. zum Gelenk hin; o. zur Achsel hin. — Die Bedeutung des bautechnischen Begriffs ist nicht mit Sicherheit zu ermitteln."] },
      { number: 9, text: "Die Stärke der Außenwand des Anbaues <betrug> fünf Ellen; *und der Raum, der freigelassen war zwischen den Seitenkammern des Tempelhauses", footnotes: ["so mit LXX; Mas. T.: und der Raum, der freigelassen war, <bildete> das Seitenkammergebäude zum Tempelhaus hin. Und zwischen den Zellen war eine Breite von zwanzig Ellen"] },
      { number: 10, text: "und den Zellen, war zwanzig Ellen breit* rings um das Tempelhaus, ringsherum*.", footnotes: ["so mit LXX; Mas. T.: und der Raum, der freigelassen war, <bildete> das Seitenkammergebäude zum Tempelhaus hin. Und zwischen den Zellen war eine Breite von zwanzig Ellen", "℘ Kap. 42,1-9"] },
      { number: 11, text: "Und die Eingänge des Anbaues <gingen>* auf den freigelassenen Raum, ein Eingang in nördliche Richtung und ein Eingang in südliche Richtung. Und die Breite der Mauer* des freigelassenen Raumes <betrug> fünf Ellen ringsherum.", footnotes: ["so mit LXX; Mas. T.: der Eingang des Seitenbaus <ging>", "so mit Änderung eines Wortes; Mas. T.: des Ortes"] },
      { number: 12, text: "Und das Bauwerk, das an der Vorderseite des abgesonderten Platzes* auf der nach Westen gerichteten Seite* <liegt>, war 70 Ellen tief und die Mauer des Bauwerks fünf Ellen breit ringsherum, und seine Länge <betrug> 90 Ellen.", footnotes: ["hebr. gisra (das Abgeschnittene); ein vom Heiligtum abgesonderter Platz auf der hinteren oder Westseite des Tempels", "d. h. des Tempels"] },
      { number: 13, text: "Und er maß das Tempelhaus: 100 Ellen lang; und den abgesonderten Platz und das Bauwerk und seine Mauern: 100 Ellen lang;" },
      { number: 14, text: "auch die Breite der Vorderseite des Tempelhauses und des abgesonderten Platzes nach Osten: 100 Ellen." },
      { number: 15, text: "Und er maß die Breite des Bauwerks an der Vorderseite des abgesonderten Platzes, das <sich bis> auf seine Rückseite <erstreckte>; und seine Galerien* auf dieser und auf jener Seite: 100 Ellen. Und der innere Tempelraum und seine äußere Vorhalle", footnotes: ["Andere geben den bautechnischen Begriff mit »Böschungen« wieder."] },
      { number: 16, text: "waren getäfelt. Und die* gerahmten* Fenster und die Galerien* ringsum hatten in ihren drei <Teilen>, der Schwelle gegenüber, eine Holzverkleidung ringsherum, und zwar vom* Boden bis an die Fenster — die Fenster aber waren verdeckbar —", footnotes: ["so mit zwei hebr. Handschr. und LXX; Mas. T.: Und der innere Tempelraum und die Vorhallen des Vorhofs; 16 die Schwellen und die", "o. vergitterten", "o. die Absätze <der Fenster>", "w. der"] },
      { number: 17, text: "<und> bis über den Eingang*. Und im inneren Tempelhaus und draußen und an der ganzen Wand ringsherum, der inneren und äußeren, waren abgemessene Felder*,", footnotes: ["so mit einer hebr. Handschr. und der aram. Üs.; Mas. T.: oberhalb des Eingangs", "w. Abmessungen"] },
      { number: 18, text: "und <in ihnen waren> Cherubim und Palmen* gestaltet, und zwar eine Palme zwischen Cherub und Cherub. Und der Cherub hatte zwei Gesichter:", footnotes: ["℘ Kap. 40,16"] },
      { number: 19, text: "Das Gesicht eines Menschen <war> zur Palme auf der einen Seite <gewandt> und das Gesicht eines Löwen zur Palme auf der anderen Seite*. <Diese> Ausgestaltung <befand sich> im ganzen Tempelhaus ringsherum.", footnotes: ["℘ Kap. 1,10; 1Kö 7,29"] },
      { number: 20, text: "Vom Boden bis hinauf über den Eingang waren die Cherubim und die Palmen angebracht, und zwar an der Wand des Tempelraums." },
      { number: 21, text: "<In der Wand im> Tempelraum waren vierfach gestaffelte Türrahmen. An der Vorderseite des Heiligtums* aber war etwas zu sehen, das aussah wie", footnotes: ["d. i. das Allerheiligste"] },
      { number: 22, text: "ein Altar* aus Holz, drei Ellen hoch; und seine Länge <betrug> zwei Ellen *und seine Breite zwei Ellen*; und er hatte seine Ecken; und sein Fußgestell* und seine Wände waren aus Holz. Und er redete zu mir: Das ist der Tisch, der vor dem HERRN <steht>*.", footnotes: ["T.; Mas. T.: An der Vorderseite des Heiligtums: Aussehen gleich Aussehen. 22 Der Altar war\n℘ 2Mo 30,1", "Diesen Text überliefert LXX. In Mas. T. fehlt die Breitenangabe.", "Diesen Text überliefert LXX. In Mas. T. fehlt die Breitenangabe.", "so mit LXX; Mas. T.: seine Länge", "℘ Kap. 44,16; Mal 1,7.12"] },
      { number: 23, text: "Und der Tempelraum hatte zwei Türen, und das Heiligtum* hatte", footnotes: ["d. i. das Allerheiligste"] },
      { number: 24, text: "zwei Türen*. Die Türen hatten zwei <bis an die Wand> drehbare Türflügel*, zwei hatte die eine Tür, und zwei Türflügel hatte die andere.", footnotes: ["℘ 1Kö 6,23; 2Chr 4,22", "T.; Mas. T.: Und der Tempelraum hatte zwei Türen und das Heiligtum. 24 Und die Türen hatten zwei Türflügel, zwei <bis an die Wand> drehbare Türflügel"] },
      { number: 25, text: "Und an ihnen, an den Flügeltüren des Tempelraums, waren Cherubim und Palmen gestaltet, wie sie an den Wänden gestaltet waren. Und ein hölzernes Dachgesims* war an der Vorderseite der Vorhalle draußen.", footnotes: ["o. Gebälk. — Die Bedeutung des hebr. Wortes ist ungewiss."] },
      { number: 26, text: "Und gerahmte* Fenster* und Palmen waren auf dieser und auf jener Seite, an den Seitenwänden* der Vorhalle und an den Seitenkammern des Tempelhauses und den Dachgesimsen*.", footnotes: ["o. vergitterte", "℘ Kap. 40,16", "w. an den Schultern", "o. Gebälk. — Die Bedeutung des hebr. Wortes ist ungewiss."] },
    ]},
    { number: 42, verses: [
      { number: 1, text: "Und er führte mich hinaus in den äußeren Vorhof*, den Weg in nördlicher Richtung. Und er brachte mich zu dem Zellenbau*, der quer zu dem abgesonderten Platz und quer zu dem Bauwerk im Norden <liegt>*.", heading: "Vision vom zukünftigen Tempel: Nebengebäude — Vermessung des heiligen Bezirks", footnotes: ["℘ Kap. 40,17", "d. i. das nördliche Zellengebäude", "℘ Kap. 41,10"] },
      { number: 2, text: "Die Länge <betrug> 100 Ellen auf der Nordseite* und die Breite 50 Ellen.", footnotes: ["so mit LXX; Mas. T.: An der Vorderseite: eine Länge von 100 Ellen am nördlichen Eingang"] },
      { number: 3, text: "Quer zu den 20 <Ellen> des inneren Vorhofs und quer zu dem Steinpflaster des äußeren Vorhofs war Galerie vor Galerie* im dritten <Stockwerk>*.", footnotes: ["o. Absatz vor Absatz", "Die lat. und die aram. Üs. lesen: in drei Stufen"] },
      { number: 4, text: "Und vor den Zellen war ein Gang von zehn Ellen Breite, zum inneren <Vorhof> hin ein Weg von hundert Ellen*. Und ihre Eingänge waren nach Norden <gerichtet>.", footnotes: ["so mit LXX; Mas. T.: von einer Elle"] },
      { number: 5, text: "Und die oberen Zellen waren, weil die Galerien* ihnen <Raum> wegnahmen, schmaler als die unteren und die mittleren des Bauwerks.", footnotes: ["o. die Absätze"] },
      { number: 6, text: "Denn sie waren dreistöckig*, hatten aber keine Säulen wie die Säulen der Vorhöfe. So war <das Bauwerk> vom Boden her terrassenartig zurückgesetzt, von den unteren und den mittleren <Zellen>.", footnotes: ["o. dreistufig <angeordnet>"] },
      { number: 7, text: "Und eine Mauer war da, die draußen parallel zu den Zellen <verlief>, in Richtung zum äußeren Vorhof hin, an der Vorderseite der Zellen; ihre Länge <betrug> 50 Ellen." },
      { number: 8, text: "Denn die Länge der Zellen, die zum äußeren Vorhof <gehörten, betrug> 50 Ellen; *jene aber <lagen> ihnen gegenüber. Im Ganzen waren es* 100 Ellen.", footnotes: ["so mit LXX; Mas. T.: Und siehe, an der Vorderseite des Tempelraums <betrugen sie>", "so mit LXX; Mas. T.: Und siehe, an der Vorderseite des Tempelraums <betrugen sie>"] },
      { number: 9, text: "Und <für> die Türen dieser Zellen <gab es> einen Zugang* von Osten her, wenn man vom äußeren Vorhof her zu ihnen hineinging*,", footnotes: ["LXX entsprechend V. 12; Mas. T.: Und unterhalb der Zellen war ein Zugang", "℘ Kap. 46,19"] },
      { number: 10, text: "am Anfang*. In südlicher Richtung der Mauer des Vorhofs, vor dem abgesonderten Platz und vor dem Bauwerk* waren Zellen", footnotes: ["so mit LXX; Mas. T.: An der Breite", "d. i. das nördliche Zellengebäude"] },
      { number: 11, text: "und ein Weg vor ihnen; wie die Gestalt der Zellen, die in nördlicher Richtung <lagen, war ihre Gestalt>, ihrer Länge und ihrer Breite entsprechend*, allen ihren Ausgängen und ihren Einrichtungen entsprechend und entsprechend ihren Eingängen.", footnotes: ["T.; Mas. T.: wie ihre Länge, so ihre Breite"] },
      { number: 12, text: "Und zu den Eingängen* der Zellen, die in südlicher Richtung <lagen>, <führte> ein Eingang am Anfang des Weges, <nämlich> des Weges, <der an> der Schutzmauer entlang<lief>, nach Osten hin <offen>, wenn man hineinkam*.", footnotes: ["T.; Mas. T.: Und wie die Eingänge", "Diese Üs. ergibt sich mit geringfügiger Korrektur eines Buchstabens in Anlehnung an V. 9; Mas. T.: wenn sie hineinkamen"] },
      { number: 13, text: "Und er sprach zu mir: Die Zellen im Norden <und> die Zellen im Süden, die entlang dem abgesonderten Platz <liegen>, das sind die heiligen Zellen, wo die Priester, die dem HERRN nahen*, die hochheiligen Gaben essen sollen. Dort sollen sie die hochheiligen Gaben niederlegen, sowohl das Speisopfer als auch das Sündopfer und das Schuldopfer; denn der Ort ist heilig*.", footnotes: ["T. in Anlehnung an Kap. 40,46; Mas. T.: die dem HERRN nahe sind", "℘ 3Mo 6,19"] },
      { number: 14, text: "Wenn sie, die Priester, hineingegangen sind, dann sollen sie aus dem Heiligtum nicht <unmittelbar> in den äußeren Vorhof hinausgehen, sondern sollen dort ihre Kleider niederlegen, in denen sie den Dienst verrichten; denn sie sind heilig; sie sollen <erst> andere Kleider anziehen und sich <dann> dem <Ort> nahen, der dem Volk <zugänglich> ist*.", footnotes: ["℘ Kap. 44,19; 3Mo 16,24"] },
      { number: 15, text: "Und als er die Messung des inneren Tempelhauses vollendet hatte, führte er mich hinaus in Richtung auf das Tor, dessen Vorderseite in östliche Richtung <wies>*; und er maß ihn* ringsherum*.", footnotes: ["℘ Kap. 40,6", "d. h. den gesamten Tempelbezirk", "℘ Kap. 40,5; Offb 11,1"] },
      { number: 16, text: "Er maß die Ostseite mit der Messrute, 500 Ruten*, *mit der Messrute <gemessen>. Und er wandte sich*", footnotes: ["richtig wäre: »Ellen«; LXX gibt kein Längenmaß an", "so mit LXX; Mas. T.: mit der Messrute ringsherum", "so mit LXX; Mas. T.: mit der Messrute ringsherum"] },
      { number: 17, text: "<und> maß die Nordseite, 500 Ruten*, *mit der Messrute <gemessen>. Und er wandte sich*;", footnotes: ["richtig wäre: »Ellen«; LXX gibt kein Längenmaß an", "so mit LXX; Mas. T.: mit der Messrute ringsherum", "so mit LXX; Mas. T.: mit der Messrute ringsherum"] },
      { number: 18, text: "die Südseite maß er, 500 Ruten* mit der Messrute.", footnotes: ["richtig wäre: »Ellen«; LXX gibt kein Längenmaß an"] },
      { number: 19, text: "Er wandte sich zur Westseite <und> maß 500 Ruten* mit der Messrute.", footnotes: ["richtig wäre: »Ellen«; LXX gibt kein Längenmaß an"] },
      { number: 20, text: "Er maß ihn* nach den vier Seiten*. Er hatte eine Mauer ringsherum* — die Länge <betrug> 500 und die Breite 500* —, um zwischen dem Heiligen und dem Unheiligen zu scheiden*.", footnotes: ["d. h. den gesamten Tempelbezirk", "w. Winden", "℘ Kap. 40,5; Offb 11,1", "℘ Kap. 45,2", "℘ Kap. 43,12"] },
    ]},
    { number: 43, verses: [
      { number: 1, text: "Und er führte mich zum Tor, dem Tor, das in östliche Richtung weist*.", heading: "Vision vom zukünftigen Tempel: Einzug der Herrlichkeit des HERRN — Einweihung des Brandopferaltars", footnotes: ["℘ Kap. 10,19; 44,1"] },
      { number: 2, text: "Und siehe, die Herrlichkeit des Gottes Israels kam von Osten her*; und ihr Rauschen war wie das Rauschen großer Wasser*, und die Erde leuchtete von seiner Herrlichkeit*.", footnotes: ["℘ Kap. 11,23", "℘ Kap. 1,24", "℘ Jes 6,3; Hab 3,3.4; Offb 18,1"] },
      { number: 3, text: "Und die Erscheinung, die ich sah*, war wie die Erscheinung, die ich gesehen hatte, als er kam*, um die Stadt zu vernichten*; und <es waren> Erscheinungen wie die Erscheinung, die ich am Fluss Kebar gesehen hatte*. Und ich fiel nieder auf mein Gesicht*.", footnotes: ["Diese Üs. bietet LXX; Mas. T.: Und wie die Erscheinung (o. das Aussehen) der Erscheinung", "so mit sechs hebr. Handschr., einer griech. Üs. und Vulg.; Mas. T.: als ich kam", "℘ Kap. 8,4; 9,10", "℘ Kap. 10,22", "℘ Kap. 3,23"] },
      { number: 4, text: "Und die Herrlichkeit des HERRN ging in das Haus hinein <auf dem> Weg <vom> Tor, dessen Vorderseite in östliche Richtung <weist>*.", footnotes: ["℘ Kap. 44,2; Jes 60,1"] },
      { number: 5, text: "Und der Geist hob mich empor* und brachte mich in den inneren Vorhof; und siehe, die Herrlichkeit des HERRN erfüllte das Haus*.", footnotes: ["℘ Kap. 3,12.14", "℘ Kap. 3,5; 10,4; 2Mo 40,34; Hag 2,9"] },
      { number: 6, text: "Und ich hörte einen, der aus dem Haus zu mir redete* — der Mann aber stand neben mir —,", footnotes: ["℘ 2Mo 29,42"] },
      { number: 7, text: "und er sprach zu mir: Menschensohn, <sieh> die Stätte meines Thrones* und die Stätte meiner Fußsohlen*, wo ich mitten unter den Söhnen Israel wohnen werde für ewig*. Und das Haus Israel wird meinen heiligen Namen nicht mehr unrein machen* — weder sie noch ihre Könige — durch ihre Hurerei und durch die Leichen ihrer Könige, wenn sie sterben*,", footnotes: ["℘ Ps 99,1; Jer 3,17; 17,12", "℘ 1Chr 28,2", "℘ Kap. 37,26-28; 2Mo 29,45; 1Kö 8,13; Ps 68,17; Joe 4,17; Offb 21,3", "℘ Sach 13,2", "Diese Lesart bieten etwa 20 hebr. Handschr., eine griech. und die aram. Üs.; Mas. T.: ihre Höhen"] },
      { number: 8, text: "indem sie ihre Schwelle an meine Schwelle und ihre Türpfosten neben meine Türpfosten setzten, dass <nur> die Wand zwischen mir und ihnen war, und so meinen heiligen Namen unrein machten durch ihre Gräuel, die sie verübten*, so dass ich sie in meinem Zorn vernichtet habe*.", footnotes: ["℘ Kap. 8,6; 2Kö 16,14", "℘ Kap. 5,11.12"] },
      { number: 9, text: "Jetzt <aber> werden sie ihre Hurerei und die Leichen ihrer Könige von mir fernhalten, und ich werde in ihrer Mitte wohnen für ewig*.", footnotes: ["℘ Kap. 37,26-28; 2Mo 29,45; 1Kö 8,13; Ps 68,17; Joe 4,17; Offb 21,3"] },
      { number: 10, text: "Du, Menschensohn, berichte dem Haus Israel <über> das Tempelhaus*, damit sie sich ihrer Sünden schämen* und das Modell messen!", footnotes: ["℘ Kap. 40,4", "℘ Kap. 16,61.63"] },
      { number: 11, text: "Und wenn sie sich wegen all dessen schämen, was sie getan haben, dann lass sie die Zeichnung des Hauses wissen und seine Einrichtung und seine Ausgänge und seine Eingänge und alle Zeichnungen davon und all seine Ordnungen* und alle Weisungen dafür* und schreibe sie vor ihren Augen auf, damit sie *alle Weisungen dafür* und all seine Ordnungen bewahren und sie tun!", footnotes: ["so mit LXX; Mas. T. fügt hinter »und all seine Ordnungen« noch einmal »und alle Zeichnungen davon« ein", "℘ Kap. 44,5; Hebr 8,5", "so mit LXX; Mas. T.: die ganze Zeichnung davon", "so mit LXX; Mas. T.: die ganze Zeichnung davon"] },
      { number: 12, text: "Das ist die Weisung für das Tempelhaus: Auf der Kuppe des Berges soll sein ganzes Gebiet ringsherum hochheilig sein*; siehe, das ist die Weisung für das Tempelhaus.", footnotes: ["℘ Kap. 42,20; Ps 93,5"] },
      { number: 13, text: "Und das sind die Maße des Altars* nach Ellen, die Elle zu einer Elle und einer Handbreit*: die ihn <umgebende> Ausbuchtung: eine Elle <tief>* und eine Elle breit; und ihre* Begrenzung an ihrem Rand ringsum: eine Spanne*. Und das ist der Sockel* des Altars:", footnotes: ["d. i. des Brandopferaltars\n℘ 2Chr 4,1", "s. Anm. zu Kap. 40,5", "d. i. eine aus dem Felsboden herausgehauene Rinne; die Üs. ergibt sich aus anderer Wortabtrennung; Mas. T.: eine Ausbuchtung: die Elle <tief>", "nämlich der Ausbuchtung oder Rinne", "℘ Kap. 40,5", "Mit geringfügiger Änderung lesen andere: das ist die Höhe"] },
      { number: 14, text: "von der Ausbuchtung am Boden bis zur unteren Einfassung: zwei Ellen und eine Elle Breite; und von der kleineren Einfassung bis zur größeren Einfassung: vier Ellen und eine Elle Breite." },
      { number: 15, text: "Und der Opferherd: vier Ellen <Höhe>; und vom Opferherd* <ragen> die vier Hörner aufwärts*.", footnotes: ["hebr. Ariël", "℘ 2Mo 27,1.2"] },
      { number: 16, text: "Und der Opferherd*: zwölf <Ellen> Länge auf zwölf <Ellen> Breite, quadratisch zu seinen vier Seiten hin.", footnotes: ["hebr. Ariël\n℘ Jes 29,1"] },
      { number: 17, text: "Und die <größere> Einfassung: vierzehn <Ellen> Länge auf vierzehn <Ellen> Breite, zu ihren vier Seiten hin; und die Abgrenzung rings um sie her: eine halbe Elle*; und ihre Ausbuchtung eine Elle ringsum. Und seine Stufen wiesen nach Osten.", footnotes: ["d. i. eine Spanne; s. V. 13"] },
      { number: 18, text: "Und er sprach zu mir: Menschensohn, so spricht der Herr, HERR: Das sind die Ordnungen für den Altar an dem Tag, da er gemacht wird, um Brandopfer darauf zu opfern und Blut darauf zu sprengen*.", footnotes: ["℘ 3Mo 1,5"] },
      { number: 19, text: "Da sollst du den Priestern, den Leviten, die von der Nachkommenschaft Zadoks sind*, die mir nahen, spricht der Herr, HERR*, um mir zu dienen, einen Jungstier zum Sündopfer geben.", footnotes: ["℘ Kap. 40,46; Jer 33,18", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 20, text: "Und du sollst von seinem Blut nehmen und es an seine vier Hörner tun und an die vier Ecken der Einfassung und an die Abgrenzung ringsum; und so sollst du ihn entsündigen und Sühnung für ihn erwirken*.", footnotes: ["℘ Kap. 45,18.19; 2Mo 29,36.37; 3Mo 8,14.15"] },
      { number: 21, text: "Und du sollst den Stier des Sündopfers nehmen, und man soll ihn am Musterungsplatz des Tempelhauses, außerhalb des Heiligtums, verbrennen*.", footnotes: ["℘ Kap. 45,2; 2Mo 29,14"] },
      { number: 22, text: "Und am zweiten Tag sollst du einen Ziegenbock* ohne Fehler zum Sündopfer darbringen*; und man soll den Altar entsündigen, ebenso wie man ihn mit dem Stier entsündigt hat.", footnotes: ["w. Haarigen der Ziegen", "℘ 3Mo 4,23.26"] },
      { number: 23, text: "Wenn du das Entsündigen vollendet hast, sollst du einen Jungstier ohne Fehler und einen Widder ohne Fehler von den Schafen darbringen:" },
      { number: 24, text: "du sollst sie vor dem HERRN darbringen, und die Priester sollen Salz auf sie streuen* und sie dem HERRN als Brandopfer opfern.", footnotes: ["℘ 3Mo 2,13"] },
      { number: 25, text: "Sieben Tage lang sollst du täglich einen Ziegenbock als Sündopfer zubereiten; und einen Jungstier und einen Widder von den Schafen, <Tiere> ohne Fehler, soll man zubereiten*.", footnotes: ["℘ 2Mo 29,37"] },
      { number: 26, text: "Sieben Tage lang soll man für den Altar Sühnung erwirken und ihn reinigen und ihn einweihen*.", footnotes: ["w. seine Hand füllen; die Wendung wird sonst bei der Amtseinführung von Priestern gebraucht\n℘ 3Mo 8,33-35"] },
      { number: 27, text: "So soll man die Tage vollenden. Und es soll am achten Tag und fernerhin geschehen, dass die Priester eure Brandopfer und eure Heilsopfer* auf dem Altar zubereiten*. Und ich werde euch wohlgefällig annehmen*, spricht der Herr, HERR*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ 3Mo 9,1-4", "℘ Kap. 20,40.41; 2Kor 6,17", "w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 44, verses: [
      { number: 1, text: "Und er führte mich zurück auf dem Weg zum äußeren Tor des Heiligtums, das nach Osten weist*. Das aber war verschlossen*.", heading: "Vision vom zukünftigen Tempel: Diener des Heiligtums", footnotes: ["℘ Kap. 43,1.4", "℘ Kap. 46,1"] },
      { number: 2, text: "Und der HERR sprach zu mir: Dieses Tor soll verschlossen sein; es soll nicht geöffnet werden, und niemand soll durch es hineingehen! Denn der HERR, der Gott Israels, ist durch es hineingegangen*, so soll es verschlossen sein*.", footnotes: ["℘ Kap. 46,1", "℘ Kap. 46,1"] },
      { number: 3, text: "Was den Fürsten betrifft, er, der Fürst, soll darin sitzen, um Speise zu essen* vor dem HERRN*; auf dem Weg der Vorhalle des Tores* soll er hineingehen, und auf demselben* Weg soll er hinausgehen*.", footnotes: ["d. h. um eine Opfermahlzeit zu halten", "℘ 5Mo 12,7", "d. i. des Torhauses", "w. ihrem", "℘ Kap. 46,2; 2Kö 16,18"] },
      { number: 4, text: "Und er brachte mich auf dem Weg zum Nordtor an die Vorderseite des Tempelhauses; und ich sah: und siehe, die Herrlichkeit des HERRN erfüllte das Haus des HERRN*; und ich fiel auf mein Gesicht nieder*.", footnotes: ["℘ Kap. 10,4; Offb 15,8", "℘ Kap. 3,23"] },
      { number: 5, text: "Und der HERR sprach zu mir: Menschensohn, richte dein Herz darauf, und sieh mit deinen Augen, und höre mit deinen Ohren alles, was ich mit dir rede in Bezug auf alle Ordnungen des Hauses des HERRN und in Bezug auf alle Weisungen dafür*; und richte dein Herz *auf den Zutritt zum Tempelhaus <und> auf alle Ausgänge des Heiligtums* *!", footnotes: ["℘ Kap. 40,4; 43,11", "o. auf den, der in das Tempelhaus hineingehen darf, <und> auf alle, die aus dem Heiligtum herausgebracht werden müssen", "o. auf den, der in das Tempelhaus hineingehen darf, <und> auf alle, die aus dem Heiligtum herausgebracht werden müssen", "℘ Ps 24,3-6"] },
      { number: 6, text: "Und sage zu den Widerspenstigen, zum Haus Israel*: So spricht der Herr, HERR: Lass es genug sein mit all euren Gräueln*, Haus Israel,", footnotes: ["s. Anm. zu Kap. 2,5\n℘ Kap. 2,5", "℘ Kap. 45,9; 1Petr 4,3"] },
      { number: 7, text: "dass ihr Söhne der Fremde, unbeschnitten am Herzen und unbeschnitten am Fleisch, habt hineinkommen lassen, in meinem Heiligtum zu sein, um es, mein Haus, zu entweihen*, wenn ihr meine Speise, Fett und Blut, darbrachtet. So habt ihr* meinen Bund gebrochen* um aller eurer Gräuel willen.", footnotes: ["so mit einer hebr. Handschr.; Mas. T.: es zu entweihen, mein Haus\n℘ Jer 9,25; Apg 21,28", "so mit LXX, der syr. Üs. und Vulg.; Mas. T.: So haben sie", "℘ Mal 2,4-8"] },
      { number: 8, text: "Und ihr habt den Dienst an meinen heiligen Dingen nicht versehen, sondern habt sie* zu solchen gemacht, die für euch meinen Dienst in meinem Heiligtum versehen*.", footnotes: ["nämlich die Fremden (V. 7)", "℘ 3Mo 22,10"] },
      { number: 9, text: "<Darum>, so spricht der Herr, HERR: Kein Sohn der Fremde, unbeschnitten am Herzen und unbeschnitten am Fleisch, soll in mein Heiligtum hineinkommen*, <keiner> von allen Söhnen der Fremde, die mitten unter den Söhnen Israel <leben>*;", footnotes: ["℘ Ps 24,3-6", "℘ 2Mo 12,48; 5Mo 23,4; Sach 14,21"] },
      { number: 10, text: "sondern die Leviten, die sich von mir entfernt haben, als Israel in die Irre ging, als sie von mir abirrten, ihren Götzen nach*, sie sollen ihre Schuld* tragen*.", footnotes: ["℘ Jer 23,11", "o. Strafe", "℘ Hos 4,9"] },
      { number: 11, text: "Sie sollen in meinem Heiligtum den Dienst verrichten als Wachen an den Toren des Hauses* und den Dienst am Tempelhaus verrichten; sie sollen das Brandopfer und das Schlachtopfer für das Volk schlachten*, und sie sollen vor ihnen stehen, um ihnen zu dienen*.", footnotes: ["℘ 1Chr 26,1", "℘ 2Chr 30,17", "℘ 4Mo 16,9"] },
      { number: 12, text: "Weil sie ihnen vor ihren Götzen gedient haben* und dem Haus Israel ein Anstoß zur Schuld geworden sind*, darum habe ich meine Hand <zum Schwur> gegen sie erhoben, spricht der Herr, HERR*, dass sie ihre Schuld* tragen sollen*.", footnotes: ["so mit den alten Üs.; Mas. T.: dienen", "℘ Kap. 14,3; Mal 2,8", "w. ist der Ausspruch des Herrn, HERRN", "o. Strafe", "℘ Hos 4,9"] },
      { number: 13, text: "Sie sollen mir nicht <mehr> nahen, um mir den Priesterdienst auszuüben* und um allen meinen heiligen Dingen, den hochheiligen, zu nahen; sondern sie sollen ihre Schmach und ihre Gräuel tragen, die sie verübt haben*.", footnotes: ["℘ 4Mo 18,3", "℘ Jer 3,25"] },
      { number: 14, text: "Und ich mache sie zu solchen, die den Dienst am Tempelhaus versehen, für alle Arbeiten in ihm* und für alles, was darin getan werden muss*.", footnotes: ["w. für seine ganze Arbeit", "℘ Kap. 46,24; 4Mo 18,4; 1Chr 23,28-32"] },
      { number: 15, text: "Aber die Priester, die Leviten, die Söhne Zadoks*, die den Dienst an meinem Heiligtum versehen haben, als die Söhne Israel von mir abirrten*, sie sollen mir nahen, um mir zu dienen*, und sollen vor mir stehen, um mir das Fett und das Blut darzubringen*, spricht der Herr, HERR*!", footnotes: ["℘ 2Sam 8,17", "℘ Kap. 48,11", "℘ Kap. 40,46; Sach 3,7", "℘ 3Mo 3,3-16; 17,6", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 16, text: "Sie sollen in mein Heiligtum hineinkommen, und sie sollen meinem Tisch nahen*, um mir zu dienen, und sollen den Dienst für mich verrichten*.", footnotes: ["℘ Kap. 41,22", "℘ 4Mo 16,9; 18,5; 1Sam 2,35"] },
      { number: 17, text: "Und es soll geschehen, wenn sie durch die Tore des inneren Vorhofs hineingehen, sollen sie leinene Kleider anziehen; aber Wolle soll nicht auf sie kommen, wenn sie in den Toren des inneren Vorhofs und drinnen dienen*.", footnotes: ["℘ 3Mo 16,4"] },
      { number: 18, text: "Leinene Kopfbunde sollen auf ihrem Kopf sein und leinene Beinkleider an ihren Hüften; sie sollen sich nicht mit schweißfördernder Kleidung* gürten.", footnotes: ["w. mit Schweiß"] },
      { number: 19, text: "Und wenn sie in den äußeren Vorhof hinausgehen, in den äußeren Vorhof zum Volk, sollen sie ihre Kleider, in denen sie Dienst getan haben, ausziehen* und in die heiligen Zellen legen und sollen andere Kleider anziehen, damit sie das Volk nicht mit ihren Kleidern heilig machen*.", footnotes: ["℘ Kap. 42,14; 3Mo 6,3.4", "℘ Kap. 46,20"] },
      { number: 20, text: "Und sie sollen weder ihr Haupt <kahl>scheren noch das Haar frei wachsen lassen; sie sollen ihr Haupt<haar kurz> schneiden*.", footnotes: ["℘ 3Mo 21,5"] },
      { number: 21, text: "Und kein Priester soll Wein trinken, wenn sie in den inneren Vorhof hineingehen*.", footnotes: ["℘ 3Mo 10,9"] },
      { number: 22, text: "Und eine Witwe und eine Verstoßene sollen sie sich nicht zu Frauen nehmen, sondern Jungfrauen von den Nachkommen des Hauses Israel. Und die Witwe, die eine Priesterwitwe ist, dürfen sie nehmen*.", footnotes: ["℘ 3Mo 21,13.14"] },
      { number: 23, text: "Und sie sollen mein Volk unterweisen, zwischen heilig und nicht heilig <zu unterscheiden>, und sollen sie <den Unterschied> zwischen unrein und rein erkennen lassen*.", footnotes: ["℘ Kap. 22,26"] },
      { number: 24, text: "Und über einen Rechtsstreit sollen sie Gericht halten*, nach meinen Rechtsbestimmungen sollen sie richten*; und sie sollen meine Gesetze und meine Ordnungen bei all meinen Festzeiten beachten* und meine Sabbate heilig halten*.", footnotes: ["w. dastehen, um zu richten", "℘ 5Mo 17,9", "℘ Kap. 46,9; 3Mo 23,2", "℘ Kap. 22,26; Jes 58,13"] },
      { number: 25, text: "Und zu einem toten Menschen sollen sie* nicht hineingehen, sich unrein zu machen; nur beim Vater und der Mutter und beim Sohn und der Tochter, beim Bruder und bei der Schwester, die keinem Mann gehört hat, dürfen sie sich verunreinigen*.", footnotes: ["w. soll er", "℘ 3Mo 21,1-3"] },
      { number: 26, text: "Und nach seiner Reinigung soll man ihm sieben Tage zuzählen*;", footnotes: ["℘ 4Mo 19,11-13"] },
      { number: 27, text: "und an dem Tag, da er *ins Heiligtum*, in den inneren Vorhof, hineingeht, um im Heiligtum den Dienst zu verrichten, soll er sein Sündopfer darbringen*, spricht der Herr, HERR*. —", footnotes: ["nicht in LXX", "nicht in LXX", "℘ 3Mo 4,3", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 28, text: "Und darin soll ihr Erbteil bestehen*: Ich bin ihr Erbteil; und ihr sollt ihnen keinen Grundbesitz in Israel geben: ich bin ihr Grundbesitz*.", footnotes: ["Vulg. liest: Und sie sollen kein Erbteil haben", "℘ 5Mo 18,2; Jos 13,14"] },
      { number: 29, text: "Das Speisopfer und das Sündopfer und das Schuldopfer, das sollen sie essen*; und alles Gebannte in Israel soll ihnen gehören*.", footnotes: ["℘ 3Mo 2,3.10", "℘ 3Mo 27,21"] },
      { number: 30, text: "Und das Beste* aller Erstlinge von allem* und alle Hebopfer von allem aus all euren Hebopfern sollen den Priestern gehören. Und das Beste* eures Schrotmehls* sollt ihr dem Priester geben*, damit Segen auf deinem Haus ruht*.", footnotes: ["o. das Erste", "℘ 2Mo 23,19", "o. das Erste", "o. eures Teigs", "℘ 4Mo 15,20", "℘ Mal 3,10"] },
      { number: 31, text: "Keinerlei Aas noch Zerrissenes von Vögeln oder vom Vieh sollen die Priester essen*.", footnotes: ["℘ 3Mo 22,8"] },
    ]},
    { number: 45, verses: [
      { number: 1, text: "*Und wenn ihr das Land als Erbteil verlost*, sollt ihr für den HERRN eine Weihegabe aussondern*, als heiliges <Stück> vom Land, in der Länge 25 000 <Ellen> lang und in einer Breite von 20 000* <Ellen>. Die soll heilig sein in ihrem ganzen Gebiet ringsum.", heading: "Vision vom zukünftigen Tempel: Aufteilung des Landes um den Tempelbezirk — Pflichten und Opfer der Fürsten — Festtage", footnotes: ["℘ V. 1-8: Kap. 48,8-22", "℘ Kap. 47,21.22; Jos 14,1.2", "w. ein Hebopfer abheben", "Diese Zahl liest LXX; Mas. T.: 10 000"] },
      { number: 2, text: "Davon sollen zum Heiligtum* gehören ein Viereck von 500 auf 500 <Ellen> ringsum*, und 500 Ellen Weideland hat es ringsum*.", footnotes: ["w. zum Heiligen; d. i. der Gesamtkomplex des Heiligtums", "℘ Kap. 42,15-20", "℘ Kap. 43,21"] },
      { number: 3, text: "Und von diesem abgemessenen Stück sollst du eine Länge von 25 000 <Ellen> abmessen und eine Breite von 10 000 <Ellen>; da soll das Heiligtum, das Allerheiligste, sein*.", footnotes: ["℘ 1Kö 6,16"] },
      { number: 4, text: "Der heilige <Teil> vom Land ist es; den Priestern, die am Heiligtum Dienst tun, soll es gehören, die nahen, um dem HERRN zu dienen. Und es soll ihnen als Platz für Häuser und *als Weideland für das Vieh dienen*.", footnotes: ["so mit LXX und geringfügiger Korrektur eines Wortes; Mas. T.: als Heiligtum des Heiligtums", "so mit LXX und geringfügiger Korrektur eines Wortes; Mas. T.: als Heiligtum des Heiligtums"] },
      { number: 5, text: "Und <ein Stück von> 25 000 <Ellen> Länge und 10 000 <Ellen> Breite soll den Leviten, die am Tempelhaus Dienst tun, gehören, ihnen zum Besitz <für> Städte zum Wohnen*.", footnotes: ["Diesen Text setzt LXX voraus. Mas. T.: ihnen zum Grundbesitz, zwanzig Zellen\n℘ 4Mo 35,2"] },
      { number: 6, text: "Und als Besitz der Stadt sollt ihr <ein Stück von> 5 000 <Ellen> Breite und 25 000 <Ellen> Länge geben, entlang der heiligen Weihegabe*. Dem ganzen Haus Israel soll es gehören.", footnotes: ["w. gleichlaufend mit dem heiligen Hebopfer"] },
      { number: 7, text: "Und dem Fürsten <sollt ihr Land geben> auf dieser und auf jener Seite der heiligen Weihegabe* und des Grundbesitzes der Stadt, längs der heiligen Weihegabe* und längs des Grundbesitzes der Stadt, an der Westseite westwärts und an der Ostseite ostwärts und in der Länge* entsprechend eines der <Stammes>anteile von der Westgrenze bis zur Ostgrenze", footnotes: ["w. des heiligen Hebopfers", "w. des heiligen Hebopfers", "d. h. eigentlich der Breite nach, da es die Schmalseite ist; aber hier und in Kap. 48 bedeutet der Ausdruck »Länge« stets die von Osten nach Westen sich erstreckende Seite. Vgl. die Anm. zu Kap. 48,21."] },
      { number: 8, text: "als Land<besitz>. Es soll ihm als Grundbesitz in Israel gehören*; und meine Fürsten sollen mein Volk nicht mehr unterdrücken*, sondern das Land dem Haus Israel nach seinen Stämmen überlassen*.", footnotes: ["℘ Jos 19,49", "℘ Kap. 22,6.27", "w. geben\n℘ Kap. 46,18"] },
      { number: 9, text: "So spricht der Herr, HERR: Lasst es euch genug sein*, ihr Fürsten Israels! Gewalttat und Misshandlung beseitigt, und übt Recht und Gerechtigkeit*! Hört auf, mein Volk aus seinem Grundbesitz zu vertreiben*!, spricht der Herr, HERR*.", footnotes: ["℘ Kap. 44,6", "℘ Ps 82,2-4; Jes 1,17; Am 5,15", "w. Hört auf mit euren Vertreibungen gegenüber meinem Volk\n℘ Mi 2,2", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 10, text: "Gerechte Waage und gerechtes Efa und gerechtes Bat sollt ihr haben*.", footnotes: ["℘ 3Mo 19,35.36"] },
      { number: 11, text: "Das Efa und das Bat sollen gleiches Maß* haben, so dass das Bat den zehnten Teil des Homer enthält* und das Efa den zehnten <Teil> des Homer; nach dem Homer soll seine Maßbestimmung geschehen.", footnotes: ["w. ein einziges Maß", "℘ 2Mo 16,36; 1Kö 7,26"] },
      { number: 12, text: "Und der Schekel soll 20 Gera <betragen>*; 20 Schekel, 25 Schekel und 15 Schekel soll bei euch die Mine <betragen>.", footnotes: ["℘ 2Mo 30,13"] },
      { number: 13, text: "Das ist das Hebopfer, das ihr abheben sollt: ein sechstel Efa vom Homer Weizen und ein sechstel Efa vom Homer Gerste" },
      { number: 14, text: "und die Gebühr an Öl — das Bat ist das Öl<maß> —: ein zehntel Bat vom Kor; zehn Bat sind ein Homer, denn zehn Bat sind <auch> ein Kor*;", footnotes: ["T.; Mas. T.: ein Homer"] },
      { number: 15, text: "und ein Schaf* von der Herde, von zweihundert, von den Geschlechtern Israels* zum Speisopfer und zum Brandopfer und zu den Heilsopfern*, um ihnen Sühnung zu erwirken*, spricht der Herr, HERR*.", footnotes: ["o. eine Ziege", "so mit LXX; andere lesen: vom Viehbesitz Israels; Mas. T.: von dem wasserreichen <Gebiet> Israels", "o. Friedensopfern; o. Abschlussopfern; o. Gemeinschaftsopfern", "℘ 3Mo 1,4", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 16, text: "Das ganze Volk des Landes soll <verpflichtet> sein zu diesem Hebopfer an den Fürsten in Israel*.", footnotes: ["℘ 2Mo 30,14"] },
      { number: 17, text: "Dem Fürsten aber obliegen die Brandopfer und das Speisopfer und das Trankopfer an den Festen* und an den Neumonden und an den Sabbaten, zu allen Festzeiten des Hauses Israel*. Er soll das Sündopfer und das Speisopfer und das Brandopfer und die Heilsopfer* zubereiten, um dem Haus Israel Sühnung zu erwirken.", footnotes: ["℘ 2Chr 8,12.13", "℘ 4Mo 28; 29; 2Chr 35,7", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 18, text: "So spricht der Herr, HERR: Im ersten <Monat>, am Ersten des Monats, sollst du einen fehlerlosen Jungstier nehmen und das Heiligtum entsündigen*.", footnotes: ["℘ Kap. 43,20; 3Mo 16,16.18"] },
      { number: 19, text: "Und der Priester soll <etwas> von dem Blut des Sündopfers nehmen und es an die <Tür>pfosten* des Hauses tun und an die vier Ecken der Einfassung des Altars und an die Pfosten* der Tore des inneren Vorhofs*.", footnotes: ["So lesen 2 hebr. Handschr., LXX, die syr. Üs. und Vulg.; im Mas. T. Einzahl", "So lesen 2 hebr. Handschr., LXX, die syr. Üs. und Vulg.; im Mas. T. Einzahl", "℘ Kap. 43,20; 3Mo 16,16.18"] },
      { number: 20, text: "Und ebenso sollst du tun am Siebten des Monats wegen des Mannes, der <aus Versehen> sündigt*, und wegen des Einfältigen. Und so sollt ihr dem Haus Sühnung erwirken.", footnotes: ["℘ 3Mo 4,27"] },
      { number: 21, text: "Im ersten <Monat>, am vierzehnten Tag des Monats, sollt ihr das Passah halten, als Fest <sollt ihr es feiern>; sieben Tage soll man* ungesäuerte Brote essen*.", footnotes: ["so mit vielen hebr. Handschr. und den alten Üs.; Mas. T.: als Wochenfest <sollt ihr es feiern>; tagelang soll man", "℘ 2Mo 12,2-20"] },
      { number: 22, text: "Und der Fürst soll an diesem Tag für sich und für das ganze Volk des Landes einen Sündopferstier darbringen*.", footnotes: ["℘ Kap. 46,4; 3Mo 4,13-16.21"] },
      { number: 23, text: "Und die sieben Tage des Festes <hindurch> soll er dem HERRN ein Brandopfer darbringen: sieben Stiere und sieben Widder, ohne Fehler, täglich, die sieben Tage lang, und als Sündopfer täglich einen Ziegenbock*.", footnotes: ["w. Haarigen der Ziegen\n℘ 3Mo 23,8; 4Mo 28,16-24"] },
      { number: 24, text: "Und als Speisopfer soll er ein Efa für den Stier und ein Efa für den Widder darbringen; und ein Hin Öl für das Efa*.", footnotes: ["℘ Kap. 46,5.7.11"] },
      { number: 25, text: "Im siebten <Monat>, am fünfzehnten Tag des Monats, am Fest*, soll er die sieben Tage lang ebenso <Opfer> darbringen, so das Sündopfer wie das Brandopfer und so das Speisopfer wie das Öl*.", footnotes: ["d. i. am Laubhüttenfest", "℘ 3Mo 23,34-36"] },
    ]},
    { number: 46, verses: [
      { number: 1, text: "So spricht der Herr, HERR: Das Tor des inneren Vorhofs, das nach Osten weist, soll die sechs Werktage <hindurch> geschlossen sein*; aber am Sabbattag soll es geöffnet werden, und am Tag des Neumondes soll es geöffnet werden*.", heading: "Vision vom zukünftigen Tempel: Vorschriften für Festtage, für Fürst und Volk und für die Opferküchen", footnotes: ["℘ Kap. 44,1.2", "℘ Jes 66,23"] },
      { number: 2, text: "Und der Fürst soll durch die Vorhalle des Tores von außen her hineingehen* und an den Pfosten des Tores stehen bleiben*; und die Priester sollen sein Brandopfer und seine Heilsopfer* darbringen, und er soll auf der Schwelle des Tores anbeten* und hinausgehen; das Tor soll aber bis zum Abend nicht geschlossen werden.", footnotes: ["℘ Kap. 44,3", "℘ 2Chr 23,13", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "w. sich niederwerfen"] },
      { number: 3, text: "Und das Volk des Landes soll vor dem HERRN anbeten* am Eingang dieses Tores, an den Sabbaten und an den Neumonden. —", footnotes: ["w. sich niederwerfen\n℘ Ps 96,8.9"] },
      { number: 4, text: "Und das Brandopfer, das der Fürst dem HERRN darbringt, soll am Sabbattag sechs fehlerlose Lämmer und einen fehlerlosen Widder <betragen>*.", footnotes: ["℘ Kap. 45,17.22; 4Mo 28,10"] },
      { number: 5, text: "Und das Speisopfer: ein Efa für den Widder; für die Lämmer aber <beträgt> das Speisopfer eine Gabe seiner Hand*; und Öl: ein Hin für das Efa*.", footnotes: ["d. h. so viel er geben kann; vgl. V. 7", "℘ Kap. 45,24"] },
      { number: 6, text: "Und am Tag des Neumondes <soll das Brandopfer> einen fehlerlosen Jungstier <betragen> und sechs Lämmer und einen Widder; ohne Fehler sollen sie sein*.", footnotes: ["℘ 4Mo 28,11-14"] },
      { number: 7, text: "Und ein Efa für den Stier und ein Efa für den Widder soll er als Speisopfer opfern; und für die Lämmer: so viel seine Hand aufbringen kann; und Öl: ein Hin für das Efa*.", footnotes: ["℘ Kap. 45,24"] },
      { number: 8, text: "Und wenn der Fürst hineingeht, soll er durch die Vorhalle des Tores* hineingehen; und auf demselben Weg soll er hinausgehen*.", footnotes: ["d. i. die Halle des Osttores; wie V. 2", "℘ Kap. 44,3"] },
      { number: 9, text: "Und wenn das Volk des Landes zu den Festzeiten* vor den HERRN kommt*: wer durch das Nordtor hineingeht, um anzubeten, soll durch das Südtor hinausgehen; und wer durch das Südtor hineingeht, soll durch das Nordtor hinausgehen; er soll nicht durch das Tor zurückkehren, durch das er hineingegangen ist, sondern geradeaus* soll er hinausgehen.", footnotes: ["℘ Kap. 36,38; 44,24", "℘ 2Mo 23,14-17", "w. <durch> das ihm Gegenüber<liegende>"] },
      { number: 10, text: "Und der Fürst soll mitten unter ihnen hineingehen, wenn sie hineingehen; und wenn sie hinausgehen, soll <auch> er hinausgehen*. —", footnotes: ["so mit vielen hebr. Handschr., LXX und Vulg.; Mas. T.: sollen sie hinausgehen"] },
      { number: 11, text: "Und an den Festen und zu den Festzeiten soll das Speisopfer ein Efa für den Stier betragen und ein Efa für den Widder; und für die Lämmer: eine Gabe seiner Hand*; und Öl: ein Hin für das Efa*.", footnotes: ["d. h. so viel er geben kann; vgl. V. 7", "℘ Kap. 45,24"] },
      { number: 12, text: "Und wenn der Fürst eine freiwillige Gabe darbringen will, ein Brandopfer oder ein Heilsopfer*, als freiwillige Gabe für den HERRN, dann soll man ihm das Tor öffnen, das nach Osten weist, und er soll sein Brandopfer und seine Heilsopfer* darbringen, ebenso wie er <es> am Sabbattag darbringt. Dann soll er hinausgehen, und man soll das Tor schließen, nachdem er hinausgegangen ist*. —", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 44,1.2"] },
      { number: 13, text: "Und du sollst täglich ein einjähriges fehlerloses Lamm dem HERRN als Brandopfer zubereiten, Morgen für Morgen sollst du es zubereiten*.", footnotes: ["℘ 2Mo 29,38-42"] },
      { number: 14, text: "Und ein Speisopfer sollst du dazu zubereiten, Morgen für Morgen: ein sechstel Efa und Öl, ein drittel Hin, um den Weizengrieß zu befeuchten, ein Speisopfer für den HERRN — ewige Ordnungen<, die> beständig <gelten sollen>." },
      { number: 15, text: "Und man soll das Lamm und das Speisopfer und das Öl, Morgen für Morgen, als ein regelmäßiges Brandopfer darbringen*.", footnotes: ["℘ 2Mo 29,38-42"] },
      { number: 16, text: "So spricht der Herr, HERR: Wenn der Fürst einem seiner Söhne ein Geschenk aus seinem Erbbesitz gibt, so gehört es* seinen Söhnen, es ist ihr Grundeigentum als Erbbesitz.", footnotes: ["so mit LXX; Mas. T.: Wenn ein Fürst einem seiner Söhne ein Geschenk gibt — <es ist ja> sein Erbbesitz — so gehört es"] },
      { number: 17, text: "Wenn er aber einem seiner Knechte ein Geschenk von seinem Erbbesitz gibt, dann soll es dem bis zum Jahr der Freilassung gehören*, soll dann aber wieder an den Fürsten kommen. Nur seinen Söhnen, ihnen soll es als sein Erbbesitz* <für immer> gehören.", footnotes: ["℘ 3Mo 25,10.13", "d. h. als Erbbesitz des Fürsten als leiblichem Vater"] },
      { number: 18, text: "Und der Fürst soll nichts von dem Erbbesitz des Volkes nehmen, so dass er sie gewaltsam aus ihrem Grundbesitz verdrängt*; von seinem <eigenen> Grundbesitz soll er an seine Söhne vererben, damit sich mein Volk nicht zerstreut, jeder aus seinem Grundbesitz.", footnotes: ["℘ Kap. 45,8.9; 1Kö 21,3"] },
      { number: 19, text: "Und er brachte mich durch den Eingang, der an der Seite* des Tores war, zu den heiligen Priesterzellen*, die nach Norden gerichtet sind, und siehe, dort war ein Ort am äußersten Ende nach Westen zu.", footnotes: ["w. Schulter; nämlich des nördlichen Binnentores", "T.; Mas. T.: zu den Zellen des Heiligtums (w. des Heiligen), zu den Priestern\n℘ Kap. 42,9"] },
      { number: 20, text: "Und er sprach zu mir: Das ist der Ort, wo die Priester das Schuldopfer und das Sündopfer kochen*, wo sie das Speisopfer backen sollen*, damit man es nicht in den äußeren Vorhof hinaustragen muss <und dabei> das Volk heilig macht*.", footnotes: ["℘ 2Mo 29,31; 1Sam 2,13; 2Chr 35,13", "℘ 3Mo 2,1-10", "℘ Kap. 44,19"] },
      { number: 21, text: "Und er führte mich in den äußeren Vorhof* hinaus und ließ mich an den vier Ecken des Vorhofs vorübergehen; und siehe, in jeder Ecke des Vorhofs war je ein Hof.", footnotes: ["℘ Kap. 40,17"] },
      { number: 22, text: "In den vier Ecken des Vorhofs waren kleine* Höfe, vierzig <Ellen> lang und dreißig breit. Ein <und dasselbe> Maß hatten alle vier*.", footnotes: ["so mit LXX; die Bedeutung des Wortes im Mas. T. ist ungewiss, vielleicht: »geschlossene« o. »nicht überdachte«", "so mit LXX, syr. Üs. und Vulg.; Mas. T.: hatten alle vier an den Ecken"] },
      { number: 23, text: "Und in ihnen war eine Steinlage ringsherum bei allen vieren; und Kochstellen waren unten an den Steinlagen angebracht ringsum." },
      { number: 24, text: "Und er sprach zu mir: Dies sind die Küchen*, wo die, die den Dienst am Haus versehen, das Schlachtopfer des Volkes kochen sollen*.", footnotes: ["so mit LXX; Mas. T.: Diese sind das Haus der Köche", "℘ Kap. 44,11.14"] },
    ]},
    { number: 47, verses: [
      { number: 1, text: "Und er führte mich zurück zum Eingang des Hauses; und siehe, Wasser floss unter der Schwelle des Hauses hervor* nach Osten*, denn die Vorderseite des Hauses war nach Osten <gerichtet>; und das Wasser floss unten herab an der rechten Seite* des Hauses, südlich vom Altar.", heading: "Vision vom zukünftigen Tempel: Das Wasser aus dem Tempel", footnotes: ["℘ Ps 46,5; 87,7; Sach 13,1; Offb 22,1", "℘ Kap. 40,6", "w. Schulter"] },
      { number: 2, text: "Und er führte mich hinaus durch das Nordtor und ließ mich den Weg außen herumgehen zum äußeren Tor, auf dem Weg, der sich nach Osten wendet; und siehe, Wasser rieselte auf der rechten Seite* hervor.", footnotes: ["w. Schulter"] },
      { number: 3, text: "Und als der Mann gegen Osten hinausging, die Messschnur in seiner Hand*, da maß er tausend Ellen und ließ mich durch das Wasser gehen: Wasser bis an die Knöchel.", footnotes: ["℘ Kap. 40,3; Sach 2,5"] },
      { number: 4, text: "Und er maß tausend <Ellen> und ließ mich durch das Wasser gehen: Wasser bis an die Knie. Und er maß tausend <Ellen> und ließ mich hindurchgehen: Wasser bis an die Hüften." },
      { number: 5, text: "Und er maß tausend <Ellen>: ein Fluss, den ich nicht durchschreiten konnte, denn das Wasser war tief*, Wasser zum Schwimmen, ein Fluss, der nicht <mehr> durchschritten werden kann.", footnotes: ["w. hoch"] },
      { number: 6, text: "Und er sprach zu mir: Hast du gesehen, Menschensohn? Und er führte mich wieder zurück am Ufer des Flusses <entlang>*.", footnotes: ["so mit vielen hebr. Handschr. und den alten Üs.; Mas. T.: zurück zum Ufer des Flusses"] },
      { number: 7, text: "Als ich zurückkehrte, siehe, <da standen> am Ufer des Flusses sehr viele Bäume auf dieser und auf jener Seite*.", footnotes: ["℘ Offb 22,2"] },
      { number: 8, text: "Und er sprach zu mir: Dieses Wasser fließt hinaus in den östlichen Bezirk* und fließt in die Ebene* hinab und gelangt ins Meer*, in das salzige Wasser, und das Wasser wird gesund werden*.", footnotes: ["d. i. die Gegend oberhalb des Toten Meeres; vgl. Jos 22,10", "hebr. Araba; d. i. die Niederung, die zu beiden Seiten des Jordan und des Toten Meeres liegt und sich bis zum Golf von Elat erstreckt", "℘ 5Mo 4,49", "so in Anlehnung an LXX; Mas. T.: und gelangt ins Meer — zum Meer hin wird es (das Flusswasser) hinausgeführt — und das Wasser (des Toten Meeres) wird gesund werden.\n℘ 2Mo 15,25"] },
      { number: 9, text: "Und es wird geschehen, jedes Lebewesen, das* da wimmelt — überall wohin der Fluss* kommt —, wird leben. Und es wird sehr viele Fische geben. Wenn dieses Wasser dorthin kommt, dann wird das Salzwasser gesund werden*, und alles wird leben, wohin der Fluss kommt.", footnotes: ["w. jede lebende Seele, die", "so mit den alten Üs.; Mas. T.: der Doppelfluss", "w. dann wird es gesund werden"] },
      { number: 10, text: "Und es wird geschehen, dass Fischer an ihm* stehen werden: von En-Gedi* bis En-Eglajim werden Trockenplätze für Netze sein. Fische von jeder Art werden in ihm* sein*, sehr zahlreich, wie die Fische des großen Meeres.", footnotes: ["d. i. dem Salzmeer", "℘ 2Chr 20,2", "d. i. dem Salzmeer", "w. Nach ihrer Art werden deren Fische sein"] },
      { number: 11, text: "Seine Sümpfe und seine Lachen <aber> werden nicht gesund werden. Zur Salzgewinnung sind sie bestimmt*.", footnotes: ["w. Dem Salz sind sie hingegeben"] },
      { number: 12, text: "An dem Fluss aber, an seinem Ufer, werden auf dieser und auf jener Seite allerlei Bäume wachsen, von denen man isst, deren Blätter nicht welken und deren Früchte nicht ausgehen werden. Monat für Monat* werden sie frische Früchte tragen, denn sein Wasser fließt aus dem Heiligtum hervor; und ihre Früchte werden als Speise dienen und ihre Blätter als Heilmittel*.", footnotes: ["w. Nach ihren Monaten", "℘ Offb 22,2"] },
      { number: 13, text: "*So spricht der Herr, HERR: Das ist die Grenze, innerhalb derer ihr euch das Land als Erbe zuweisen sollt nach den zwölf Stämmen Israels*: für Josef <zwei> Anteile*.", heading: "Die Grenzen des Landes", footnotes: ["℘ vgl. 4Mo 34,1-12", "℘ Kap. 48,1-7; 4Mo 34,2.13", "w. Messschnüre; d. h. abgemessene Landstücke\n℘ 1Mo 48,5; Jos 16,4; 17,1"] },
      { number: 14, text: "Und ihr sollt es zum Erbe erhalten, der eine wie der andere*, da ich meine Hand <im Schwur> erhoben habe, es euren Vätern zu geben. Dieses Land soll euch als Erbteil zufallen*.", footnotes: ["w. ein Mann wie sein Bruder", "℘ 2Mo 6,8"] },
      { number: 15, text: "Und das ist die Grenze des Landes: Auf der Nordseite, vom großen Meer an, in der Richtung auf Hetlon*, bis man nach Hamat kommt, nach Zedad hin,", footnotes: ["℘ Kap. 48,1"] },
      { number: 16, text: "* Berota*, Sibrajim, das zwischen dem Gebiet von Damaskus und dem Gebiet von Hamat liegt, <und> Hazar-Enan*, das an der Grenze von Hauran liegt.", footnotes: ["so mit LXX; vgl. Kap. 48,1; Mas. T.: bis man nach Zedad kommt, 16 Hamat,", "℘ 2Sam 8,8", "so mit V. 17; Mas. T.: das mittlere Hazar"] },
      { number: 17, text: "Und die Grenze verläuft vom Meer <bis nach> Hazar-Enan. <Dabei liegt> die Grenze von Damaskus — und zwar, was den Norden betrifft — nördlich und ebenso das Gebiet von Hamat. Das ist die Nordseite. —" },
      { number: 18, text: "Und die Ostseite: *<Von Hazar-Enan, das> zwischen Hauran und Damaskus <liegt,> bildet zwischen Gilead und dem Land Israel der Jordan die Grenze* bis zum östlichen Meer* hin bis Tamar*. Das ist die Ostseite. —", footnotes: ["so mit LXX; Mas. T.: Zwischen Hauran und Damaskus und Gilead und dem Land Israel ist der Jordan als Grenze", "so mit LXX; Mas. T.: Zwischen Hauran und Damaskus und Gilead und dem Land Israel ist der Jordan als Grenze", "℘ Joe 2,20", "Diesen Text setzen LXX und die syr. Üs. voraus; Mas. T.: <das> sollt ihr messen"] },
      { number: 19, text: "Und die Mittagseite südwärts: von Tamar* bis zum Streitwasser von Kadesch* <und> nach dem Bach <Ägyptens> hin bis an das große Meer. Das ist die Südseite gegen Mittag*. —", footnotes: ["℘ 1Kö 9,18; 2Chr 20,2", "Einige hebr. Handschr., die syr., aram. Üs. und Vulg. lesen den Ortsnamen: Meribat-Kadesch\n℘ 4Mo 20,1.13", "℘ Kap. 48,28"] },
      { number: 20, text: "Und die Westseite: Das große Meer bildet die Grenze* bis gegenüber <der Stelle>, wo man nach Hamat kommt. Das ist die Westseite.", footnotes: ["So lesen LXX und die syr. Üs.; Mas. T.: Das große Meer als Grenze"] },
      { number: 21, text: "Und dieses Land sollt ihr unter euch verteilen nach den Stämmen Israels.", heading: "Die Aufteilung des Landes" },
      { number: 22, text: "Und es soll geschehen: Ihr sollt es als Erbteil verlosen* unter euch und den Fremden, die sich in eurer Mitte aufhalten, die in eurer Mitte Söhne gezeugt haben. Und sie sollen euch gelten wie Einheimische* unter den Söhnen Israel*. Mit euch sollen sie <es> als Erbteil durch das Los erhalten* mitten unter den Stämmen Israels*.", footnotes: ["℘ Kap. 48,29", "o. der Vollbürger", "℘ 3Mo 19,34; Jes 56,6.7", "so mit Vulg., der syr. und aram. Üs.; Mas. T.: Bei euch sollen sie <euch> als Erbteil zufallen", "℘ Kap. 45,1"] },
      { number: 23, text: "Und es soll geschehen, in dem Stamm, bei dem der Fremde sich aufhält, dort sollt ihr ihm sein Erbteil geben, spricht der Herr, HERR*.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN"] },
    ]},
    { number: 48, verses: [
      { number: 1, text: "Und das sind die Namen der Stämme: Im äußersten Norden, seitlich vom Weg nach Hetlon, nach Hamat* <und> nach Hazar-Enan — das Gebiet von Damaskus <bleibt dabei> nordwärts, seitlich von Hamat —, von der Ostseite nach Westen: <für> Dan* ein <Anteil>*.", footnotes: ["w. <des Weges>, wenn man nach Hamat kommt\n℘ Kap. 47,15-17", "℘ Jos 19,48", "so in Angleichung an die folgenden Verse; Mas. T.: die Ostseite — Westen: für Dan ein <Anteil>"] },
      { number: 2, text: "Und neben dem Gebiet von Dan, von der Ostseite bis zur Westseite: Asser* ein <Anteil>.", footnotes: ["℘ Jos 19,31"] },
      { number: 3, text: "Und neben dem Gebiet von Asser, von der Ostseite bis zur Westseite: Naftali* ein <Anteil>.", footnotes: ["℘ Jos 19,39"] },
      { number: 4, text: "Und neben dem Gebiet von Naftali, von der Ostseite bis zur Westseite: Manasse* ein <Anteil>.", footnotes: ["℘ Jos 13,31; 17,6"] },
      { number: 5, text: "Und neben dem Gebiet von Manasse, von der Ostseite bis zur Westseite: Ephraim* ein <Anteil>.", footnotes: ["℘ Jos 16,9"] },
      { number: 6, text: "Und neben dem Gebiet von Ephraim, von der Ostseite bis zur Westseite: Ruben* ein <Anteil>.", footnotes: ["℘ Jos 13,23"] },
      { number: 7, text: "Und neben dem Gebiet von Ruben, von der Ostseite bis zur Westseite: Juda* ein <Anteil>.", footnotes: ["℘ Jos 15,12"] },
      { number: 8, text: "*Und neben dem Gebiet von Juda, von der Ostseite bis zur Westseite, soll die Weihegabe liegen, die ihr aussondern sollt*: 25 000 <Ellen> die Breite und die Länge wie eines der <Stammes>anteile von der Ostseite bis zur Westseite; und das Heiligtum soll in seiner Mitte sein.", footnotes: ["℘ V. 8-22: Kap. 45,1-8", "w. soll das Hebopfer sein, das ihr abheben sollt"] },
      { number: 9, text: "Die Weihegabe, die ihr für den HERRN aussondern sollt*, soll 25 000 <Ellen> in der Länge und 20 000* <Ellen> in der Breite <betragen>.", footnotes: ["w. Das Hebopfer, das ihr für den HERRN abheben sollt", "so mit einer griech. Üs.; Mas. T.: 10 000"] },
      { number: 10, text: "Und diesen <Personen> soll die heilige Weihegabe* gehören: den Priestern. Nach Norden zu 25 000 <Ellen lang> und nach Westen 10 000 <Ellen> breit und nach Osten 10 000 <Ellen> breit und nach Süden 25 000 <Ellen> lang; und das Heiligtum des HERRN soll in seiner Mitte sein.", footnotes: ["w. das heilige Hebopfer"] },
      { number: 11, text: "Den geweihten Priestern <soll es gehören>, den Söhnen Zadoks*, die meinen Dienst versehen haben, die, als die Söhne Israel abirrten, nicht abgeirrt sind, wie die Leviten abgeirrt sind*.", footnotes: ["so mit LXX, der syr. und aram. Üs.; Mas. T.: Den Priestern gehört das Geheiligte von den Söhnen Zadoks", "℘ Kap. 44,15.16"] },
      { number: 12, text: "Und sie sollen eine Sonderweihegabe von der Weihegabe des Landes erhalten*, ein Hochheiliges neben dem Gebiet der Leviten.", footnotes: ["w. Und ihnen ist ein Abgehobenes von dem Hebopfer des Landes"] },
      { number: 13, text: "Und die Leviten <sollen> entsprechend dem Gebiet der Priester <ein Gebiet haben von> 25 000 <Ellen> Länge und 10 000 <Ellen> Breite. Jede Langseite soll <also> 25 000 <Ellen betragen> und die Breite 10 000 <Ellen>." },
      { number: 14, text: "Und man soll nichts davon verkaufen noch vertauschen*; und das Beste* des Landes soll man nicht <an andere> übergehen lassen, denn es ist dem HERRN heilig*.", footnotes: ["℘ 3Mo 25,34", "w. das Erste", "℘ 2Mo 23,19"] },
      { number: 15, text: "Und die 5 000 <Ellen>, die in der Breite übrig bleiben, längs der 25 000 <Ellen>, das soll nicht heilig sein, <sondern> der Stadt als Wohngebiet und Weideland <dienen>. Und die Stadt soll mitten darin liegen." },
      { number: 16, text: "Und das sollen ihre Maße sein*: die Nordseite 4 500 <Ellen> und die Südseite 4 500 <Ellen> und die* Ostseite 4 500 <Ellen> und die Westseite 4 500 <Ellen>.", footnotes: ["℘ Offb 21,16.17", "so mit 6 hebr. Handschr.; Mas. T.: an der"] },
      { number: 17, text: "Und die Stadt soll <dies> als Weideland haben: nach Norden 250 <Ellen> und nach Süden 250 <Ellen> und nach Osten 250 <Ellen> und nach Westen 250 <Ellen>." },
      { number: 18, text: "Und was übrig bleibt, <beträgt> in der Länge, parallel zur Weihegabe*, 10 000 <Ellen> nach Osten und 10 000 <Ellen> nach Westen, es läuft parallel zur heiligen Weihegabe*. Sein Ertrag soll denen, die <in> der Stadt arbeiten, als Nahrung dienen.", footnotes: ["w. zum heiligen Hebopfer", "w. zum heiligen Hebopfer"] },
      { number: 19, text: "Und die <in> der Stadt arbeiten, sollen es bearbeiten aus allen Stämmen Israels*.", footnotes: ["d. h. entweder: alle Israeliten, die in der Stadt wohnen, oder: nur die von allen Israeliten, die in der Stadt wohnen"] },
      { number: 20, text: "Die ganze Weihegabe* soll <eine Fläche von> 25 000 auf 25 000 <Ellen haben>. Als Viereck sollt ihr die heilige Weihegabe aussondern* zusammen mit dem Grundbesitz der Stadt.", footnotes: ["w. Das ganze Hebopfer", "w. sollt ihr das heilige Hebopfer abheben"] },
      { number: 21, text: "Und was übrig bleibt, soll dem Fürsten <gehören: Das Gebiet> auf dieser und auf jener Seite der heiligen Weihegabe* und des Grundbesitzes der Stadt, längs der 25 000 <Ellen>* bis zur Ostgrenze und nach Westen längs der 25 000 <Ellen> zur Westgrenze hin, <soll> entsprechend den <Stammes>anteilen dem Fürsten <gehören>. Und die heilige Weihegabe* und das Heiligtum des Hauses soll in seiner Mitte sein.", footnotes: ["w. des heiligen Hebopfers", "so mit LXX und der syr. Üs.; Mas. T.: längs der 25 000 <Ellen> des Hebopfers (o. der Weihegabe)", "w. das heilige Hebopfer"] },
      { number: 22, text: "Und von dem Grundbesitz der Leviten und von dem Grundbesitz der Stadt mitten zwischen dem, was dem Fürsten gehört, was zwischen dem Gebiet von Juda und dem Gebiet von Benjamin <liegt>, soll dem Fürsten gehören." },
      { number: 23, text: "Und der Rest der Stämme: Von der Ostseite bis zur Westseite: Benjamin* ein <Anteil>.", footnotes: ["℘ Jos 18,11"] },
      { number: 24, text: "Und neben dem Gebiet von Benjamin, von der Ostseite bis zur Westseite: Simeon* ein <Anteil>.", footnotes: ["℘ Jos 19,1"] },
      { number: 25, text: "Und neben dem Gebiet von Simeon, von der Ostseite bis zur Westseite: Issaschar* ein <Anteil>.", footnotes: ["℘ Jos 19,17"] },
      { number: 26, text: "Und neben dem Gebiet von Issaschar, von der Ostseite bis zur Westseite: Sebulon* ein <Anteil>.", footnotes: ["℘ Jos 19,10"] },
      { number: 27, text: "Und neben dem Gebiet von Sebulon, von der Ostseite bis zur Westseite: Gad* ein <Anteil>.", footnotes: ["℘ Jos 13,24"] },
      { number: 28, text: "Und neben dem Gebiet von Gad, nach der Mittagseite hin, südwärts, da soll die Grenze von Tamar sein <bis zum> Wasser von Meribat-Kadesch*, zum Bach <Ägyptens> hin, bis an das große Meer*.", footnotes: ["d. h. Streitwasser von Kadesch; vgl. Kap. 47,19", "℘ Kap. 47,19"] },
      { number: 29, text: "Das ist das Land, das ihr den Stämmen Israels als Erbteil verlosen sollt; und das sind ihre Anteile*, spricht der Herr, HERR*.", footnotes: ["℘ Kap. 47,21.22; Jos 18,10", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 30, text: "*Und das sind die Ausgänge der Stadt: Von der Nordseite aus<, die> 4 500 <Ellen> misst* —", heading: "Die Stadt, ihre Tore und ihr Name", footnotes: ["℘ V. 31-34; 1Mo 35,23-26", "w. Maß <hat>"] },
      { number: 31, text: "die Tore der Stadt aber <heißen> nach den Namen der Stämme Israels* —, drei Tore nach Norden zu: das Tor Ruben eins, das Tor Juda eins, das Tor Levi eins.", footnotes: ["℘ Offb 21,12.13"] },
      { number: 32, text: "Und nach der Ostseite hin 4 500 <Ellen> und drei Tore: das Tor Josef eins, das Tor Benjamin eins, das Tor Dan eins." },
      { number: 33, text: "Und an der Südseite 4 500 <Ellen> Maß und drei Tore: das Tor Simeon eins, das Tor Issaschar eins, das Tor Sebulon eins." },
      { number: 34, text: "An der Westseite 4 500 <Ellen> drei Tore*: das Tor Gad eins, das Tor Asser eins, das Tor Naftali eins.", footnotes: ["so mit anderen hebr. Handschr., LXX und der syr. Üs.; Mas. T.: ihre drei Tore"] },
      { number: 35, text: "Ringsherum 18 000 <Ellen>. Und der Name der Stadt <heißt> von nun an: Hier ist der HERR*.", footnotes: ["hebr. jahwe schammah\n℘ Kap. 35,10; 37,26-28; 4Mo 23,21; 1Chr 23,25; Ps 46,6; 87,3; Jes 12,6; Joe 4,21"] },
    ]},
  ]
};
